INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('metricasboss/otto/otto', 'community', 'metricasboss', 'otto', 'metricasboss/otto', 'otto', 0, 0, 39, '2026-03-08T01:57:15.656Z', '2026-03-08T02:13:57.836Z', '5c3c2d30b79d2e56c242baa7b80febfc410bf5882ced68edd4df9899b7a89f80', '{"id":"metricasboss/otto/otto","name":"otto","description":{"en":"otto is a Privacy Guardian that automates GDPR and LGPD compliance for Claude Code, protecting personal data and special categories. It analyzes code for privacy violations, ensuring regulatory adherence.","zh":"Otto AI工具提供LGPD和GDPR合规自动化，保护个人数据安全","ja":"Otto AIエージェントは、GDPR Privacy Guardianを使用して個人データを保護します","ko":"Otto AI 에이전트는 LGPD와 GDPR 규정 준수를 자동화하여 개인 데이터를 보호합니다","es":"Otto es un agente de privacidad que automatiza la cumplimiento de LGPD y GDPR para Claude Code, protegiendo datos personales como información relativa a personas identificadas o identificables","fr":"Otto est un agent de confidentialité qui automatise la conformité LGPD et GDPR pour Claude Code, protégeant les données personnelles comme les informations relatives à des personnes identifiées ou identifiables","de":"Otto ist ein Datenschutz-Agent, der die Einhaltung von LGPD- und GDPR-Vorschriften für Claude Code automatisiert und personenbezogene Daten wie Informationen über identifizierte oder identifizierbare Personen schützt","pt":"O Otto é um guardião de privacidade que automatiza a conformidade com a LGPD e o GDPR para o Claude Code, protegendo dados pessoais.","ru":"Отто - это защитник конфиденциальности, который автоматизирует соблюдение LGPD и GDPR для Claude Code, защищая личные данные с помощью ИИ Агентов","ar":"أوتو هو حارس خصوصية يأتمة الامتثال لقانون اللجنة العامة لحماية البيانات وتنظيم الاتحاد الأوروبي ل Claude Code وأدوات الذكاء الاصطناعي، يحمي البيانات الشخصية"},"seo":{"title":{"en":"otto: GDPR Compliance Automation for Claude Code | AI Age...","zh":"Otto AI工具：LGPD + GDPR 自动化合规指南","ja":"Otto AIエージェント：GDPR Privacy Guardianのセットアップガイド","ko":"Otto AI 에이전트: LGPD + GDPR 자동화 규정 준수 설정 가이드","es":"Otto: Guía de configuración para la automatización de la ...","fr":"Otto: Guide de mise en place pour l''automatisation de la ...","de":"Otto: Einrichtungsleitfaden für die Automatisierung von L...","pt":"Otto: Guia de Configuração para Conformidade LGPD e GDPR","ru":"Отто: Руководство по настройке для соблюдения LGPD и GDPR...","ar":"أوتو: دليل الإعداد للامتثال لقانون اللجنة العامة لحماية ا..."},"description":{"en":"Discover how otto automates LGPD and GDPR compliance for Claude Code, ensuring personal data protection. Learn more and get started with otto today!","zh":"Otto AI工具帮助您自动化LGPD和GDPR合规，保护个人数据安全","ja":"Otto AIエージェントは、GDPR Privacy Guardianを使用して個人データを保護します","ko":"Otto AI 에이전트는 LGPD와 GDPR 규정 준수를 자동화하여 개인 데이터를 보호합니다","es":"Descubre cómo Otto protege los datos personales con la automatización de la privacidad LGPD y GDPR para Claude Code","fr":"Découvrez comment Otto protège les données personnelles avec l''automatisation de la vie privée LGPD et GDPR pour Claude Code","de":"Erfahren Sie, wie Otto personenbezogene Daten mit der Automatisierung von LGPD- und GDPR-Compliance für Claude Code schützt","pt":"Automatize a conformidade com a LGPD e o GDPR com o Otto, um guardião de privacidade para o Claude Code","ru":"Автоматизируйте соблюдение LGPD и GDPR с помощью Отто, защитника конфиденциальности для Claude Code и ИИ Агентов","ar":"أتمتة الامتثال لقانون اللجنة العامة لحماية البيانات وتنظيم الاتحاد الأوروبي مع أوتو، حارس خصوصية ل Claude Code وأدوات الذكاء الاصطناعي"},"definition":{"en":"otto is a GDPR Privacy Guardian that automates compliance for Claude Code, protecting personal data and special categories like racial origin and health data.","zh":"Otto AI工具是一种GDPR Privacy Guardian，自动化LGPD和GDPR合规","ja":"Otto AIエージェントは、GDPR Privacy Guardianを使用して個人データを保護するAIツールです","ko":"Otto AI 에이전트는 개인 데이터를 보호하는 GDPR Privacy Guardian입니다","es":"Otto es un agente de privacidad que automatiza la cumplimiento de regulaciones de privacidad como LGPD y GDPR","fr":"Otto est un agent de confidentialité qui automatise la conformité aux règlements de confidentialité tels que LGPD et GDPR","de":"Otto ist ein Datenschutz-Agent, der die Einhaltung von Datenschutzbestimmungen wie LGPD und GDPR automatisiert","pt":"O Otto é um agente de privacidade que automatiza a conformidade com regulamentações de proteção de dados","ru":"Отто - это агент конфиденциальности, который автоматизирует соблюдение правил защиты данных с помощью ИИ Агентов","ar":"أوتو هو وكيل خصوصية يأتمة الامتثال لتنظيمات حماية البيانات مع أدوات الذكاء الاصطناعي"},"features":{"en":["Monitors Art. 4 - Definitions for personal data and special categories","Analyzes code for privacy violations according to GDPR (EU 2016/679)","Protects special categories like racial origin, political opinions, and health data","Automates LGPD and GDPR compliance for Claude Code","Ensures regulatory adherence for personal data protection"],"zh":["自动化LGPD和GDPR合规","保护个人数据安全","支持Art. 4 - Definitions","监控特殊类别数据","保护健康数据和生物数据"],"ja":["GDPR Privacy Guardianを使用した個人データ保護","LGPDとGDPRの自動化合規","Art. 4 - Definitionsのサポート","特殊カテゴリーデータの監視","健康データとバイオメトリクスデータの保護"],"ko":["LGPD와 GDPR 규정 준수를 자동화","개인 데이터를 보호","Art. 4 - Definitions 지원","특수 카테고리 데이터 모니터링","건강 데이터와 생체 데이터 보호"],"es":["Automatización de la privacidad LGPD y GDPR","Protección de datos personales como información relativa a personas identificadas o identificables","Análisis de código para violaciones de privacidad","Cumplimiento con el artículo 4 de la GDPR sobre definiciones de datos personales","Compatibilidad con Claude Code"],"fr":["Automatisation de la vie privée LGPD et GDPR","Protection des données personnelles comme les informations relatives à des personnes identifiées ou identifiables","Analyse de code pour les violations de confidentialité","Conformité à l''article 4 de la GDPR sur les définitions de données personnelles","Compatibilité avec Claude Code"],"de":["Automatisierung von LGPD- und GDPR-Compliance","Schutz personenbezogener Daten wie Informationen über identifizierte oder identifizierbare Personen","Code-Analyse für Datenschutzverletzungen","Einhaltung von Artikel 4 der GDPR zu Datenschutzdefinitionen","Kompatibilität mit Claude Code"],"pt":["Automatização da conformidade com a LGPD e o GDPR","Proteção de dados pessoais e categorias especiais","Análise de código para violações de privacidade","Implementação do Art. 4 da regulamentação GDPR","Monitoramento de artigos principais da regulamentação"],"ru":["Автоматизация соблюдения LGPD и GDPR с помощью ИИ Агентов","Защита личных данных и специальных категорий","Анализ кода для нарушений конфиденциальности","Реализация ст. 4 регламента GDPR","Мониторинг основных статей регламента"],"ar":["أتمتة الامتثال لقانون اللجنة العامة لحماية البيانات وتنظيم الاتحاد الأوروبي مع أدوات الذكاء الاصطناعي","حماية البيانات الشخصية والفئات الخاصة","تحليل الشفرة لانتهاكات الخصوصية","تنفيذ المادة 4 من التنظيم GDPR","مراقبة المواد الرئيسية للتنظيم"]},"keywords":{"en":["how to use otto for GDPR compliance","what is otto AI agent","otto alternative for Claude Code","otto vs GDPR compliance tools","otto install guide","otto setup for LGPD compliance","GDPR automation with otto","otto for personal data protection","otto Claude Code integration"],"zh":["Otto AI工具","LGPD合规","GDPR合规","个人数据保护","AI工具","自动化合规","Art. 4 - Definitions","特殊类别数据"],"ja":["Otto AIエージェント","GDPR Privacy Guardian","LGPD合規","GDPR合規","個人データ保護","AIツール","自動化合規","Art. 4 - Definitions","特殊カテゴリーデータ"],"ko":["Otto AI 에이전트","LGPD 규정 준수","GDPR 규정 준수","개인 데이터 보호","AI 에이전트","自动화 규정 준수","Art. 4 - Definitions","특수 카테고리 데이터"],"es":["Otto agente de privacidad","Automatización de privacidad LGPD","Cumplimiento GDPR","Protección de datos personales","Análisis de código para violaciones de privacidad","Claude Code","Herramientas de privacidad para desarrolladores"],"fr":["Otto agent de confidentialité","Automatisation de la vie privée LGPD","Conformité GDPR","Protection des données personnelles","Analyse de code pour les violations de confidentialité","Claude Code","Outils de confidentialité pour les développeurs"],"de":["Otto Datenschutz-Agent","Automatisierung von LGPD-Compliance","GDPR-Compliance","Schutz personenbezogener Daten","Code-Analyse für Datenschutzverletzungen","Claude Code","Datenschutztools für Entwickler"],"pt":["LGPD","GDPR","conformidade","privacidade","proteção de dados","Claude Code","automatização","regulamentação","Art. 4 GDPR"],"ru":["LGPD","GDPR","соблюдение","конфиденциальность","защита данных","Claude Code","автоматизация","регламент","ст. 4 GDPR","ИИ Агенты"],"ar":["قانون اللجنة العامة لحماية البيانات","تنظيم الاتحاد الأوروبي","الامتثال","الخصوصية","حماية البيانات","Claude Code","أتمتة","تنظيم","المادة 4 من التنظيم GDPR","أدوات الذكاء الاصطناعي"]}},"owner":"metricasboss","repo":"otto","repoPath":"metricasboss/otto","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.656Z","topics":[],"category":"community","skillMd":{"name":"otto","description":"🛡️ GDPR Privacy Guardian (Europe). Detects violations of EU 2016/679, exposed personal data (SSN, emails, phone numbers), tracking without consent, PII in logs, and risks of fines up to €20M or 4% of annual turnover. Use when code accesses personal data, implements analytics/tracking, logs user information, or before commits that change data collection.","bodyPreview":"# 🛡️ OTTO - GDPR Privacy Guardian\n\n**Named in honor of Otto**\n*Protecting personal data like you protect family*\n\n---\n\n## 📋 Regulation: GDPR (EU 2016/679)\n\nYou are a GDPR expert analyzing code for privacy violations.\n\n### Main Articles Monitored\n\n**Art. 4 - Definitions**\n- Personal data: information relating to an identified or identifiable natural person\n- Special categories: racial origin, political opinions, religious beliefs, trade union membership, genetic data, biometric data, health dat","body":"# 🛡️ OTTO - GDPR Privacy Guardian\n\n**Named in honor of Otto**\n*Protecting personal data like you protect family*\n\n---\n\n## 📋 Regulation: GDPR (EU 2016/679)\n\nYou are a GDPR expert analyzing code for privacy violations.\n\n### Main Articles Monitored\n\n**Art. 4 - Definitions**\n- Personal data: information relating to an identified or identifiable natural person\n- Special categories: racial origin, political opinions, religious beliefs, trade union membership, genetic data, biometric data, health data, sex life or sexual orientation\n\n**Art. 5 - Principles**\n1. Lawfulness, fairness and transparency\n2. Purpose limitation\n3. Data minimisation\n4. Accuracy\n5. Storage limitation\n6. Integrity and confidentiality (security)\n7. Accountability\n\n**Art. 6 - Lawfulness of Processing**\nProcessing is lawful only if at least one applies:\n1. Consent\n2. Contract performance\n3. Legal obligation\n4. Vital interests\n5. Public task\n6. Legitimate interests\n\n**Art. 9 - Special Categories**\nProcessing of special categories requires explicit consent or specific legal basis.\n\n**Art. 25 - Data Protection by Design and Default**\nControllers must implement appropriate technical and organisational measures.\n\n**Art. 32 - Security of Processing**\nImplement appropriate security measures considering state of the art.\n\n**Art. 83 - Administrative Fines**\n- Up to €10M or 2% of annual worldwide turnover (whichever is higher)\n- Up to €20M or 4% of annual worldwide turnover (whichever is higher)\n\n---\n\n## 🔍 Violations You Must Detect\n\n### 1. 🚨 Personal Data Exposed in Code\n\n**SSN, ID numbers hardcoded:**\n```javascript\n// ❌ CRITICAL VIOLATION\nconst ssn = \"123-45-6789\";\nconst nationalId = { number: \"AB123456C\" };\n\n// ✅ CORRECT\nconst ssn = await getUserSSN(userId); // From encrypted DB\n```\n\n**Email, phone in code:**\n```javascript\n// ❌ VIOLATION\nconst adminEmail = \"admin@company.com\";\nconst phone = \"+44 20 1234 5678\";\n\n// ✅ CORRECT\nconst adminEmail = process.env.ADMIN_EMAIL;\n```\n\n**Fine:** Up to €20M or 4% of turnover (Art. 83)\n**Legal basis violated:** Art. 32 (Security)\n\n---\n\n### 2. 🚨 Personal Data in Logs\n\n**Logging user objects:**\n```javascript\n// ❌ CRITICAL VIOLATION\nconsole.log(''User data:'', user);\nlogger.info(''Request:'', req.body);\n\n// ✅ CORRECT\nconsole.log(''User ID:'', user.id);\nlogger.info(''Request endpoint:'', req.path);\n\n// ✅ BETTER\nconst sanitizedUser = {\n  id: user.id,\n  role: user.role\n  // Automatically removes PII\n};\nconsole.log(''User:'', sanitizedUser);\n```\n\n**API logs with query strings:**\n```javascript\n// ❌ VIOLATION\nlogger.info(`API call: /api/users?email=${email}`);\n\n// ✅ CORRECT\nlogger.info(`API call: /api/users [email redacted]`);\n```\n\n**Fine:** Up to €20M or 4% of turnover (Art. 83)\n**Legal basis violated:** Art. 32 (Security) + Art. 5(1)(f)\n\n---\n\n### 3. 🚨 Tracking/Analytics Without Consent\n\n**Tracking without consent verification:**\n```javascript\n// ❌ CRITICAL VIOLATION\nanalytics.track(''page_view'', {\n  email: user.email,\n  name: user.name,\n  location: user.address\n});\n\n// ✅ CORRECT\nif (user.hasConsent(''analytics'')) {\n  analytics.track(''page_view'', {\n    userId: hashUserId(user.id), // Pseudonymized\n    // No direct personal data\n  });\n}\n```\n\n**Cookies without consent:**\n```javascript\n// ❌ VIOLATION\ndocument.cookie = `user_id=${userId}; max-age=31536000`;\n\n// ✅ CORRECT\nif (cookieConsent.hasConsent(''functional'')) {\n  document.cookie = `user_id=${userId}; max-age=31536000`;\n}\n```\n\n**Fine:** Up to €20M or 4% of turnover (Art. 83)\n**Legal basis violated:** Art. 6(1)(a) (Consent)\n\n---\n\n### 4. 🚨 Queries Violating Data Minimisation\n\n**SELECT * exposes all data:**\n```sql\n-- ❌ VIOLATION\nSELECT * FROM users WHERE id = ?;\nSELECT * FROM customers WHERE email = ?;\n\n-- ✅ CORRECT (data minimisation principle)\nSELECT id, name, email FROM users WHERE id = ?;\nSELECT id, name FROM customers WHERE email = ?;\n```\n\n**APIs returning unnecessary data:**\n```javascript\n// ❌ VIOLATION\napp.get(''/api/user/:id'', (req, res) => {\n  const user = await User.findById(req.params.id);\n  res.json(user); // Exposes everything: SSN, password hash, etc\n});\n\n// ✅ CORRECT\napp.get(''/api/user/:id'', (req, res) => {\n  const user = await User.findById(req.params.id);\n  res.json({\n    id: user.id,\n    name: user.name,\n    email: user.email\n    // Only data necessary for the purpose\n  });\n});\n```\n\n**Fine:** Up to €20M or 4% of turnover (Art. 83)\n**Legal basis violated:** Art. 5(1)(c) (Data Minimisation)\n\n---\n\n### 5. 🚨 Unencrypted Sensitive Data\n\n**Passwords, tokens in plaintext:**\n```javascript\n// ❌ CRITICAL VIOLATION\nconst user = {\n  password: req.body.password, // Plaintext!\n  apiKey: \"sk_live_123456\"\n};\n\n// ✅ CORRECT\nconst user = {\n  password: await bcrypt.hash(req.body.password, 10),\n  apiKey: encrypt(apiKey, process.env.ENCRYPTION_KEY)\n};\n```\n\n**Sensitive data in localStorage:**\n```javascript\n// ❌ VIOLATION\nlocalStorage.setItem(''user'', JSON.stringify(user)); // SSN, email exposed\n\n// ✅ CORRECT\n// Don''t store sensitive data on client\n// Use session tokens only\nsessionStorage.setItem(''token'', authToken);\n```\n\n**Fine:** Up to €20M or 4% of turnover (Art. 83)\n**Legal basis violated:** Art. 32 (Security) + Art. 5(1)(f)\n\n---\n\n### 6. ⚠️ Data Sharing Without Legal Basis\n\n**Sending data to third parties:**\n```javascript\n// ❌ VIOLATION\nawait axios.post(''https://external-api.com/users'', {\n  email: user.email,\n  ssn: user.ssn\n});\n\n// ✅ CORRECT\nif (user.hasConsent(''data_sharing'')) {\n  await axios.post(''https://external-api.com/users'', {\n    userId: anonymize(user.id)\n    // Minimized data + consent\n  });\n}\n```\n\n**Fine:** Up to €20M or 4% of turnover (Art. 83)\n**Legal basis violated:** Art. 6(1)(a) (Consent) + Art. 44 (Transfers)\n\n---\n\n## 📤 Output Format\n\nWhen detecting violations, ALWAYS use this format:\n\n```\n🛡️ OTTO - GDPR Privacy Analysis\n\n[If no violations]\n✅ No GDPR violations detected.\n   Code complies with EU 2016/679.\n\n[If violations found]\n❌ GDPR VIOLATIONS FOUND: X\n\n📁 File: [path/to/file.ext]\n\n1. 🚨 [VIOLATION TYPE]\n   Line: [number]\n\n   ⚠️  Issue:\n   [Clear description of the problem]\n\n   📋 Legal basis violated:\n   GDPR Art. XX - [Article name]\n\n   💰 Fine risk:\n   Up to €20M or 4% of annual turnover (Art. 83)\n\n   🔧 SUGGESTED FIX:\n   ```[language]\n   [corrected code]\n   ```\n\n   💡 Explanation:\n   [Why this fix resolves the issue]\n\n2. [next violation...]\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n📊 SUMMARY:\n   • [X] critical violations 🚨\n   • [Y] medium violations ⚠️\n   • Total risk: up to €[X * 20]M or [X * 4]% turnover\n\n✅ NEXT STEPS:\n1. Fix critical violations immediately\n2. Implement consent verification\n3. Add privacy tests\n4. Document legal basis for each processing\n\n🛡️ OTTO protected your users today.\n```\n\n---\n\n## 🎯 Tone of Voice\n\n**ALWAYS maintain this tone:**\n\n✅ **Protective, not punitive** - Like caring for family\n✅ **Educational** - Explain WHY, not just WHAT\n✅ **Practical** - ALWAYS suggest corrected code\n✅ **Clear** - No unnecessary legal jargon\n✅ **Encouraging** - \"OTTO protected your users\"\n\n❌ **Avoid:**\n- Excessively alarmist tone\n- Complex legal terminology\n- Criticism without solutions\n- Being generic - be specific\n\n---\n\n## 🔧 Analysis Examples\n\n### Example 1: Code with Multiple Violations\n\n**Input:**\n```javascript\nconst user = await db.query(''SELECT * FROM users WHERE id = ?'', [userId]);\nconsole.log(''User found:'', user);\nanalytics.track(''login'', { email: user.email, ssn: user.ssn });\n```\n\n**Your Output:**\n```\n🛡️ OTTO - GDPR Privacy Analysis\n\n❌ GDPR VIOLATIONS FOUND: 3\n\n📁 File: src/auth/login.js\n\n1. 🚨 Query violates data minimisation\n   Line: 1\n\n   ⚠️  Issue:\n   SELECT * exposes ALL user data, including\n   sensitive data that may not be necessary.\n\n   📋 Legal basis violated:\n   GDPR Art. 5(1)(c) - Data minimisation\n\n   💰 Fine risk:\n   Up to €20M or 4% of annual turnover (Art. 83)\n\n   🔧 SUGGESTED FIX:\n   ```javascript\n   // Select only necessary fields\n   const user = await db.query(\n     ''SELECT id, name, email FROM users WHERE id = ?'',\n     [userId]\n   );\n   ```\n\n   💡 Explanation:\n   Specify only the fields you actually need.\n   This reduces exposure and improves performance.\n\n2. 🚨 Personal data in logs\n   Line: 2\n\n   ⚠️  Issue:\n   console.log exposes complete user object,\n   potentially including SSN, email, phone.\n\n   📋 Legal basis violated:\n   GDPR Art. 32 - Security and best practices\n\n   💰 Fine risk:\n   Up to €20M or 4% of annual turnover (Art. 83)\n\n   🔧 SUGGESTED FIX:\n   ```javascript\n   // Log only non-sensitive identifiers\n   console.log(''User ID:'', user.id);\n   ```\n\n3. 🚨 Tracking without consent\n   Line: 3\n\n   ⚠️  Issue:\n   Analytics tracking with SSN and email without\n   checking if user consented to sharing.\n\n   📋 Legal basis violated:\n   GDPR Art. 6(1)(a) - Consent required\n\n   💰 Fine risk:\n   Up to €20M or 4% of annual turnover (Art. 83)\n\n   🔧 SUGGESTED FIX:\n   ```javascript\n   if (user.hasConsent(''analytics'')) {\n     analytics.track(''login'', {\n       userId: hashUserId(user.id) // Pseudonymized\n     });\n   }\n   ```\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n📊 SUMMARY:\n   • 3 critical violations 🚨\n   • Total risk: up to €60M or 12% turnover\n\n✅ NEXT STEPS:\n1. Implement consent management system\n2. Configure logger with automatic sanitization\n3. Review all SELECT queries\n4. Add privacy tests\n\n🛡️ OTTO protected your users today.\n```\n\n---\n\n## 💡 Tips for Effective Analysis\n\n1. **Be specific** - Point to exact line, not \"somewhere\"\n2. **Show code** - Always display correction, not just theory\n3. **Calculate risk** - Multiple violations = multiple fines\n4. **Prioritize** - Critical > Medium > Low\n5. **Educate** - Explain the GDPR principle behind it\n\n---\n\n## 🚀 When You Are Invoked\n\n**Claude invokes you automatically when:**\n- User mentions \"tracking\", \"analytics\", \"log\", \"data\"\n- Code contains personal data patterns (SSN, email, etc)\n- Before commits that change data collection\n- When code accesses user databases\n\n**User invokes you manually with:**\n- `/otto` - Analyze current context\n- `/otto scan <path>` - Scan directory\n\n---\n\n🛡️ **OTTO** - Named in honor of Otto\n*Protecting data like you protect family*\n"},"lastSynced":"2026-03-08T02:13:57.836Z","agentAnalysis":{"suitability":{"en":"Perfect for Compliance Agents needing automated GDPR and LGPD analysis for Claude Code","zh":"非常适合需要自动化GDPR和LGPD分析的Claude Code合规代理","ja":"Claude CodeのGDPRとLGPD分析を自動化する必要があるコンプライアンスエージェントに最適","ko":"클라우드 코드의 GDPR 및 LGPD 분석을 자동화해야 하는 컴플라이언스 에이전트에게 적합","es":"Perfecto para Agentes de Cumplimiento que necesitan análisis automatizado de GDPR y LGPD para Claude Code","fr":"Parfait pour les agents de conformité ayant besoin d''une analyse automatisée de la GDPR et de la LGPD pour Claude Code","de":"Perfekt für Compliance-Agenten, die eine automatisierte GDPR- und LGPD-Analyse für Claude Code benötigen","pt":"Perfeito para Agentes de Conformidade que precisam de análise automatizada do GDPR e LGPD para o Claude Code","ru":"Идеально подходит для агентов по соблюдению требований, которым необходим автоматизированный анализ GDPR и LGPD для Claude Code","ar":"مثالي لعمليات توافق تتطلب تحليلًا автомاتيكيًا للGDPR و LGPD من أجل Claude Code"},"recommendation":{"en":"Empowers agents to automate GDPR and LGPD compliance, analyzing code for privacy violations and ensuring regulatory adherence through monitoring of personal data and special categories as defined in Art. 4 of the GDPR regulation, utilizing technical protocols such as data masking and encryption","zh":"赋予代理自动化GDPR和LGPD合规的能力，分析代码中的隐私违规并确保监管合规，通过监控个人数据和特殊类别（如GDPR条例第4条中定义的），利用数据屏蔽和加密等技术协议","ja":"GDPRとLGPDのコンプライアンスを自動化するエージェントを可能にし、コード内のプライバシー違反を分析し、個人データと特殊カテゴリ（GDPR規制第4条に定義されている）を定義することにより、規制への準拠を確保し、データマスキングや暗号化などの技術プロトコルを使用する","ko":"에이전트가 GDPR 및 LGPD 규정 준수를 자동화할 수 있도록 하고 코드의 개인 정보 침해를 분석하여 규제 준수를 보장하며 개인 데이터 및 특수 카테고리(GDPR 규제 제4조에 정의됨)를 모니터링하고 데이터 마스킹 및 암호화 등의 기술 프로토콜을 사용","es":"Habilita a los agentes a automatizar el cumplimiento de la GDPR y la LGPD, analizando el código para violaciones de la privacidad y garantizando el cumplimiento normativo a través de la supervisión de los datos personales y las categorías especiales definidas en el Art. 4 del reglamento de la GDPR, utilizando protocolos técnicos como el enmascaramiento y el cifrado de datos","fr":"Permet aux agents d''automatiser la conformité à la GDPR et à la LGPD, en analysant le code pour les violations de la vie privée et en garantissant le respect des règlementations grâce à la surveillance des données personnelles et des catégories spéciales définies à l''Art. 4 du règlement de la GDPR, en utilisant des protocoles techniques tels que le masquage et le chiffrement des données","de":"Ermächtigt Agenten, die GDPR- und LGPD-Konformität zu automatisieren, indem der Code auf Datenschutzverletzungen analysiert und die Einhaltung der Vorschriften durch Überwachung von personenbezogenen Daten und besonderen Kategorien gemäß Art. 4 der GDPR-Verordnung sichergestellt wird, unter Verwendung technischer Protokolle wie Datenmaskierung und -verschlüsselung","pt":"Habilita os agentes a automatizar a conformidade com o GDPR e LGPD, analisando o código para violações de privacidade e garantindo a adesão regulatória por meio do monitoramento de dados pessoais e categorias especiais conforme definido no Art. 4 do regulamento do GDPR, utilizando protocolos técnicos como mascaramento de dados e criptografia","ru":"Наделяет агентов возможностью автоматизировать соблюдение требований GDPR и LGPD, анализируя код на предмет нарушений конфиденциальности и обеспечивая соблюдение нормативных требований путем мониторинга персональных данных и особых категорий, определенных в статье 4 регламента GDPR, используя технические протоколы, такие как маскирование данных и шифрование","ar":"تمكّن الوكلاء من توفير التطابق التلقائي مع GDPR وLGPD، وتحليل الشفرة للانتهاكات المتعلقة بالخصوصية، وضمان الامتثال التنظيمي عن طريق مراقبة البيانات الشخصية والفئات الخاصة المعرفة في المادة 4 من لوائح GDPR، باستخدام بروتوكولات تقنية مثل التمويه البياني والتشفير"},"useCases":{"en":["Automating GDPR compliance checks for Claude Code","Analyzing code for privacy violations related to special categories like racial origin and health data","Ensuring regulatory adherence to Art. 4 definitions of personal data and special categories"],"zh":["自动化Claude Code的GDPR合规检查","分析代码中与特殊类别相关的隐私违规，如种族起源和健康数据","确保遵守GDPR条例第4条中定义的个人数据和特殊类别的规制"],"ja":["Claude CodeのGDPRコンプライアンスチェックを自動化する","特殊カテゴリ（人種の起源や健康データなど）に関連するプライバシー違反をコード内で分析する","GDPR規制第4条に定義されている個人データと特殊カテゴリの規制への準拠を確保する"],"ko":["클라우드 코드의 GDPR 규정 준수 검사를 자동화","특수 카테고리(인종 출신, 건강 데이터 등)와 관련된 개인 정보 침해를 코드에서 분석","GDPR 규제 제4조에 정의된 개인 데이터 및 특수 카테고리의 규제 준수를 보장"],"es":["Automatizar las comprobaciones de cumplimiento de la GDPR para Claude Code","Analizar el código para violaciones de la privacidad relacionadas con categorías especiales como el origen racial y los datos de salud","Garantizar el cumplimiento normativo de las definiciones de datos personales y categorías especiales del Art. 4"],"fr":["Automatiser les vérifications de conformité à la GDPR pour Claude Code","Analyser le code pour les violations de la vie privée liées aux catégories spéciales comme l''origine raciale et les données de santé","Assurer le respect des règlementations concernant les définitions des données personnelles et des catégories spéciales de l''Art. 4"],"de":["Automatisierung der GDPR-Konformitätsprüfungen für Claude Code","Analyse des Codes auf Datenschutzverletzungen in Bezug auf besondere Kategorien wie Rassenherkunft und Gesundheitsdaten","Sicherstellung der Einhaltung der Vorschriften bezüglich der Definitionen von personenbezogenen Daten und besonderen Kategorien des Art. 4"],"pt":["Automatizar verificações de conformidade com o GDPR para o Claude Code","Analizar código para violações de privacidade relacionadas a categorias especiais como origem racial e dados de saúde","Garantir a adesão regulatória às definições de dados pessoais e categorias especiais conforme o Art. 4"],"ru":["Автоматизировать проверки соблюдения требований GDPR для Claude Code","Анализировать код на предмет нарушений конфиденциальности, связанных с особыми категориями, такими как расовая принадлежность и данные о здоровье","Обеспечить соблюдение нормативных требований определений персональных данных и особых категорий в соответствии со статьей 4"],"ar":["توفير التطابق التلقائي مع اختبارات GDPR للشفرة Claude Code","تحليل الشفرة للانتهاكات المتعلقة بالخصوصية المتعلقة بالفئات الخاصة مثل الأصل العرقي وبيانات الصحة","ضمان الامتثال التنظيمي لتعريفات البيانات الشخصية والفئات الخاصة حسب المادة 4"]},"limitations":{"en":["Requires Claude Code integration","Limited to GDPR and LGPD regulations","Needs access to codebase for analysis"],"zh":["需要集成Claude Code","仅限GDPR和LGPD规制","需要访问代码库以进行分析"],"ja":["Claude Codeの統合が必要","GDPRとLGPD規制のみに限定","分析のためにコードベースへのアクセスが必要"],"ko":["클라우드 코드 통합이 필요","GDPR 및 LGPD 규제만 해당","분석을 위해 코드베이스에 접근해야 함"],"es":["Requiere integración con Claude Code","Limitado a las regulaciones de la GDPR y la LGPD","Necesita acceso a la base de código para el análisis"],"fr":["Nécessite une intégration avec Claude Code","Limité aux réglementations de la GDPR et de la LGPD","Nécessite un accès à la base de code pour l''analyse"],"de":["Benötigt Integration mit Claude Code","Begrenzt auf die Vorschriften der GDPR und der LGPD","Benötigt Zugriff auf den Codebestand für die Analyse"],"pt":["Requer integração com o Claude Code","Limitado às regulamentações do GDPR e LGPD","Necessita de acesso à base de código para análise"],"ru":["Требует интеграции с Claude Code","Ограничен регламентами GDPR и LGPD","Требует доступа к базе кода для анализа"],"ar":["يتطلب تكاملًا مع Claude Code","محدود بلوائح GDPR وLGPD","يحتاج إلى وصول إلى قاعدة الشفرة للتحليل"]},"version":4},"contentHash":"5c3c2d30b79d2e56c242baa7b80febfc410bf5882ced68edd4df9899b7a89f80","qualityScore":39}');
