INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('metricasboss/otto/otto', 'otto', 'metricasboss', 'otto', 'community', 'otto metricasboss otto community otto is a Privacy Guardian that automates GDPR and LGPD compliance for Claude Code, protecting personal data and special categories. It analyzes code for privacy violations, ensuring regulatory adherence. Otto AI工具提供LGPD和GDPR合规自动化，保护个人数据安全 Otto AIエージェントは、GDPR Privacy Guardianを使用して個人データを保護します Otto AI 에이전트는 LGPD와 GDPR 규정 준수를 자동화하여 개인 데이터를 보호합니다 Otto es un agente de privacidad que automatiza la cumplimiento de LGPD y GDPR para Claude Code, protegiendo datos personales como información relativa a personas identificadas o identificables Otto est un agent de confidentialité qui automatise la conformité LGPD et GDPR pour Claude Code, protégeant les données personnelles comme les informations relatives à des personnes identifiées ou identifiables Otto ist ein Datenschutz-Agent, der die Einhaltung von LGPD- und GDPR-Vorschriften für Claude Code automatisiert und personenbezogene Daten wie Informationen über identifizierte oder identifizierbare Personen schützt O Otto é um guardião de privacidade que automatiza a conformidade com a LGPD e o GDPR para o Claude Code, protegendo dados pessoais. Отто - это защитник конфиденциальности, который автоматизирует соблюдение LGPD и GDPR для Claude Code, защищая личные данные с помощью ИИ Агентов أوتو هو حارس خصوصية يأتمة الامتثال لقانون اللجنة العامة لحماية البيانات وتنظيم الاتحاد الأوروبي ل Claude Code وأدوات الذكاء الاصطناعي، يحمي البيانات الشخصية how to use otto for GDPR compliance what is otto AI agent otto alternative for Claude Code otto vs GDPR compliance tools otto install guide otto setup for LGPD compliance GDPR automation with otto otto for personal data protection otto Claude Code integration Otto AI工具 LGPD合规 GDPR合规 个人数据保护 AI工具 自动化合规 Art. 4 - Definitions 特殊类别数据 Monitors Art. 4 - Definitions for personal data and special categories Analyzes code for privacy violations according to GDPR (EU 2016/679) Protects special categories like racial origin, political opinions, and health data Automates LGPD and GDPR compliance for Claude Code Ensures regulatory adherence for personal data protection otto is a GDPR Privacy Guardian that automates compliance for Claude Code, protecting personal data and special categories like racial origin and health data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RedWilly/Anima/anima', 'community', 'RedWilly', 'Anima', 'RedWilly/Anima', 'anima', 0, 0, 39, '2026-03-08T01:57:15.656Z', '2026-03-08T02:13:58.006Z', 'ee1ed0886cab0db256e77578267c2c38fb1bb9cd14425768b3808f798c0c4a98', '{"id":"RedWilly/Anima/anima","name":"anima","description":{"en":"anima is a TypeScript animation engine for creating precise, structured animations. It benefits developers who need to generate clean visual output for mathematical visualizations.","zh":"Anima是一种TypeScript动画引擎，用于创建精确的数学可视化。它支持Bun和Node.js，并可以直接在浏览器中运行","ja":"AnimaはTypeScriptで作られたアニメーションエンジンで、数学的可視化を作成するために使用されます","ko":"Anima는 TypeScript로 작성된 애니메이션 엔진으로 수학적 시각화를 생성하는 데 사용됩니다","es":"Anima es un motor de animación de TypeScript para visualizaciones matemáticas, compatible con Bun y Node.js. Ofrece una salida visual limpia y precisa","fr":"Anima est un moteur d''animation TypeScript pour les visualisations mathématiques, compatible avec Bun et Node.js. Il offre une sortie visuelle propre et précise","de":"Anima ist ein TypeScript-Animation-Motor für mathematische Visualisierungen, kompatibel mit Bun und Node.js. Es bietet eine saubere und präzise visuelle Ausgabe","pt":"O Anima é um motor de animação TypeScript para visualizações matemáticas, permitindo a criação de animações precisas e estruturadas","ru":"Anima - это движок анимации на TypeScript для математических визуализаций, позволяющий создавать точные и структурированные анимации для ИИ Агентов","ar":"أنيما هو محرك أنماط TypeScript للتصورات الرياضية، يسمح بإنشاء أنماط دقيقة ومنظمة للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"anima: TypeScript Animation Engine Setup Guide | AI Agent...","zh":"Anima Animation Engine Setup Guide","ja":"Anima アニメーションエンジンのベストプラクティス","ko":"Anima 애니메이션 엔진 사용법","es":"Guía de configuración de Anima: Motor de animación de Typ...","fr":"Guide de mise en route d''Anima: Moteur d''animation TypeSc...","de":"Anima-Setup-Leitfaden: TypeScript-Animation-Motor","pt":"Guia de Configuração do Anima: Motor de Animação TypeScript","ru":"Настройка Anima: Инструмент анимации на TypeScript для ИИ...","ar":"دليل إعداد أنيما: محرك أنماط TypeScript للوكلاء الذكاء ال..."},"description":{"en":"Unlock precise animations with anima, a TypeScript engine for mathematical visualizations. Learn how to get started with anima and create stunning visuals to...","zh":"使用Anima TypeScript动画引擎创建精确的数学可视化，支持Bun和Node.js","ja":"Anima AIエージェントを使用して数学的可視化を作成する","ko":"Anima 애니메이션 엔진을 사용하여 정교한 수학 시각화를 생성하세요","es":"Aprende a utilizar Anima, un motor de animación de TypeScript para visualizaciones matemáticas, compatible con Bun y Node.js","fr":"Découvrez Anima, un moteur d''animation TypeScript pour les visualisations mathématiques, compatible avec Bun et Node.js","de":"Erfahren Sie, wie Sie Anima verwenden, einen TypeScript-Animation-Motor für mathematische Visualisierungen, kompatibel mit Bun und Node.js","pt":"Aprenda a usar o Anima, um motor de animação TypeScript para visualizações matemáticas, com suporte a Bun e Node.js","ru":"Узнайте, как использовать Anima, движок анимации на TypeScript для математических визуализаций, с поддержкой Bun и Node.js для ИИ Агентов","ar":"تعرف على كيفية استخدام أنيما، محرك أنماط TypeScript للتصورات الرياضية، مع دعم Bun و Node.js للوكلاء الذكاء الاصطناعي"},"definition":{"en":"anima is a TypeScript animation engine built for precise, structured animations with clean visual output, running on Bun or Node.js, or directly in the browser.","zh":"Anima是一种用于创建精确数学可视化的TypeScript动画引擎","ja":"Animaは数学的可視化を作成するためのTypeScriptアニメーションエンジンです","ko":"Anima는 정교한 수학 시각화를 생성하는 TypeScript 애니메이션 엔진입니다","es":"Anima es un motor de animación de TypeScript para visualizaciones matemáticas","fr":"Anima est un moteur d''animation TypeScript pour les visualisations mathématiques","de":"Anima ist ein TypeScript-Animation-Motor für mathematische Visualisierungen","pt":"O Anima é um motor de animação TypeScript para visualizações matemáticas","ru":"Anima - это движок анимации на TypeScript для математических визуализаций","ar":"أنيما هو محرك أنماط TypeScript للتصورات الرياضية"},"features":{"en":["Imports everything from ''anima'' package index","Supports rendering to canvas with Bun","Exports classes, animations, and easing functions","Allows customization of scene properties like width, height, and frameRate","Includes easing functions like easeInOutQuad","Extends Scene class for custom animation creation"],"zh":["支持Bun和Node.js","直接在浏览器中运行","使用TypeScript编写","提供精确的数学可视化","支持easeInOutQuad缓动函数","可以创建自定义场景和动画"],"ja":["BunとNode.jsをサポート","ブラウザで直接実行","TypeScriptで書かれています","正確な数学的可視化を提供","easeInOutQuadイージング関数をサポート","カスタムシーンとアニメーションを作成できます"],"ko":["Bun과 Node.js를 지원","브라우저에서 직접 실행","TypeScript로 작성됨","정확한 수학적 시각화를 제공","easeInOutQuad 이징 함수를 지원","사용자 정의 장면과 애니메이션을 생성할 수 있음"],"es":["Compatibilidad con Bun y Node.js","Salida visual limpia y precisa","Ejecución directa en el navegador","Soporte para canvas","Easing functions personalizables"],"fr":["Compatibilité avec Bun et Node.js","Sortie visuelle propre et précise","Exécution directe dans le navigateur","Prise en charge de canvas","Fonctions d''easing personnalisables"],"de":["Kompatibilität mit Bun und Node.js","Saubere und präzise visuelle Ausgabe","Direkte Ausführung im Browser","Unterstützung für canvas","Anpassbare Easing-Funktionen"],"pt":["Suporte a Bun e Node.js","Renderização para canvas","Criação de animações precisas e estruturadas","Importação de classes, animações e funções de easing","Suporte a TypeScript"],"ru":["Поддержка Bun и Node.js","Рендеринг в canvas","Создание точных и структурированных анимаций","Импорт классов, анимаций и функций easing","Поддержка TypeScript для ИИ Агентов"],"ar":["دعم Bun و Node.js","إخراج إلى.canvas","إنشاء أنماط دقيقة ومنظمة","استيراد الفئات والأنماط والوظائف المتدرجة","دعم TypeScript للوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use anima","anima alternative","anima install","anima setup guide","what is anima","anima vs manim","typescript animation engine","mathematical visualization tools","bun animation"],"zh":["Anima动画引擎","TypeScript动画","数学可视化","Bun支持","Node.js支持","浏览器动画","easeInOutQuad缓动函数","AIエージェント","アニメーションエンジン"],"ja":["Anima AIエージェント","TypeScriptアニメーション","数学的可視化","Bunサポート","Node.jsサポート","ブラウザアニメーション","easeInOutQuadイージング関数","AIエージェント","アニメーションエンジン"],"ko":["Anima 애니메이션 엔진","TypeScript 애니메이션","수학적 시각화","Bun 지원","Node.js 지원","브라우저 애니메이션","easeInOutQuad 이징 함수","AI 에이전트","애니메이션 엔진"],"es":["Anima","motor de animación","TypeScript","visualizaciones matemáticas","Bun","Node.js","canvas","easing functions","animación en el navegador"],"fr":["Anima","moteur d''animation","TypeScript","visualisations mathématiques","Bun","Node.js","canvas","fonctions d''easing","animation dans le navigateur"],"de":["Anima","Animation-Motor","TypeScript","mathematische Visualisierungen","Bun","Node.js","canvas","Easing-Funktionen","Animation im Browser"],"pt":["anima","motor de animação","TypeScript","visualizações matemáticas","Bun","Node.js","canvas","animação precisa","estrutura de animação"],"ru":["Anima","движок анимации","TypeScript","математические визуализации","Bun","Node.js","canvas","точная анимация","структура анимации для ИИ Агентов"],"ar":["أنيما","محرك أنماط","TypeScript","التصورات الرياضية","Bun","Node.js","canvas","أنماط دقيقة","هيكل أنماط للوكلاء الذكاء الاصطناعي"]}},"owner":"RedWilly","repo":"Anima","repoPath":"RedWilly/Anima","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.656Z","topics":[],"category":"community","skillMd":{"name":"anima","description":"Summarizes how to use the Anima animation engine (Scene, Mobjects, Fluent API, Pro API, camera, timeline, rendering, and CLI). Use when authoring or explaining Anima animations.","bodyPreview":"# Using the Anima Engine\n\nAnima is a TypeScript animation engine for mathematical visualizations. It runs on Bun and renders to canvas.\n\nImport everything from `''anima''` (the package index). All classes, animations, and easing functions are exported from there.\n\n## Quick Start\n\n```ts\nimport { Scene, Circle, Rectangle, Color, easeInOutQuad } from ''anima'';\n\nexport class MyScene extends Scene {\n  constructor() {\n    super({ width: 1920, height: 1080, frameRate: 60, backgroundColor: Color.BLACK });","body":"# Using the Anima Engine\n\nAnima is a TypeScript animation engine for mathematical visualizations. It runs on Bun and renders to canvas.\n\nImport everything from `''anima''` (the package index). All classes, animations, and easing functions are exported from there.\n\n## Quick Start\n\n```ts\nimport { Scene, Circle, Rectangle, Color, easeInOutQuad } from ''anima'';\n\nexport class MyScene extends Scene {\n  constructor() {\n    super({ width: 1920, height: 1080, frameRate: 60, backgroundColor: Color.BLACK });\n\n    const circle = new Circle(1).stroke(Color.WHITE, 2).pos(-2, 0); // radius 1, at position (-2, 0)\n    const rect = new Rectangle(2, 1).fill(Color.BLUE, 0.6).pos(2, 0); // 2×1, at position (2, 0)\n\n    // Items in the same play() call run in PARALLEL\n    this.play(\n      circle.fadeIn(1).moveTo(0, 0, 1), // fadeIn 1s, then move to (x=0, y=0) over 1s\n      rect.fadeIn(1)                     // fadeIn 1s (runs in parallel with circle''s chain)\n    );\n\n    this.wait(0.5); // 0.5 second pause\n\n    // Successive play() calls run SEQUENTIALLY\n    this.play(circle.fadeOut(0.5)); // fadeOut over 0.5s\n  }\n}\n```\n\nRender with CLI: `anima render myfile.ts -s MyScene -o output.mp4`\n\n## Coordinate System\n\nOrigin `(0, 0)` is screen center. Y-axis points **up**. Visible frame is ~14.2 × 8 world units at 1920×1080.\n\n## Skill Modules\n\nFor detailed usage of each subsystem, read the relevant module:\n\n| Module | What it covers |\n|---|---|\n| [Scene](rules/scene.md) | Scene setup, config, coordinate system, `play()`, `wait()`, `add()`/`remove()`, lifecycle rules |\n| [Mobjects](rules/mobjects.md) | Mobject/VMobject hierarchy, immediate setters (`pos`, `show`, `hide`, `setScale`, `setRotation`), `saveState()`/`restore()` |\n| [Geometry](rules/geometry.md) | `Circle`, `Rectangle`, `Line`, `Arrow`, `Arc`, `Polygon`, `Point` — constructors and usage |\n| [Styling](rules/styling.md) | `Color` class (presets, `fromHex`, `fromHSL`), `.stroke()`, `.fill()`, default appearance rules |\n| [Animations](rules/animations.md) | Fluent API (chaining), Pro API (explicit objects), `Sequence`, `Parallel`, `MorphTo`, `delay()`, hybrid usage |\n| [Easing](rules/easing.md) | All 30+ easing functions: standard, bounce, Manim-style rate functions, choosing guide |\n| [Camera](rules/camera.md) | `CameraFrame` animations (`zoomIn`, `zoomOut`, `centerOn`, `fitTo`, `zoomToPoint`), `Shake`, `Follow`, bounds, instant methods |\n| [Text](rules/text.md) | `Text` creation from font files, `TextStyle`, glyph access, animating text |\n| [Graph](rules/graph.md) | `Graph` nodes/edges, layout algorithms (`circular`, `tree`, `force-directed`), `updateEdges()` |\n| [VGroup](rules/vgroup.md) | `VGroup` children management, `arrange()`, `center()`, `toCorner()`, `alignTo()`, cascading styles |\n| [Keyframes](rules/keyframes.md) | `KeyframeAnimation`, `KeyframeTrack` — fine-grained multi-property keyframe control |\n| [Rendering](rules/rendering.md) | `Renderer`, formats (mp4/webp/gif/sprite/png), `Resolution` presets, quality, CLI commands, `serialize`/`deserialize` |\n\n## Core Rules for Authoring Scenes\n\n1. **Extend `Scene`** and build everything in the constructor.\n2. **Intro animations** (`fadeIn`, `write`, `draw`, `FadeIn`, `Write`, `Draw`) auto-add objects to the scene.\n3. **Transform/exit animations** (`moveTo`, `rotate`, `scaleTo`, `fadeOut`, etc.) require the target to already be in the scene.\n4. Use `this.add(obj)` for static objects that should be visible without animation.\n5. All durations are in **seconds**.\n6. All angles are in **radians**.\n7. Multiple items in one `this.play(...)` call run in **parallel**. Successive `play()` calls run **sequentially**.\n8. Use `this.wait(seconds)` to insert gaps between play calls.\n\n## Long Video Tips\n\nFor 30–50 minute videos:\n\n- **Structure in sections**: Group related animations with `this.wait()` between logical sections.\n- **Use `saveState()` / `restore()`**: Save object positions before zooming in, restore to return.\n- **Camera management**: Use `centerOn`, `fitTo`, and `zoomIn`/`zoomOut` to guide the viewer''s focus.\n- **Reuse objects**: `remove()` objects when done, `add()` new ones. Don''t leave hundreds of invisible objects in the scene.\n- **Use `Sequence` and `Parallel`**: For complex choreography, compose explicitly rather than deeply nesting fluent chains.\n- **Keyframes**: For complex motion paths, use `KeyframeAnimation` instead of chaining dozens of `moveTo` calls.\n- **Preview quality**: Use `quality: ''preview''` or the CLI `preview` command during iteration, switch to `production` for final render.\n"},"lastSynced":"2026-03-08T02:13:58.006Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing precise, structured animations for mathematical visualizations.","zh":"非常适合需要精确、结构化动画的数学可视化的前端代理。","ja":"数学の視覚化に正確で構造化されたアニメーションが必要なフロントエンドエージェントに最適です。","ko":"정확하고 구조화된 애니메이션을 필요로 하는 수학적 시각화 프론트엔드 에이전트에 적합합니다.","es":"Ideal para agentes Frontend que necesitan animaciones precisas y estructuradas para visualizaciones matemáticas.","fr":"Parfait pour les agents Frontend qui ont besoin d''animations précises et structurées pour des visualisations mathématiques.","de":"Perfekt für Frontend-Agents, die präzise, strukturierte Animationen für mathematische Visualisierungen benötigen.","pt":"Perfeito para Agentes Frontend que precisam de animações precisas e estruturadas para visualizações matemáticas.","ru":"Идеально подходит для агентов Фронтенда, которым необходимы точные, структурированные анимации для математических визуализаций.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى رسوم متحركة دقيقة ومنظمة للتصور الرياضي."},"recommendation":{"en":"Empowers agents to generate clean visual output using TypeScript and the canvas rendering engine, with features like easing functions such as easeInOutQuad and support for various shapes like Circle and Rectangle.","zh":"赋予代理使用TypeScript和canvas渲染引擎生成干净的视觉输出的能力，具有如easeInOutQuad的缓动函数和对Circle和Rectangle等各种形状的支持。","ja":"TypeScriptとcanvasレンダリングエンジンを使用して、easeInOutQuadなどのイージング関数やCircleとRectangleなどの様々な形状をサポートするクリーンな視覚出力を生成するためのエージェントの能力を強化します。","ko":"TypeScript와 canvas 렌더링 엔진을 사용하여 easeInOutQuad와 같은 이징 함수와 Circle 및 Rectangle와 같은 다양한 도형을 지원하는 깨끗한 시각적 출력을 생성하기 위한 에이전트의 능력을 강화합니다.","es":"Habilita a los agentes a generar una salida visual limpia utilizando TypeScript y el motor de renderizado de canvas, con características como funciones de suavizado como easeInOutQuad y soporte para varias formas como Circle y Rectangle.","fr":"Permet aux agents de générer une sortie visuelle propre en utilisant TypeScript et le moteur de rendu de canvas, avec des fonctionnalités comme des fonctions de lissage telles que easeInOutQuad et un support pour diverses formes comme Circle et Rectangle.","de":"Ermächtigt die Agenten, eine saubere visuelle Ausgabe mit TypeScript und dem Canvas-Rendering-Engine zu generieren, mit Funktionen wie Übertragungsfunktionen wie easeInOutQuad und Unterstützung für verschiedene Formen wie Circle und Rectangle.","pt":"Habilita os agentes a gerar saída visual limpa usando TypeScript e o mecanismo de renderização do canvas, com recursos como funções de suavização, como easeInOutQuad, e suporte a várias formas, como Circle e Rectangle.","ru":"Наделяет агентов возможностью генерировать чистый визуальный вывод с помощью TypeScript и движка рендеринга canvas, с функциями, такими как функции сглаживания, например easeInOutQuad, и поддержкой различных форм, таких как Circle и Rectangle.","ar":"يمكن الوكلاء من生成 مخرجات بصرية نظيفة باستخدام TypeScript و محرك تحرير Canvas، مع ميزات مثل دوال التخفيف مثل easeInOutQuad ودعم أشكال مختلفة مثل الدائرة والمستطيل."},"useCases":{"en":["Creating interactive mathematical visualizations","Generating animations for data-driven stories","Building precise, frame-rate controlled scenes"],"zh":["创建交互式数学可视化","生成数据驱动故事的动画","构建精确、帧率控制的场景"],"ja":["インタラクティブな数学の視覚化の作成","データドリブンのストーリーのアニメーション生成","正確でフレームレート制御のシーンの構築"],"ko":["상호작용 수학 시각화 생성","데이터 주도 스토리의 애니메이션 생성","정확하고 프레임 레이트 제어된 장면 구축"],"es":["Creación de visualizaciones matemáticas interactivas","Generación de animaciones para historias impulsadas por datos","Construcción de escenas precisas y controladas por velocidad de fotogramas"],"fr":["Création de visualisations mathématiques interactives","Génération d''animations pour des histoires basées sur des données","Conception de scènes précises et contrôlées par taux d''images"],"de":["Erstellung interaktiver mathematischer Visualisierungen","Generierung von Animationen für datengetriebene Geschichten","Aufbau präziser, frame-rate-kontrollierter Szenen"],"pt":["Criação de visualizações matemáticas interativas","Geração de animações para histórias impulsionadas por dados","Construção de cenas precisas, controladas por taxa de quadros"],"ru":["Создание интерактивных математических визуализаций","Генерация анимаций для историй, управляемых данными","Построение точных, контролируемых по кадрам сцен"],"ar":["إنشاء تصورات رياضية تفاعلية","إنتاج رسوم متحركة لروايات مدفوعة بالبيانات","بناء مشاهد دقيقة ومسيطرة على معدل الإطار"]},"limitations":{"en":["Requires TypeScript environment","Runs on Bun","Limited to canvas rendering"],"zh":["需要TypeScript环境","运行于Bun","仅限canvas渲染"],"ja":["TypeScript環境が必要","Bun上で実行","canvasレンダリングのみ"],"ko":["TypeScript 환경이 필요함","Bun에서 실행됨","canvas 렌더링만 지원"],"es":["Requiere entorno de TypeScript","Se ejecuta en Bun","Limitado al renderizado de canvas"],"fr":["Nécessite un environnement TypeScript","S''exécute sur Bun","Limité au rendu de canvas"],"de":["Benötigt eine TypeScript-Umgebung","Läuft auf Bun","Begrenzt auf Canvas-Rendering"],"pt":["Requer ambiente TypeScript","Executa no Bun","Limitado à renderização do canvas"],"ru":["Требует среды TypeScript","Запускается на Bun","Ограничен рендерингом canvas"],"ar":["يتطلب بيئة TypeScript","يعمل على Bun","محدود بتصيير Canvas"]},"version":4},"contentHash":"ee1ed0886cab0db256e77578267c2c38fb1bb9cd14425768b3808f798c0c4a98","qualityScore":39}');
