INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RedWilly/Anima/anima', 'anima', 'RedWilly', 'Anima', 'community', 'anima RedWilly Anima community anima is a TypeScript animation engine for creating precise, structured animations. It benefits developers who need to generate clean visual output for mathematical visualizations. Anima是一种TypeScript动画引擎，用于创建精确的数学可视化。它支持Bun和Node.js，并可以直接在浏览器中运行 AnimaはTypeScriptで作られたアニメーションエンジンで、数学的可視化を作成するために使用されます Anima는 TypeScript로 작성된 애니메이션 엔진으로 수학적 시각화를 생성하는 데 사용됩니다 Anima es un motor de animación de TypeScript para visualizaciones matemáticas, compatible con Bun y Node.js. Ofrece una salida visual limpia y precisa Anima est un moteur d''animation TypeScript pour les visualisations mathématiques, compatible avec Bun et Node.js. Il offre une sortie visuelle propre et précise Anima ist ein TypeScript-Animation-Motor für mathematische Visualisierungen, kompatibel mit Bun und Node.js. Es bietet eine saubere und präzise visuelle Ausgabe O Anima é um motor de animação TypeScript para visualizações matemáticas, permitindo a criação de animações precisas e estruturadas Anima - это движок анимации на TypeScript для математических визуализаций, позволяющий создавать точные и структурированные анимации для ИИ Агентов أنيما هو محرك أنماط TypeScript للتصورات الرياضية، يسمح بإنشاء أنماط دقيقة ومنظمة للوكلاء الذكاء الاصطناعي how to use anima anima alternative anima install anima setup guide what is anima anima vs manim typescript animation engine mathematical visualization tools bun animation Anima动画引擎 TypeScript动画 数学可视化 Bun支持 Node.js支持 浏览器动画 easeInOutQuad缓动函数 AIエージェント アニメーションエンジン Imports everything from ''anima'' package index Supports rendering to canvas with Bun Exports classes, animations, and easing functions Allows customization of scene properties like width, height, and frameRate Includes easing functions like easeInOutQuad Extends Scene class for custom animation creation anima is a TypeScript animation engine built for precise, structured animations with clean visual output, running on Bun or Node.js, or directly in the browser.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('totoroyyb/amag/external-researcher', 'community', 'totoroyyb', 'amag', 'totoroyyb/amag', 'external-researcher', 0, 0, 39, '2026-03-08T01:57:15.658Z', '2026-03-08T02:14:00.578Z', 'd9901c96e73452cf9409ee2e2b115890e672d4e5f956d1edd3c239d28bf0b1af', '{"id":"totoroyyb/amag/external-researcher","name":"external-researcher","description":{"en":"The External Researcher skill provides a protocol for finding authoritative external knowledge, benefiting developers working with unfamiliar libraries, frameworks, or tools. It surfaces concrete guidance from official docs and OSS examples.","zh":"External Researcher 协议用于找到权威的外部知识，通过搜索官方文档和 OSS 实现来提供具体的指导","ja":"External Researcher プロトコルは、公式ドキュメントと OSS の実装を検索して、具体的なガイダンスを提供するために使用されます","ko":"External Researcher 프로토콜은 외부 권위 지식을 찾는 데 사용되며 공식 문서와 OSS 구현을 검색하여 구체적인 가이드를 제공합니다","es":"El agente de investigación externa es un protocolo para encontrar conocimientos autorizados en fuentes externas, como documentos oficiales y ejemplos de código abierto","fr":"L''agent de recherche externe est un protocole pour trouver des connaissances autorisées dans des sources externes, telles que des documents officiels et des exemples de code open source","de":"Der externe Forscher-Agent ist ein Protokoll, um autorisierte Kenntnisse in externen Quellen wie offiziellen Dokumenten und Open-Source-Code-Beispielen zu finden","pt":"O External Researcher é um protocolo para encontrar conhecimento autoritário externo, ajudando desenvolvedores a encontrar documentação oficial e exemplos de OSS","ru":"ИИ Агент External Researcher - это протокол для поиска внешних авторитетных знаний, помогающий разработчикам найти официальную документацию и примеры OSS","ar":"ال_external Researcher هو بروتوكول لتحديد المعرفة الخارجية الموثوقة، يساعد المطورين على العثور على الوثائق الرسمية وأمثلة OSS"},"seo":{"title":{"en":"External Researcher: Protocol Setup Guide for AI Agents","zh":"External Researcher Setup Guide - AI工具","ja":"External Researcher ベストプラクティス - AIエージェント","ko":"External Researcher 구현 방법 - AI 에이전트","es":"Guía de configuración del agente de investigación externa...","fr":"Guide de configuration de l''agent de recherche externe po...","de":"Konfigurationsleitfaden für den externen Forscher-Agenten...","pt":"Guia de Configuração do External Researcher para Desenvol...","ru":"Настройка ИИ Агента External Researcher для разработчиков","ar":"دليل إعداد External Researcher للاستفادة من الأدوات الذكية"},"description":{"en":"Unlock authoritative external knowledge with External Researcher. Discover how to activate reference-finding mode and surface concrete guidance for unfamilia...","zh":"了解 External Researcher 的功能和用途，发现如何找到权威的外部知识和文档","ja":"External Researcher の機能と使い方を学び、公式ドキュメントと OSS の実装を探す方法を発見","ko":"External Researcher 의 기능과 사용 방법을 알아보고 공식 문서와 OSS 구현을 찾는 방법을 발견","es":"Descubre cómo utilizar el agente de investigación externa para encontrar conocimientos autorizados y mejorar tus proyectos de desarrollo con herramientas de ...","fr":"Découvrez comment utiliser l''agent de recherche externe pour trouver des connaissances autorisées et améliorer vos projets de développement avec des outils d...","de":"Erfahren Sie, wie Sie den externen Forscher-Agenten verwenden können, um autorisierte Kenntnisse zu finden und Ihre Entwicklungsprojekte mit erweiterten Such...","pt":"Aprenda a configurar o External Researcher para encontrar conhecimento autoritário externo e melhorar seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить ИИ Агента External Researcher для поиска внешних авторитетных знаний и улучшения рабочего процесса разработки","ar":"تعرف على كيفية إعداد External Researcher للاستفادة من المعرفة الخارجية الموثوقة وتحسين تدفق العمل التطويري"},"definition":{"en":"External Researcher is a protocol for finding authoritative external knowledge, enabling developers to shift into reference-finding mode and access concrete guidance.","zh":"External Researcher 是一种用于找到权威外部知识的协议","ja":"External Researcher は、権威のある外部知識を見つけるためのプロトコルです","ko":"External Researcher 는 외부 권위 지식을 찾는 데 사용되는 프로토콜입니다","es":"El agente de investigación externa es un protocolo que permite a los desarrolladores encontrar conocimientos autorizados en fuentes externas","fr":"L''agent de recherche externe est un protocole qui permet aux développeurs de trouver des connaissances autorisées dans des sources externes","de":"Der externe Forscher-Agent ist ein Protokoll, das es Entwicklern ermöglicht, autorisierte Kenntnisse in externen Quellen zu finden","pt":"O External Researcher é um protocolo de pesquisa que ajuda desenvolvedores a encontrar conhecimento autoritário externo","ru":"ИИ Агент External Researcher - это протокол поиска, помогающий разработчикам найти внешние авторитетные знания","ar":"ال_external Researcher هو بروتوكول بحث يساعد المطورين على العثور على المعرفة الخارجية الموثوقة"},"features":{"en":["Searches official documentation for authoritative knowledge","Finds production OSS examples to inform design decisions","Surfaces concrete guidance for unfamiliar libraries and frameworks","Activates reference-finding mode for specific external dependencies","Provides best practices for library decisions"],"zh":["支持搜索官方文档","能够找到生产环境中的 OSS 实现","提供具体的指导和最佳实践","适用于处理不熟悉的库、框架或工具","能够找到外部依赖的具体实现"],"ja":["公式ドキュメントの検索をサポート","生産環境での OSS 実装を探すことができる","具体的なガイダンスとベストプラクティスを提供","未経験のライブラリ、フレームワーク、またはツールの処理に適している","外部依存関係の具体的な実装を探すことができる"],"ko":["공식 문서의 검색을 지원","생산 환경에서의 OSS 구현을 찾을 수 있음","구체적인 가이드와 최선의 방법을 제공","미숙한 라이브러리, 프레임워크 또는 도구의 처리에 적합","외부 종속성의 구체적인 구현을 찾을 수 있음"],"es":["Búsqueda de documentos oficiales","Encontrar ejemplos de código abierto","Proporcionar orientación concreta para la toma de decisiones","Compatibilidad con bibliotecas y frameworks desconocidos","Integración con herramientas de desarrollo para mejorar la productividad"],"fr":["Recherche de documents officiels","Trouver des exemples de code open source","Fournir des conseils concrets pour la prise de décision","Compatibilité avec des bibliothèques et des frameworks inconnus","Intégration avec des outils de développement pour améliorer la productivité"],"de":["Suche nach offiziellen Dokumenten","Finden von Open-Source-Code-Beispielen","Bereitstellung von konkreten Richtlinien für die Entscheidungsfindung","Kompatibilität mit unbekannten Bibliotheken und Frameworks","Integration mit Entwicklungstools zur Steigerung der Produktivität"],"pt":["Pesquisa de documentação oficial","Encontrar exemplos de OSS para aprender","Identificar dependências externas específicas","Melhorar o fluxo de trabalho de desenvolvimento com orientação concreta"],"ru":["Поиск официальной документации","Найти примеры OSS для обучения","Определить конкретные внешние зависимости","Улучшить рабочий процесс разработки с помощью конкретных рекомендаций"],"ar":["بحث الوثائق الرسمية","العثور على أمثلة OSS للتعلم","تحديد الاعتماديات الخارجية المحددة","تحسين تدفق العمل التطويري بإرشادات ملموسة"]},"keywords":{"en":["how to use external researcher","what is external researcher","external researcher setup guide","external researcher alternative","external researcher vs research tools","external researcher install","external researcher for AI agents","authoritative external knowledge","reference finding mode"],"zh":["External Researcher","AI工具","外部知识","官方文档","OSS 实现","最佳实践","库框架工具","外部依赖"],"ja":["External Researcher","AIエージェント","外部知識","公式ドキュメント","OSS 実装","ベストプラクティス","ライブラリフレームワークツール","外部依存関係"],"ko":["External Researcher","AI 에이전트","외부 지식","공식 문서","OSS 구현","최선의 방법","라이브러리 프레임워크 도구","외부 종속성"],"es":["agente de investigación externa","desarrollo de software","herramientas de desarrollo","búsqueda de conocimientos","documentos oficiales","código abierto","bibliotecas y frameworks","productividad en el desarrollo"],"fr":["agent de recherche externe","développement de logiciels","outils de développement","recherche de connaissances","documents officiels","code open source","bibliothèques et frameworks","productivité dans le développement"],"de":["externer Forscher-Agent","Software-Entwicklung","Entwicklungstools","Suche nach Kenntnissen","offizielle Dokumente","Open-Source-Code","Bibliotheken und Frameworks","Produktivität in der Entwicklung"],"pt":["External Researcher","desenvolvimento de software","conhecimento autoritário","documentação oficial","exemplos de OSS","dependências externas","fluxo de trabalho de desenvolvimento"],"ru":["ИИ Агент External Researcher","разработка программного обеспечения","внешние авторитетные знания","официальная документация","примеры OSS","внешние зависимости","рабочий процесс разработки"],"ar":["ال_external Researcher","تطوير البرمجيات","المعرفة الخارجية الموثوقة","الوثائق الرسمية","أمثلة OSS","الاعتماديات الخارجية","تدفق العمل التطويري"]}},"owner":"totoroyyb","repo":"amag","repoPath":"totoroyyb/amag","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.658Z","topics":[],"category":"community","skillMd":{"name":"external-researcher","description":"External knowledge retrieval — official docs, OSS examples, and best practices via web search","bodyPreview":"# External Researcher\n\nProtocol for finding authoritative external knowledge. When activated, shift into reference-finding mode: search official docs, find production OSS examples, and surface concrete guidance — not tutorials, not blog posts.\n\n## When to Activate\n\n- Working with an unfamiliar library, framework, or tool\n- User mentions a specific external dependency\n- Best practices needed for a library decision\n- Finding OSS implementations to learn from before designing something\n- \"How do I","body":"# External Researcher\n\nProtocol for finding authoritative external knowledge. When activated, shift into reference-finding mode: search official docs, find production OSS examples, and surface concrete guidance — not tutorials, not blog posts.\n\n## When to Activate\n\n- Working with an unfamiliar library, framework, or tool\n- User mentions a specific external dependency\n- Best practices needed for a library decision\n- Finding OSS implementations to learn from before designing something\n- \"How do I use [library] correctly?\" or \"What does [framework feature] actually do?\"\n\n**Key trigger phrases:**\n- \"How do I use [library]?\"\n- \"What''s the best practice for [framework feature]?\"\n- \"Why does [external dependency] behave this way?\"\n- \"Find examples of [technology] usage\"\n- Working with an npm/pip/cargo package you haven''t used before\n\n**Loaded by:**\n- `/plan` Step 1 (Build from Scratch, Architecture, Research intents)\n- `/ultrawork` for unfamiliar technology\n- Default behavior when user mentions external library\n\n## Core Pattern\n\nAlways prefer in this order:\n1. **Official docs** — canonical API reference, config options, migration guides\n2. **Production OSS** (1000+ stars) — real implementations, not tutorials\n3. **Changelog/issues** — for gotchas, breaking changes, known bugs\n\nNever cite:\n- Personal blog posts as authoritative (as supplementary evidence only)\n- Tutorials as API reference\n- Stack Overflow as the primary source for library design decisions\n\n## Search Patterns\n\n### For Library/Framework Docs\n\n```\nsearch_web(\"{library} official documentation API reference\")\nsearch_web(\"{library} {specific feature} best practices\")\nread_url_content({official_docs_url})\n```\n\nFocus on:\n- API signatures with parameter types and defaults\n- Recommended usage patterns\n- Pitfalls and common mistakes sections\n- Version compatibility (check if docs match the version in use)\n\n### For Production OSS Examples\n\n```\nsearch_web(\"{feature} site:github.com stars:>1000\")\nsearch_web(\"{library} example implementation production\")\n```\n\nFocus on:\n- Architecture choices, not surface-level patterns\n- Edge case handling\n- Error strategies\n- What 2-3 quality implementations have in common (consensus pattern)\n\n### For Gotchas and Migration\n\n```\nsearch_web(\"{library} {version} breaking changes migration\")\nsearch_web(\"{library} common mistakes pitfalls\")\n```\n\nFocus on:\n- API changes between versions\n- Performance gotchas\n- Security considerations\n\n## Synthesis Format\n\n```\nSource: [URL — official docs / OSS / other]\nKey finding: [What to do / API signature / pattern]\nPitfall: [What to avoid]\nVersion note: [Any version-specific considerations]\nConfidence: HIGH (official docs) / MEDIUM (OSS pattern) / LOW (community)\n```\n\n## Quality Bar\n\n- Always verify the version of docs matches the project''s dependency version\n- When official docs and OSS patterns conflict — follow official docs, note the discrepancy\n- Production code (GitHub, verified OSS) > tutorials > blog posts\n- Cite the specific URL + section, not just \"I found online\"\n- If docs are ambiguous: note it explicitly, don''t fabricate certainty\n"},"lastSynced":"2026-03-08T02:14:00.578Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing authoritative external knowledge for unfamiliar libraries, frameworks, or tools","zh":"非常适合需要外部权威知识的开发人员代理，用于不熟悉的库、框架或工具","ja":"開発者エージェントが未熟悉のライブラリ、フレームワーク、またはツールに権威ある外部知識を必要とする場合に最適","ko":"개발자 에이전트가 생소한 라이브러리, 프레임워크 또는 도구에 대한 권위 있는 외부 지식을 필요로 할 때 완벽함","es":"Perfecto para Agentes de Desarrollador que necesitan conocimiento externo autorizado para bibliotecas, frameworks o herramientas desconocidas","fr":"Parfait pour les Agents de Développeur ayant besoin de connaissances externes autorisées pour des bibliothèques, des frameworks ou des outils inconnus","de":"Perfekt für Entwickleragenten, die autorisiertes externes Wissen für unbekannte Bibliotheken, Frameworks oder Tools benötigen","pt":"Perfeito para Agentes de Desenvolvedor que precisam de conhecimento externo autoritativo para bibliotecas, frameworks ou ferramentas desconhecidas","ru":"Идеально подходит для агентов разработчиков, которым необходим внешний авторитетный знания для незнакомых библиотек, фреймворков или инструментов","ar":"مثالي للوكلاء المطورين الذين يحتاجون إلى معرفة خارجية موثوقة لمكتبات أو إطارات أو أدوات غير مألوفة"},"recommendation":{"en":"Empowers agents to surface concrete guidance from official docs and OSS examples, providing best practices for library decisions and finding production-ready implementations, all while avoiding non-authoritative sources like tutorials and blog posts","zh":"赋予代理从官方文档和开源示例中提供具体指导的能力，提供有关库决策的最佳实践，并找到生产就绪的实现，同时避免非权威来源，如教程和博客帖子","ja":"公式ドキュメントやOSSの例から具体的なガイダンスを提示する能力をエージェントに与え、ライブラリの決定や生産向けの実装を見つけるためのベストプラクティスを提供し、チュートリアルやブログ記事のような非公式な情報源を避ける","ko":"공식 문서 및 오픈 소스 예제에서 구체적인 지침을 제공할 수 있는 능력을 에이전트에게 부여하여 라이브러리 결정 및 생산 준비 구현을 찾기 위한 모범 사례를 제공하며, 튜토리얼 및 블로그 게시물과 같은 비권위적 출처를 피함","es":"Habilita a los agentes a proporcionar orientación concreta desde la documentación oficial y ejemplos de OSS, brindando las mejores prácticas para decisiones de bibliotecas y encontrar implementaciones listas para producción, todo ello mientras evita fuentes no autorizadas como tutoriales y publicaciones de blogs","fr":"Permet aux agents de fournir des conseils concrets à partir de la documentation officielle et d''exemples de OSS, en fournissant les meilleures pratiques pour les décisions de bibliothèque et en trouvant des implementations prêtes pour la production, le tout en évitant les sources non autorisées comme les didacticiels et les billets de blog","de":"Ermächtigt die Agenten, konkrete Anleitungen von offiziellen Dokumentationen und OSS-Beispielen bereitzustellen, dabei die besten Praktiken für Bibliotheksentscheidungen und die Suche nach produktionsbereiten Implementierungen liefern, all dies während sie nicht autorisierte Quellen wie Tutorials und Blog-Beiträge vermeiden","pt":"Habilita os agentes a fornecer orientação concreta a partir de documentos oficiais e exemplos de OSS, fornecendo as melhores práticas para decisões de bibliotecas e encontrando implementações prontas para produção, tudo isso enquanto evita fontes não autoritativas como tutoriais e posts de blog","ru":"Наделяет агентов возможностью предоставлять конкретные рекомендации из официальной документации и примеров OSS, предоставляя лучшие практики для принятия решений о библиотеках и поиска готовых к производству реализаций, все это при этом избегая неавторитетных источников, таких как учебники и блог-посты","ar":"تمكّن الوكلاء من تقديم إرشادات ملموسة من وثائق رسمية وأمثلة من OSS، وتقديم أفضل الممارسات لقرارات المكتبات والبحث عن التنفيذات الجاهزة للانتاج، كل ذلك مع تجنب المصادر غير الموثوقة مثل التutorials والمنشورات على المدونات"},"useCases":{"en":["Researching official documentation for specific external dependencies","Finding open-source implementations to inform design decisions","Determining best practices for unfamiliar libraries or frameworks"],"zh":["研究特定外部依赖项的官方文档","找到开源实现以告知设计决策","确定不熟悉的库或框架的最佳实践"],"ja":["特定外部依存関係の公式ドキュメントを調査する","設計上の決定を通知するためのOSSの実装を見つける","未熟悉のライブラリまたはフレームワークのベストプラクティスを決定する"],"ko":["특정 외부 종속성에 대한 공식 문서 연구","디자인 결정에 대한 정보를 제공하는 오픈 소스 구현 찾기","생소한 라이브러리 또는 프레임워크에 대한 모범 사례 결정"],"es":["Investigar la documentación oficial para dependencias externas específicas","Encontrar implementaciones de código abierto para informar decisiones de diseño","Determinar las mejores prácticas para bibliotecas o frameworks desconocidos"],"fr":["Rechercher la documentation officielle pour des dépendances externes spécifiques","Trouver des implementations open-source pour éclairer les décisions de conception","Déterminer les meilleures pratiques pour des bibliothèques ou des frameworks inconnus"],"de":["Recherchieren der offiziellen Dokumentation für bestimmte externe Abhängigkeiten","Finden von Open-Source-Implementierungen, um Entwurfsentscheidungen zu informieren","Feststellen der besten Praktiken für unbekannte Bibliotheken oder Frameworks"],"pt":["Pesquisando documentação oficial para dependências externas específicas","Encontrando implementações de código aberto para informar decisões de design","Determinando as melhores práticas para bibliotecas ou frameworks desconhecidas"],"ru":["Изучение официальной документации для конкретных внешних зависимостей","Поиск открытых реализаций для информирования решений по проектированию","Определение лучших практик для незнакомых библиотек или фреймворков"],"ar":["البحث في الوثائق الرسمية للاعتماديات الخارجية المحددة","العثور على تنفيذات مفتوحة المصدر لتزويد القرارات التصميمية بالمعلومات","تحديد أفضل الممارسات للمكتبات أو الإطارات غير المألوفة"]},"limitations":{"en":["Requires internet access for external knowledge retrieval","Limited to publicly available official documentation and OSS examples"],"zh":["需要互联网访问以检索外部知识","仅限于公开可用的官方文档和OSS示例"],"ja":["外部知識の取得のためにインターネットアクセスが必要","公開可能な公式ドキュメントとOSSの例のみに限定"],"ko":["외부 지식 검색을 위해 인터넷 액세스가 필요","공개 가능한 공식 문서 및 오픈 소스 예제로 제한"],"es":["Requiere acceso a Internet para la recuperación de conocimiento externo","Limitado a la documentación oficial pública y ejemplos de OSS"],"fr":["Nécessite un accès à Internet pour la récupération de connaissances externes","Limité à la documentation officielle publique et aux exemples de OSS"],"de":["Benötigt Internetzugang für die Abrufung von externem Wissen","Begrenzt auf öffentlich zugängliche offizielle Dokumentationen und OSS-Beispiele"],"pt":["Requer acesso à internet para recuperação de conhecimento externo","Limitado à documentação oficial pública e exemplos de OSS"],"ru":["Требует доступа к интернету для извлечения внешних знаний","Ограничен только публично доступной официальной документацией и примерами OSS"],"ar":["يتطلب الوصول إلى الإنترنت لاسترجاع المعرفة الخارجية","محدود بالوثائق الرسمية العامة وأمثلة OSS"]},"version":4},"contentHash":"d9901c96e73452cf9409ee2e2b115890e672d4e5f956d1edd3c239d28bf0b1af","qualityScore":39}');
