INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('totoroyyb/amag/external-researcher', 'external-researcher', 'totoroyyb', 'amag', 'community', 'external-researcher totoroyyb amag community The External Researcher skill provides a protocol for finding authoritative external knowledge, benefiting developers working with unfamiliar libraries, frameworks, or tools. It surfaces concrete guidance from official docs and OSS examples. External Researcher 协议用于找到权威的外部知识，通过搜索官方文档和 OSS 实现来提供具体的指导 External Researcher プロトコルは、公式ドキュメントと OSS の実装を検索して、具体的なガイダンスを提供するために使用されます External Researcher 프로토콜은 외부 권위 지식을 찾는 데 사용되며 공식 문서와 OSS 구현을 검색하여 구체적인 가이드를 제공합니다 El agente de investigación externa es un protocolo para encontrar conocimientos autorizados en fuentes externas, como documentos oficiales y ejemplos de código abierto L''agent de recherche externe est un protocole pour trouver des connaissances autorisées dans des sources externes, telles que des documents officiels et des exemples de code open source Der externe Forscher-Agent ist ein Protokoll, um autorisierte Kenntnisse in externen Quellen wie offiziellen Dokumenten und Open-Source-Code-Beispielen zu finden O External Researcher é um protocolo para encontrar conhecimento autoritário externo, ajudando desenvolvedores a encontrar documentação oficial e exemplos de OSS ИИ Агент External Researcher - это протокол для поиска внешних авторитетных знаний, помогающий разработчикам найти официальную документацию и примеры OSS ال_external Researcher هو بروتوكول لتحديد المعرفة الخارجية الموثوقة، يساعد المطورين على العثور على الوثائق الرسمية وأمثلة OSS how to use external researcher what is external researcher external researcher setup guide external researcher alternative external researcher vs research tools external researcher install external researcher for AI agents authoritative external knowledge reference finding mode External Researcher AI工具 外部知识 官方文档 OSS 实现 最佳实践 库框架工具 外部依赖 Searches official documentation for authoritative knowledge Finds production OSS examples to inform design decisions Surfaces concrete guidance for unfamiliar libraries and frameworks Activates reference-finding mode for specific external dependencies Provides best practices for library decisions External Researcher is a protocol for finding authoritative external knowledge, enabling developers to shift into reference-finding mode and access concrete guidance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MusserLab/lab-claude-skills/tree-formatting', 'community', 'MusserLab', 'lab-claude-skills', 'MusserLab/lab-claude-skills', 'tree-formatting', 0, 0, 39, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:06.052Z', 'e88c04fe97b2e88c80caec4bcae29810db76487639915d4c4a3dce15e21539ce', '{"id":"MusserLab/lab-claude-skills/tree-formatting","name":"tree-formatting","description":{"en":"The tree-formatting skill enables developers to render phylogenetic trees using ggtree or iTOL. It benefits bioinformaticians and researchers needing publication-quality figures or interactive tree visualizations.","zh":"树格式化是使用ggtree和iTOL对树进行格式化和可视化的过程，用于创建出版物级别的图表和进行交互式探索","ja":"ツリーフォーマットは、ggtreeとiTOLを使ってツリーをフォーマットし、可視化するプロセスで、出版物級の図を作成し、インタラクティブに探索するために使用されます","ko":"트리 포매팅은 ggtree와 iTOL을 사용하여 트리를 포매팅하고 시각화하는 과정으로, 출판물 수준의 그래프를 생성하고 인터랙티브하게 탐색하기 위해 사용됩니다","es":"El formato de árbol es fundamental para la visualización de relaciones filogenéticas. Aprende a configurar ggtree e iTOL para tus necesidades","fr":"Le formatage d''arbre est essentiel pour la visualisation des relations phylogénétiques. Apprenez à configurer ggtree et iTOL pour vos besoins","de":"Die Baumformatierung ist entscheidend für die Visualisierung von phylogenetischen Beziehungen. Erfahren Sie, wie Sie ggtree und iTOL für Ihre Bedürfnisse konfigurieren","pt":"Formatação de árvore para figuras de publicação e exploração interativa usando ggtree e iTOL","ru":"Форматирование деревьев для публикаций и интерактивного исследования с помощью ggtree и iTOL","ar":"تنسيق الشجرة للنشر والاستكشاف التفاعلي باستخدام ggtree و iTOL"},"seo":{"title":{"en":"tree-formatting: Phylogenetic Tree Rendering Setup Guide ...","zh":"树格式化设置指南 - 使用ggtree和iTOL","ja":"ツリーフォーマットのベストプラクティス - ggtreeとiTOLの使い方","ko":"트리 포매팅 설정 가이드 - ggtree와 iTOL 사용법","es":"Configuración de Formato de Árbol: Guía para ggtree e iTOL","fr":"Mise en Forme d''Arbre : Guide pour ggtree et iTOL","de":" Baumformatierung: Einrichtungsleitfaden für ggtree und iTOL","pt":"Guia de Formatação de Árvore com ggtree e iTOL","ru":"ИИ Агенты: Настройка Форматирования Деревьев с ggtree и iTOL","ar":"إعداد تنسيق الشجرة باستخدام ggtree و iTOL"},"description":{"en":"Discover how to render phylogenetic trees with tree-formatting. Learn to choose between ggtree and iTOL backends for publication figures or interactive explo...","zh":"学习如何使用ggtree和iTOL进行树格式化和可视化，创建出版物级别的图表并进行交互式探索","ja":"ggtreeとiTOLを使ったツリーフォーマットと可視化の方法を学び、出版物級の図を作成し、インタラクティブに探索する","ko":"ggtree와 iTOL을 사용하여 트리 포매팅과 시각화를 수행하고, 출판물 수준의 그래프를 생성하고 인터랙티브하게 탐색하는 방법을 배우세요","es":"Aprende a utilizar ggtree y iTOL para la visualización y formato de árboles filogenéticos con nuestra guía de configuración","fr":"Découvrez comment utiliser ggtree et iTOL pour la visualisation et le formatage d''arbres phylogénétiques avec notre guide de configuration","de":"Erfahren Sie, wie Sie ggtree und iTOL für die Visualisierung und Formatierung von phylogenetischen Bäumen mit unserem Einrichtungsleitfaden verwenden","pt":"Aprenda a formatar árvores filogenéticas com ggtree e iTOL para figuras de publicação e exploração interativa","ru":"Откройте для себя возможности форматирования деревьев с помощью ggtree и iTOL для публикаций и интерактивного исследования","ar":"تعرف على كيفية تنسيق الأشجار الفيلوجينية باستخدام ggtree و iTOL للنشر والاستكشاف التفاعلي"},"definition":{"en":"tree-formatting is a convention for rendering phylogenetic trees using ggtree or iTOL, supporting output formats like PDF, PNG, and SVG.","zh":"树格式化是指使用ggtree和iTOL对树进行格式化和可视化的技术","ja":"ツリーフォーマットとは、ggtreeとiTOLを使ってツリーをフォーマットし、可視化する技術です","ko":"트리 포매팅은 ggtree와 iTOL을 사용하여 트리를 포매팅하고 시각화하는 기술입니다","es":"El formato de árbol se refiere a la representación visual de relaciones filogenéticas utilizando herramientas como ggtree e iTOL","fr":"Le formatage d''arbre fait référence à la représentation visuelle des relations phylogénétiques à l''aide d''outils tels que ggtree et iTOL","de":"Die Baumformatierung bezeichnet die visuelle Darstellung von phylogenetischen Beziehungen mithilfe von Tools wie ggtree und iTOL","pt":"Formatação de árvore é uma técnica para renderizar árvores filogenéticas usando ggtree ou iTOL","ru":"Форматирование деревьев - это техника для отображения филогенетических деревьев с помощью ggtree или iTOL","ar":"تنسيق الشجرة هو تقنية لتصيير الأشجار الفيلوجينية باستخدام ggtree أو iTOL"},"features":{"en":["Supports ggtree backend for publication figures and full programmatic control","Enables interactive exploration with iTOL backend","Generates output in PDF, PNG, and SVG formats","Compatible with R language for scripting and automation","Allows offline use with ggtree backend","Integrates with Bioconductor for comprehensive bioinformatics workflows"],"zh":["使用ggtree进行出版物级别的图表创建","使用iTOL进行交互式探索","支持PDF、PNG、SVG输出格式","使用R语言进行程序化控制"],"ja":["ggtreeを使った出版物級の図の作成","iTOLを使ったインタラクティブな探索","PDF、PNG、SVG出力形式のサポート","R言語を使ったプログラム的制御"],"ko":["ggtree를 사용하여 출판물 수준의 그래프 생성","iTOL을 사용하여 인터랙티브하게 탐색","PDF, PNG, SVG 출력 형식 지원","R 언어를 사용하여 프로그래밍 방식으로 제어"],"es":["Compatibilidad con ggtree para la creación de figuras de publicación","Uso de iTOL para la exploración interactiva de árboles filogenéticos","Salida en formatos PDF, PNG y SVG","Control programático completo con R y scripts .qmd","Visualización de árboles filogenéticos en línea y fuera de línea"],"fr":["Compatibilité avec ggtree pour la création de figures de publication","Utilisation d''iTOL pour l''exploration interactive d''arbres phylogénétiques","Sortie au format PDF, PNG et SVG","Contrôle programmatique complet avec R et scripts .qmd","Visualisation d''arbres phylogénétiques en ligne et hors ligne"],"de":["Kompatibilität mit ggtree für die Erstellung von Publikationsfiguren","Verwendung von iTOL für die interaktive Exploration von phylogenetischen Bäumen","Ausgabe im PDF-, PNG- und SVG-Format","Vollständige programatische Kontrolle mit R und .qmd-Skripten","Visualisierung von phylogenetischen Bäumen online und offline"],"pt":["Uso de ggtree para figuras de publicação","Uso de iTOL para exploração interativa","Saída em PDF, PNG e SVG","Controle programático total com R","Uso offline com ggtree","Interação online com iTOL"],"ru":["Использование ggtree для публикаций","Использование iTOL для интерактивного исследования","Вывод в форматах PDF, PNG и SVG","Полный программный контроль с помощью R","Офлайн-использование с ggtree","Онлайн-взаимодействие с iTOL"],"ar":["استخدام ggtree للنشر","استخدام iTOL للاستكشاف التفاعلي","الإخراج في صيغ PDF و PNG و SVG","التحكم البرمجي الكامل مع R","استخدام غير متصل مع ggtree","التفاعل عبر الإنترنت مع iTOL"]},"keywords":{"en":["how to use tree-formatting","tree-formatting vs ggtree","tree-formatting setup guide","what is tree-formatting","tree-formatting alternative to iTOL","tree-formatting install R","phylogenetic tree rendering","ggtree tutorial","iTOL interactive tree visualization"],"zh":["树格式化","ggtree","iTOL","树可视化","出版物级别的图表","交互式探索","R语言","PDF输出","PNG输出","SVG输出"],"ja":["ツリーフォーマット","ggtree","iTOL","ツリー可視化","出版物級の図","インタラクティブな探索","R言語","PDF出力","PNG出力","SVG出力"],"ko":["트리 포매팅","ggtree","iTOL","트리 시각화","출판물 수준의 그래프","인터랙티브하게 탐색","R 언어","PDF 출력","PNG 출력","SVG 출력"],"es":["formato de árbol filogenético","ggtree","iTOL","visualización de árboles","R para la visualización de datos","Bioconductor"," árboles de vida interactivos","formato de árbol para publicaciones"],"fr":["formatage d''arbre phylogénétique","ggtree","iTOL","visualisation d''arbres","R pour la visualisation de données","Bioconductor","arbres de vie interactifs","formatage d''arbre pour les publications"],"de":["Baumformatierung phylogenetischer Bäume","ggtree","iTOL","Visualisierung von Bäumen","R für die Datenvisualisierung","Bioconductor","interaktive Lebensbäume","Baumformatierung für Publikationen"],"pt":["formatação de árvore","ggtree","iTOL","árvore filogenética","figuras de publicação","exploração interativa","R","Bioconductor","renderização de árvore"],"ru":["форматирование деревьев","ggtree","iTOL","филогенетическое дерево","публикации","интерактивное исследование","R","Bioconductor","отображение деревьев"],"ar":["تنسيق الشجرة","ggtree","iTOL","الشجرة الفيلوجينية","النشر","الاستكشاف التفاعلي","R","Bioconductor","تصيير الشجرة"]}},"owner":"MusserLab","repo":"lab-claude-skills","repoPath":"MusserLab/lab-claude-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.661Z","topics":[],"category":"community","skillMd":{"name":"tree-formatting","description":">","bodyPreview":"# Tree Formatting & Visualization\n\nConventions for rendering phylogenetic trees using **ggtree** (R/Bioconductor)\nor **iTOL** (Interactive Tree of Life, web-based).\n\n---\n\n## Step 0: Choose Rendering Backend\n\nAsk the user which backend to use based on their needs:\n\n| Backend | Best for | Output | Language |\n|---------|----------|--------|----------|\n| **ggtree** | Publication figures, full programmatic control, offline use | PDF/PNG/SVG | R (.qmd script) |\n| **iTOL** | Interactive exploration, qu","body":"# Tree Formatting & Visualization\n\nConventions for rendering phylogenetic trees using **ggtree** (R/Bioconductor)\nor **iTOL** (Interactive Tree of Life, web-based).\n\n---\n\n## Step 0: Choose Rendering Backend\n\nAsk the user which backend to use based on their needs:\n\n| Backend | Best for | Output | Language |\n|---------|----------|--------|----------|\n| **ggtree** | Publication figures, full programmatic control, offline use | PDF/PNG/SVG | R (.qmd script) |\n| **iTOL** | Interactive exploration, quick iteration, web sharing, UI tweaking | Web + PDF/SVG/PNG exports | R (.qmd annotations) + Python (.qmd upload) |\n\n### Backend comparison\n\n| Feature | ggtree | iTOL |\n|---------|--------|------|\n| Interactive exploration | No | Yes (web UI) |\n| Label alignment control | Full (programmatic) | Limited (UI toggle only, not via API) |\n| Collapse triangle labels | Manual `geom_text()` | Built-in LABELS for internal nodes |\n| Circular label positioning | Complex (manual angle computation) | Automatic |\n| Branch length display | Yes (phylogram/cladogram toggle) | Yes (via UI) |\n| Offline/reproducible | Fully offline | Requires iTOL API + internet |\n| Two-script workflow | No (single .qmd) | Yes (R .qmd annotations + Python .qmd upload) |\n\n---\n\n## Step 1: Choose the Tree Type\n\nHelp the user select the right visualization. Ask about **purpose** and **tree size**,\nthen recommend from the options below.\n\n### Tree type options\n\n| Type | Best for | Tips | Key features |\n|------|----------|------|-------------|\n| **Collapsed rectangular phylogram** | Large family trees; showing branch-length variation and gene family structure | 250-2000+ | Collapsed pure clades, branch lengths, selective labels |\n| **Collapsed rectangular cladogram** | Large family trees; topology focus, cleaner labels | 250-2000+ | Same as phylogram but no branch lengths, narrower page |\n| **Collapsed circular** | Large trees; compact overview showing overall structure | 250-2000+ | Circular layout, collapsed clades, optional selective labels |\n| **Simple rectangular phylogram** | Small-medium trees where all tips are readable | < 250 | All tips labeled, no collapsing needed |\n| **Unrooted** | Networks, showing relationships without root assumption | Any | No directionality implied |\n\n### Decision flow\n\n1. **How many tips?**\n   - < 250: Simple rectangular (all tips labeled)\n   - 250+: Collapsed rectangular or circular — ask user preference\n2. **Branch lengths meaningful?**\n   - Yes -> phylogram option available\n   - No / topology-only -> cladogram\n3. **Layout**: Rectangular or circular? Often useful to produce both.\n4. **Both phylogram and cladogram?** Often useful to produce both for rectangular trees.\n5. **Which species to highlight?** -> Focal species list (see Step 2)\n\n---\n\n## Step 2: User Prompts (Ask Before Building)\n\nGather these decisions before writing any code:\n\n1. **Rendering backend**: ggtree or iTOL? (see Step 0)\n2. **Tree type**: Offer the relevant options from the table above based on tip count\n3. **Collapsing strategy**: \"Should pure clades be collapsed?\n   (Recommended for trees with >100 tips.)\"\n   - **Which groups to collapse?** The `collapse_groups` parameter controls which\n     taxonomic groups are eligible. Common choices:\n     - `c(\"Bilateria\")` — only collapse bilaterians (keeps sponges/cnidarians expanded)\n     - `c(\"Bilateria\", \"Protostomia\", \"Deuterostomia\")` — collapse specific groups\n     - `NULL` — all groups eligible for collapsing\n   - **Purity threshold**: 100% pure (strict) or 90%+ (relaxed)?\n   - **Model species on triangles**: Collapsed triangles automatically list gene\n     names of model species (human, mouse, fly, worm) inside them, e.g.,\n     `\"Bilateria (36 tips: LAMA1, LAMA2, LAMB1)\"`. This ensures key gene family\n     members remain visible even when the clade is collapsed.\n   - **Never collapse by gene family** — unless eggNOG orthogroup data is available\n4. **Labeling level**: \"What level of tip labeling do you want?\"\n   - **No labels** — branch colors only (good for overview figures)\n   - **All tips labeled** — every visible tip gets a label (good for small trees)\n   - **Selective** — model species + focal species only (recommended for large trees)\n5. **Focal species list** (if selective labeling): \"Which non-model species should be\n   individually labeled? Typically sponges + species with single-cell data\n   (e.g., Hydra, Nematostella). Provide full species names.\"\n6. **Rooting strategy**: \"Midpoint root, or specify an outgroup?\"\n7. **Gene name resolution**: \"Do tips include model species from non-Swiss-Prot\n   sources (e.g., tr| entries, Ensembl, FlyBase, WormBase)? If so, we need to look\n   up gene symbols.\" -> See **gene-lookup** skill for database-specific workflows.\n8. **iTOL project** (if iTOL backend): \"Which iTOL project should the tree go in?\n   Name an existing project, or create a new one in the iTOL web UI\n   (My Trees > New Project) and tell me the name.\" Set as `ITOL_PROJECT` env var\n   or hardcode in the upload script.\n\n---\n\n## Step 3a: Build with ggtree\n\n**All ggtree templates are Quarto `.qmd` documents** following the project''s data\nscience conventions (YAML frontmatter with status field, git hash, BUILD_INFO.txt).\n\n### Collapsed rectangular (phylogram / cladogram)\n\n**Reference template**: `~/.claude/skills/tree-formatting/templates/ggtree/collapsed_rectangular.qmd`\n\nThis template is a complete, runnable `.qmd` with all tuned style parameters. Copy it\ninto the project''s `scripts/` directory and adapt the sections marked PROJECT-SPECIFIC:\n- File paths\n- Tip label parsing functions (must match actual label formats in the tree)\n- Taxonomy mapping (species -> group)\n- Model and focal species lists\n- `collapse_groups` parameter (which taxonomic groups to collapse)\n\nThe template handles: tree loading, midpoint rooting, pure-clade collapsing by\ntaxonomic group, branch coloring by taxonomy, all visible tips labeled, model species\ngene names on collapsed triangle labels, formula-based page sizing, and PDF output.\n\n**Key features:**\n- **No branch capping** — branch lengths are never manipulated (this is a hard rule)\n- **Formula-based page sizing** — `INCHES_PER_TIP = 0.12`, height = `max(8, n_visible * INCHES_PER_TIP)`\n- **`collapse_groups` parameter** — controls which taxonomic groups are eligible for\n  collapsing (e.g., `c(\"Bilateria\")` to only collapse bilaterians, or `NULL` for all)\n- **Model species gene names on triangles** — collapsed labels show\n  `\"Group (N tips: GENE1, GENE2, ...)\"` so key gene family members remain visible\n- **Collapse label positioning** — labels at `max(pre_data$x[tip_ids])` (triangle tip),\n  not at internal node x (triangle base)\n\n### Collapsed circular (overview and/or labeled)\n\n**Reference template**: `~/.claude/skills/tree-formatting/templates/ggtree/collapsed_circular.qmd`\n\nSame structure as rectangular — adapt PROJECT-SPECIFIC sections. Produces:\n- **Circular overview** (no labels): 20\" square page, branch colors only\n- **Circular labeled** (selective labels): 28\" square page, manually positioned labels\n\n**Critical circular gotcha**: Labels must be positioned BEFORE `collapse()` is called.\nThe template handles this by computing angles from y-position (`y / max_y * 360`),\nflipping text on the left half of the circle, and using `geom_text()` with explicit\nangle/hjust values instead of `geom_tiplab2()`.\n\n### Other tree types\n\nFor simple rectangular or unrooted trees, no template exists yet. Build from ggtree\nbasics:\n\n```r\n# Simple rectangular (all tips labeled)\np <- ggtree(tree) + geom_tiplab(size = 2)\n\n# Unrooted\np <- ggtree(tree, layout = \"unrooted\")\n```\n\n**All style parameters are defined as named constants at the top of each template**\n(e.g., `BRANCH_LINE_WIDTH`, `LABEL_SIZE`, `INCHES_PER_TIP`). Do not scatter\nmagic numbers through the code.\n\n---\n\n## Step 3b: Build with iTOL\n\n### Two-script workflow\n\niTOL requires separate R and Python steps (do not mix in one `.qmd`):\n\n1. **R script** — generates annotation files + relabeled Newick tree\n2. **Python script** — uploads tree + annotations to iTOL, exports rendered images\n\n### Annotation generation (R)\n\n**Reference template**: `~/.claude/skills/tree-formatting/templates/itol/annotations.R`\n\nCopy into project and adapt PROJECT-SPECIFIC sections. Generates these files:\n- `GENE.tree` — relabeled Newick (short display labels, no `|` characters)\n- `GENE_branch_colors.txt` — TREE_COLORS with clade + branch entries\n- `GENE_label_colors.txt` — TREE_COLORS label color entries\n- `GENE_collapse.txt` — COLLAPSE entries for pure clades\n- `GENE_collapse_labels.txt` — LABELS for collapsed clade internal nodes\n\n### Upload and export (Python)\n\n**Reference template**: `~/.claude/skills/tree-formatting/templates/itol/upload_export.py`\n\nUploads two versions:\n1. **Uncollapsed** — tree + branch colors + label colors (all tips visible)\n2. **Collapsed** — tree + all annotations including collapse files\n\nExports multiple layout/format combinations (circular PDF/SVG/PNG, rectangular\nPDF/SVG, unrooted PDF).\n\n### iTOL API setup\n\n- **API key**: iTOL > My Account > API access -> set as `ITOL_API_KEY` env var\n- **Project**: set `ITOL_PROJECT` env var (default: \"misc\"). The project must\n  already exist — **the iTOL API cannot create projects**, only the web UI can\n  (My Trees > New Project). Prompt the user to create it if needed.\n- **Paid subscription** required for full batch export API access\n\n### After upload: always report links\n\nAfter rendering the upload script, **always read the BUILD_INFO.txt** and report the\niTOL URLs back to the user in chat. These clickable links are essential for quick\niteration. Format:\n\n```\n**Uncollapsed:** http://itol.embl.de/external.cgi?tree=TREE_ID&restore_saved=1\n**Collapsed:** http://itol.embl.de/external.cgi?tree=TREE_ID&restore_saved=1\n```\n\n---\n\n## Tip Label Parsing (General Guidance)\n\nTip label formats vary substantially depending on data source. **Do not assume a\nfixed format.** Inspect the actual tip labels first, then write parsing functions\ntailored to what''s present.\n\n### Common formats\n\n| Source | Example | Species part | ID part |\n|--------|---------|-------------|---------|\n| UniProt (sp) | `sp\\|O95631\\|NET1_HUMAN` | Suffix: `HUMAN` | Gene: `NET1` |\n| UniProt (tr) | `tr\\|Q23158\\|Q23158_CAEEL` | Suffix: `CAEEL` | Accession: `Q23158` |\n| Species\\|taxid.acc | `Mus_musculus\\|10090.Q9R1A3` | Before `\\|` | After `taxid.` |\n| Species\\|acc | `Nematostella\\|XP_032238380.2` | Before `\\|` | After `\\|` |\n| BLAST-annotated | `Hydra\\|8692.t25743aep_EHBP1_HUMAN_...` | Before `\\|` | Transcript ID only |\n\n### Key rules\n\n- **Model species** (human, mouse, fly, worm): resolve to gene names via sp| labels\n  or the **gene-lookup** skill for other databases\n- **Non-model species**: use actual protein/transcript IDs only — **never** infer\n  gene names from BLAST annotations\n- **Display format**: `G._species_GENE_OR_ID` (e.g., `H._sapiens_SPTB1`,\n  `E._muelleri_Em0014g869a`)\n\n---\n\n## Taxonomic Color Scheme\n\n| Taxonomic Group | Hex |\n|-----------------|-----|\n| Demosponges | `#2ca02c` |\n| Calcarea + Homoscleromorpha | `#98df8a` |\n| Ctenophora | `#9467bd` |\n| Cnidaria + Placozoa | `#ff7f0e` |\n| Deuterostomia | `#d62728` |\n| Protostomia | `#1f77b4` |\n| Non-metazoan eukaryotes | `#555555` |\n| Mixed (internal nodes) | `#999999` |\n\nSpecies that are commonly misclassified:\n\n| Species | Correct group | Notes |\n|---------|---------------|-------|\n| Thelohanellus_kitauei | Cnidaria + Placozoa | Myxozoan = cnidarian |\n| Meara_stichopi, Waminoa | Deuterostomia | Xenacoelomorpha |\n| Spadella_cephaloptera | Protostomia | Chaetognath |\n| Monosiga, Salpingoeca | Non-metazoan | Choanoflagellates |\n\n---\n\n## Key ggtree Gotchas\n\nThese are hard-won lessons — do not skip:\n\n1. **Pre-compute label positions BEFORE `collapse()`** — collapse modifies `p$data`\n   coordinates. Extract x/y from `p$data` first. This applies to BOTH rectangular\n   and circular layouts.\n\n2. **Match on node column, not row index** — `p$data` rows may not be ordered by\n   node ID. Always use `match(tip_node_ids, pre_data$node)`.\n\n3. **Collapse label x-position: use `max(pre_data$x[tip_ids])`, NOT node x** —\n   The internal node sits at the base of the collapsed triangle, but the label\n   should appear at the triangle tip (where descendant tips extend to). Using the\n   node x places labels at the triangle base, which looks wrong.\n\n4. **Never cap branch lengths** — Branch lengths represent real evolutionary\n   distances. Capping or truncating them is data manipulation. If long branches\n   compress internal structure, offer a cladogram as the honest alternative.\n\n5. **Circular labels: use `geom_text()` with manual angles, NOT `geom_tiplab2()`** —\n   compute angles as `y / max_y * 360`, flip text on left half (`angles > 90 & < 270`),\n   and pass angle/hjust outside `aes()`.\n\n6. **`show.legend = FALSE` on `geom_text`** — prevents \"a\" character artifacts\n   appearing in the color legend.\n\n7. **`branch.length = \"none\"` for cladogram** — cannot pass `NULL`. Must use\n   if/else to conditionally include this argument.\n\n8. **`coord_cartesian(clip = \"off\")`** — required for rectangular labels that extend\n   beyond the plot area. Pair with wide right margin. Not needed for circular.\n\n9. **Daylight layout** — produces unusable output for large trees (branches crossing,\n   triangles overlapping). Avoid it.\n\n10. **Page sizing formula** — Use `INCHES_PER_TIP = 0.12` with\n    `PAGE_HEIGHT = max(8, n_visible * INCHES_PER_TIP)` where `n_visible` counts\n    non-collapsed tips plus collapsed triangles. This formula keeps labels readable\n    without excess whitespace. Hardcoded page sizes invariably need adjustment.\n\n11. **Never collapse by gene family** — Unless eggNOG orthogroup data is available\n    to intelligently define ortholog groups, only collapse by taxonomic group.\n    Gene families within a tree are the object of study, not noise to be hidden.\n\n---\n\n## Key iTOL Gotchas\n\nHard-won lessons from iTOL annotation file development:\n\n1. **Tip labels must NOT contain `|` characters** — iTOL uses `|` as the MRCA\n   separator in TREE_COLORS clade entries (`tipA|tipB clade ...`), COLLAPSE entries,\n   and LABELS internal node entries. If tip labels contain `|`, all clade/collapse\n   specifications silently break (wrong MRCA selected, or entries ignored entirely).\n   **Solution**: relabel tips to short display names before writing the Newick tree.\n\n2. **`ape::write.tree()` converts spaces to underscores** — display labels must use\n   underscores from the start (`H._sapiens_SPTN2` not `H. sapiens SPTN2`), or\n   annotation file IDs will not match the tree.\n\n3. **`itol.toolkit` R package is incompatible with `|` in tip labels** — the toolkit\n   also uses `|` internally and cannot escape it. Write annotation files manually\n   (plain text with TAB separator) instead of using `itol.toolkit`.\n\n4. **MRCA pair selection**: to specify an internal node, provide one tip from each\n   child subtree (`tipA|tipB`). Using `tips[1]` and `tips[N]` (first/last by array\n   index) can give two tips from the same child, which specifies a different MRCA.\n\n5. **Label alignment is NOT controllable via batch export API** — the \"Align tip\n   labels\" toggle is UI-only. The `label_display` export parameter controls\n   visibility (0=hide, 1=show) but not alignment. Users must toggle alignment\n   manually in the iTOL web interface.\n\n6. **Collapsed triangle labels** — use LABELS annotation type with MRCA specification\n   (`tipA|tipB\\tLabel text`). These render as the displayed name on collapsed\n   triangles.\n\n7. **Two uploads for collapsed vs uncollapsed** — upload annotation files are baked\n   into the tree on upload. To have both an uncollapsed and collapsed version,\n   upload twice: once without collapse files, once with all files.\n\n---\n\n## Related Skills\n\n- **protein-phylogeny:** Inference pipeline that produces the tree\n- **gene-lookup:** Resolve accessions to gene symbols across databases (UniProt,\n  Ensembl, FlyBase, WormBase, etc.)\n- **Pfam domain annotation (future):** Domain annotations for overlay\n"},"lastSynced":"2026-03-08T02:14:06.052Z","agentAnalysis":{"suitability":{"en":"Perfect for Bioinformatics Agents needing advanced phylogenetic tree visualization capabilities.","zh":"非常适合需要高级系统发育树可视化能力的生物信息学代理。","ja":"高度な系統樹の可視化機能を必要とするバイオインフォマティクスエージェントに最適です。","ko":"고급 계통수 시각화 기능이 필요한 생물정보학 에이전트에 적합합니다.","es":"Ideal para agentes de bioinformática que necesitan capacidades avanzadas de visualización de árboles filogenéticos.","fr":"Parfait pour les agents de bioinformatique nécessitant des capacités de visualisation d''arbres phylogénétiques avancées.","de":"Perfekt für Bioinformatik-Agenten, die erweiterte phylogenetische Baumvisualisierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Bioinformática que necessitam de capacidades avançadas de visualização de árvores filogenéticas.","ru":"Идеально подходит для агентов биоинформатики, которым необходимы продвинутые возможности визуализации филогенетических деревьев.","ar":"مثالي لعميل المعلوماتية الحيوية الذين يحتاجون إلى إمكانيات متقدمة في تمثيل الشجرة التطورية."},"recommendation":{"en":"Empowers agents to render publication-quality figures and interactive tree visualizations using ggtree or iTOL, supporting formats like PDF, PNG, and SVG, and leveraging languages such as R for offline use and web-based interactive exploration.","zh":"能够让代理渲染出版质量的图形和交互式树可视化，使用ggtree或iTOL，支持PDF、PNG和SVG等格式，并利用R等语言进行离线使用和基于Web的交互式探索。","ja":"ggtreeまたはiTOLを使用して、エージェントが出版品質の図形やインタラクティブな樹可視化をレンダリングできるようにし、PDF、PNG、SVGなどの形式をサポートし、Rなどの言語を使用してオフラインでの使用とWebベースのインタラクティブな探索を可能にします。","ko":"ggtree 또는 iTOL을 사용하여 에이전트가 출판 품질의 도형과 상호작용 트리 시각화를 렌더링할 수 있도록 하며, PDF, PNG, SVG 등의 형식을 지원하며, R 등의 언어를 사용하여 오프라인 사용과 웹 기반의 상호작용형 탐색을 가능하게 합니다.","es":"Habilita a los agentes a renderizar figuras de publicación de alta calidad y visualizaciones de árboles interactivas utilizando ggtree o iTOL, admitiendo formatos como PDF, PNG y SVG, y aprovechando lenguajes como R para uso offline y exploración interactiva basada en web.","fr":"Permet aux agents de rendre des figures de publication de haute qualité et des visualisations d''arbres interactives à l''aide de ggtree ou iTOL, prenant en charge des formats tels que PDF, PNG et SVG, et exploitant des langages tels que R pour une utilisation hors ligne et une exploration interactive basée sur le web.","de":"Ermächtigt Agenten, publikationsreife Abbildungen und interaktive Baumvisualisierungen mithilfe von ggtree oder iTOL zu rendern, unterstützt Formate wie PDF, PNG und SVG und nutzt Sprachen wie R für den Offline-Einsatz und die webbasierte interaktive Erforschung.","pt":"Permite que os agentes gerem figuras de árvores filogenéticas de qualidade de publicação e visualizações de árvores interativas usando ggtree ou iTOL, suportando formatos como PDF, PNG e SVG, e aproveitando linguagens como R para uso offline e exploração interativa baseada na web.","ru":"Позволяет агентам создавать публикации высокого качества фигур филогенетических деревьев и интерактивные визуализации деревьев, используя ggtree или iTOL, поддерживая форматы, такие как PDF, PNG и SVG, и используя языки, такие как R для автономного использования и веб-интерактивного исследования.","ar":"يمنح العميل إمكانية إنشاء أشكال منشورات ذات جودة عالية لشجرة التطورية وتصورات تفاعلية للشجرة باستخدام ggtree أو iTOL، ودعم صيغ مثل PDF و PNG وSVG، وتوظيف لغات مثل R للاستخدام غير المتصل واستكشاف الويب التفاعلي."},"useCases":{"en":["Generating publication-quality phylogenetic tree figures using ggtree","Creating interactive tree visualizations for exploratory research with iTOL","Automating tree formatting for large-scale bioinformatic analyses"],"zh":["使用ggtree生成出版质量的系统发育树图形","使用iTOL创建交互式树可视化用于探索性研究","自动化树格式化用于大规模生物信息学分析"],"ja":["ggtreeを使用して出版品質の系統樹図形を生成する","iTOLを使用して探索性研究用のインタラクティブな樹可視化を作成する","大規模バイオインフォマティクス分析用の樹形式の自動化"],"ko":["ggtree를 사용하여 출판 품질의 계통수 도형을 생성하는こと","iTOL를 사용하여 탐색적 연구를 위한 상호작용 트리 시각화를 생성하는こと","대규모 생물정보학 분석을 위한 트리 형식의 자동화"],"es":["Generar figuras de árboles filogenéticos de publicación de alta calidad utilizando ggtree","Crear visualizaciones de árboles interactivas para la investigación exploratoria con iTOL","Automatizar el formato de árboles para análisis bioinformáticos a gran escala"],"fr":["Générer des figures d''arbres phylogénétiques de publication de haute qualité à l''aide de ggtree","Créer des visualisations d''arbres interactives pour la recherche exploratoire avec iTOL","Automatiser le formatage d''arbres pour les analyses bioinformatiques à grande échelle"],"de":["Erzeugen von publikationsreifen phylogenetischen Baumabbildungen mit ggtree","Erstellen interaktiver Baumvisualisierungen für die exploratorische Forschung mit iTOL","Automatisieren des Baumformats für groß angelegte bioinformatische Analysen"],"pt":["Geração de figuras de árvores filogenéticas de qualidade de publicação usando ggtree","Criação de visualizações de árvores interativas para pesquisa exploratória com iTOL","Automatização do formato da árvore para análises bioinformáticas em larga escala"],"ru":["Генерация фигур филогенетических деревьев высокого качества публикаций с использованием ggtree","Создание интерактивных визуализаций деревьев для исследовательской эксплорации с помощью iTOL","Автоматизация формата дерева для крупномасштабных биоинформатических анализов"],"ar":["إنشاء أشكال منشورات ذات جودة عالية لشجرة التطورية باستخدام ggtree","إنشاء تصورات تفاعلية للشجرة لأغراض البحث الاستكشافي مع iTOL","تأتمة تنسيق الشجرة للتحليلات البيولوجية الحاسوبية على نطاق واسع"]},"limitations":{"en":["Requires R/Bioconductor for ggtree or web access for iTOL","Limited to phylogenetic tree visualization"],"zh":["需要R/Bioconductor用于ggtree或web访问用于iTOL","仅限于系统发育树可视化"],"ja":["ggtree用のR/Bioconductor、またはiTOL用のWebアクセスが必要","系統樹可視化に限定される"],"ko":["ggtree를 위한 R/Bioconductor 또는 iTOL을 위한 웹 액세스가 필요함","계통수 시각화에만 제한됨"],"es":["Requiere R/Bioconductor para ggtree o acceso web para iTOL","Limitado a la visualización de árboles filogenéticos"],"fr":["Nécessite R/Bioconductor pour ggtree ou un accès web pour iTOL","Limité à la visualisation d''arbres phylogénétiques"],"de":["Benötigt R/Bioconductor für ggtree oder Webzugriff für iTOL","Begrenzt auf die Visualisierung von phylogenetischen Bäumen"],"pt":["Requer R/Bioconductor para ggtree ou acesso web para iTOL","Limitado à visualização de árvores filogenéticas"],"ru":["Требуется R/Bioconductor для ggtree или веб-доступ для iTOL","Ограничен до визуализации филогенетических деревьев"],"ar":["يتطلب R/Bioconductor ل ggtree أو الوصول إلى الويب لـ iTOL","محدود بتمثيل الشجرة التطورية"]},"version":4},"contentHash":"e88c04fe97b2e88c80caec4bcae29810db76487639915d4c4a3dce15e21539ce","qualityScore":39}');
