INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MusserLab/lab-claude-skills/tree-formatting', 'tree-formatting', 'MusserLab', 'lab-claude-skills', 'community', 'tree-formatting MusserLab lab-claude-skills community The tree-formatting skill enables developers to render phylogenetic trees using ggtree or iTOL. It benefits bioinformaticians and researchers needing publication-quality figures or interactive tree visualizations. 树格式化是使用ggtree和iTOL对树进行格式化和可视化的过程，用于创建出版物级别的图表和进行交互式探索 ツリーフォーマットは、ggtreeとiTOLを使ってツリーをフォーマットし、可視化するプロセスで、出版物級の図を作成し、インタラクティブに探索するために使用されます 트리 포매팅은 ggtree와 iTOL을 사용하여 트리를 포매팅하고 시각화하는 과정으로, 출판물 수준의 그래프를 생성하고 인터랙티브하게 탐색하기 위해 사용됩니다 El formato de árbol es fundamental para la visualización de relaciones filogenéticas. Aprende a configurar ggtree e iTOL para tus necesidades Le formatage d''arbre est essentiel pour la visualisation des relations phylogénétiques. Apprenez à configurer ggtree et iTOL pour vos besoins Die Baumformatierung ist entscheidend für die Visualisierung von phylogenetischen Beziehungen. Erfahren Sie, wie Sie ggtree und iTOL für Ihre Bedürfnisse konfigurieren Formatação de árvore para figuras de publicação e exploração interativa usando ggtree e iTOL Форматирование деревьев для публикаций и интерактивного исследования с помощью ggtree и iTOL تنسيق الشجرة للنشر والاستكشاف التفاعلي باستخدام ggtree و iTOL how to use tree-formatting tree-formatting vs ggtree tree-formatting setup guide what is tree-formatting tree-formatting alternative to iTOL tree-formatting install R phylogenetic tree rendering ggtree tutorial iTOL interactive tree visualization 树格式化 ggtree iTOL 树可视化 出版物级别的图表 交互式探索 R语言 PDF输出 PNG输出 SVG输出 Supports ggtree backend for publication figures and full programmatic control Enables interactive exploration with iTOL backend Generates output in PDF, PNG, and SVG formats Compatible with R language for scripting and automation Allows offline use with ggtree backend Integrates with Bioconductor for comprehensive bioinformatics workflows tree-formatting is a convention for rendering phylogenetic trees using ggtree or iTOL, supporting output formats like PDF, PNG, and SVG.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('verygoodmurph/figma-plugin-starter/figma-plugin', 'community', 'verygoodmurph', 'figma-plugin-starter', 'verygoodmurph/figma-plugin-starter', 'figma-plugin', 0, 0, 39, '2026-03-07T20:05:29Z', '2026-03-08T02:14:16.663Z', 'a9314fed4926c767d4aabc9dc532a108d5b0a2cb64a833d4a961d63dc5e6b512', '{"id":"verygoodmurph/figma-plugin-starter/figma-plugin","name":"figma-plugin","description":{"en":"The figma-plugin skill provides a zero-build-step Figma plugin scaffold for expert developers, streamlining the process from idea to working plugin. It benefits developers looking to create custom Figma plugins.","zh":"Figma插件开发模板，提供零构建步骤的Figma插件开发环境","ja":"Figmaプラグイン開発テンプレート、ゼロビルドステップのFigmaプラグイン開発環境を提供","ko":"피그마 플러그인 개발 템플릿, 제로 빌드 스텝의 피그마 플러그인 개발 환경을 제공","es":"Desarrolla plugins de Figma con nuestra plantilla de inicio y recursos técnicos. Aprende a crear plugins desde cero.","fr":"Développez des plugins Figma avec notre modèle de démarrage et des ressources techniques. Apprenez à créer des plugins desde zéro.","de":"Entwickeln Sie Figma-Plugins mit unserer Startvorlage und technischen Ressourcen. Lernen Sie, Plugins von Grund auf zu erstellen.","pt":"Desenvolva plugins do Figma com facilidade usando este modelo de configuração. Aprenda a criar plugins com ES5 syntax e manifest fields.","ru":"Разрабатывайте плагины Figma легко с помощью этого конфигурационного шаблона. Узнайте, как создавать плагины с синтаксисом ES5 и полями манифеста.","ar":"قُم بتطوير إضافات فيجما بسهولة باستخدام هذا النموذج الضبط. تعلم كيفية إنشاء الإضافات باستخدام بناء الجملة ES5 وحقول الملف التفسيري."},"seo":{"title":{"en":"figma-plugin: Zero-Build-Step Figma Plugin Scaffold Setup...","zh":"Figma插件开发设置指南","ja":"Figmaプラグイン開発ベストプラクティス","ko":"피그마 플러그인 개발 가이드","es":"Guía de configuración de Figma Plugin con AI","fr":"Guide de configuration de Figma Plugin avec IA","de":"Einrichtungsleitfaden für Figma-Plugin mit KI","pt":"Guia de Configuração do Figma Plugin","ru":"Настройка плагина Figma: ИИ Агенты","ar":"دليل إعداد إضافة فيجما"},"description":{"en":"Unlock efficient Figma plugin development with our expert-crafted scaffold. Read the CLAUDE.md and AGENTS.md files to get started and create your own plugin ...","zh":"了解Figma插件开发的规则和模式，快速创建功能插件","ja":"Figmaプラグイン開発のルールとパターンをマスターして、効率的にプラグインを作成する","ko":"피그마 플러그인 개발을 위한 규칙과 패턴을 익히고 쉽게 플러그인을 제작하세요","es":"Aprende a configurar plugins de Figma con nuestra guía paso a paso y recursos técnicos para desarrolladores","fr":"Découvrez comment configurer des plugins Figma avec notre guide étape par étape et des ressources techniques pour les développeurs","de":"Erfahren Sie, wie Sie Figma-Plugins mit unserer Schritt-für-Schritt-Anleitung und technischen Ressourcen für Entwickler konfigurieren","pt":"Aprenda a configurar o plugin do Figma com este guia passo a passo, incluindo ES5 syntax e manifest fields.","ru":"Узнайте, как настроить плагин Figma с помощью этого пошагового руководства, включая синтаксис ES5 и поля манифеста.","ar":"تعرف على كيفية ضبط إضافة فيجما باستخدام هذا الدليل الخطوة خطوة، بما في ذلك بناء الجملة ES5 وحقول الملف التفسيري."},"definition":{"en":"figma-plugin is a starter template for building Figma plugins, following specific rules and patterns outlined in CLAUDE.md and AGENTS.md files.","zh":"Figma插件是一种AIエージェント工具，用于扩展Figma的功能","ja":"Figmaプラグインは、Figmaの機能を拡張するためのAIエージェントツールです","ko":"피그마 플러그인은 피그마의 기능을 확장하기 위한 AI 도구입니다","es":"Un plugin de Figma es una extensión que amplía la funcionalidad del software de diseño gráfico","fr":"Un plugin Figma est une extension qui élargit les fonctionnalités du logiciel de conception graphique","de":"Ein Figma-Plugin ist eine Erweiterung, die die Funktionalität der Grafikdesign-Software erweitert","pt":"O plugin do Figma é uma ferramenta que permite estender a funcionalidade do Figma.","ru":"Плагин Figma - это инструмент, который позволяет расширить функциональность Figma.","ar":"إضافة فيجما هي أداة تسمح بتعزيز وظيفة فيجما."},"features":{"en":["Follows ES5 syntax for compatibility","Adheres to two-context boundary for efficient development","Avoids common pitfalls as outlined in CLAUDE.md","Utilizes API recipes and theming as described in AGENTS.md","Supports manifest fields for plugin configuration","Enables phase-based workflow for streamlined development"],"zh":["支持ES5语法","提供两种上下文边界","包含常见的陷阱和解决方案","提供API配方和主题设置","支持manifest字段设置"],"ja":["ES5構文をサポート","2つのコンテキスト境界を提供","一般的な落とし穴と解決策を含む","APIレシピとテーマ設定を提供","マニフェストフィールド設定をサポート"],"ko":["ES5 구문을 지원","2개의 컨텍스트 경계를 제공","일반적인 함정과 해결책을 포함","API 레시피와 테마 설정을 제공","매니페스트 필드 설정을 지원"],"es":["Plantilla de inicio de Figma Plugin con cero pasos de compilación","Compatibilidad con ES5 syntax","Soporte para dos contextos de límite","Recursos para evitar trampas comunes","API recipes y campos de manifiesto"],"fr":["Modèle de démarrage de Figma Plugin avec zéro étape de compilation","Compatibilité avec la syntaxe ES5","Prise en charge de deux contextes de limite","Ressources pour éviter les pièges courants","Recettes d''API et champs de manifeste"],"de":["Startvorlage für Figma-Plugin mit null Kompilierungsschritten","Unterstützung für ES5-Syntax","Unterstützung für zwei Kontextgrenzen","Ressourcen zur Vermeidung von häufigen Fallen","API-Rezepte und Manifestfelder"],"pt":["Suporte a sintaxe ES5","Manifest fields personalizáveis","Integração com a API do Figma","Modelo de configuração zero-build-step","Compatibilidade com vários contextos"],"ru":["Поддержка синтаксиса ES5","Поля манифеста настраиваемые","Интеграция с API Figma","Конфигурационный шаблон с нулевым шагом сборки","Совместимость с несколькими контекстами"],"ar":["دعم بناء الجملة ES5","حقول الملف التفسيري قابلة للتخصيص","التكامل مع واجهة برمجة التطبيقات فيجما","نموذج الضبط بخطوة بناء صفر","التوافق مع سياقات متعددة"]},"keywords":{"en":["how to use figma-plugin","figma-plugin setup guide","what is figma-plugin","figma-plugin alternative","figma-plugin vs Adobe XD","figma-plugin install","zero-build-step Figma plugin scaffold","Figma plugin development best practices","ES5 syntax for Figma plugins"],"zh":["Figma插件开发","AIエージェント工具","零构建步骤","ES5语法","Figma插件设置","Figma插件开发教程","Figma插件开发最佳实践"],"ja":["Figmaプラグイン開発","AIエージェントツール","ゼロビルドステップ","ES5構文","Figmaプラグイン設定","Figmaプラグイン開発チュートリアル","Figmaプラグイン開発ベストプラクティス"],"ko":["피그마 플러그인 개발","AI 도구","제로 빌드 스텝","ES5 구문","피그마 플러그인 설정","피그마 플러그인 개발 튜토리얼","피그마 플러그인 개발 가이드"],"es":["figma plugin","desarrollo de plugins","configuración de plugins","ai para diseño gráfico","herramientas de diseño","recursos para desarrolladores","plantilla de inicio de figma","es5 syntax"],"fr":["figma plugin","développement de plugins","configuration de plugins","ia pour conception graphique","outils de conception","ressources pour les développeurs","modèle de démarrage de figma","syntaxe es5"],"de":["figma plugin","entwicklung von plugins","konfiguration von plugins","ki für grafikdesign","design-tools","ressourcen für entwickler","startvorlage für figma","es5 syntax"],"pt":["figma plugin","desenvolvimento de plugin","configuração do figma","ES5 syntax","manifest fields","API do Figma","modelo de configuração","zero-build-step"],"ru":["плагин Figma","разработка плагина","настройка Figma","синтаксис ES5","поля манифеста","API Figma","конфигурационный шаблон","нулевой шаг сборки"],"ar":["إضافة فيجما","تطوير الإضافة","ضبط فيجما","بناء الجملة ES5","حقول الملف التفسيري","واجهة برمجة التطبيقات فيجما","نموذج الضبط","خطوة بناء صفر"]}},"owner":"verygoodmurph","repo":"figma-plugin-starter","repoPath":"verygoodmurph/figma-plugin-starter","stars":0,"forks":0,"updatedAt":"2026-03-07T20:05:29Z","topics":["ai-enabled","figma-plugin"],"category":"community","skillMd":{"name":"figma-plugin","description":">","bodyPreview":"# Figma Plugin Development\n\nYou are an expert Figma plugin developer. This starter template is a zero-build-step Figma plugin scaffold. Your job is to help users go from idea to working plugin.\n\n## Rules & Patterns\n\nAll rules (ES5 syntax, two-context boundary, pitfalls) are in **CLAUDE.md** (always loaded).\nAll code patterns (API recipes, theming, manifest fields) are in **AGENTS.md** — read it before implementing.\n\n## Workflow\n\nFollow the phase that matches what the user is asking for. If they","body":"# Figma Plugin Development\n\nYou are an expert Figma plugin developer. This starter template is a zero-build-step Figma plugin scaffold. Your job is to help users go from idea to working plugin.\n\n## Rules & Patterns\n\nAll rules (ES5 syntax, two-context boundary, pitfalls) are in **CLAUDE.md** (always loaded).\nAll code patterns (API recipes, theming, manifest fields) are in **AGENTS.md** — read it before implementing.\n\n## Workflow\n\nFollow the phase that matches what the user is asking for. If they have a new idea with no spec, start at Phase 1. If they already have a SPEC.md filled out, skip to Phase 2. If they want to add a feature to an existing plugin, go to Phase 3.\n\n---\n\n### Phase 1: Spec Out the Plugin\n\nUse this when the user has a plugin idea but no specification yet.\n\n**Goal:** Produce a complete `SPEC.md` that''s detailed enough to build from.\n\n1. Read the current `SPEC.md`, `code.js`, `ui.html`, and `manifest.json` to understand the starting point.\n\n2. Interview the user. Ask focused questions across these areas — skip anything already obvious from context:\n   - **Core purpose:** What does the plugin do? What problem does it solve?\n   - **Target workflow:** What''s the user''s step-by-step interaction with the plugin?\n   - **UI layout:** What controls, displays, or panels does the plugin need? Approximate dimensions?\n   - **Figma API surface:** Which Figma APIs are needed? (selection, variables, styles, text, nodes, etc.)\n   - **Data flow:** What data moves between code.js and ui.html? What message types are needed?\n   - **External dependencies:** Does it need network access? What domains?\n   - **Edge cases:** What happens with empty selection, wrong node types, missing fonts, large documents?\n   - **Persistence:** Does it need to store data? (clientStorage for user prefs, pluginData for per-node data)\n\n3. Ask questions iteratively — follow up on answers, don''t dump everything at once. Stop when you have enough to build.\n\n4. Write the complete specification to `SPEC.md` with these sections:\n\n```markdown\n# [Plugin Name] — Specification\n\n## Overview\nOne paragraph describing what the plugin does and why.\n\n## Features\nNumbered list of everything the plugin does.\n\n## UI Layout\nDescription of the interface. Include dimensions (width x height).\nDescribe each section, control, and interactive element.\n\n## Architecture\n\n### Message Passing Protocol\nTable of all message types:\n| Direction | Type | Data | Purpose |\n|-----------|------|------|---------|\n\n### Code Context (code.js)\nWhat the plugin thread does: event listeners, API calls, data processing.\n\n### UI Context (ui.html)\nWhat the UI does: rendering, user interaction, message sending.\n\n## Figma API Usage\nWhich APIs are used and why.\n\n## Manifest Configuration\nAny changes needed to manifest.json (permissions, capabilities, domains).\n\n## Edge Cases & Error Handling\nHow to handle each failure mode.\n\n## Accessibility\nKeyboard navigation, ARIA labels, focus management.\n```\n\n---\n\n### Phase 2: Build From Spec\n\nUse this when `SPEC.md` is filled out and the user wants to build the plugin.\n\n**Goal:** Transform the starter template into a working plugin matching the spec.\n\n1. Read `SPEC.md` thoroughly. Read `AGENTS.md` for API patterns and best practices.\n\n2. Plan the implementation: message types, API calls, UI components, build order.\n\n3. Update `manifest.json` — name, id, editorType, permissions, capabilities, allowedDomains.\n\n4. Implement `code.js` — showUI, event listeners, message handlers, API calls, error handling.\n\n5. Implement `ui.html` — HTML structure, Figma CSS tokens, interactivity, message passing, loading/error states.\n\n6. Validate:\n   - Every message type in the spec has a sender AND receiver\n   - Every Figma API call is wrapped in try-catch\n   - Selection is checked before accessing `selection[0]`\n   - Fonts are loaded before setting text\n   - UI works in both light and dark theme\n   - No `?.` or `??` in code.js\n\n---\n\n### Phase 3: Add a Feature\n\nUse this when the user wants to add functionality to an existing plugin.\n\n1. Read the current `code.js`, `ui.html`, and `manifest.json` to understand what exists.\n\n2. Discuss the feature with the user: what it does, how it''s triggered, what APIs it needs, any new message types.\n\n3. Create a `SPEC-FEATURE-<NAME>.md` file documenting the feature (kebab-case name).\n\n4. Implement: add message types to both contexts, new UI elements, new API calls with error handling, update manifest if needed.\n\n5. Verify the feature works without breaking existing functionality.\n"},"lastSynced":"2026-03-08T02:14:16.663Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Agents needing streamlined Figma plugin development with zero-build-step scaffolding.","zh":"非常适合需要简化Figma插件开发且无需构建步骤的UI/UX代理","ja":"UI/UXエージェントがFigmaプラグイン開発をストリームライン化し、ビルド手順をゼロにしたい場合に最適","ko":"UI/UX 에이전트가 피그마 플러그인 개발을 간소화하고 빌드 단계를 제로로 하는 데 적합합니다.","es":"Perfecto para agentes de UI/UX que necesitan un desarrollo de plugins de Figma optimizado con estructura de scaffolding sin paso de compilación.","fr":"Parfait pour les agents UI/UX ayant besoin d''un développement de plugins Figma rationalisé avec une structure de scaffolding sans étape de construction.","de":"Perfekt für UI/UX-Agents, die ein optimiertes Figma-Plugin-Entwicklungserlebnis mit Zero-Build-Schritt-Scaffolding benötigen.","pt":"Perfeito para Agentes UI/UX que necesitam desenvolvimento de plugins Figma com estrutura de scaffolding sem passos de compilação.","ru":"Идеально для агентов UI/UX, которым требуется разработка плагинов Figma с упрощенной системой скелетного каркаса без этапов сборки.","ar":"مثالي للوكلاء UI/UX الذين يحتاجون إلى تطوير الإضافات Figma مع هيكل السقالة بدون خطوات بناء."},"recommendation":{"en":"Empowers agents to rapidly create custom Figma plugins using ES5 syntax, leveraging API recipes and theming, while avoiding common pitfalls outlined in CLAUDE.md and AGENTS.md, facilitating efficient manifest field management.","zh":"赋予代理快速创建自定义Figma插件的能力，使用ES5语法，利用API食谱和主题，同时避免CLAUDE.md和AGENTS.md中概述的常见陷阱，实现高效的清单字段管理","ja":"エージェントがES5構文を使用して、APIレシピとテーミングを活用し、CLAUDE.mdとAGENTS.mdに概説されている一般的な落とし穴を回避しながら、カスタムFigmaプラグインを迅速に作成できるようにする","ko":"에이전트가 ES5 구문을 사용하여 API 레시피 및 테마를 활용하고 CLAUDE.md 및 AGENTS.md에 설명된 일반적인 함정을 피하면서 사용자 지정 피그마 플러그인을 신속하게 만들 수 있도록 합니다.","es":"Habilita a los agentes a crear rápidamente plugins personalizados de Figma utilizando la sintaxis ES5, aprovechando las recetas de API y el tema, y evitando las trampas comunes descritas en CLAUDE.md y AGENTS.md, facilitando una gestión eficiente de los campos de manifiesto.","fr":"Permet aux agents de créer rapidement des plugins Figma personnalisés en utilisant la syntaxe ES5, en exploitant les recettes d''API et le thème, tout en évitant les pièges courants décrits dans CLAUDE.md et AGENTS.md, facilitant une gestion efficace des champs de manifeste.","de":"Ermöglich es den Agenten, benutzerdefinierte Figma-Plugins mit der ES5-Syntax schnell zu erstellen, indem sie API-Rezepte und Themen nutzen und gemeinsame Fallstricke vermeiden, die in CLAUDE.md und AGENTS.md beschrieben sind, und erleichtert so eine effiziente Verwaltung der Manifestfelder.","pt":"Habilita os agentes a criar rapidamente plugins personalizados Figma usando sintaxe ES5, aproveitando receitas de API e tema, enquanto evitam armadilhas comuns descritas em CLAUDE.md e AGENTS.md, facilitando a gestão eficiente dos campos de manifesto.","ru":"Наделяет агентов возможностью быстро создавать пользовательские плагины Figma, используя синтаксис ES5, опираясь на рецепты API и темизацию, а также избегая распространенных ошибок, описанных в CLAUDE.md и AGENTS.md, обеспечивая эффективное управление полями манифеста.","ar":"يمنح الوكلاء khảية إنشاء الإضافات المخصصة Figma بسرعة باستخدام بناء الجملة ES5، واستخدام وصفات API والتهيئة، مع تجنب الفخاخ الشائعة الموضحة في CLAUDE.md و AGENTS.md، وتسهيل إدارة الحقول الفعالة للبيان."},"useCases":{"en":["Streamlining Figma plugin development for expert developers","Creating custom plugins with zero-build-step scaffolding","Implementing API recipes and theming for enhanced plugin functionality"],"zh":["为专家开发人员简化Figma插件开发","使用零构建步骤的脚手架创建自定义插件","实现API食谱和主题以增强插件功能"],"ja":["エキスパート開発者向けのFigmaプラグイン開発のストリームライン化","ゼロビルドステップのスキャフォールディングを使用したカスタムプラグインの作成","APIレシピとテーミングの実装によるプラグイン機能の強化"],"ko":["전문 개발자를 위한 피그마 플러그인 개발의 간소화","제로 빌드 단계 스캐폴딩을 사용한 사용자 지정 플러그인 생성","API 레시피 및 테마 구현을 통한 플러그인 기능 향상"],"es":["Optimizar el desarrollo de plugins de Figma para desarrolladores expertos","Crear plugins personalizados con estructura de scaffolding sin paso de compilación","Implementar recetas de API y temas para una funcionalidad mejorada de los plugins"],"fr":["Rationaliser le développement de plugins Figma pour les développeurs experts","Créer des plugins personnalisés avec une structure de scaffolding sans étape de construction","Mettre en œuvre des recettes d''API et des thèmes pour améliorer la fonctionnalité des plugins"],"de":["Optimieren der Figma-Plugin-Entwicklung für erfahrene Entwickler","Erstellen benutzerdefinierter Plugins mit Zero-Build-Schritt-Scaffolding","Implementieren von API-Rezepten und Themen für eine verbesserte Plugin-Funktionalität"],"pt":["Otimização do desenvolvimento de plugins Figma para desenvolvedores experientes","Criação de plugins personalizados com estrutura de scaffolding sem passos de compilação","Implementação de receitas de API e tema para funcionalidade de plugin aprimorada"],"ru":["Оптимизация разработки плагинов Figma для опытных разработчиков","Создание пользовательских плагинов с системой скелетного каркаса без этапов сборки","Реализация рецептов API и темизации для расширенной функциональности плагина"],"ar":["تحسين تطوير الإضافات Figma للمطورين الخبراء","إنشاء الإضافات المخصصة بهيكل السقالة بدون خطوات بناء","تنفيذ وصفات API والتهيئة لتحسين وظيفة الإضافة"]},"limitations":{"en":["Requires knowledge of ES5 syntax","Adherence to two-context boundary rules","Figma plugin development expertise"],"zh":["需要ES5语法知识","遵守两个上下文边界规则","Figma插件开发专业知识"],"ja":["ES5構文の知識が必要","2つのコンテキスト境界規則の遵守","Figmaプラグイン開発の専門知識"],"ko":["ES5 구문 지식 필요","2개 컨텍스트 경계 규칙 준수","피그마 플러그인 개발 전문 지식"],"es":["Requiere conocimiento de la sintaxis ES5","Cumplimiento de las reglas de límite de dos contextos","Experiencia en desarrollo de plugins de Figma"],"fr":["Nécessite une connaissance de la syntaxe ES5","Respect des règles de limite de deux contextes","Expertise dans le développement de plugins Figma"],"de":["Benötigt Kenntnisse der ES5-Syntax","Befolgung der Regeln für die Zwei-Kontext-Grenze","Erfahrung in der Entwicklung von Figma-Plugins"],"pt":["Exige conhecimento de sintaxe ES5","Adesão às regras de limite de dois contextos","Experiência em desenvolvimento de plugins Figma"],"ru":["Требует знания синтаксиса ES5","Соблюдение правил двухконтекстной границы","Опыт разработки плагинов Figma"],"ar":["يتطلب معرفة بناء الجملة ES5","الامتثال لقواعد الحدود الثنائية","خبرة في تطوير الإضافات Figma"]},"version":4},"contentHash":"a9314fed4926c767d4aabc9dc532a108d5b0a2cb64a833d4a961d63dc5e6b512","qualityScore":39}');
