INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('verygoodmurph/figma-plugin-starter/figma-plugin', 'figma-plugin', 'verygoodmurph', 'figma-plugin-starter', 'community', 'figma-plugin verygoodmurph figma-plugin-starter community ai-enabled figma-plugin The figma-plugin skill provides a zero-build-step Figma plugin scaffold for expert developers, streamlining the process from idea to working plugin. It benefits developers looking to create custom Figma plugins. Figma插件开发模板，提供零构建步骤的Figma插件开发环境 Figmaプラグイン開発テンプレート、ゼロビルドステップのFigmaプラグイン開発環境を提供 피그마 플러그인 개발 템플릿, 제로 빌드 스텝의 피그마 플러그인 개발 환경을 제공 Desarrolla plugins de Figma con nuestra plantilla de inicio y recursos técnicos. Aprende a crear plugins desde cero. Développez des plugins Figma avec notre modèle de démarrage et des ressources techniques. Apprenez à créer des plugins desde zéro. Entwickeln Sie Figma-Plugins mit unserer Startvorlage und technischen Ressourcen. Lernen Sie, Plugins von Grund auf zu erstellen. Desenvolva plugins do Figma com facilidade usando este modelo de configuração. Aprenda a criar plugins com ES5 syntax e manifest fields. Разрабатывайте плагины Figma легко с помощью этого конфигурационного шаблона. Узнайте, как создавать плагины с синтаксисом ES5 и полями манифеста. قُم بتطوير إضافات فيجما بسهولة باستخدام هذا النموذج الضبط. تعلم كيفية إنشاء الإضافات باستخدام بناء الجملة ES5 وحقول الملف التفسيري. how to use figma-plugin figma-plugin setup guide what is figma-plugin figma-plugin alternative figma-plugin vs Adobe XD figma-plugin install zero-build-step Figma plugin scaffold Figma plugin development best practices ES5 syntax for Figma plugins Figma插件开发 AIエージェント工具 零构建步骤 ES5语法 Figma插件设置 Figma插件开发教程 Figma插件开发最佳实践 Follows ES5 syntax for compatibility Adheres to two-context boundary for efficient development Avoids common pitfalls as outlined in CLAUDE.md Utilizes API recipes and theming as described in AGENTS.md Supports manifest fields for plugin configuration Enables phase-based workflow for streamlined development figma-plugin is a starter template for building Figma plugins, following specific rules and patterns outlined in CLAUDE.md and AGENTS.md files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JetBrains/intellij-community/registry', 'community', 'JetBrains', 'intellij-community', 'JetBrains/intellij-community', 'registry', 0, 0, 39, '2026-03-07T12:46:33.563Z', '2026-03-07T12:57:28.875Z', 'a04e0dab80539e6fc7269ac8bf9faf8c023f0a90382d895ed19966dd61870853', '{"id":"JetBrains/intellij-community/registry","name":"registry","description":{"en":"The registry skill provides guidelines for using the IntelliJ Registry API, benefiting developers working with IntelliJ IDEA and Platform. It offers documentation on defining registry keys and cloud registry updates","zh":"IntelliJ IDEA 和 IntelliJ Platform 的注册表设置指南，包括 Registry API 的使用和注册表键的定义","ja":"IntelliJ IDEA と IntelliJ Platform のレジストリ設定ガイド。レジストリ API の使用方法とレジストリ キーの定義を含みます","ko":"IntelliJ IDEA 및 IntelliJ Platform의 레지스트리 설정 가이드입니다. 레지스트리 API 사용법과 레지스트리 키 정의를 포함합니다","es":"El registro de IntelliJ es un sistema que permite a los desarrolladores declarar claves y configurar la plataforma. Aprende a utilizar la API de registro y a declarar claves en plugin.xml o registry.properties.","fr":"Le registre d''IntelliJ est un système qui permet aux développeurs de déclarer des claves et de configurer la plateforme. Apprenez à utiliser l''API de registre et à déclarer des claves dans plugin.xml ou registry.properties.","de":"Das Registrierungssystem von IntelliJ ist ein System, das es Entwicklern ermöglicht, Schlüssel zu deklarieren und die Plattform zu konfigurieren. Erfahren Sie, wie Sie die Registrierungs-API verwenden und Schlüssel in plugin.xml oder registry.properties deklarieren.","pt":"O Registro do IntelliJ é uma API que permite declarar chaves em plugin.xml ou registry.properties, e também suporta atualizações de registro remoto","ru":"Регистр IntelliJ - это API, который позволяет определять ключи в plugin.xml или registry.properties, и также поддерживает удаленные обновления реестра","ar":"سجل IntelliJ هو واجهة برمجة تطبيقات تسمح بتعريف المفاتيح في plugin.xml أو registry.properties، ويدعم أيضًا تحديثات السجل عن بُعد"},"seo":{"title":{"en":"Registry: Setup Guide for IntelliJ IDEA & Platform | AI A...","zh":"注册表 Setup Guide - IntelliJ IDEA 和 IntelliJ Platform","ja":"レジストリ Setup Guide - IntelliJ IDEA と IntelliJ Platform の A...","ko":"레지스트리 설정 가이드 - IntelliJ IDEA 및 IntelliJ Platform","es":"Guía de configuración del registro de IntelliJ","fr":"Guide de démarrage rapide pour le registre d''IntelliJ","de":"Einrichtungsleitfaden für das IntelliJ-Registrierungssystem","pt":"Guia de Configuração do Registro do IntelliJ","ru":"Настройка Регистра IntelliJ: Лучшие Практики","ar":"دليل إعداد سجل IntelliJ IDEA"},"description":{"en":"Unlock the full potential of IntelliJ IDEA and Platform with our registry setup guide. Learn how to define registry keys and leverage cloud registry updates ...","zh":"了解如何使用 IntelliJ Registry API 并设置注册表，以提高开发效率。查看我们的文档和快速参考指南","ja":"IntelliJ Registry API を使用してレジストリを設定する方法を学び、開発効率を向上させましょう。ドキュメントとクイックリファレンスガイドをご覧ください","ko":"IntelliJ Registry API를 사용하여 레지스트리를 설정하는 방법을 배우고 개발 효율성을 향상시키세요. 문서와 빠른 참조 가이드를 확인하세요","es":"Aprende a trabajar con el registro de IntelliJ IDEA y la plataforma IntelliJ. Descubre cómo declarar claves y utilizar la API de registro.","fr":"Découvrez comment utiliser le registre d''IntelliJ IDEA et de la plateforme IntelliJ. Apprenez à déclarer des clés et à utiliser l''API de registre.","de":"Erfahren Sie, wie Sie mit dem Registrierungssystem von IntelliJ IDEA und der IntelliJ-Plattform arbeiten. Entdecken Sie, wie Sie Schlüssel deklarieren und di...","pt":"Aprenda a trabalhar com o Registro do IntelliJ IDEA e Platform, incluindo definição de chaves e atualizações de registro remoto","ru":"Изучите возможности Регистра IntelliJ IDEA и Platform, включая определение ключей и обновления удаленного реестра","ar":"تعرف على كيفية العمل مع سجل IntelliJ IDEA و Platform، بما في ذلك تعريف المفاتيح وتحديثات السجل عن بُعد"},"definition":{"en":"Registry is a mechanism for storing and retrieving configuration data in IntelliJ IDEA and Platform, allowing developers to customize and extend the functionality of their IDE","zh":"注册表是 IntelliJ IDEA 和 IntelliJ Platform 中用于存储配置和设置的仓库","ja":"レジストリは、IntelliJ IDEA と IntelliJ Platform でコンフィギュレーションと設定を保存するためのリポジトリです","ko":"레지스트리는 IntelliJ IDEA 및 IntelliJ Platform에서 설정과 구성 정보를 저장하기 위한 저장소입니다","es":"El registro de IntelliJ es un sistema de configuración que permite a los desarrolladores declarar claves y personalizar la plataforma.","fr":"Le registre d''IntelliJ est un système de configuration qui permet aux développeurs de déclarer des claves et de personnaliser la plateforme.","de":"Das Registrierungssystem von IntelliJ ist ein Konfigurationssystem, das es Entwicklern ermöglicht, Schlüssel zu deklarieren und die Plattform anzupassen.","pt":"O Registro do IntelliJ é uma API que gerencia configurações e preferências","ru":"Регистр IntelliJ - это API, который управляет настройками и предпочтениями","ar":"سجل IntelliJ هو واجهة برمجة تطبيقات لإدارة الإعدادات والتفضيلات"},"features":{"en":["Declaring registry keys in plugin.xml or registry.properties","Leveraging cloud registry updates for remote configuration management","Using the IntelliJ Registry API for customized development","Defining registry keys for personalized IDE settings","Accessing cloud registry and notifications for JetBrains IDEs","Utilizing Registry.md and Cloud Registry and Notifications.md documentation for guided setup"],"zh":["使用 Registry API 定义注册表键","在 plugin.xml 或 registry.properties 中声明注册表键","支持云注册表和远程更新","快速参考指南用于注册表键的定义"],"ja":["レジストリ API を使用してレジストリ キーを定義する","plugin.xml または registry.properties でレジストリ キーを宣言する","クラウド レジストリとリモート更新のサポート","レジストリ キーの定義用のクイック リファレンス ガイド"],"ko":["레지스트리 API를 사용하여 레지스트리 키를 정의","plugin.xml 또는 registry.properties에서 레지스트리 키를 선언","클라우드 레지스트리 및 원격 업데이트를 지원","레지스트리 키 정의를 위한 빠른 참조 가이드"],"es":["Declaración de claves en plugin.xml o registry.properties","Uso de la API de registro para configurar la plataforma","Compatibilidad con IntelliJ IDEA y la plataforma IntelliJ","Actualizaciones remotas del registro para JetBrains IDEs","Documentación detallada para el uso del registro","Soporte para la nube y notificaciones"],"fr":["Déclaration de clés dans plugin.xml ou registry.properties","Utilisation de l''API de registre pour configurer la plateforme","Compatibilité avec IntelliJ IDEA et la plateforme IntelliJ","Mises à jour à distance du registre pour les IDE JetBrains","Documentation détaillée pour l''utilisation du registre","Prise en charge de la cloud et des notifications"],"de":["Deklaration von Schlüsseln in plugin.xml oder registry.properties","Verwendung der Registrierungs-API zur Konfiguration der Plattform","Kompatibilität mit IntelliJ IDEA und der IntelliJ-Plattform","Remote-Updates des Registrierungssystems für JetBrains-IDEs","Detaillierte Dokumentation für die Verwendung des Registrierungssystems","Unterstützung für die Cloud und Benachrichtigungen"],"pt":["Definição de chaves em plugin.xml ou registry.properties","Suporte a atualizações de registro remoto","Integração com a plataforma IntelliJ","Utilização da API do Registro para gerenciar configurações","Compatibilidade com o IntelliJ IDEA e outras IDEs"],"ru":["Определение ключей в plugin.xml или registry.properties","Поддержка удаленных обновлений реестра","Интеграция с платформой IntelliJ","Использование API Регистра для управления настройками","Совместимость с IntelliJ IDEA и другими IDE"],"ar":["تعريف المفاتيح في plugin.xml أو registry.properties","دعم تحديثات السجل عن بُعد","التكامل مع منصة IntelliJ","استخدام واجهة برمجة تطبيقات السجل لإدارة الإعدادات","التوافق مع IntelliJ IDEA وواجهات التطوير المتكاملة الأخرى"]},"keywords":{"en":["how to use registry in IntelliJ","what is registry in IntelliJ IDEA","registry setup guide for IntelliJ Platform","intellij registry api documentation","cloud registry updates for jetbrains ide","registry vs preferences in intellij","registry install for intellij idea","intellij registry alternative","registry configuration for intellij platform"],"zh":["IntelliJ IDEA 注册表","IntelliJ Platform 注册表","Registry API","注册表键","plugin.xml","registry.properties","云注册表","AI 工具"],"ja":["IntelliJ IDEA レジストリ","IntelliJ Platform レジストリ","レジストリ API","レジストリ キー","plugin.xml","registry.properties","クラウド レジストリ","AI エージェント"],"ko":["IntelliJ IDEA 레지스트리","IntelliJ Platform 레지스트리","레지스트리 API","레지스트리 키","plugin.xml","registry.properties","클라우드 레지스트리","AI 도구"],"es":["registro de IntelliJ","API de registro","plugin.xml","registry.properties","IntelliJ IDEA","plataforma IntelliJ","desarrollo de plugins","configuración de la plataforma","actualizaciones remotas del registro"],"fr":["registre d''IntelliJ","API de registre","plugin.xml","registry.properties","IntelliJ IDEA","plateforme IntelliJ","développement de plugins","configuration de la plateforme","mises à jour à distance du registre"],"de":["Registrierungssystem von IntelliJ","Registrierungs-API","plugin.xml","registry.properties","IntelliJ IDEA","IntelliJ-Plattform","Plug-in-Entwicklung","Plattformkonfiguration","Remote-Updates des Registrierungssystems"],"pt":["IntelliJ Registro","Registro do IntelliJ IDEA","API do Registro","Definição de chaves","Atualizações de registro remoto","Integração com plataforma IntelliJ","Gerenciamento de configurações","Desenvolvimento de plugins"],"ru":["Регистр IntelliJ","Регистр IntelliJ IDEA","API Регистра","Определение ключей","Удаленные обновления реестра","Интеграция с платформой IntelliJ","Управление настройками","Разработка плагинов"],"ar":["سجل IntelliJ","سجل IntelliJ IDEA","واجهة برمجة تطبيقات السجل","تعريف المفاتيح","تحديثات السجل عن بُعد","التكامل مع منصة IntelliJ","إدارة الإعدادات","تطوير البرامج المساعدة"]}},"owner":"JetBrains","repo":"intellij-community","repoPath":"JetBrains/intellij-community","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.563Z","topics":[],"category":"community","skillMd":{"name":"registry","description":"Guidelines for using the IntelliJ Registry API. Use when working with registry keys or feature flags.","bodyPreview":"# Working with Registry\n\nGuidelines for using the IntelliJ Registry API.\n\n## Documentation\n\n- **Defining Registry Keys**: [Registry.md](../docs/IntelliJ-Platform/4_man/Registry.md) - How to declare keys in `plugin.xml` or `registry.properties`\n- **Cloud Registry**: [Cloud Registry and Notifications.md](../docs/IntelliJ-Platform/4_man/Cloud%20Registry%20and%20Notifications.md) - Remote registry updates for JetBrains IDEs\n\n## Quick Reference\n\n### Defining a Registry Key\n\nAlways prefer declaring in","body":"# Working with Registry\n\nGuidelines for using the IntelliJ Registry API.\n\n## Documentation\n\n- **Defining Registry Keys**: [Registry.md](../docs/IntelliJ-Platform/4_man/Registry.md) - How to declare keys in `plugin.xml` or `registry.properties`\n- **Cloud Registry**: [Cloud Registry and Notifications.md](../docs/IntelliJ-Platform/4_man/Cloud%20Registry%20and%20Notifications.md) - Remote registry updates for JetBrains IDEs\n\n## Quick Reference\n\n### Defining a Registry Key\n\nAlways prefer declaring in `plugin.xml` (not `registry.properties`):\n\n```xml\n<registryKey key=\"my.feature.enabled\"\n             defaultValue=\"true\"\n             description=\"Enables my feature\"\n             restartRequired=\"false\"/>\n```\n\nTo override in a dependent plugin:\n```xml\n<registryKey key=\"my.feature.enabled\"\n             defaultValue=\"false\"\n             description=\"Enables my feature\"\n             restartRequired=\"false\"\n             overrides=\"true\"/>\n```\n\n### Accessing the Registry\nIn suspending code:\n```kotlin\nval isEnabled = RegistryManager.getInstanceAsync().get(\"my.key\")\n```\n\nIn blocking code:\n```kotlin\nval isEnabled = RegistryManager.getInstance().get(\"my.key\")\n```\n\nAccess via `Registry.get()` or `Registry.is()` is effectively deprecated, since it might cause problems during early IDE startup.\nAlways prefer the `RegistryManager` when possible.\n\n### Early Startup: Registry.is() with Default Value\n\nWhen code may run before `COMPONENTS_LOADED` state (e.g., during EULA dialog, splash screen),\nyou MUST use `Registry.is(key, defaultValue)` with an explicit default:\n\n```kotlin\n// Required for early startup code\nRegistry.`is`(\"my.key\", false)  // default must match registry.properties\n```\n\n**How to find the default value:**\n1. Search in `community/platform/util/resources/misc/registry.properties`\n2. Or check the `<registryKey>` declaration in `plugin.xml`\n\n**Why:** `Registry.is(key)` without default throws an exception if called before\n`LoadingState.COMPONENTS_LOADED`. The safe overload returns the provided default\nwhen Registry is not yet initialized.\n\n### Override via Command Line\n\nFor testing or run configurations:\n```\n-Dmy.registry.key=value\n```\n\n## Registry in Tests\n\nUse `@RegistryKey` annotation instead of `Registry.get().setValue()`:\n\n```kotlin\n@Test\n@RegistryKey(key = \"my.registry.key\", value = \"true\")\nfun testWithRegistryEnabled() { ... }\n```\n\nSee [writing-tests.md](../writing-tests/SKILL.md#registry-values-in-tests) for more test patterns.\n"},"lastSynced":"2026-03-07T12:57:28.875Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents working with IntelliJ IDEA and Platform, needing to leverage the IntelliJ Registry API for efficient plugin development.","zh":"适用于使用IntelliJ IDEA和Platform的开发者代理，需要利用IntelliJ Registry API进行高效的插件开发。","ja":"IntelliJ IDEAおよびPlatformを使用する開発者エージェントに適しています。IntelliJ Registry APIを利用して効率的なプラグイン開発を行う必要があります。","ko":"IntelliJ IDEA 및 Platform을 사용하는 개발자 에이전트에게 적합하며, 효율적인 플러그인 개발을 위해 IntelliJ Registry API를 활용해야 합니다.","es":"Ideal para Agentes de Desarrollador que trabajan con IntelliJ IDEA y Plataforma, necesitando aprovechar la API del Registro de IntelliJ para un desarrollo de plugins eficiente.","fr":"Idéal pour les Agents de Développeur travaillant avec IntelliJ IDEA et Plateforme, ayant besoin d''utiliser l''API du Registre IntelliJ pour un développement de plugins efficace.","de":"Ideal für Entwicklungsagenten, die mit IntelliJ IDEA und Plattform arbeiten und die IntelliJ-Registrierungs-API für eine effiziente Plug-in-Entwicklung nutzen müssen.","pt":"Ideal para Agentes de Desenvolvedor que trabalham com IntelliJ IDEA e Plataforma, necessitando utilizar a API do Registro do IntelliJ para um desenvolvimento de plugin eficiente.","ru":"Идеально для агентов-разработчиков, работающих с IntelliJ IDEA и Платформой, нуждающихся в использовании API реестра IntelliJ для эффективного разработки плагинов.","ar":"مثالي للوكلاء المطورين العاملين مع IntelliJ IDEA والمنصة، والذين يحتاجون إلى الاستفادة من واجهة برمجة تطبيقات سجل IntelliJ من أجل تطوير البرامج الإضافية بفعالية."},"recommendation":{"en":"Empowers agents to define registry keys and manage cloud registry updates seamlessly, utilizing `plugin.xml` and `registry.properties` files, and integrating with JetBrains IDEs for remote registry updates.","zh":"赋予代理定义注册表键并管理云注册表更新的能力，无缝地利用`plugin.xml`和`registry.properties`文件，并与JetBrains IDE集成以进行远程注册表更新。","ja":"エージェントがレジストリキーを定義し、クラウドレジストリの更新を管理する機能を提供します。`plugin.xml`と`registry.properties`ファイルを利用して、JetBrains IDEと統合してリモートレジストリの更新を行うことができます。","ko":"에이전트가 레지스트리 키를 정의하고 클라우드 레지스트리 업데이트를 관리할 수 있는 능력을 부여합니다. `plugin.xml` 및 `registry.properties` 파일을 활용하여 JetBrains IDE와 통합하여 원격 레지스트리 업데이트를 수행할 수 있습니다.","es":"Habilita a los agentes a definir claves de registro y gestionar actualizaciones de registro en la nube de forma fluida, utilizando archivos `plugin.xml` y `registry.properties`, e integrándose con los IDE de JetBrains para actualizaciones de registro remoto.","fr":"Permet aux agents de définir des clés de registre et de gérer les mises à jour du registre cloud de manière transparente, en utilisant les fichiers `plugin.xml` et `registry.properties`, et en s''intégrant avec les IDE de JetBrains pour les mises à jour de registre à distance.","de":"Ermöglicht es Agenten, Registrierungsschlüssel zu definieren und Cloud-Registrierungsaktualisierungen nahtlos zu verwalten, indem sie die Dateien `plugin.xml` und `registry.properties` verwenden und sich in die JetBrains-IDEs für Remote-Registrierungsaktualisierungen integrieren.","pt":"Habilita os agentes a definir chaves de registro e gerenciar atualizações de registro de nuvem de forma transparente, utilizando arquivos `plugin.xml` e `registry.properties`, e integrando-se com IDEs da JetBrains para atualizações de registro remoto.","ru":"Наделяет агентов возможностью определять ключи реестра и управлять обновлениями облачного реестра бесшовно, используя файлы `plugin.xml` и `registry.properties`, и интегрируясь с IDE от JetBrains для удаленных обновлений реестра.","ar":"تمكّن الوكلاء من تعريف مفاتيح السجل وإدارة تحديثات السجل السحابي بطريقة متسلسلة، واستخدام ملفات `plugin.xml` و `registry.properties`، والدمج مع بيئات تطوير JetBrains من أجل تحديثات سجل عن بُعد."},"useCases":{"en":["Defining registry keys for plugin configuration","Updating cloud registry for JetBrains IDEs","Managing registry properties for seamless integration"],"zh":["定义插件配置的注册表键","更新JetBrains IDE的云注册表","管理注册表属性以实现无缝集成"],"ja":["プラグイン構成のレジストリキーを定義する","JetBrains IDEのクラウドレジストリを更新する","統合を容易にするレジストリ属性を管理する"],"ko":["플러그인 구성의 레지스트리 키 정의","JetBrains IDE의 클라우드 레지스트리 업데이트"," 无缝 통합을 위한 레지스트리 속성 관리"],"es":["Definir claves de registro para la configuración de plugins","Actualizar el registro en la nube para los IDE de JetBrains","Gestionar propiedades de registro para una integración fluida"],"fr":["Définir des clés de registre pour la configuration de plugins","Mettre à jour le registre cloud pour les IDE de JetBrains","Gérer les propriétés de registre pour une intégration transparente"],"de":["Registrierungsschlüssel für die Plug-in-Konfiguration definieren","Cloud-Registrierung für die JetBrains-IDEs aktualisieren","Registriereigenschaften für eine nahtlose Integration verwalten"],"pt":["Definir chaves de registro para configuração de plugin","Atualizar registro de nuvem para IDEs da JetBrains","Gerenciar propriedades de registro para integração transparente"],"ru":["Определение ключей реестра для конфигурации плагина","Обновление облачного реестра для IDE от JetBrains","Управление свойствами реестра для бесшовной интеграции"],"ar":["تعريف مفاتيح السجل لتكوين البرامج الإضافية","تحديث السجل السحابي لبيئات تطوير JetBrains","إدارة خصائص السجل من أجل التكامل المتسلسل"]},"limitations":{"en":["Requires IntelliJ IDEA and Platform setup","Limited to JetBrains IDEs for cloud registry updates"],"zh":["需要IntelliJ IDEA和Platform设置","仅限JetBrains IDE的云注册表更新"],"ja":["IntelliJ IDEAおよびPlatformの設定が必要","クラウドレジストリの更新はJetBrains IDEに限定される"],"ko":["IntelliJ IDEA 및 Platform 설정 필요","클라우드 레지스트리 업데이트는 JetBrains IDE에만 제한됨"],"es":["Requiere una configuración de IntelliJ IDEA y Plataforma","Limitado a los IDE de JetBrains para actualizaciones de registro en la nube"],"fr":["Nécessite une configuration de IntelliJ IDEA et Plateforme","Limité aux IDE de JetBrains pour les mises à jour de registre cloud"],"de":["Benötigt eine Konfiguration von IntelliJ IDEA und Plattform","Begrenzt auf die JetBrains-IDEs für Cloud-Registrierungsaktualisierungen"],"pt":["Requer configuração do IntelliJ IDEA e Plataforma","Limitado a IDEs da JetBrains para atualizações de registro de nuvem"],"ru":["Требует настройки IntelliJ IDEA и Платформы","Ограничен IDE от JetBrains для обновлений облачного реестра"],"ar":["يتطلب إعداد IntelliJ IDEA والمنصة","محدود ببيئات تطوير JetBrains لتحديثات السجل السحابي"]},"version":4},"contentHash":"a04e0dab80539e6fc7269ac8bf9faf8c023f0a90382d895ed19966dd61870853","qualityScore":39}');
