INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SHUAXINDIARY/vue-ganttastic-demo/vite', 'vite', 'SHUAXINDIARY', 'vue-ganttastic-demo', 'community', 'vite SHUAXINDIARY vue-ganttastic-demo community Vite多任务并行甘特图demo展示了如何使用Vite实现高效的任务管理和并行执行 Viteマルチタスク並行ガント図demoは、Viteを使用して効率的なタスク管理と並行実行を実現する方法を示しています Vite 다중 태스크 병렬 간트 차트 demo는 Vite를 사용하여 효율적인 태스크 관리와 병렬 실행을 구현하는 방법을展示합니다 Vite es una herramienta que permite crear gráficos Gantt para gestionar tareas paralelas de manera eficiente Vite est un outil qui permet de créer des graphiques Gantt pour gérer des tâches parallèles de manière efficace Vite ist ein Tool, das die Erstellung von Gantt-Graphiken zur effizienten Verwaltung von parallelen Aufgaben ermöglicht O Vite é uma ferramenta de desenvolvimento que oferece uma demo de Gantt para gerenciamento de tarefas paralelas Vite - это инструмент разработки, который предлагает демку Ганта для управления параллельными задачами فايت هو أداة تطوير تقدم ديمو جانت لإدارة المهام الموازية 多任务并行甘特图demo Vite教程 多任务并行 甘特图demo 前端构建工具 Vite构建 任务管理 Vite vs Webpack Vite安装 Vite设置指南 多任务并行甘特图demo');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BnayaZil/agent-vault-cli/npm-publish', 'community', 'BnayaZil', 'agent-vault-cli', 'BnayaZil/agent-vault-cli', 'npm-publish', 0, 0, 39, '2026-03-04T13:07:01.846Z', '2026-03-04T14:48:13.509Z', '74b8219f542b5438dca57ef2c9c36b559abb4c9937780c9921a06ed8dd488826', '{"id":"BnayaZil/agent-vault-cli/npm-publish","name":"npm-publish","description":{"zh":"npm-publish是AI代理的安全凭证存储CLI工具，通过CDP填充登录表单而不暴露凭证","ja":"npm-publishはAIエージェントのセキュアな資格情報保管CLIツールで、CDPを使用してログインフォームを埋めながら資格情報を公開しない","ko":"npm-publish는 AI 에이전트의 보안 자격 증명 저장 CLI 도구로 CDP를 통해 로그인 폼을 채우면서 자격 증명을 노출하지 않습니다","es":"npm-publish es una bóveda de credenciales seguras para Agentes de IA que llena formularios de inicio de sesión a través de CDP sin exponer credenciales, para una mayor seguridad y eficiencia","fr":"npm-publish est un coffre-fort d''informations d''identification sécurisé pour les Agents IA qui remplit les formulaires de connexion via CDP sans exposer les informations d''identification, pour une sécurité et une efficacité accrues","de":"npm-publish ist ein sicherer Credential-Vault für AI-Agents, der Anmeldeformulare über CDP ausfüllt, ohne Anmeldeinformationen offenzulegen, für mehr Sicherheit und Effizienz","pt":"O npm-publish é uma ferramenta de segurança para agentes de IA, permitindo o preenchimento de formulários de login via CDP sem expor credenciais.","ru":"ИИ Агенты могут использовать npm-publish для безопасного хранения учетных данных и заполнения форм входа через CDP.","ar":"أداة npm-publish توفر حماية لعميل الإي آي من خلال ملء استمارات تسجيل الدخول عبر بروتوكول التطوير المستمر","en":"Secure credential vault CLI for AI agents - fills login forms via CDP without exposing credentials"},"seo":{"title":{"zh":"AI代理npm-publish工具 - 安全凭证存储","ja":"AIエージェント用npm-publishツール - セキュアな資格情報保管","ko":"AI 에이전트용 npm-publish 도구 - 보안 자격 증명 저장","es":"Herramientas