INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BnayaZil/agent-vault-cli/npm-publish', 'npm-publish', 'BnayaZil', 'agent-vault-cli', 'community', 'npm-publish BnayaZil agent-vault-cli community npm-publish是AI代理的安全凭证存储CLI工具，通过CDP填充登录表单而不暴露凭证 npm-publishはAIエージェントのセキュアな資格情報保管CLIツールで、CDPを使用してログインフォームを埋めながら資格情報を公開しない npm-publish는 AI 에이전트의 보안 자격 증명 저장 CLI 도구로 CDP를 통해 로그인 폼을 채우면서 자격 증명을 노출하지 않습니다 npm-publish es una bóveda de credenciales seguras para Agentes de IA que llena formularios de inicio de sesión a través de CDP sin exponer credenciales, para una mayor seguridad y eficiencia npm-publish est un coffre-fort d''informations d''identification sécurisé pour les Agents IA qui remplit les formulaires de connexion via CDP sans exposer les informations d''identification, pour une sécurité et une efficacité accrues npm-publish ist ein sicherer Credential-Vault für AI-Agents, der Anmeldeformulare über CDP ausfüllt, ohne Anmeldeinformationen offenzulegen, für mehr Sicherheit und Effizienz O npm-publish é uma ferramenta de segurança para agentes de IA, permitindo o preenchimento de formulários de login via CDP sem expor credenciais. ИИ Агенты могут использовать npm-publish для безопасного хранения учетных данных и заполнения форм входа через CDP. أداة npm-publish توفر حماية لعميل الإي آي من خلال ملء استمارات تسجيل الدخول عبر بروتوكول التطوير المستمر Secure credential vault CLI for AI agents - fills login forms via CDP without exposing credentials AI代理工具 npm-publish安装 如何使用npm-publish AI代理安全凭证存储 npm-publish与其他工具比较 AI代理开发效率 npm-publish设置指南 AI代理安全开发 Secure credential vault CLI for AI agents - fills login forms via CDP without exposing credentials');
