INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RockwallJMC/Threadbilt-v0/verification-before-completion', 'verification-before-completion', 'RockwallJMC', 'Threadbilt-v0', 'community', 'verification-before-completion RockwallJMC Threadbilt-v0 community Verification-before-completion ensures that claims are backed by evidence, promoting honesty and efficiency in AI agent development. This skill benefits developers by providing a core principle for verification. Verification Before Completion 技术强调在完成工作之前进行验证的重要性，确保效率和可靠性 Verification Before Completion 技術は、仕事が完了する前に検証を行うことの重要性を強調する Verification Before Completion 기술은 작업 완료 전 검증의 중요성을 강조하여 효율성과 신뢰성을 높입니다 La verificación antes de la finalización es un principio fundamental para garantizar la calidad del código. Aprende a implementarla en tu proyecto La vérification avant l''achèvement est un principe clé pour assurer la qualité du code. Découvrez comment l''implémenter dans votre projet Die Verifizierung vor dem Abschluss ist ein grundlegendes Prinzip für die Sicherstellung der Code-Qualität. Erfahren Sie, wie Sie es in Ihrem Projekt implementieren A verificação antes da conclusão é uma técnica que garante a integridade do seu projeto. Aprenda a usá-la com Playwright. Верификация перед завершением - это техника, которая гарантирует целостность вашего проекта. Узнайте, как использовать ее с Playwright. التحقق من الصحة قبل الإكمال هو تقنية تضمن سلامة مشروعك. تعرف على كيفية استخدامها مع Playwright. how to use verification-before-completion what is verification-before-completion verification-before-completion alternative verification-before-completion setup guide verification-before-completion install npx playwright verification evidence-based claims in AI development verification-before-completion best practices verification-before-completion AIエージェント npx playwright 终端可见性 验证证据 Iron Law 技术原则 完成声明 效率和可靠性 Enforces the core principle of evidence before claims Requires running verification commands in the terminal for visibility Violating the letter of this rule is considered violating the spirit of this rule Implements the Iron Law: NO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE Supports running npx playwright in the terminal for verification Verification-before-completion is a development principle that requires evidence before claims, ensuring that completion claims are backed by fresh verification evidence.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DataDog/lading/lading-preflight', 'community', 'DataDog', 'lading', 'DataDog/lading', 'lading-preflight', 93, 14, 38, '2026-02-24T16:31:57Z', '2026-03-06T06:31:59.952Z', '4efddc3d30cf50f82da313c2cbb404df0c5b034ecc3bba63b2a3f1f5c08c86c3', '{"id":"DataDog/lading/lading-preflight","name":"lading-preflight","description":{"en":"lading-preflight is a suite of tools for data generation and load testing, benefiting developers and QA engineers. It provides a preflight script to ensure environment readiness.","zh":"lading-preflight是一套数据生成和负载测试工具，通过运行preflight脚本可以轻松设置和使用","ja":"lading-preflightはデータ生成とロードテストツールです。preflightスクリプトを実行して簡単に設定と使用を開始できます","ko":"lading-preflight는 데이터 생성 및 로드 테스트 도구입니다. preflight 스크립트를 실행하여 쉽게 설정하고 사용할 수 있습니다","es":"Lading-preflight es una suite de herramientas de generación de datos y pruebas de carga que ayuda a los desarrolladores a probar y optimizar sus aplicaciones","fr":"Lading-preflight est une suite d''outils de génération de données et de tests de charge qui aide les développeurs à tester et optimiser leurs applications","de":"Lading-preflight ist eine Suite von Daten generierungs- und Lasttesttools, die Entwicklern hilft, ihre Anwendungen zu testen und zu optimieren","pt":"O Lading-Preflight é uma suíte de ferramentas de geração de dados e teste de carga que ajuda a garantir a estabilidade das aplicações.","ru":"Lading-Preflight - это набор инструментов для генерации данных и тестирования нагрузки, который помогает обеспечить стабильность приложений ИИ Агентов.","ar":"Lading-Preflight هو مجموعة من أدوات توليد البيانات واختبار الحمل التي تساعد على ضمان استقرار التطبيقات للوكلاء الذكاء الاصطناعي."},"seo":{"title":{"en":"lading-preflight: Load Testing and Data Generation Setup ...","zh":"lading-preflight.setup指南：数据生成和负载测试工具","ja":"lading-preflightセットアップガイド：データ生成とロードテストツール","ko":"lading-preflight 설정 가이드: 데이터 생성 및 로드 테스트 도구","es":"Guía de configuración de lading-preflight para pruebas de...","fr":"Guide de configuration de lading-preflight pour les tests...","de":"Einrichtungsleitfaden für lading-preflight zur Lasttestung","pt":"Guia de Configuração do Lading-Preflight: Ferramentas de ...","ru":"Настройка Lading-Preflight: Инструменты для генерации дан...","ar":"دليل إعداد Lading-Preflight: أدوات توليد البيانات واختبار..."},"description":{"en":"Discover how to setup lading-preflight for robust load testing and data generation. Get started with our expert guide and optimize your workflow today!","zh":"了解lading-preflight的功能和特点，包括数据生成和负载测试，通过本指南轻松设置和使用","ja":"lading-preflightの機能と特徴を紹介します。データ生成とロードテストを実現するツールです。","ko":"lading-preflight의 기능과 특징을 알아보세요. 데이터 생성과 로드 테스트를 위한 도구입니다.","es":"Descubre cómo configurar lading-preflight para pruebas de carga y generación de datos con nuestra guía paso a paso","fr":"Découvrez comment configurer lading-preflight pour les tests de charge et la génération de données avec notre guide étape par étape","de":"Erfahren Sie, wie Sie lading-preflight für Lasttests und Daten generierung mit unserem Schritt-für-Schritt-Leitfaden konfigurieren","pt":"Aprenda a configurar o Lading-Preflight para gerar dados e testar a carga de suas aplicações com ferramentas de linha de comando","ru":"Узнайте, как настроить Lading-Preflight для генерации данных и тестирования нагрузки ваших приложений с помощью инструментов командной строки ИИ Агентов","ar":"تعلم كيفية إعداد Lading-Preflight لتوليد البيانات واختبار الحمل لتطبيقاتك باستخدام أدوات سطر الأوامر للوكلاء الذكاء الاصطناعي"},"definition":{"en":"lading-preflight is a collection of data generation and load testing tools, enabling developers to test and validate their applications","zh":"lading-preflight是一种AI工具，提供数据生成和负载测试功能","ja":"lading-preflightはAIエージェントの一種で、データ生成とロードテスト機能を提供します","ko":"lading-preflight는 AI 도구 중 하나로, 데이터 생성 및 로드 테스트 기능을 제공합니다","es":"Lading-preflight es un conjunto de herramientas de pruebas de carga y generación de datos para desarrolladores","fr":"Lading-preflight est un ensemble d''outils de tests de charge et de génération de données pour les développeurs","de":"Lading-preflight ist eine Sammlung von Lasttest- und Daten generierungstools für Entwickler","pt":"O Lading-Preflight é uma ferramenta de teste de carga que gera dados para garantir a estabilidade das aplicações.","ru":"Lading-Preflight - это инструмент для тестирования нагрузки, который генерирует данные для обеспечения стабильности приложений ИИ Агентов.","ar":"Lading-Preflight هو أداة اختبار الحمل التي تولد البيانات لضمان استقرار التطبيقات للوكلاء الذكاء الاصطناعي."},"features":{"en":["Runs preflight script using bash","Supports rustc installation via curl","Provides a table for resolving failed checks","Allows for load testing and data generation","Includes scripts for environment setup and validation","Stops on any failure to ensure robust testing"],"zh":["运行preflight脚本进行设置","支持数据生成和负载测试","提供rustc安装脚本","支持HTTPS和TLS协议"],"ja":["preflightスクリプトを実行して設定","データ生成とロードテストをサポート","rustcのインストールスクリプトを提供","HTTPSとTLSプロトコルをサポート"],"ko":["preflight 스크립트를 실행하여 설정","데이터 생성 및 로드 테스트를 지원","rustc 설치 스크립트를 제공","HTTPS 및 TLS 프로토콜을 지원"],"es":["Ejecución de scripts de preflight con bash","Resolución de errores con rustc","Uso de curl para descargas seguras","Integración con herramientas de desarrollo como CLI","Generación de datos para pruebas de carga","Análisis de resultados para optimización"],"fr":["Exécution de scripts de prévol avec bash","Résolution d''erreurs avec rustc","Utilisation de curl pour des téléchargements sécurisés","Intégration avec des outils de développement comme CLI","Génération de données pour les tests de charge","Analyse de résultats pour l''optimisation"],"de":["Ausführung von Preflight-Skripten mit bash","Fehlerbehebung mit rustc","Verwendung von curl für sichere Downloads","Integration mit Entwicklungstools wie CLI","Daten generierung für Lasttests","Ergebnisanalyse für Optimierung"],"pt":["Ferramentas de linha de comando para teste de carga","Geração de dados para simular cenários reais","Suporte a scripts de pré-voo para automação","Integração com ferramentas de desenvolvimento como Rust","Relatórios detalhados de teste de carga","Suporte a resolução de problemas com tabelas de erro"],"ru":["Инструменты командной строки для тестирования нагрузки","Генерация данных для模拟 реальных сценариев","Поддержка скриптов pré-полета для автоматизации","Интеграция с инструментами разработки как Rust","Подробные отчеты о тестировании нагрузки","Поддержка решения проблем с таблицами ошибок ИИ Агентов"],"ar":["أدوات سطر الأوامر لاختبار الحمل","توليد البيانات لتحاكي السيناريوهات الحقيقية","دعم سكريبتات ما قبل الطيران للتحكم الآلي","التكامل مع أدوات التطوير مثل Rust","تقارير مفصلة لاختبار الحمل","دعم حل المشكلات مع جداول الأخطاء للوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use lading-preflight","lading-preflight alternative","lading-preflight setup guide","what is lading-preflight","lading-preflight vs load testing tools","lading-preflight install","lading-preflight data generation","lading-preflight load testing","lading-preflight preflight script"],"zh":["lading-preflight","数据生成","负载测试","AI工具","preflight脚本","rustc安装"],"ja":["lading-preflight","データ生成","ロードテスト","AIエージェント","preflightスクリプト","rustcのインストール"],"ko":["lading-preflight","데이터 생성","로드 테스트","AI 도구","preflight 스크립트","rustc 설치"],"es":["lading-preflight","pruebas de carga","generación de datos","herramientas de desarrollo","CLI","rustc","curl","bash","optimización de aplicaciones","Agentes de IA para desarrolladores"],"fr":["lading-preflight","tests de charge","génération de données","outils de développement","CLI","rustc","curl","bash","optimisation d''applications","Outils d''IA pour les développeurs"],"de":["lading-preflight","Lasttests","Daten generierung","Entwicklungstools","CLI","rustc","curl","bash","Optimierung von Anwendungen","KI-Tools für Entwickler"],"pt":["Lading-Preflight","teste de carga","geração de dados","ferramentas de desenvolvimento","Rust","script de pré-voo","automatização de testes","relatórios de teste de carga","solução de problemas"],"ru":["Lading-Preflight","тестирование нагрузки","генерация данных","инструменты разработки","Rust","скрипт pré-полета","автоматизация тестирования","отчеты о тестировании нагрузки","решение проблем ИИ Агентов"],"ar":["Lading-Preflight","اختبار الحمل","توليد البيانات","أدوات التطوير","Rust","سكريبت ما قبل الطيران","التحكم الآلي للاختبار","تقارير اختبار الحمل","حل المشكلات للوكلاء الذكاء الاصطناعي"]}},"owner":"DataDog","repo":"lading","repoPath":"DataDog/lading","stars":93,"forks":14,"updatedAt":"2026-02-24T16:31:57Z","topics":[],"category":"community","skillMd":{"name":"lading-preflight","description":"Environment validation checklist. Run this FIRST when starting a new Claude session to verify the environment is ready for optimization work. Checks Rust toolchain, ci/ scripts, build, benchmarking tools, profilers, memory tools, and git state.","bodyPreview":"# Run preflight script\n\n```bash\n.claude/skills/lading-preflight/scripts/preflight\n```\n\n**STOP on any failure.** Use the table below to resolve `[X]` items:\n\n# Offer suggestions\n\n| Failed Check                             | Fix                                                               |\n| ---------------------------------------- | ----------------------------------------------------------------- |\n| rustc not found                          | `curl --proto ''=https'' --tlsv1.2 -sSf https://sh.ru","body":"# Run preflight script\n\n```bash\n.claude/skills/lading-preflight/scripts/preflight\n```\n\n**STOP on any failure.** Use the table below to resolve `[X]` items:\n\n# Offer suggestions\n\n| Failed Check                             | Fix                                                               |\n| ---------------------------------------- | ----------------------------------------------------------------- |\n| rustc not found                          | `curl --proto ''=https'' --tlsv1.2 -sSf https://sh.rustup.rs \\| sh` |\n| cargo not found                          | Reinstall rustup                                                  |\n| cargo-nextest not found                  | `cargo install cargo-nextest`                                     |\n| ci/* not executable                      | `chmod +x ci/*`                                                   |\n| ci/check failed                          | `cargo update`, check dependency issues                           |\n| payloadtool build failed                 | Check Rust version and dependencies                               |\n| hyperfine not found                      | `brew install hyperfine`                                          |\n| cargo-criterion not found                | `cargo install cargo-criterion`                                   |\n| criterion benchmarks missing             | Check `lading_payload/benches/` and `Cargo.toml`                  |\n| payloadtool --memory-stats not supported | Rebuild payloadtool from current branch                           |\n| git user.name not set                    | `git config user.name \"Your Name\"`                                |\n| git user.email not set                   | `git config user.email \"you@example.com\"`                         |\n"},"lastSynced":"2026-03-06T06:31:59.952Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive environment readiness and load testing capabilities.","zh":"非常适合需要全面的环境就绪性和负载测试能力的开发代理。","ja":"開発エージェントが包括的な環境の準備と負荷テストの機能を必要とする場合に最適です。","ko":"개발 에이전트가 종합적인 환경 준비와 로드 테스트 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una preparación y capacidades de prueba de carga de entorno integral.","fr":"Parfait pour les agents de développement nécessitant une préparation et des capacités de test de charge d''environnement complètes.","de":"Perfekt für Entwicklungsmittel, die eine umfassende Umgebungs bereitstellung und Lasttestfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de preparação abrangente do ambiente e capacidades de teste de carga.","ru":"Идеально подходит для агентов разработки, которым необходима всесторонняя подготовка среды и возможности тестирования нагрузки.","ar":"مثالي للوكلاء المتضررين من التطوير الذين يحتاجون إلى جاهزية بيئة شاملة وقدرات اختبار الحمل."},"recommendation":{"en":"Empowers agents to ensure environment readiness using a preflight script, providing rustc installation and troubleshooting via protocols like HTTPS, and stopping on any failure to guarantee reliable testing.","zh":"通过预飞脚本使代理能够确保环境就绪，提供rustc安装和通过HTTPS等协议进行故障排除，并在任何故障时停止以保证可靠的测试。","ja":"プレフライトスクリプトを使用してエージェントが環境の準備を確認できるようにし、rustcのインストールとHTTPSなどのプロトコルを使用したトラブルシューティングを提供し、どのような障害でも停止して信頼性の高いテストを保証する。","ko":"프리플ライト 스크립트를 사용하여 에이전트가 환경 준비를 확인할 수 있도록 하며, rustc 설치 및 HTTPS와 같은 프로토콜을 사용한 문제 해결을 제공하며, 모든 오류 발생 시 중단하여 신뢰할 수 있는 테스트를 보장합니다.","es":"Habilita a los agentes a garantizar la preparación del entorno mediante un script de preflight, proporcionando instalación y solución de problemas de rustc a través de protocolos como HTTPS, y deteniéndose en caso de cualquier error para garantizar pruebas confiables.","fr":"Permet aux agents de garantir la préparation de l''environnement en utilisant un script de préflight, en fournissant l''installation et la résolution des problèmes de rustc via des protocoles tels que HTTPS, et en s''arrêtant en cas de défaillance pour garantir des tests fiables.","de":"Ermöglicht es den Agenten, die Umgebungs bereitstellung mithilfe eines Preflight-Skripts sicherzustellen, indem rustc-Installation und Fehlerbehebung über Protokolle wie HTTPS bereitgestellt werden und bei jedem Fehler gestoppt wird, um zuverlässige Tests zu gewährleisten.","pt":"Habilita os agentes a garantir a preparação do ambiente usando um script de pré-voo, fornecendo instalação e solução de problemas do rustc por meio de protocolos como HTTPS, e parando em caso de falha para garantir testes confiáveis.","ru":"Наделяет агентов возможностью обеспечить готовность среды с помощью предполетного скрипта, предоставляя установку и устранение неполадок rustc через протоколы như HTTPS, и останавливаясь при любой неудаче для обеспечения надежного тестирования.","ar":"يمنح الوكلاء القدرة على ضمان جاهزية البيئة باستخدام سценاريو ما قبل الطيران ، وتوفير تركيب rustc ومعالجة الأعطال من خلال بروتوكولات مثل HTTPS ، وتوقف عند أي فشل لضمان الاختبارات الموثوقة."},"useCases":{"en":["Running preflight scripts for environment validation","Troubleshooting rustc installation issues","Performing load testing with data generation tools"],"zh":["运行预飞脚本以验证环境","解决rustc安装问题","使用数据生成工具执行负载测试"],"ja":["環境の検証のためにプレフライトスクリプトを実行する","rustcのインストールの問題を解決する","データ生成ツールを使用して負荷テストを実行する"],"ko":["환경 검증을 위해 프리플ライト 스크립트를 실행하는 것","rustc 설치 문제를 해결하는 것","데이터 생성 도구를 사용하여 로드 테스트를 수행하는 것"],"es":["Ejecución de scripts de preflight para la validación del entorno","Solución de problemas de instalación de rustc","Realización de pruebas de carga con herramientas de generación de datos"],"fr":["Exécution de scripts de préflight pour la validation de l''environnement","Résolution des problèmes d''installation de rustc","Réalisation de tests de charge avec des outils de génération de données"],"de":["Ausführen von Preflight-Skripten für die Umgebungsvalidierung","Beheben von rustc-Installationsproblemen","Durchführen von Lasttests mit Daten generierenden Tools"],"pt":["Executar scripts de pré-voo para validação do ambiente","Solucionar problemas de instalação do rustc","Realizar testes de carga com ferramentas de geração de dados"],"ru":["Выполнение предполетных скриптов для проверки среды","Устранение неполадок при установке rustc","Проведение тестирования нагрузки с помощью инструментов генерации данных"],"ar":["تشغيل سيناريوهات ما قبل الطيران للتحقق من بيئة","معالجة مشاكل تركيب rustc","إجراء اختبارات الحمل بأدوات توليد البيانات"]},"limitations":{"en":["Requires rustc installation","STOP on any failure may interrupt workflow","Specific fix commands like curl required for troubleshooting"],"zh":["需要rustc安装","任何故障都会停止可能会中断工作流","需要特定的修复命令，如curl，用于故障排除"],"ja":["rustcのインストールが必要","どのような障害でも停止するため、ワークフローが中断される可能性がある","特定の修復コマンド、例えばcurlがトラブルシューティングに必要"],"ko":["rustc 설치가 필요함","어떤 오류가 발생해도 중단되므로 워크플ロー가 중단될 수 있음","특정한 수정 명령어, 예를 들어 curl이 문제 해결에 필요함"],"es":["Requiere instalación de rustc","DETENER en caso de cualquier error puede interrumpir el flujo de trabajo","Se requieren comandos de solución de problemas específicos como curl"],"fr":["Nécessite l''installation de rustc","ARRÊTER en cas de défaillance peut interrompre le flux de travail","Des commandes de dépannage spécifiques comme curl sont requises"],"de":["Erfordert rustc-Installation","STOP bei jedem Fehler kann den Arbeitsfluss unterbrechen","Spezifische Fehlerbehebungsbefehle wie curl sind erforderlich"],"pt":["Requer instalação do rustc","PARAR em caso de falha pode interromper o fluxo de trabalho","Comandos de reparo específicos como curl necessários para solução de problemas"],"ru":["Требует установки rustc","ОСТАНОВКА при любой неудаче может прервать рабочий процесс","Конкретные команды исправления, такие как curl, необходимы для устранения неполадок"],"ar":["يتطلب تركيب rustc","توقف عند الفشل قد يقطع تدفق العمل","أوامر إصلاح محددة مثل curl مطلوبة لمعالجة الأعطال"]},"version":4},"contentHash":"4efddc3d30cf50f82da313c2cbb404df0c5b034ecc3bba63b2a3f1f5c08c86c3","qualityScore":38}');
