INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DataDog/lading/lading-preflight', 'lading-preflight', 'DataDog', 'lading', 'community', 'lading-preflight DataDog lading community lading-preflight is a suite of tools for data generation and load testing, benefiting developers and QA engineers. It provides a preflight script to ensure environment readiness. lading-preflight是一套数据生成和负载测试工具，通过运行preflight脚本可以轻松设置和使用 lading-preflightはデータ生成とロードテストツールです。preflightスクリプトを実行して簡単に設定と使用を開始できます lading-preflight는 데이터 생성 및 로드 테스트 도구입니다. preflight 스크립트를 실행하여 쉽게 설정하고 사용할 수 있습니다 Lading-preflight es una suite de herramientas de generación de datos y pruebas de carga que ayuda a los desarrolladores a probar y optimizar sus aplicaciones Lading-preflight est une suite d''outils de génération de données et de tests de charge qui aide les développeurs à tester et optimiser leurs applications Lading-preflight ist eine Suite von Daten generierungs- und Lasttesttools, die Entwicklern hilft, ihre Anwendungen zu testen und zu optimieren O Lading-Preflight é uma suíte de ferramentas de geração de dados e teste de carga que ajuda a garantir a estabilidade das aplicações. Lading-Preflight - это набор инструментов для генерации данных и тестирования нагрузки, который помогает обеспечить стабильность приложений ИИ Агентов. Lading-Preflight هو مجموعة من أدوات توليد البيانات واختبار الحمل التي تساعد على ضمان استقرار التطبيقات للوكلاء الذكاء الاصطناعي. how to use lading-preflight lading-preflight alternative lading-preflight setup guide what is lading-preflight lading-preflight vs load testing tools lading-preflight install lading-preflight data generation lading-preflight load testing lading-preflight preflight script lading-preflight 数据生成 负载测试 AI工具 preflight脚本 rustc安装 Runs preflight script using bash Supports rustc installation via curl Provides a table for resolving failed checks Allows for load testing and data generation Includes scripts for environment setup and validation Stops on any failure to ensure robust testing lading-preflight is a collection of data generation and load testing tools, enabling developers to test and validate their applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('radioactive-labs/plutonium-core/plutonium', 'community', 'radioactive-labs', 'plutonium-core', 'radioactive-labs/plutonium-core', 'plutonium', 56, 7, 38, '2026-02-23T22:18:28Z', '2026-03-06T06:34:58.750Z', 'e83fe7aa9838e2012fbb24dcf57aa67e902edd650d7f9f5ab23cc93afa7bedc4', '{"id":"radioactive-labs/plutonium-core/plutonium","name":"plutonium","description":{"en":"Plutonium is a convention-driven framework for building production-ready Rails apps in minutes. It benefits developers by providing a customizable and AI-ready solution.","zh":"Plutonium是一个快速开发Rails应用的工具，通过AI驱动的开发流程，帮助开发者快速构建生产就绪的应用","ja":"Plutoniumは、AIエージェントを活用したRailsアプリの迅速開発ツールです","ko":"Plutonium은 AI 도구를 활용한 빠른 Rails 앱 개발을 위한 도구입니다","es":"Plutonium es una herramienta para crear aplicaciones Rails listas para producción en minutos, con generadores y personalizaciones","fr":"Plutonium est un outil pour créer des applications Rails prêtes pour la production en quelques minutes, avec des générateurs et des personnalisation","de":"Plutonium ist ein Tool, um Rails-Anwendungen in Minuten zu erstellen, die bereit für die Produktion sind, mit Generatoren und Anpassungen","pt":"O Plutonium é um framework de desenvolvimento rápido para aplicativos Rails, que permite a criação de aplicações personalizadas em minutos.","ru":"Plutonium - это быстрый фреймворк для разработки приложений Rails, который позволяет создавать настраиваемые приложения за минуты.","ar":"بليوتونيوم هو إطار سريع للتنمية لتطبيقات ريلز، يسمح بإنشاء تطبيقات مخصصة في دقائق."},"seo":{"title":{"en":"Plutonium: Rapid Rails App Development Setup Guide | AI A...","zh":"Plutonium 快速开发指南 - AI智能工具","ja":"Plutonium Setup Guide - AIエージェントを活用したRailsアプリ開発","ko":"Plutonium 빠른 개발 가이드 - AI 도구로 Rails 앱을 만들기","es":"Guía de configuración de Plutonium para aplicaciones Rails","fr":"Guide de démarrage de Plutonium pour les applications Rails","de":"Plutonium-Setup-Leitfaden für Rails-Anwendungen","pt":"Guia de Configuração do Plutonium: Desenvolvimento Rápido...","ru":"Настройка Plutonium: Быстрое создание приложений Rails с ...","ar":"دليل إعداد بليوتونيوم: تطوير تطبيقات ريلز السريع مع أدوات..."},"description":{"en":"Unlock fast and customizable Rails app development with Plutonium. Learn how to use generators, definitions, and policies to build production-ready apps in m...","zh":"使用Plutonium快速构建生产就绪的Rails应用，通过AI驱动的开发流程，节省时间和成本","ja":"Plutoniumを使用して、AIエージェントによる開発フローで、短時間でプロダクションレディのRailsアプリを作成","ko":"Plutonium을 사용하여 AI 도구를 통해 빠르고 효율적인 Rails 앱 개발을 실현","es":"Aprende a crear aplicaciones Rails listas para producción en minutos con Plutonium, utilizando generadores y personalizaciones","fr":"Découvrez comment créer des applications Rails prêtes pour la production en quelques minutes avec Plutonium, en utilisant des générateurs et des personnalisa...","de":"Erfahren Sie, wie Sie mit Plutonium Rails-Anwendungen in Minuten erstellen können, die bereit für die Produktion sind, mit Generatoren und Anpassungen","pt":"Aprenda a criar aplicativos Rails personalizados em minutos com o Plutonium, um framework de desenvolvimento rápido e convencional","ru":"Узнайте, как создать настраиваемые приложения Rails за минуты с помощью Plutonium, быстрого и конвенционального фреймворка","ar":"تعرف على كيفية إنشاء تطبيقات ريلز المخصصة في دقائق مع بليوتونيوم، إطار سريع ومتوافق للتنمية"},"definition":{"en":"Plutonium is a Rails framework that enables rapid application development using generators, definitions, and policies.","zh":"Plutonium是一种快速开发Rails应用的工具，通过AI驱动的开发流程","ja":"Plutoniumは、AIエージェントを活用したRailsアプリの迅速開発ツール","ko":"Plutonium은 AI 도구를 활용한 빠른 Rails 앱 개발을 위한 도구","es":"Plutonium es un framework de desarrollo rápido para aplicaciones Rails","fr":"Plutonium est un framework de développement rapide pour les applications Rails","de":"Plutonium ist ein Framework für schnelles Entwickeln von Rails-Anwendungen","pt":"O Plutonium é um framework de desenvolvimento de aplicativos Rails que utiliza geradores e convenções para criar aplicações personalizadas rapidamente.","ru":"Plutonium - это фреймворк для разработки приложений Rails, который использует генераторы и конвенции для быстрого создания настраиваемых приложений.","ar":"بليوتونيوم هو إطار تطبيقات ريلز يستخدم المول丁ات والاتفاقيات لإنشاء تطبيقات مخصصة بسرعة."},"features":{"en":["Uses `rails g pu:res:scaffold` generator for rapid resource creation","Supports customizable admin dashboards with Rodauth-Rails","Employs definitions for UI customization instead of controllers","Utilizes policies for authorization and permission logic","Enables fully customizable and AI-ready Rails applications"],"zh":["基于Rails的快速开发框架","支持AI驱动的开发流程","内置RoDauth-Rails和Admin Dashboard","提供definitions和policies进行权限管理","支持多语言和国际化","提供rails g pu:res:scaffold命令进行快速开发"],"ja":["Railsベースの迅速開発フレームワーク","AIエージェントを活用した開発フロー","RoDauth-RailsとAdmin Dashboardを内蔵","definitionsとpoliciesによる権限管理","多言語と国際化に対応","rails g pu:res:scaffoldコマンドによる迅速開発"],"ko":["Rails 기반의 빠른 개발 프레임워크","AI 도구를 활용한 개발 프로세스","RoDauth-Rails와 Admin Dashboard를 내장","정의와 정책을 통해 권한 관리","다중 언어와 국제화를 지원","rails g pu:res:scaffold 명령을 통해 빠른 개발"],"es":["Generadores de código para crear recursos y paquetes","Personalizaciones con definiciones para la interfaz de usuario","Políticas de autorización para controlar permisos","Compatibilidad con RoDAuth-Rails para autenticación","Soporte para desarrollo rápido con Rails","Integración con herramientas de desarrollo de AI"],"fr":["Générateurs de code pour créer des ressources et des paquets","Personnalisation avec des définitions pour l''interface utilisateur","Politiques d''autorisation pour contrôler les permissions","Compatibilité avec RoDAuth-Rails pour l''authentification","Prise en charge du développement rapide avec Rails","Intégration avec des outils de développement d''AI"],"de":["Code-Generatoren für die Erstellung von Ressourcen und Paketen","Anpassungen mit Definitionen für die Benutzeroberfläche","Autorisierungspolitiken für die Steuerung von Berechtigungen","Kompatibilität mit RoDAuth-Rails für Authentifizierung","Unterstützung für schnelles Entwickeln mit Rails","Integration mit AI-Entwicklungstools"],"pt":["Geração de recursos e pacotes com o comando ''rails g pu:res:scaffold''","Customização de UI com definições, não controladores","Autorização com políticas de permissão","Desenvolvimento rápido de aplicativos Rails","Compatibilidade com Rodauth-Rails","Suporte a internacionalização"],"ru":["Генерация ресурсов и пакетов с помощью команды ''rails g pu:res:scaffold''","Настройка UI с помощью определений, а не контроллеров","Авторизация с помощью политик разрешения","Быстрое создание приложений Rails","Совместимость с Rodauth-Rails","Поддержка интернационализации"],"ar":["إنشاء موارد وحزم باستخدام الأمر ''rails g pu:res:scaffold''","تخصيص واجهة المستخدم مع التعريفات، وليس الموجهات","التأشير مع سياسات التصريح","التنمية السريعة لتطبيقات ريلز","التوافق مع روداوث-ريلز","دعم التدويل"]},"keywords":{"en":["how to use plutonium","plutonium vs rails","plutonium setup guide","what is plutonium","plutonium alternative","plutonium install","rapid rails development","customizable rails apps","rodauth-rails integration"],"zh":["Plutonium","Rails开发","AI智能工具","快速开发","RoDauth-Rails","Admin Dashboard","definitions","policies","多语言","国际化"],"ja":["Plutonium","Rails開発","AIエージェント","迅速開発","RoDauth-Rails","Admin Dashboard","definitions","policies","多言語","国際化"],"ko":["Plutonium","Rails 개발","AI 도구","빠른 개발","RoDauth-Rails","Admin Dashboard","정의","정책","다중 언어","국제화"],"es":["plutonium","rails","desarrollo rápido","generadores de código","personalización","autorización","rodauth-rails","herramientas de desarrollo de AI","aplicaciones web","framework de desarrollo"],"fr":["plutonium","rails","développement rapide","générateurs de code","personnalisation","autorisation","rodauth-rails","outils de développement d''AI","applications web","framework de développement"],"de":["plutonium","rails","schnelles Entwickeln","Code-Generatoren","Anpassung","Autorisierung","rodauth-rails","AI-Entwicklungstools","Webanwendungen","Entwicklungsfamework"],"pt":["plutonium","desenvolvimento rápido de aplicativos rails","geradores de recursos","customização de ui","autorização com políticas","rodauth-rails","rails","ruby","framework de desenvolvimento"],"ru":["plutonium","быстрое создание приложений rails","генераторы ресурсов","настройка ui","авторизация с политиками","rodauth-rails","rails","ruby","фреймворк для разработки"],"ar":["بليوتونيوم","التنمية السريعة لتطبيقات ريلز","مولدات الموارد","تخصيص واجهة المستخدم","التأشير مع السياسات","رودااوث-ريلز","ريلز","روبي","إطار التنمية"]}},"owner":"radioactive-labs","repo":"plutonium-core","repoPath":"radioactive-labs/plutonium-core","stars":56,"forks":7,"updatedAt":"2026-02-23T22:18:28Z","topics":["admin-dashboard","admin-panel","framework","rails","rapid-development","rodauth-rails","ruby","starter"],"category":"community","skillMd":{"name":"plutonium","description":"High-level guide for working with Plutonium applications - read this first","bodyPreview":"# Plutonium Development Guide\n\nRead this first when working on a Plutonium application.\n\n## Core Rules\n\n1. **Always use generators** - Never manually create resources, packages, or portals\n2. **Check relevant skills first** - Each concept has a dedicated skill with details\n3. **Definitions over controllers** - UI customization belongs in definitions, not controllers\n4. **Policies for authorization** - All permission logic goes in policies\n\n## Key Generators\n\n```bash\nrails g pu:res:scaffold Post","body":"# Plutonium Development Guide\n\nRead this first when working on a Plutonium application.\n\n## Core Rules\n\n1. **Always use generators** - Never manually create resources, packages, or portals\n2. **Check relevant skills first** - Each concept has a dedicated skill with details\n3. **Definitions over controllers** - UI customization belongs in definitions, not controllers\n4. **Policies for authorization** - All permission logic goes in policies\n\n## Key Generators\n\n```bash\nrails g pu:res:scaffold Post title:string --dest=main_app    # Create resource\nrails g pu:res:conn Post --dest=admin_portal                 # Connect to portal\nrails g pu:pkg:package blogging                              # Create feature package\nrails g pu:pkg:portal admin_portal                           # Create portal\n```\n\nAlways specify `--dest` to avoid interactive prompts.\n\n## Resource Architecture\n\nA resource has four layers:\n\n| Layer | Purpose | Customize when... |\n|-------|---------|-------------------|\n| Model | Data, validations, associations | Adding business logic |\n| Definition | UI - fields, actions, filters | Changing how things look/behave |\n| Policy | Authorization - who can do what | Restricting access |\n| Controller | Request handling | Rarely - use hooks if needed |\n\n## Skill Reference\n\n| Topic | Skill |\n|-------|-------|\n| Creating resources | `plutonium-create-resource` |\n| Connecting to portals | `plutonium-connect-resource` |\n| Field configuration | `plutonium-definition-fields` |\n| Actions & interactions | `plutonium-definition-actions` |\n| Search, filters, scopes | `plutonium-definition-query` |\n| Authorization | `plutonium-policy` |\n| Custom views | `plutonium-views` |\n| Custom forms | `plutonium-forms` |\n| Nested resources | `plutonium-nested-resources` |\n| Packages & portals | `plutonium-package`, `plutonium-portal` |\n| Authentication | `plutonium-rodauth` |\n"},"lastSynced":"2026-03-06T06:34:58.750Z","agentAnalysis":{"suitability":{"en":"Perfect for Rails Developers needing rapid prototyping and customizable AI-ready solutions.","zh":"非常适合需要快速原型开发和可定制的AI解决方案的Rails开发人员。","ja":"Rails開発者が迅速なプロトタイピングとカスタマイズ可能なAI対応ソリューションを必要とする場合に最適です。","ko":"신속한 프로토 타이핑 및 사용자 지정 가능한 AI 솔루션을 필요로하는 Rails 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de Rails que necesitan prototipado rápido y soluciones personalizables listas para AI.","fr":"Parfait pour les développeurs Rails ayant besoin d''un prototypage rapide et de solutions personnalisables prêtes pour l''IA.","de":"Perfekt für Rails-Entwickler, die ein schnelles Prototyping und anpassbare AI-fähige Lösungen benötigen.","pt":"Perfeito para desenvolvedores Rails que precisam de prototipagem rápida e soluções personalizáveis prontas para IA.","ru":"Идеально для разработчиков Rails, которым необходима быстрая прототипизация и настраиваемые решения, готовые к ИИ.","ar":"مثالي لمطوري Rails الذين يحتاجون إلى إمكانية اختبار سريع وحلول قابلة للتعديل وجاهزة للذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to generate production-ready Rails apps in minutes using customizable and AI-driven frameworks, leveraging generators, definitions, and policies for efficient development and authorization, while utilizing protocols like rails g pu:res:scaffold.","zh":"赋予代理生成生产就绪的Rails应用程序的能力，使用可定制和AI驱动的框架，在几分钟内，利用生成器、定义和策略实现高效的开发和授权，同时利用诸如rails g pu:res:scaffold的协议。","ja":"エージェントに、生成可能なフレームワークとAI駆動のフレームワークを使用して、数分以内に生成できるRailsアプリケーションを生成する能力を与え、生成器、定義、ポリシーを利用して効率的な開発と認可を実現し、同時にrails g pu:res:scaffoldなどのプロトコルを利用する。","ko":"에이전트가 사용자 지정 가능하고 AI 구동 프레임워크를 사용하여 몇 분 안에 생성할 수 있는 프로덕션 준비 Rails 애플리케이션을 생성할 수 있는 능력을 부여하여, 생성기, 정의 및 정책을 사용하여 효율적인 개발 및 권한 부여를 달성하며, 동시에 rails g pu:res:scaffold와 같은 프로토콜을 사용한다.","es":"Habilita a los agentes a generar aplicaciones de Rails de producción en minutos utilizando frameworks personalizables y impulsados por IA, aprovechando generadores, definiciones y políticas para un desarrollo y autorización eficientes, mientras se utilizan protocolos como rails g pu:res:scaffold.","fr":"Permet aux agents de générer des applications Rails de production en quelques minutes en utilisant des frameworks personnalisables et alimentés par l''IA, en exploitant les générateurs, les définitions et les politiques pour un développement et une autorisation efficaces, tout en utilisant des protocoles tels que rails g pu:res:scaffold.","de":"Ermächtigt Agenten, produktionsbereite Rails-Apps in Minuten zu generieren, indem sie anpassbare und von KI angetriebene Frameworks verwenden, Generatoren, Definitionen und Richtlinien für effiziente Entwicklung und Autorisierung nutzen und Protokolle wie rails g pu:res:scaffold verwenden.","pt":"Habilita agentes a gerar aplicativos Rails de produção em minutos usando frameworks personalizáveis e impulsionados por IA, aproveitando geradores, definições e políticas para desenvolvimento eficiente e autorização, enquanto utiliza protocolos como rails g pu:res:scaffold.","ru":"Позволяет агентам генерировать приложения Rails, готовые к производству, за несколько минут, используя настраиваемые и управляемые ИИ фреймворки, используя генераторы, определения и политики для эффективного развития и авторизации, а также используя протоколы, такие как rails g pu:res:scaffold.","ar":"تمكّن الوكلاء من إنشاء تطبيقات ريلز جاهزة للإنتاج في دقائق باستخدام الإطارات القابلة للتعديل والمحفزة بالذكاء الاصطناعي، باستخدام المولّدين والتعريفات والسياسات من أجل التطوير الكفء والتصريح، بينما يستفيد من بروتوكولات مثل rails g pu:res:scaffold."},"useCases":{"en":["Automating resource creation with rails g pu:res:scaffold","Generating customizable UI components using definitions","Implementing permission logic with policies"],"zh":["使用rails g pu:res:scaffold自动执行资源创建","使用定义生成可定制的UI组件","使用策略实现权限逻辑"],"ja":["rails g pu:res:scaffoldを使用してリソース作成を自動化する","定義を使用してカスタマイズ可能なUIコンポーネントを生成する","ポリシーを使用してアクセス制御ロジックを実装する"],"ko":["rails g pu:res:scaffold를 사용하여 리소스 생성을 자동화한다","정의를 사용하여 사용자 지정 가능한 UI 컴포넌트를 생성한다","정책을 사용하여 권한 논리를 구현한다"],"es":["Automatización de la creación de recursos con rails g pu:res:scaffold","Generación de componentes de IU personalizables utilizando definiciones","Implementación de lógica de permisos con políticas"],"fr":["Automatisation de la création de ressources avec rails g pu:res:scaffold","Génération de composants d''interface utilisateur personnalisables à l''aide de définitions","Mise en œuvre de la logique des autorisations avec des politiques"],"de":["Automatisierung der Ressourcenerstellung mit rails g pu:res:scaffold","Generierung von anpassbaren Benutzeroberflächenkomponenten unter Verwendung von Definitionen","Implementierung von Berechtigungslogik mit Richtlinien"],"pt":["Automatizar a criação de recursos com rails g pu:res:scaffold","Gerar componentes de interface do usuário personalizáveis usando definições","Implementar lógica de permissão com políticas"],"ru":["Автоматизировать создание ресурсов с помощью rails g pu:res:scaffold","Генерировать настраиваемые компоненты пользовательского интерфейса, используя определения","Реализовать логику разрешений с помощью политик"],"ar":["التحكم الآلي في إنشاء الموارد باستخدام rails g pu:res:scaffold","إنشاء مكونات واجهة المستخدم القابلة للتعديل باستخدام التعريفات","تنفيذ منطق التصريح باستخدام السياسات"]},"limitations":{"en":["Requires adherence to core rules, such as always using generators and checking relevant skills first","Specific to Rails apps","Must follow conventions for optimal performance"],"zh":["需要遵守核心规则，例如始终使用生成器并检查相关技能","仅适用于Rails应用程序","必须遵循惯例以实现最佳性能"],"ja":["コアルールに従う必要があります。たとえば、常に生成器を使用し、関連スキルを確認する","Railsアプリケーションのみに適用されます","最適なパフォーマンスを実現するには、規約に従う必要があります"],"ko":["코어 규칙을遵守해야 한다. 예를 들어, 항상 생성기를 사용하고 관련 스킬을 확인한다","Rails 애플리케이션에만 적용된다","최적의 성능을 달성하려면 규칙을 따라야 한다"],"es":["Requiere adherirse a las reglas básicas, como siempre utilizar generadores y comprobar las habilidades relevantes primero","Específico para aplicaciones de Rails","Debe seguir convenciones para un rendimiento óptimo"],"fr":["Nécessite de se conformer aux règles de base, telles que toujours utiliser des générateurs et vérifier les compétences pertinentes en premier","Spécifique aux applications Rails","Doit suivre les conventions pour des performances optimales"],"de":["Erfordert die Einhaltung der Grundregeln, wie z.B. immer Generatoren zu verwenden und relevante Fähigkeiten zuerst zu überprüfen","Spezifisch für Rails-Anwendungen","Muss Konventionen befolgen, um ein optimales Leistungsvermögen zu erzielen"],"pt":["Exige aderência às regras centrais, como sempre usar geradores e verificar habilidades relevantes primeiro","Específico para aplicativos Rails","Deve seguir convenções para desempenho ótimo"],"ru":["Требует соблюдения основных правил, таких как всегда использовать генераторы и проверять соответствующие навыки сначала","Конкретно для приложений Rails","Должно следовать соглашениям для оптимальной производительности"],"ar":["يتطلب الالتزام بالقواعد الأساسية، مثل استخدام المولّدين دائمًا والتحقق من المهارات ذات الصلة أولا","محدد لتطبيقات ريلز","يجب اتباع الاتفاقيات من أجل أداء مثالي"]},"version":4},"contentHash":"e83fe7aa9838e2012fbb24dcf57aa67e902edd650d7f9f5ab23cc93afa7bedc4","qualityScore":38}');
