INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('radioactive-labs/plutonium-core/plutonium', 'plutonium', 'radioactive-labs', 'plutonium-core', 'community', 'plutonium radioactive-labs plutonium-core community admin-dashboard admin-panel framework rails rapid-development rodauth-rails ruby starter Plutonium is a convention-driven framework for building production-ready Rails apps in minutes. It benefits developers by providing a customizable and AI-ready solution. Plutonium是一个快速开发Rails应用的工具，通过AI驱动的开发流程，帮助开发者快速构建生产就绪的应用 Plutoniumは、AIエージェントを活用したRailsアプリの迅速開発ツールです Plutonium은 AI 도구를 활용한 빠른 Rails 앱 개발을 위한 도구입니다 Plutonium es una herramienta para crear aplicaciones Rails listas para producción en minutos, con generadores y personalizaciones Plutonium est un outil pour créer des applications Rails prêtes pour la production en quelques minutes, avec des générateurs et des personnalisation Plutonium ist ein Tool, um Rails-Anwendungen in Minuten zu erstellen, die bereit für die Produktion sind, mit Generatoren und Anpassungen O Plutonium é um framework de desenvolvimento rápido para aplicativos Rails, que permite a criação de aplicações personalizadas em minutos. Plutonium - это быстрый фреймворк для разработки приложений Rails, который позволяет создавать настраиваемые приложения за минуты. بليوتونيوم هو إطار سريع للتنمية لتطبيقات ريلز، يسمح بإنشاء تطبيقات مخصصة في دقائق. how to use plutonium plutonium vs rails plutonium setup guide what is plutonium plutonium alternative plutonium install rapid rails development customizable rails apps rodauth-rails integration Plutonium Rails开发 AI智能工具 快速开发 RoDauth-Rails Admin Dashboard definitions policies 多语言 国际化 Uses `rails g pu:res:scaffold` generator for rapid resource creation Supports customizable admin dashboards with Rodauth-Rails Employs definitions for UI customization instead of controllers Utilizes policies for authorization and permission logic Enables fully customizable and AI-ready Rails applications Plutonium is a Rails framework that enables rapid application development using generators, definitions, and policies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('uhyo/funstack-router/release-funstack', 'community', 'uhyo', 'funstack-router', 'uhyo/funstack-router', 'release-funstack', 43, 1, 38, '2026-02-25T14:03:12Z', '2026-03-06T06:36:34.631Z', '7f90a61240242a2e4483a216eb19a875411c76d8682863479c4ff092740dc405', '{"id":"uhyo/funstack-router/release-funstack","name":"release-funstack","description":{"en":"The release-funstack skill helps developers release new versions of the @funstack/router package. It guides users through updating package.json and route files.","zh":"Release FUNSTACK Skill 是一个基于 Navigation API 的 Router 库，用于优化 React 应用路由管理","ja":"Release FUNSTACK Skill は Navigation API ベースのルーター ライブラリで、React アプリのルーティングを最適化する","ko":"Release FUNSTACK Skill은 Navigation API 기반의 Router 라이브러리로서 React 애플리케이션의 라우팅을 최적화합니다","es":"release-funstack es una biblioteca de enrutamiento basada en Navigation API para React, que permite una experiencia de enrutamiento sin History API legacy","fr":"release-funstack est une bibliothèque de routage basée sur Navigation API pour React, qui permet une expérience de routage sans History API legacy","de":"release-funstack ist eine Router-Bibliothek basierend auf Navigation API für React, die eine Routierungserfahrung ohne History API legacy ermöglicht","pt":"O release-funstack é uma biblioteca de roteamento baseada na Navigation API para React, permitindo uma exploração mais eficiente sem a necessidade da History API","ru":"release-funstack — это библиотека маршрутизации на основе Navigation API для React, позволяющая более эффективно исследовать без необходимости History API","ar":"release-funstack هي مكتبة تحكم الروتر تستند إلى Navigation API ل React، مما يسمح بالاستكشاف بشكل أكثر كفاءة دون الحاجة إلى History API"},"seo":{"title":{"en":"release-funstack: Router Library Setup Guide | AI Agent S...","zh":"Release FUNSTACK Skill Setup Guid