INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('uhyo/funstack-router/release-funstack', 'release-funstack', 'uhyo', 'funstack-router', 'community', 'release-funstack uhyo funstack-router community react router The release-funstack skill helps developers release new versions of the @funstack/router package. It guides users through updating package.json and route files. Release FUNSTACK Skill 是一个基于 Navigation API 的 Router 库，用于优化 React 应用路由管理 Release FUNSTACK Skill は Navigation API ベースのルーター ライブラリで、React アプリのルーティングを最適化する Release FUNSTACK Skill은 Navigation API 기반의 Router 라이브러리로서 React 애플리케이션의 라우팅을 최적화합니다 release-funstack es una biblioteca de enrutamiento basada en Navigation API para React, que permite una experiencia de enrutamiento sin History API legacy release-funstack est une bibliothèque de routage basée sur Navigation API pour React, qui permet une expérience de routage sans History API legacy release-funstack ist eine Router-Bibliothek basierend auf Navigation API für React, die eine Routierungserfahrung ohne History API legacy ermöglicht O release-funstack é uma biblioteca de roteamento baseada na Navigation API para React, permitindo uma exploração mais eficiente sem a necessidade da History API release-funstack — это библиотека маршрутизации на основе Navigation API для React, позволяющая более эффективно исследовать без необходимости History API release-funstack هي مكتبة تحكم الروتر تستند إلى Navigation API ل React، مما يسمح بالاستكشاف بشكل أكثر كفاءة دون الحاجة إلى History API how to use release-funstack release-funstack setup guide release-funstack alternative release-funstack vs react-router release-funstack install what is release-funstack release-funstack documentation release-funstack navigation api release-funstack semantic versioning Release FUNSTACK Skill Navigation API React 路由 Router 库 语义版本规则 AIエージェント React 性能优化 Updates package.json file based on semantic versioning rules Confirms version updates with the user before making changes Follows steps outlined in SKILL.md for releasing new package versions Supports react and router technologies Updates route files according to user instructions Determines current package version from packages/router/package.json file release-funstack is a router library based on Navigation API, designed to release new versions of the @funstack/router package without using History API legacy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kim-em/lean-zip/lean-array-list', 'community', 'kim-em', 'lean-zip', 'kim-em/lean-zip', 'lean-array-list', 38, 3, 38, '2026-03-06T12:49:20Z', '2026-03-07T01:50:15.571Z', '1d5daf8cbb5f31873592ec0fc67d658c93f99e03a95374187ac603b9a1f78aa3', '{"id":"kim-em/lean-zip/lean-array-list","name":"lean-array-list","description":{"en":"The lean-array-list skill simplifies ByteArray, Array, and List indexing for developers, providing efficient proof patterns. It benefits developers working with Lean 4.","zh":"Lean 4 中的 ByteArray/Array/List 优化涉及索引和长度转换，使用特定的函数和方法。","ja":"Lean 4 の ByteArray/Array/List 最適化は、インデックスと長さの変換を伴う特殊な関数とメソッドを使用します。","ko":"Lean 4 에서의 ByteArray/Array/List 최적화는 인덱싱과 길이 변환을 위한 특정 함수와 메서드를 사용합니다.","es":"Lean-array-list es una habilidad para trabajar con patrones de prueba en Lean 4, especialmente para ByteArray, Array y List. Ofrece funcionalidades como indexing y conversiones de longitud.","fr":"Lean-array-list est une compétence pour travailler avec des modèles de preuve dans Lean 4, en particulier pour ByteArray, Array et List. Elle propose des fonctionnalités telles que l''indexation et les conversions de longueur.","de":"Lean-array-list ist eine Fähigkeit, um mit Testmustern in Lean 4 zu arbeiten, insbesondere für ByteArray, Array und List. Sie bietet Funktionalitäten wie Indexierung und Längenkonvertierungen.","pt":"O Lean Array List é uma ferramenta para melhorar a eficiência do código, fornecendo padrões de prova para bytearray, array e list. Aprenda a configurá-lo corretamente.","ru":"Lean Array List - это инструмент для повышения эффективности кода, предоставляющий доказательные шаблоны для bytearray, array и list. Узнайте, как его настроить.","ar":"قائمة المصفوفة المحددة هي أداة لتحسين كفاءة الرمز، وتوفر أنماطاً إثباتية للمصفوفة والموادر والقائمة. تعلم كيفية إعدادها بشكل صحيح."},"seo":{"title":{"en":"lean-array-list: Proof Patterns Setup Guide | AI Agent Skill","zh":"Lean 4 ByteArray/Array/List 优化指南","ja":"Lean 4 ByteArray/Array/List 最適化セットアップガイド","ko":"Lean 4 ByteArray/Array/List 최적화 설정 가이드","es":"Guía de configuración de lean-array-list para Agentes de IA","fr":"Guide de mise en place de lean-array-list pour les Outils...","de":"Einrichtungsleitfaden für lean-array-list in KI-Agents","pt":"Guia de Configuração do Lean Array List para Desenvolvedores","ru":"Настройка ИИ Агентов: Руководство по Lean Array List","ar":"دليل إعداد قائمة المصفوفة المحددة لملحقي البرمجيات"},"description":{"en":"Unlock efficient ByteArray, Array, and List indexing with lean-array-list. Discover how to simplify proof patterns and optimize your workflow - learn more now!","zh":"了解 Lean 4 中的 ByteArray/Array/List 优化技巧，包括索引和长度转换。","ja":"Lean 4 の ByteArray/Array/List 最適化テクニックを紹介します。インデックスと長さの変換について学びましょう。","ko":"Lean 4 에서 ByteArray/Array/List 최적화를 위한 기술을 알아보세요. 인덱싱 및 길이 변환에 대해 자세히 알아보겠습니다.","es":"Aprende a utilizar lean-array-list con patrones de prueba para ByteArray, Array y List en Lean 4. Mejora tu desarrollo con Agentes de IA.","fr":"Découvrez comment utiliser lean-array-list avec des modèles de preuve pour ByteArray, Array et List dans Lean 4. Améliorez votre développement avec les Outil...","de":"Erfahren Sie, wie Sie lean-array-list mit Testmustern für ByteArray, Array und List in Lean 4 verwenden. Verbessern Sie Ihre Entwicklung mit KI-Agents.","pt":"Aprenda a configurar o Lean Array List para melhorar a eficiência do seu código. Descubra dicas e práticas recomendadas para desenvolvedores.","ru":"Узнайте, как настроить Lean Array List для повышения эффективности вашего кода. Получите советы и рекомендации для разработчиков от ИИ Агентов.","ar":"تعرف على كيفية إعداد قائمة المصفوفة المحددة لتحسين كفاءة رمزك. استكشف النصائح وأفضل الممارسات للمطورين من أدوات الذكاء الاصطناعي."},"definition":{"en":"lean-array-list is a skill that provides proof patterns for ByteArray, Array, and List indexing in Lean 4, enabling efficient data manipulation.","zh":"Lean 4 ByteArray/Array/List 优化是指在 Lean 4 中优化 ByteArray、Array 和 List 数据结构的性能和功能。","ja":"Lean 4 ByteArray/Array/List 最適化は、Lean 4 で ByteArray、Array、List データ構造のパフォーマンスと機能を最適化することです。","ko":"Lean 4 ByteArray/Array/List 최적화는 Lean 4에서 ByteArray, Array, List 데이터 구조의 성능과 기능을 최적화하는 것을 의미합니다.","es":"Lean-array-list es una habilidad de Agentes de IA que proporciona patrones de prueba para operaciones de ByteArray, Array y List en Lean 4.","fr":"Lean-array-list est une compétence des Outils d''IA qui fournit des modèles de preuve pour les opérations de ByteArray, Array et List dans Lean 4.","de":"Lean-array-list ist eine Fähigkeit von KI-Agents, die Testmuster für Operationen von ByteArray, Array und List in Lean 4 bereitstellt.","pt":"O que é Lean Array List? É uma ferramenta de prova de padrões para bytearray, array e list.","ru":"Что такое Lean Array List? Это инструмент доказательных шаблонов для bytearray, array и list.","ar":"ما هي قائمة المصفوفة المحددة؟ هي أداة أنماط إثباتية للمصفوفة والموادر والقائمة."},"features":{"en":["Simplifies ByteArray indexing using `data.data[pos] = data[pos]`","Supports Array indexing with `simp only [Array.getElem_toList]`","Enables List indexing with `List.getElem_map` and `Array.getElem_toList`","Provides length conversions using `Array.length_toList`","Optimizes proof patterns for ByteArray, Array, and List data structures"],"zh":["使用 data.data[pos] = data[pos] 进行 ByteArray 索引","使用 simp only [Array.getElem_toList] 进行 Array 到 List 的转换","使用 List.getElem_map 进行 List 元素的映射","支持长度转换，例如 Array.length_toList"],"ja":["ByteArray のインデックスを data.data[pos] = data[pos] で行う","Array を List に変換するときに simp only [Array.getElem_toList] を使用する","List の要素を List.getElem_map でマッピングする","長さの変換をサポートする、たとえば Array.length_toList"],"ko":["ByteArray 인덱싱을 위해 data.data[pos] = data[pos] 사용","Array 를 List 로 변환할 때 simp only [Array.getElem_toList] 사용","List 요소의 매핑을 위해 List.getElem_map 사용","길이 변환 지원, 예를 들어 Array.length_toList"],"es":["Indexación de ByteArray y Array con patrones de prueba","Conversión de longitud entre Array y List","Compatibilidad con List.getElem_map para operaciones de mapeo","Uso de simp only para simplificar pruebas","Soporte para versiones recientes de Lean 4, como v4.29.0-rc2"],"fr":["Indexation de ByteArray et Array avec des modèles de preuve","Conversion de longueur entre Array et List","Compatibilité avec List.getElem_map pour les opérations de mappage","Utilisation de simp only pour simplifier les preuves","Prise en charge des versions récentes de Lean 4, comme v4.29.0-rc2"],"de":["Indexierung von ByteArray und Array mit Testmustern","Längenkonvertierung zwischen Array und List","Unterstützung für List.getElem_map bei Mapping-Operationen","Verwendung von simp only zur Vereinfachung von Tests","Unterstützung für neuere Versionen von Lean 4, wie v4.29.0-rc2"],"pt":["Padrões de prova para bytearray","Conversões de comprimento para array e list","Indexação de bytearray e array","Suporte a List.getElem_map"],"ru":["Паттерны доказательств для bytearray","Преобразования длины для array и list","Индексация bytearray и array","Поддержка List.getElem_map"],"ar":["أنماط إثباتية للمصفوفة","تحويلات الطول للمصفوفة والقائمة","فهرسة المصفوفة والموادر","دعم List.getElem_map"]},"keywords":{"en":["how to use lean-array-list","lean-array-list setup guide","lean-array-list vs Lean 3","what is lean-array-list","lean-array-list install","lean-array-list proof patterns","ByteArray indexing in Lean 4","Array indexing in Lean 4","List indexing in Lean 4"],"zh":["Lean 4","ByteArray","Array","List","索引","长度转换","最適化","AIエージェント","Lean 4 优化"],"ja":["Lean 4","ByteArray","Array","List","インデックス","長さの変換","最適化","AIエージェント","Lean 4 最適化"],"ko":["Lean 4","ByteArray","Array","List","인덱싱","길이 변환","최적화","AI 에이전트","Lean 4 최적화"],"es":["lean-array-list","Agentes de IA","patrones de prueba","ByteArray","Array","List","Lean 4","indexación","conversión de longitud","List.getElem_map"],"fr":["lean-array-list","Outils d''IA","modèles de preuve","ByteArray","Array","List","Lean 4","indexation","conversion de longueur","List.getElem_map"],"de":["lean-array-list","KI-Agents","Testmuster","ByteArray","Array","List","Lean 4","Indexierung","Längenkonvertierung","List.getElem_map"],"pt":["Lean Array List","padrões de prova","bytearray","array","list","indexação","conversões de comprimento","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Lean Array List","паттерны доказательств","bytearray","array","list","индексация","преобразования длины","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["قائمة المصفوفة المحددة","أنماط إثباتية","المصفوفة","الموادر","القائمة","فهرسة","تحويلات الطول","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"kim-em","repo":"lean-zip","repoPath":"kim-em/lean-zip","stars":38,"forks":3,"updatedAt":"2026-03-06T12:49:20Z","topics":[],"category":"community","skillMd":{"name":"lean-array-list","description":"Use when Lean 4 proofs involve ByteArray, Array, List indexing, getElem, length lemmas, take/drop, or roundtrip proofs over byte collections.","bodyPreview":"# Lean 4 ByteArray/Array/List Proof Patterns\n\n## ByteArray/Array/List Indexing\n\n- `data.data[pos] = data[pos]` (where `data : ByteArray`) is `rfl`\n- For `data.data.toList[pos] = data[pos]`: `simp only [Array.getElem_toList]` suffices\n  (as of v4.29.0-rc2; on rc1 a trailing `; rfl` was also needed)\n- When `List.getElem_map` is involved (e.g. `(arr.toList.map f)[i] = f arr[i]`):\n  `simp only [List.getElem_map, Array.getElem_toList]` closes the goal\n\n## Length Conversions\n\n- `Array.length_toList`:","body":"# Lean 4 ByteArray/Array/List Proof Patterns\n\n## ByteArray/Array/List Indexing\n\n- `data.data[pos] = data[pos]` (where `data : ByteArray`) is `rfl`\n- For `data.data.toList[pos] = data[pos]`: `simp only [Array.getElem_toList]` suffices\n  (as of v4.29.0-rc2; on rc1 a trailing `; rfl` was also needed)\n- When `List.getElem_map` is involved (e.g. `(arr.toList.map f)[i] = f arr[i]`):\n  `simp only [List.getElem_map, Array.getElem_toList]` closes the goal\n\n## Length Conversions\n\n- `Array.length_toList`: `arr.toList.length = arr.size`\n- `List.size_toArray`: `(l.toArray).size = l.length` — bridges Array.size to List.length\n  for array literals (`#[a, b, c]` elaborates as `List.toArray [a, b, c]`)\n- `ByteArray.size_data`: `ba.data.size = ba.size`\n- Chain them for `ba.data.toList.length`\n\n**Concrete array size in `simp only`**: To reduce `#[a, b, ...].size` to a number,\nuse `List.size_toArray` + `List.length_cons` + `List.length_nil`:\n```lean\nsimp only [myArray, List.size_toArray, List.length_cons, List.length_nil]\n-- Reduces #[a, b, c].size to 3\n```\nNote: `Array.size_toArray` does NOT exist — use `List.size_toArray`.\n\n## `getElem?_pos`/`getElem!_pos` for Array Lookups\n\nTo prove `arr[i]? = some arr[i]!`, use the two-step pattern:\n```lean\nrw [getElem!_pos arr i h]  -- rewrites arr[i]! to arr[i] (bounds-checked)\nexact getElem?_pos arr i h  -- proves arr[i]? = some arr[i]\n```\n`getElem?_pos` needs the explicit container argument (not `_`) to avoid\n`GetElem?` type class synthesis failures.\n\n## Fin Coercion Mismatch in omega\n\nWhen a lemma over `Fin n` is applied as `lemma ⟨k, hk⟩`, omega treats\n`arr[(⟨k, hk⟩ : Fin n).val]!` and `arr[k]!` as different variables.\n\nFix by annotating the result type:\n```lean\nhave : arr[k]! ≥ 1 := lemma ⟨k, hk⟩\n```\n**Critical**: `have := lemma ⟨k, hk⟩` (without type annotation) does NOT work —\nthe anonymous hypothesis retains the Fin.val form and omega still sees two distinct\nvariables. Always use the annotated form.\n\n**Deeper mismatch — `GetElem` vs `getInternal`**: After `unfold f at h`, the goal\nmay use `Array.getInternal` (the raw internal accessor) while a helper lemma uses\n`arr[i]''hi` (the `GetElem` typeclass). Even with type annotation, `omega` treats\nthese as distinct expressions. The fix is `exact` with `Nat.le_trans` (or similar)\ninstead of `omega`, since `exact` does full definitional unification:\n\n```lean\n-- BAD: omega can''t unify GetElem-based and getInternal-based array access\nhave := helper_lemma code hlt  -- uses arr[code]''hlt via GetElem\nomega  -- fails: sees arr[code].fst and (arr.getInternal code hlt).fst as distinct\n\n-- GOOD: exact does definitional unification\nexact Nat.le_trans (helper_lemma code hlt) (Nat.le_add_right _ _)\n```\n\n## `decide_cbv` on Fin-Bounded Array Properties\n\nTo verify a property holds for all entries of a concrete array, use `decide_cbv`\non a `Fin`-bounded universal:\n\n```lean\nprivate theorem all_baselines_ge_three :\n    ∀ i : Fin myTable.size, (myTable[i.val]''i.isLt).1 ≥ 3 := by\n  decide_cbv\n```\n\nThen wrap in a Nat-indexed helper to avoid Fin coercion issues in callers:\n\n```lean\nprivate theorem baseline_ge_three (i : Nat) (hi : i < myTable.size) :\n    (myTable[i]''hi).1 ≥ 3 :=\n  all_baselines_ge_three ⟨i, hi⟩\n```\n\n**Key constraints**:\n- The `∀ i : Fin n, P i` form is needed for `decide_cbv` — it must be a closed\n  proposition (no free Nat variables)\n- `decide` (without `_cbv`) has the same constraint but may be slower\n- The Nat wrapper eliminates the Fin coercion so callers can use `exact` or\n  `Nat.le_trans` without the GetElem/getInternal mismatch\n\n## `List.getElem_of_eq` for Extracting from List Equality\n\nWhen `hih : l1 = l2` and you need `l1[i] = l2[i]`, use\n`List.getElem_of_eq hih hbound` where `hbound : i < l1.length`.\nThis avoids dependent-type rewriting issues with direct `rw [hih]` on getElem.\n\n## `n + 0` Normalization Breaks `rw` Patterns\n\nAs of v4.29.0-rc2, Lean normalizes `n + 0` to `n` earlier. If a lemma''s conclusion\ncontains `arr[pfx.size + k]` and you instantiate `k = 0`, the rewrite target\n`arr[pfx.size + 0]` won''t match the goal''s `arr[pfx.size]`. Fix: add a specialized\n`_zero` variant of the lemma that states the result with `arr[pfx.size]` directly.\n\n## `take`/`drop` ↔ `Array.extract`\n\nTo bridge `List.take`/`List.drop` (from spec) with `Array.extract` (from native):\n```lean\nsimp only [Array.toList_extract, List.extract, Nat.sub_zero, List.drop_zero]\n```\nThen `← List.map_drop` + `List.drop_take` for drop-inside-map-take.\n\n## `Array.toArray_toList`\n\n`a.toList.toArray = a` for any Array. Use `Array.toArray_toList`.\nNOT `Array.toList_toArray` or `List.toArray_toList` — those don''t exist.\n\n## `readBitsLSB_bound` for omega\n\n`readBitsLSB n bits = some (val, rest)` implies `val < 2^n`. Essential for bounding\nUInt values (e.g., `hlit_v.toNat < 32`) before omega can prove `≤ UInt16.size`.\n\n## List Nat ↔ Array UInt8 Roundtrip\n\nTo prove `l = (l.toArray.map Nat.toUInt8).toList.map UInt8.toNat` when all elements\nare ≤ 15 (from `ValidLengths`):\n```lean\nsimp only [Array.toList_map, List.map_map]; symm\nrw [List.map_congr_left (fun n hn => by\n  show UInt8.toNat (Nat.toUInt8 n) = n\n  simp only [Nat.toUInt8, UInt8.toNat, UInt8.ofNat, BitVec.toNat_ofNat]\n  exact Nat.mod_eq_of_lt (by have := hv.1 n hn; omega))]\nsimp  -- closes `List.map (fun n => n) l = l` (not `List.map id l`)\n```\nNote: `List.map_congr_left` produces `fun n => n` not `id`, so `List.map_id`\nwon''t match — use `simp` instead.\n\n## UInt8→Nat→UInt8 Roundtrip\n\nTo prove `Nat.toUInt8 (UInt8.toNat u) = u`:\n```lean\nunfold Nat.toUInt8 UInt8.ofNat UInt8.toNat\nrw [BitVec.ofNat_toNat, BitVec.setWidth_eq]\n```\nDo NOT use `simp [Nat.toUInt8, UInt8.toNat, ...]` — it loops via\n`UInt8.toNat.eq_1` / `UInt8.toNat_toBitVec`. Do NOT try `congr 1` (max recursion)\nor `UInt8.ext` / `UInt8.eq_of_toNat_eq` (don''t exist).\n\nFor lists: `l.map (Nat.toUInt8 ∘ UInt8.toNat) = l` via `List.map_congr_left` with\nthe above per-element proof, then `simp`.\n\n## ByteArray Concatenation Indexing\n\nWhen proving properties about concatenated ByteArrays (e.g. `header ++ payload ++ trailer`),\nuse the `getElem!_append_left`/`getElem!_append_right` chain. Key lemmas (in\n`Zip/Spec/BinaryCorrect.lean`):\n\n**Two-part concatenation:**\n```lean\ngetElem!_append_left  (a b : ByteArray) (i : Nat) (h : i < a.size) :\n    (a ++ b)[i]! = a[i]!\ngetElem!_append_right (a b : ByteArray) (i : Nat) (h : i < b.size) :\n    (a ++ b)[a.size + i]! = b[i]!\n```\n\n**Three-part concatenation** (`a ++ b ++ c`):\n```lean\ngetElem!_append3_left  (a b c) (i) (h : i < a.size) :\n    (a ++ b ++ c)[i]! = a[i]!\ngetElem!_append3_mid   (a b c) (i) (h : i < b.size) :\n    (a ++ b ++ c)[a.size + i]! = b[i]!\ngetElem!_append3_right (a b c) (i) (h : i < c.size) :\n    (a ++ b ++ c)[(a ++ b).size + i]! = c[i]!\n```\n\n**Reading integers from concatenated arrays:**\n```lean\nreadUInt32LE_append_left   (a b) (offset) (h : offset + 4 ≤ a.size) :\n    readUInt32LE (a ++ b) offset = readUInt32LE a offset\nreadUInt32LE_append_right  (a b) (offset) (h : offset + 4 ≤ b.size) :\n    readUInt32LE (a ++ b) (a.size + offset) = readUInt32LE b offset\nreadUInt32LE_append3_mid   (a b c) (offset) (h : offset + 4 ≤ b.size) :\n    readUInt32LE (a ++ b ++ c) (a.size + offset) = readUInt32LE b offset\n```\n\n**Pattern for three-part concat proofs** (common in gzip/zlib framing):\n1. Unfold the function to expose individual `getElem!` or `readUInt32LE` calls\n2. Apply `getElem!_append3_*` or `readUInt32LE_append3_*` lemma for each byte/field\n3. Resolve arithmetic offsets with `show a.size + offset + k = a.size + (offset + k) from by omega`\n4. Close size bounds with `by simp [ByteArray.size_append]; omega`\n\n**Size of concatenation:**\n`ByteArray.size_append : (a ++ b).size = a.size + b.size`\n\n## Build Missing API, Don''t Work Around It\n\nIf a proof is blocked by missing lemmas for standard types (ByteArray, Array, List,\nUInt32, etc.), add the missing lemma to `ZipForStd/` in the appropriate namespace.\nFor example, if `ByteArray.foldl_toList` is missing, add it in\n`ZipForStd/ByteArray.lean` in the `ByteArray` namespace. These lemmas are candidates\nfor upstreaming to Lean''s standard library — write them as if they belonged there.\nDon''t use workarounds like going through `.data.data.foldl` when the right fix is a\nproper API lemma.\n"},"lastSynced":"2026-03-07T01:50:15.571Z","agentAnalysis":{"suitability":{"en":"Ideal for Lean 4 Agents requiring efficient ByteArray, Array, and List indexing and proof patterns.","zh":"适用于要求高效的ByteArray、Array和List索引以及证明模式的Lean 4 Agents。","ja":"効率的なByteArray、Array、およびListのインデックスと証明パターンを必要とするLean 4 Agentsに最適。","ko":"효율적인 ByteArray, Array 및 List 인덱싱 및 증명 패턴이 필요한 Lean 4 에이전트에 적합합니다.","es":"Ideal para agentes Lean 4 que requieren un indexado eficiente de ByteArray, Array y List, así como patrones de prueba.","fr":"Idéal pour les agents Lean 4 nécessitant un indexage efficace de ByteArray, Array et List, ainsi que des modèles de preuve.","de":"Ideal für Lean 4-Agents, die ein effizientes ByteArray-, Array- und List-Indexing sowie Beweismuster erfordern.","pt":"Ideal para Agentes Lean 4 que requerem indexação eficiente de ByteArray, Array e List, além de padrões de prova.","ru":"Идеально для агентов Lean 4, требующих эффективного индексирования ByteArray, Array и List, а также паттернов доказательств.","ar":"مثالي لعميل Lean 4 الذي يتطلب فهرسة كفاءة ByteArray و Array و List وأشكال البرهان."},"recommendation":{"en":"Empowers agents to simplify ByteArray, Array, and List indexing using efficient proof patterns, leveraging Lean 4''s capabilities, including `Array.getElem_toList` and `List.getElem_map` for streamlined data manipulation.","zh":"赋予代理简化ByteArray、Array和List索引的能力，使用高效的证明模式，利用Lean 4的功能，包括`Array.getElem_toList`和`List.getElem_map`，用于简化数据操作。","ja":"ByteArray、Array、およびListのインデックスを簡素化するためのエージェントを強化する、効率的な証明パターンを使用し、Lean 4の機能を利用する、`Array.getElem_toList`および`List.getElem_map`を使用したストリームライン化されたデータ操作。","ko":"ByteArray, Array 및 List 인덱싱을 간소화하는 에이전트를 강화하여 효율적인 증명 패턴을 사용하고 Lean 4의 기능을 활용하여 `Array.getElem_toList` 및 `List.getElem_map`을 사용한 스트림 라인 데이터 조작을 지원합니다.","es":"Permite a los agentes simplificar el indexado de ByteArray, Array y List utilizando patrones de prueba eficientes, aprovechando las capacidades de Lean 4, incluidas `Array.getElem_toList` y `List.getElem_map` para una manipulación de datos optimizada.","fr":"Permet aux agents de simplifier l''indexage de ByteArray, Array et List en utilisant des modèles de preuve efficaces, en exploitant les capacités de Lean 4, y compris `Array.getElem_toList` et `List.getElem_map` pour une manipulation de données optimisée.","de":"Ermöglicht es den Agents, das Indexing von ByteArray, Array und List mithilfe effizienter Beweismuster zu vereinfachen, indem es die Fähigkeiten von Lean 4 nutzt, einschließlich `Array.getElem_toList` und `List.getElem_map` für eine optimierte Datenmanipulation.","pt":"Permite que os agentes simplifiquem a indexação de ByteArray, Array e List usando padrões de prova eficientes, aproveitando as capacidades do Lean 4, incluindo `Array.getElem_toList` e `List.getElem_map` para manipulação de dados simplificada.","ru":"Наделяет агентов возможностью упростить индексирование ByteArray, Array и List с помощью эффективных паттернов доказательств, используя возможности Lean 4, включая `Array.getElem_toList` и `List.getElem_map` для оптимизированной манипуляции данными.","ar":"تمكين العميل من تبسيط فهرسة ByteArray و Array و List باستخدام أنماط برهان كفؤة، واستغلال إمكانيات Lean 4، بما في ذلك `Array.getElem_toList` و `List.getElem_map` من أجل معالجة بيانات مبسطة."},"useCases":{"en":["Simplifying ByteArray indexing with `data.data[pos] = data[pos]`","Streamlining Array to List conversions with `Array.getElem_toList`","Optimizing List indexing with `List.getElem_map`"],"zh":["使用`data.data[pos] = data[pos]`简化ByteArray索引","使用`Array.getElem_toList`简化Array到List的转换","使用`List.getElem_map`优化List索引"],"ja":["`data.data[pos] = data[pos]`を使用してByteArrayのインデックスを簡素化する","`Array.getElem_toList`を使用してArrayからListへの変換を簡素化する","`List.getElem_map`を使用してListのインデックスを最適化する"],"ko":["`data.data[pos] = data[pos]`를 사용하여 ByteArray 인덱싱을 간소화합니다","`Array.getElem_toList`를 사용하여 Array를 List로의 변환을 간소화합니다","`List.getElem_map`를 사용하여 List 인덱싱을 최적화합니다"],"es":["Simplificar el indexado de ByteArray con `data.data[pos] = data[pos]`","Optimizar la conversión de Array a List con `Array.getElem_toList`","Optimizar el indexado de List con `List.getElem_map`"],"fr":["Simplifier l''indexage de ByteArray avec `data.data[pos] = data[pos]`","Optimiser la conversion de Array en List avec `Array.getElem_toList`","Optimiser l''indexage de List avec `List.getElem_map`"],"de":["Vereinfachen des Indexing von ByteArray mit `data.data[pos] = data[pos]`","Optimieren der Konvertierung von Array zu List mit `Array.getElem_toList`","Optimieren des Indexing von List mit `List.getElem_map`"],"pt":["Simplificando a indexação de ByteArray com `data.data[pos] = data[pos]`","Otimizando conversões de Array para List com `Array.getElem_toList`","Otimizando a indexação de List com `List.getElem_map`"],"ru":["Упрощая индексирование ByteArray с `data.data[pos] = data[pos]`","Оптимизируя преобразования Array в List с `Array.getElem_toList`","Оптимизируя индексирование List с `List.getElem_map`"],"ar":["تبسيط فهرسة ByteArray مع `data.data[pos] = data[pos]`","جعل تحويلات Array إلى List أكثر كفاءة مع `Array.getElem_toList`","تحسين فهرسة List مع `List.getElem_map`"]},"limitations":{"en":["Requires Lean 4 environment","Compatible with Lean 4 version 4.29.0-rc2 and later"],"zh":["需要Lean 4环境","兼容Lean 4版本4.29.0-rc2及更高版本"],"ja":["Lean 4環境が必要","Lean 4バージョン4.29.0-rc2以降と互換性がある"],"ko":["Lean 4 환경이 필요합니다","Lean 4 버전 4.29.0-rc2 이상과 호환됩니다"],"es":["Requiere entorno Lean 4","Compatible con la versión 4.29.0-rc2 de Lean 4 y posteriores"],"fr":["Nécessite un environnement Lean 4","Compatible avec la version 4.29.0-rc2 de Lean 4 et ultérieures"],"de":["Benötigt Lean 4-Umgebung","Kompatibel mit Lean 4-Version 4.29.0-rc2 und später"],"pt":["Requer ambiente Lean 4","Compatível com a versão Lean 4 4.29.0-rc2 e posterior"],"ru":["Требует окружения Lean 4","Совместимо с версией Lean 4 4.29.0-rc2 и позже"],"ar":["يتطلب بيئة Lean 4","متوافق مع إصدار Lean 4 4.29.0-rc2 وأحدث"]},"version":4},"contentHash":"1d5daf8cbb5f31873592ec0fc67d658c93f99e03a95374187ac603b9a1f78aa3","qualityScore":38}');
