INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kim-em/lean-zip/lean-array-list', 'lean-array-list', 'kim-em', 'lean-zip', 'community', 'lean-array-list kim-em lean-zip community The lean-array-list skill simplifies ByteArray, Array, and List indexing for developers, providing efficient proof patterns. It benefits developers working with Lean 4. Lean 4 中的 ByteArray/Array/List 优化涉及索引和长度转换，使用特定的函数和方法。 Lean 4 の ByteArray/Array/List 最適化は、インデックスと長さの変換を伴う特殊な関数とメソッドを使用します。 Lean 4 에서의 ByteArray/Array/List 최적화는 인덱싱과 길이 변환을 위한 특정 함수와 메서드를 사용합니다. Lean-array-list es una habilidad para trabajar con patrones de prueba en Lean 4, especialmente para ByteArray, Array y List. Ofrece funcionalidades como indexing y conversiones de longitud. Lean-array-list est une compétence pour travailler avec des modèles de preuve dans Lean 4, en particulier pour ByteArray, Array et List. Elle propose des fonctionnalités telles que l''indexation et les conversions de longueur. Lean-array-list ist eine Fähigkeit, um mit Testmustern in Lean 4 zu arbeiten, insbesondere für ByteArray, Array und List. Sie bietet Funktionalitäten wie Indexierung und Längenkonvertierungen. O Lean Array List é uma ferramenta para melhorar a eficiência do código, fornecendo padrões de prova para bytearray, array e list. Aprenda a configurá-lo corretamente. Lean Array List - это инструмент для повышения эффективности кода, предоставляющий доказательные шаблоны для bytearray, array и list. Узнайте, как его настроить. قائمة المصفوفة المحددة هي أداة لتحسين كفاءة الرمز، وتوفر أنماطاً إثباتية للمصفوفة والموادر والقائمة. تعلم كيفية إعدادها بشكل صحيح. how to use lean-array-list lean-array-list setup guide lean-array-list vs Lean 3 what is lean-array-list lean-array-list install lean-array-list proof patterns ByteArray indexing in Lean 4 Array indexing in Lean 4 List indexing in Lean 4 Lean 4 ByteArray Array List 索引 长度转换 最適化 AIエージェント Lean 4 优化 Simplifies ByteArray indexing using `data.data[pos] = data[pos]` Supports Array indexing with `simp only [Array.getElem_toList]` Enables List indexing with `List.getElem_map` and `Array.getElem_toList` Provides length conversions using `Array.length_toList` Optimizes proof patterns for ByteArray, Array, and List data structures lean-array-list is a skill that provides proof patterns for ByteArray, Array, and List indexing in Lean 4, enabling efficient data manipulation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AJ-comp/Mythosia/clean-code-principles', 'community', 'AJ-comp', 'Mythosia', 'AJ-comp/Mythosia', 'clean-code-principles', 9, 1, 38, '2026-02-25T07:37:00Z', '2026-03-06T06:48:12.971Z', 'b37a2eb5ff326ebdbc0a6cd550b6d877754255dcd7303044239448d980264bf8', '{"id":"AJ-comp/Mythosia/clean-code-principles","name":"clean-code-principles","description":{"en":"This AI Agent skill provides a collection of principles and patterns for writing clean, readable, and maintainable code. It is designed for developers writing new functions, refactoring complex code, and reviewing code for quality improvements.","zh":"Clean Code Principles是一套编写干净、可读、可维护代码的原则和模式。适用于编写新函数、重构复杂代码和代码审查","ja":"Clean Code Principlesは、クリーンで読みやすくメンテナンス可能なコードを書くための原則とパターンの集まりです。新しい関数の作成、複雑なコードのリファクタリング、コードレビューに適しています","ko":"Clean Code Principles는 깨끗하고 가독성과 유지보수성이 높은 코드를 작성하기 위한 원칙과 패턴의 모음입니다. 새로운 함수 작성, 복잡한 코드 리팩토링, 코드 리뷰에 적합합니다","es":"Los principios de código limpio son una colección de patrones y reglas para escribir código legible y mantenible. Aprende a aplicarlos en tus proyectos","fr":"Les principes de code propre sont une collection de modèles et de règles pour écrire du code lisible et maintenable. Apprenez à les appliquer dans vos projets","de":"Die Clean-Code-Prinzipien sind eine Sammlung von Mustern und Regeln für das Schreiben von lesbarer und wartbarer Code. Erfahren Sie, wie Sie sie in Ihren Projekten anwenden können","pt":"Princípios de código limpo para melhorar a legibilidade e manutenção do código","ru":"Принципы чистого кода для улучшения читаемости и поддержки кода","ar":"مبادئ الكود النظيف لتحسين مقروئية و صيانة الرمز"},"seo":{"title":{"en":"Clean Code Principles: Refactoring & Code Review Guide | ...","zh":"Clean Code Principles_setup_guide_for_developers","ja":"Clean Code Principles_Best_Practices_for_AIエージェント","ko":"Clean Code Principles_구현_가이드_for_개발자","es":"Guía de Principios de Código Limpio para Desarrolladores","fr":"Principes de Code Propre : Guide de Mise en Place","de":"Clean Code Principles: Einrichtungsleitfaden für Entwickler","pt":"Princípios de Código Limpo: Guia de Configuração","ru":"Принципы Чистого Код: Руководство по Настройке","ar":"مبادئ الكود النظيف: دليل الإعداد"},"description":{"en":"Leverage this AI Agent skill to apply language-agnostic clean code principles. Refactor nested code, improve readability, and conduct effective code reviews....","zh":"了解Clean Code Principles，编写可读、可维护的代码。适用于编写新函数、重构复杂代码和代码审查","ja":"Clean Code Principlesを学ぶことで、読みやすくメンテナンス可能なコードを書くことができます。新しい関数の作成、複雑なコードのリファクタリング、コードレビューに適しています","ko":"Clean Code Principles를 통해 가독성과 유지보수성이 높은 코드를 작성하세요. 새로운 함수 작성, 복잡한 코드 리팩토링, 코드 리뷰에 적합합니다","es":"Aprende a aplicar principios de código limpio en tus proyectos con nuestra guía. Mejora la legibilidad y mantenibilidad de tu código","fr":"Découvrez comment appliquer les principes de code propre dans vos projets avec notre guide. Améliorez la lisibilité et la maintenabilité de votre code","de":"Erfahren Sie, wie Sie Clean-Code-Prinzipien in Ihren Projekten anwenden können. Verbessern Sie die Lesbarkeit und Wartbarkeit Ihres Codes","pt":"Aprenda a escrever código limpo e manutenível com nossa coleção de princípios e padrões para melhorar a qualidade do código","ru":"Узнайте, как писать чистый и поддерживаемый код с нашей коллекцией принципов и шаблонов для улучшения качества кода","ar":"تعلم كيفية كتابة رمز نظيف وقابل للصيانة باستخدام مجموعة مبادئ وأشكال لتحسين جودة الرمز"},"definition":{"en":"clean-code-principles is an AI Agent skill that offers a collection of language-agnostic principles and patterns for writing clean, readable, and maintainable code. It is used when writing new functions, refactoring nested code, and during code reviews.","zh":"Clean Code Principles是一套编写干净、可读、可维护代码的原则和模式","ja":"Clean Code Principlesは、クリーンで読みやすくメンテナンス可能なコードを書くための原則とパターンの集まり","ko":"Clean Code Principles는 깨끗하고 가독성과 유지보수성이 높은 코드를 작성하기 위한 원칙과 패턴의 모음","es":"Los principios de código limpio son reglas y patrones para escribir código legible y mantenible","fr":"Les principes de code propre sont des règles et des modèles pour écrire du code lisible et maintenable","de":"Die Clean-Code-Prinzipien sind Regeln und Muster für das Schreiben von lesbarer und wartbarer Code","pt":"Princípios de código limpo são regras e padrões para escrever código legível e manutenível","ru":"Принципы чистого кода - это правила и шаблоны для написания читаемого и поддерживаемого кода","ar":"مبادئ الكود النظيف هي قواعد وأشكال لكتابة رمز مقروء وقابل للصيانة"},"features":{"en":["Provides principles for writing new functions and methods","Guides refactoring of nested or complex code structures","Assists in reviewing code for readability improvements","Facilitates discussions on code quality enhancements","Offers language-agnostic patterns with concrete examples"],"zh":["编写新函数或方法","重构嵌套或复杂代码","代码审查和质量改进","语言无关的原则和模式","适用于所有编程语言"],"ja":["新しい関数やメソッドの作成","複雑なコードのリファクタリング","コードレビューと品質改善","言語に依存しない原則とパターン","すべてのプログラミング言語に対応"],"ko":["새로운 함수 또는 메서드 작성","복잡한 코드 리팩토링","코드 리뷰와 품질 개선","언어에 독립적인 원칙과 패턴","모든 프로그래밍 언어에 적용 가능"],"es":["Patrones de código para mejorar la legibilidad","Reglas para escribir funciones y métodos limpios","Técnicas de refactorización para código complejo","Herramientas para revisar la calidad del código","Aplicación de principios de código limpio en proyectos de desarrollo"],"fr":["Modèles de code pour améliorer la lisibilité","Règles pour écrire des fonctions et des méthodes propres","Techniques de refactorisation pour du code complexe","Outils pour examiner la qualité du code","Application des principes de code propre dans les projets de développement"],"de":["Code-Muster für verbesserte Lesbarkeit","Regeln für das Schreiben von sauberen Funktionen und Methoden","Refactorierungstechniken für komplexen Code","Werkzeuge zur Überprüfung der Code-Qualität","Anwendung von Clean-Code-Prinzipien in Entwicklungsprojekten"],"pt":["Padrões de código para melhorar a legibilidade","Regras para refatorar código complexo","Princípios para escrever funções e métodos limpos","Dicas para revisar código para melhorar a qualidade","Exemplos de código em diferentes linguagens de programação"],"ru":["Шаблоны кода для улучшения читаемости","Правила для рефакторинга сложного кода","Принципы для написания чистых функций и методов","Советы для проверки кода для улучшения качества","Примеры кода на разных языках программирования"],"ar":["أشكال الرمز لتحسين مقروئية","قواعد لتحويل رمز معقد","مبادئ لكتابة دالات وطرق نظيفة","نصائح لمراجعة الرمز لتحسين الجودة","أمثلة الرمز بلغات برمجة مختلفة"]},"keywords":{"en":["clean code principles for AI agents","how to use clean-code-principles skill","refactor nested code with AI","code review best practices","clean-code-principles install guide","language-agnostic coding patterns","clean-code-principles vs other linters","improve code readability AI"],"zh":["Clean Code Principles","编写干净代码","代码审查","代码重构","编程语言","代码质量","AI工具","开发者指南"],"ja":["Clean Code Principles","クリーンコード","コードレビュー","コードリファクタリング","プログラミング言語","コード品質","AIエージェント","開発者向け"],"ko":["Clean Code Principles","깨끗한 코드 작성","코드 리뷰","코드 리팩토링","프로그래밍 언어","코드 품질","AI 툴","개발자 가이드"],"es":["principios de código limpio","código legible","mantenimiento de código","refactorización de código","calidad de código","desarrollo de software","herramientas de desarrollo","mejora de código","patrones de código","reglas de código"],"fr":["principes de code propre","code lisible","maintenance de code","refactorisation de code","qualité de code","développement de logiciels","outils de développement","amélioration de code","modèles de code","règles de code"],"de":["Clean-Code-Prinzipien","lesbarer Code","Code-Wartung","Code-Refactorierung","Code-Qualität","Software-Entwicklung","Entwicklertools","Code-Verbesserung","Code-Muster","Code-Regeln"],"pt":["princípios de código limpo","código limpo","legibilidade de código","manutenção de código","refatoração de código","qualidade de código","desenvolvimento de software","programação"],"ru":["принципы чистого кода","чистый код","читаемость кода","поддержка кода","рефакторинг кода","качество кода","разработка программного обеспечения","программирование"],"ar":["مبادئ الكود النظيف","الكود النظيف","مقروئية الرمز","صيانة الرمز","تحويل الرمز","جودة الرمز","تطوير البرمجيات","البرمجة"]}},"owner":"AJ-comp","repo":"Mythosia","repoPath":"AJ-comp/Mythosia","stars":9,"forks":1,"updatedAt":"2026-02-25T07:37:00Z","topics":[],"category":"community","skillMd":{"name":"clean-code-principles","description":"Enforce clean code principles when writing or reviewing code. Use when writing new functions, refactoring existing code, or reviewing code for readability and maintainability. Covers guard clauses, modularization, naming conventions, and more.","bodyPreview":"# Clean Code Principles\n\nA collection of principles and patterns for writing clean, readable, and maintainable code.\n\n## When to Use This Skill\n\n- Writing new functions or methods\n- Refactoring nested or complex code\n- Reviewing code for readability\n- Discussing code quality improvements\n\n> **Note:** The principles and rules in each document apply to all programming languages. Examples are shown in a specific language for concreteness, but the patterns themselves are language-agnostic.\n>\n> **Imp","body":"# Clean Code Principles\n\nA collection of principles and patterns for writing clean, readable, and maintainable code.\n\n## When to Use This Skill\n\n- Writing new functions or methods\n- Refactoring nested or complex code\n- Reviewing code for readability\n- Discussing code quality improvements\n\n> **Note:** The principles and rules in each document apply to all programming languages. Examples are shown in a specific language for concreteness, but the patterns themselves are language-agnostic.\n>\n> **Important:** When refactoring, remove comments that are no longer relevant to the changed code. However, comments that are still valid and provide useful context (e.g., *why* a decision was made, business rules, workarounds, warnings) must be preserved.\n\n## Principles Overview\n\n| Principle | Description | Reference |\n| --- | --- | --- |\n| Guard Clause Pattern | Fail fast with early returns, keep code flat | `guard-clause-pattern.md` |\n| Function Decomposition | Break large functions into small, focused units | `function-decomposition.md` |\n| Magic Numbers & Strings | Replace unexplained literals with named constants or enums | `magic-numbers-and-strings.md` |\n| DRY Principle | Eliminate duplicated logic with shared abstractions | `dry-principle.md` |\n| Conditional Simplification | Reduce complex branching into clear, readable conditions | `conditional-simplification.md` |\n| Boolean & Flag Parameters | Replace boolean params with enums, methods, or option objects | `boolean-and-flag-parameters.md` |\n\n## Core Philosophy\n\n1. **Readability First** — Code is read far more often than it is written\n2. **Fail Fast** — Handle errors and edge cases early, keep the happy path clear\n3. **Single Responsibility** — Each function/class should do one thing well\n4. **Minimal Nesting** — Flat code is easier to follow than deeply nested code\n5. **Meaningful Names** — Names should reveal intent without needing comments\n6. **DRY, but not at the cost of clarity** — Avoid premature abstraction\n"},"lastSynced":"2026-03-06T06:48:12.971Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced clean code analysis and refactoring capabilities.","zh":"非常适合需要高级清洁代码分析和重构功能的代码审查代理。","ja":"高度なクリーンコード分析およびリファクタリング機能を必要とするコードレビュー代理に最適です。","ko":"고급 클린 코드 분석 및 리팩토링 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan un análisis y capacidades de refactorización de código limpio avanzadas.","fr":"Parfait pour les agents de révision de code nécessitant une analyse et des capacités de refactorisation de code propre avancées.","de":"Perfekt für Code-Review-Agents, die eine erweiterte Analyse und Refactorierungsfunktionen für sauberen Code benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise e capacidades de refatoração de código limpo avançadas.","ru":"Идеально для агентов код-ревью, которым необходимы продвинутые возможности анализа и рефакторинга чистого кода.","ar":"مثالي للوكلاء المراجعة الكود الذين يحتاجون إلى تحليل وتحسين متقدم للكود النظيف."},"recommendation":{"en":"Empowers agents to write maintainable code using principles like Don''t Repeat Yourself (DRY) and Single Responsibility Principle (SRP), and apply language-agnostic patterns for improved readability and quality.","zh":"使代理能够使用像不重复自己（DRY）和单一责任原则（SRP）这样的原则编写可维护的代码，并应用语言无关的模式以提高可读性和质量。","ja":"エージェントが、自分自身を繰り返さない（DRY）や単一責任の原則（SRP）などの原則を使用して、保守可能なコードを記述し、可読性と品質の向上のために言語に依存しないパターンを適用できるようにします。","ko":"에이전트가 자체적으로 반복하지 않기(DRY) 및 단일 책임 원칙(SRP)과 같은 원칙을 사용하여 유지 가능한 코드를 작성하고, 가독성 및 품질 개선을 위해 언어에 의존하지 않는 패턴을 적용할 수 있도록 합니다.","es":"Permite a los agentes escribir código mantenible utilizando principios como No te repitas (DRY) y Principio de responsabilidad única (SRP), y aplicar patrones independientes del lenguaje para mejorar la legibilidad y la calidad.","fr":"Permet aux agents d''écrire du code maintenable en utilisant des principes tels que Ne te répète pas (DRY) et Principe de responsabilité unique (SRP), et appliquer des modèles indépendants du langage pour améliorer la lisibilité et la qualité.","de":"Ermöglicht es den Agenten, wartbares Code zu schreiben, indem sie Prinzipien wie Wiederholung vermeiden (DRY) und Einzelverantwortungsprinzip (SRP) verwenden und sprachunabhängige Muster für verbesserte Lesbarkeit und Qualität anwenden.","pt":"Habilita os agentes a escreverem código manutenível usando princípios como Não Repita Você Mesmo (DRY) e Princípio da Responsabilidade Única (SRP), e aplicar padrões independentes de linguagem para melhorar a legibilidade e a qualidade.","ru":"Наделяет агентов возможностью писать поддерживаемый код, используя принципы như Не Повторяй Самого Себя (DRY) и Принцип единой ответственности (SRP), и применять языково-независимые шаблоны для улучшения читаемости и качества.","ar":"يتمكن الوكلاء من كتابة كود قابل للصيانة باستخدام مبادئ مثل لا تتكرر نفسك (DRY) ومبدأ المسؤولية الواحدة (SRP)، وتطبيق أنماط غير معتمدة على اللغة لتحسين القابلية للقراءة والجودة."},"useCases":{"en":["Refactoring complex functions for better readability","Reviewing code for adherence to clean code principles","Generating suggestions for improving code quality"],"zh":["为了更好的可读性而重构复杂的函数","审查代码以确保遵守清洁代码原则","生成改进代码质量的建议"],"ja":["よりよい可読性のために複雑な関数をリファクタリングする","コードをクリーンコードの原則に従ってレビューする","コード品質の改善に関する提案を生成する"],"ko":["보다 나은 가독성을 위해 복잡한 함수를 리팩토링하기","클린 코드 원칙을 준수하는 코드를 리뷰하기","코드 품질 개선을 위한 제안을 생성하기"],"es":["Reestructuración de funciones complejas para una mejor legibilidad","Revisión del código para garantizar el cumplimiento de los principios de código limpio","Generación de sugerencias para mejorar la calidad del código"],"fr":["Réorganisation de fonctions complexes pour une meilleure lisibilité","Révision du code pour garantir le respect des principes de code propre","Génération de suggestions pour améliorer la qualité du code"],"de":["Umstrukturierung komplexer Funktionen für bessere Lesbarkeit","Überprüfung des Codes auf Einhaltung der Prinzipien für sauberen Code","Erzeugung von Vorschlägen zur Verbesserung der Codequalität"],"pt":["Refatoração de funções complexas para melhor legibilidade","Revisão de código para aderência aos princípios de código limpo","Geração de sugestões para melhoria da qualidade do código"],"ru":["Рефакторинг сложных функций для лучшей читаемости","Проверка кода на соответствие принципам чистого кода","Генерация предложений для улучшения качества кода"],"ar":["إعادة هيكلة الدوال المعقدة لتحسين القابلية للقراءة","مراجعة الكود لامتثاله لمبادئ الكود النظيف","توليد اقتراحات لتحسين جودة الكود"]},"limitations":{"en":["Language-agnostic but examples may be shown in a specific language for concreteness","Requires understanding of programming fundamentals"],"zh":["语言无关，但示例可能以特定语言显示以便于理解","需要理解编程基础"],"ja":["言語に依存しないが、具体性のために特定の言語で例が表示される可能性がある","プログラミングの基礎を理解する必要がある"],"ko":["언어에 의존하지 않지만, 구체성을 위해 특정 언어로 예가 표시될 수 있음","프로그래밍 기초를 이해해야 함"],"es":["Independiente del lenguaje, pero los ejemplos pueden mostrarse en un lenguaje específico para mayor concreción","Requiere comprensión de los conceptos básicos de la programación"],"fr":["Indépendant du langage, mais les exemples peuvent être présentés dans un langage spécifique pour plus de concrétude","Nécessite une compréhension des principes fondamentaux de la programmation"],"de":["Sprachunabhängig, aber Beispiele können in einer bestimmten Sprache gezeigt werden, um Konkretheit zu bieten","Benötigt das Verständnis der Grundlagen der Programmierung"],"pt":["Independente de linguagem, mas os exemplos podem ser mostrados em uma linguagem específica para concretude","Exige compreensão dos fundamentos da programação"],"ru":["Языково-независимый, но примеры могут быть показаны на конкретном языке для конкретности","Требует понимания основ программирования"],"ar":["مستقل عن اللغة، ولكن الأمثلة قد تظهر بلغة محددة من أجل الإيضاح","يتطلب فهم أساسيات البرمجة"]},"version":4},"contentHash":"b37a2eb5ff326ebdbc0a6cd550b6d877754255dcd7303044239448d980264bf8","qualityScore":38}');
