INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AJ-comp/Mythosia/clean-code-principles', 'clean-code-principles', 'AJ-comp', 'Mythosia', 'community', 'clean-code-principles AJ-comp Mythosia community This AI Agent skill provides a collection of principles and patterns for writing clean, readable, and maintainable code. It is designed for developers writing new functions, refactoring complex code, and reviewing code for quality improvements. Clean Code Principles是一套编写干净、可读、可维护代码的原则和模式。适用于编写新函数、重构复杂代码和代码审查 Clean Code Principlesは、クリーンで読みやすくメンテナンス可能なコードを書くための原則とパターンの集まりです。新しい関数の作成、複雑なコードのリファクタリング、コードレビューに適しています Clean Code Principles는 깨끗하고 가독성과 유지보수성이 높은 코드를 작성하기 위한 원칙과 패턴의 모음입니다. 새로운 함수 작성, 복잡한 코드 리팩토링, 코드 리뷰에 적합합니다 Los principios de código limpio son una colección de patrones y reglas para escribir código legible y mantenible. Aprende a aplicarlos en tus proyectos Les principes de code propre sont une collection de modèles et de règles pour écrire du code lisible et maintenable. Apprenez à les appliquer dans vos projets Die Clean-Code-Prinzipien sind eine Sammlung von Mustern und Regeln für das Schreiben von lesbarer und wartbarer Code. Erfahren Sie, wie Sie sie in Ihren Projekten anwenden können Princípios de código limpo para melhorar a legibilidade e manutenção do código Принципы чистого кода для улучшения читаемости и поддержки кода مبادئ الكود النظيف لتحسين مقروئية و صيانة الرمز clean code principles for AI agents how to use clean-code-principles skill refactor nested code with AI code review best practices clean-code-principles install guide language-agnostic coding patterns clean-code-principles vs other linters improve code readability AI Clean Code Principles 编写干净代码 代码审查 代码重构 编程语言 代码质量 AI工具 开发者指南 Provides principles for writing new functions and methods Guides refactoring of nested or complex code structures Assists in reviewing code for readability improvements Facilitates discussions on code quality enhancements Offers language-agnostic patterns with concrete examples clean-code-principles is an AI Agent skill that offers a collection of language-agnostic principles and patterns for writing clean, readable, and maintainable code. It is used when writing new functions, refactoring nested code, and during code reviews.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sudhanshug16/blackpepper/verbump', 'community', 'sudhanshug16', 'blackpepper', 'sudhanshug16/blackpepper', 'verbump', 3, 0, 38, '2026-02-02T03:36:59Z', '2026-03-06T07:00:20.598Z', '3f930a3059421294e1843bffd1d10fb5e199953e0589da43749498fe406a9027', '{"id":"sudhanshug16/blackpepper/verbump","name":"verbump","description":{"en":"verbump is a Parallel Workspace Manager for Coding Agents that automates updates to Cargo.toml and commits changes with clean messages. It benefits developers by simplifying their workflow.","zh":"Verbump 是一个并行工作空间管理器，用于更新 crates/blackpepper/Cargo.toml 文件","ja":"Verbump はコーディング エージェント用の並列ワークスペース マネージャーで、crates/blackpepper/Cargo.toml ファイルを更新","ko":"Verbump는 코딩 에이전트를 위한 병렬 작업 공간 관리자로 crates/blackpepper/Cargo.toml 파일을 업데이트합니다","es":"Verbump es un administrador de espacios de trabajo paralelo para agentes de codificación que permite actualizar y gestionar proyectos de forma eficiente","fr":"Verbump est un gestionnaire d''espaces de travail parallèle pour agents de codage qui permet de mettre à jour et de gérer des projets de manière efficace","de":"Verbump ist ein Parallel-Arbeitsbereichs-Manager für Codierungsagenten, der die effiziente Verwaltung und Aktualisierung von Projekten ermöglicht","pt":"O Verbump é um gerenciador de espaço de trabalho paralelo para agentes de codificação que atualiza dependências e commita alterações de forma eficiente","ru":"Verbump - это параллельный менеджер рабочих пространств для кодирования ИИ Агентов, который обновляет зависимости и коммитит изменения эффективно","ar":"Verbump هو مدير مساحة العمل الموازية لعمليات الترميز الذكي التي تحديث الإعتماديات وترسل التعديلات بفاعلية"},"seo":{"title":{"en":"verbump: Automated Workspace Manager Setup Guide | AI Age...","zh":"Verbump Setup Guide: 并行工作空间管理器","ja":"Verbump の設定方法: コーディング エージェント用並列ワークスペース マネージャー","ko":"Verbump 설정 가이드: 병렬 작업 공간 관리자","es":"Guía de configuración de Verbump: Administrador de espaci...","fr":"Guide de configuration de Verbump: Gestionnaire d''espaces...","de":"Einrichtungsleitfaden für Verbump: Parallel-Arbeitsbereic...","pt":"Guia de Configuração do Verbump: Gerenciamento Paralelo d...","ru":"Настройка Verbump: Параллельный Менеджер Рабочих Простран...","ar":"دليل إعداد Verbump: مدير مساحة العمل الموازية لعمليات الت..."},"description":{"en":"Discover how verbump streamlines coding workflows with one-shot bumps and clean commit messages. Learn to integrate verbump into your project today!","zh":"了解 Verbump 的功能和优点，包括一键 bump 更新和清晰的提交消息","ja":"Verbump の機能と利点を紹介します。一键 bump 更新とクリーンなコミット メッセージなど","ko":"Verbump의 기능과 이점을 알아보세요. 한 번의 bump 업데이트와 깨끗한 커밋 메시지 등","es":"Aprende a utilizar Verbump para gestionar tus proyectos de codificación de forma paralela y eficiente. Descubre sus características clave y beneficios","fr":"Découvrez comment utiliser Verbump pour gérer vos projets de codage de manière parallèle et efficace. Explorez ses fonctionnalités clés et avantages","de":"Erfahren Sie, wie Sie Verbump verwenden können, um Ihre Codierungsprojekte parallel und effizient zu verwalten. Entdecken Sie seine wichtigsten Funktionen un...","pt":"Aprenda a configurar o Verbump para gerenciar espaços de trabalho paralelos e melhorar a eficiência do seu fluxo de trabalho de codificação","ru":"Узнайте, как настроить Verbump для управления параллельными рабочими пространствами и улучшения эффективности вашего кодирования с помощью ИИ Агентов","ar":"تعرف على كيفية ضبط Verbump للإدارة الموازية لمساحات العمل وتحسين كفاءة تدفق عمل الترميز الذكي"},"definition":{"en":"verbump is a tool that automates the process of updating dependencies and committing changes in a coding project, using Cargo.toml and providing clean commit messages.","zh":"Verbump 是一个 AI 工具，用于管理并行工作空间","ja":"Verbump は AI エージェントの一種で、並列ワークスペースを管理","ko":"Verbump는 AI 에이전트의 일종으로 병렬 작업 공간을 관리합니다","es":"Verbump es una herramienta de AI que gestiona espacios de trabajo paralelos para agentes de codificación","fr":"Verbump est un outil d''IA qui gère des espaces de travail parallèles pour les agents de codage","de":"Verbump ist ein AI-Tool, das parallele Arbeitsbereiche für Codierungsagenten verwaltet","pt":"O Verbump é um ferramenta de gerenciamento de espaço de trabalho paralelo para agentes de codificação que automatiza tarefas de atualização e commit","ru":"Verbump - это инструмент параллельного управления рабочими пространствами для кодирования ИИ Агентов, который автоматизирует задачи обновления и коммита","ar":"Verbump هو أداة لإدارة مساحة العمل الموازية لعمليات الترميز الذكي التي تلقائية المهام التحديث والارسال"},"features":{"en":["Updates crates/blackpepper/Cargo.toml with one-shot bumps","Reviews full diff including unrelated changes","Commits with clean messages","Pushes the current branch","Supports default patch bump and major/minor versioning","Proceeds without confirmation prompt for specified versions"],"zh":["一键 bump 更新","清晰的提交消息","支持指定版本","默认 patch bump","并行工作空间管理"],"ja":["一键 bump 更新","クリーンなコミット メッセージ","バージョンの指定","デフォルトの patch bump","並列ワークスペース管理"],"ko":["한 번의 bump 업데이트","깨끗한 커밋 메시지","버전 지정","기본 패치 범프","병렬 작업 공간 관리"],"es":["Actualización de versiones con un solo comando","Gestión de proyectos paralelos","Commit y push automático","Soporte para versiones principales, menores y de parches","Compatibilidad con Cargo.toml","Gestión de diffs y cambios no relacionados"],"fr":["Mise à jour des versions avec une seule commande","Gestion de projets parallèles","Commit et push automatique","Prise en charge des versions majeures, mineures et de correctifs","Compatibilité avec Cargo.toml","Gestion des diffs et des changements non liés"],"de":["Versionen aktualisieren mit einem einzigen Befehl","Parallele Projekte verwalten","Automatischer Commit und Push","Unterstützung für Haupt-, Neben- und Patchversionen","Kompatibilität mit Cargo.toml","Verwaltung von Diffs und nicht verwandten Änderungen"],"pt":["Atualização automática de dependências","Commit de alterações com mensagens limpas","Suporte a bump de versão (patch, minor, major)","Gerenciamento paralelo de espaços de trabalho","Integração com o fluxo de trabalho de codificação"],"ru":["Автоматическое обновление зависимостей","Коммит изменений с чистыми сообщениями","Поддержка бампа версии (patch, minor, major)","Параллельное управление рабочими пространствами","Интеграция с потоком кодирования"],"ar":["تحديث تلقائي للإعتماديات","إرسال التعديلات مع رسائل نظيفة","دعم بامب الإصدار (patch, minor, major)","إدارة مساحة العمل الموازية","التكامل مع تدفق عمل الترميز"]},"keywords":{"en":["how to use verbump","verbump setup guide","verbump alternative","verbump vs npm","what is verbump","verbump install","cargo.toml management","automated workspace manager","clean commit messages"],"zh":["Verbump","AI 工具","并行工作空间管理","一键 bump 更新","清晰的提交消息","Cargo.toml 更新","crates 管理"],"ja":["Verbump","AI エージェント","並列ワークスペース管理","一键 bump 更新","クリーンなコミット メッセージ","Cargo.toml 更新","crates 管理"],"ko":["Verbump","AI 에이전트","병렬 작업 공간 관리","한 번의 bump 업데이트","깨끗한 커밋 메시지","Cargo.toml 업데이트","crates 관리"],"es":["Verbump","Administrador de espacios de trabajo paralelo","Agentes de codificación","Herramientas de AI para codificación","Gestión de proyectos paralelos","Actualización de versiones","Commit y push automático","Cargo.toml"],"fr":["Verbump","Gestionnaire d''espaces de travail parallèle","Agents de codage","Outils d''IA pour la codification","Gestion de projets parallèles","Mise à jour des versions","Commit et push automatique","Cargo.toml"],"de":["Verbump","Parallel-Arbeitsbereichs-Manager","Codierungsagenten","AI-Tools für Codierung","Parallele Projekte verwalten","Versionen aktualisieren","Automatischer Commit und Push","Cargo.toml"],"pt":["verbump","gerenciamento de espaço de trabalho paralelo","agentes de codificação","atualização de dependências","commit de alterações","bump de versão","fluxo de trabalho de codificação","ferramentas de codificação"],"ru":["verbump","параллельное управление рабочими пространствами","ИИ Агенты","обновление зависимостей","коммит изменений","бамп версии","поток кодирования","инструменты кодирования"],"ar":["verbump","إدارة مساحة العمل الموازية","عمليات الترميز الذكي","تحديث الإعتماديات","إرسال التعديلات","بامب الإصدار","تدفق عمل الترميز","أدوات الترميز"]}},"owner":"sudhanshug16","repo":"blackpepper","repoPath":"sudhanshug16/blackpepper","stars":3,"forks":0,"updatedAt":"2026-02-02T03:36:59Z","topics":[],"category":"community","skillMd":{"name":"verbump","description":"Bump the Blackpepper version, review full git diffs (including unrelated changes), craft a Conventional Commit message, and push the current branch. Use when the user asks to verbump, bump version, increment version, release, or explicitly requests version bump + commit + push for this repo.","bodyPreview":"# Verbump\n\n## Overview\n\nOne-shot bump: update `crates/blackpepper/Cargo.toml`, review the full diff (including unrelated changes), commit with a clean message, and push the current branch.\nFor this project, commits are the changelog.\n\n## Workflow\n\n1. Pick target version (no confirmation prompt)\n   - If the user specifies a version, use it.\n   - If the user says \"verbump\" or \"bump\", default to a patch bump and proceed.\n   - Only ask for clarification if the user explicitly asks for a major/minor","body":"# Verbump\n\n## Overview\n\nOne-shot bump: update `crates/blackpepper/Cargo.toml`, review the full diff (including unrelated changes), commit with a clean message, and push the current branch.\nFor this project, commits are the changelog.\n\n## Workflow\n\n1. Pick target version (no confirmation prompt)\n   - If the user specifies a version, use it.\n   - If the user says \"verbump\" or \"bump\", default to a patch bump and proceed.\n   - Only ask for clarification if the user explicitly asks for a major/minor bump without giving a version.\n\n2. Review repository state and diffs\n   - Run `git status -sb`.\n   - Review complete diffs with `git diff --stat` and `git diff`.\n   - If unrelated changes exist, call them out and proceed to include them unless the user explicitly requests otherwise. Do not revert changes unless explicitly requested.\n\n3. Bump the version\n   - Update only `crates/blackpepper/Cargo.toml`.\n   - Keep edits ASCII-only and preserve file formatting.\n   - Re-check with `rg -n \"version\" crates/blackpepper/Cargo.toml` if needed.\n\n4. Validate and re-check diffs\n   - Re-run `git status -sb` and `git diff --stat`.\n   - Ensure only expected files changed before committing.\n   - If tests are run, report results; if skipped, state why.\n\n5. Commit and push\n   - Stage the relevant files (usually `crates/blackpepper/Cargo.toml`, plus anything already expected).\n   - Craft a Changelog style Commit message that includes a brief note on what changed since the last version tag.\n   - `git commit -m \"<message>\"`.\n   - `git push` the current branch.\n\n## Output expectations\n\n- Always report the chosen version and the final commit message.\n- Call out the summary note that covers changes since the last version tag.\n- Summarize any unrelated diffs you saw and whether they were included.\n"},"lastSynced":"2026-03-06T07:00:20.598Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents needing automated Cargo.toml updates and clean commit messages.","zh":"适用于需要自动更新 Cargo.toml 和清洁提交消息的编码代理。","ja":"自動でCargo.tomlを更新し、クリーンなコミットメッセージが必要なコーディングエージェントに最適。","ko":"자동으로 Cargo.toml을 업데이트하고 깨끗한 커밋 메시지가 필요한 코딩 에이전트에게 적합합니다.","es":"Perfecto para agentes de codificación que necesitan actualizaciones automatizadas de Cargo.toml y mensajes de confirmación limpios.","fr":"Parfait pour les agents de codage nécessitant des mises à jour automatiques de Cargo.toml et des messages de validation propres.","de":"Perfekt für Coding-Agents, die automatisierte Cargo.toml-Updates und saubere Commit-Mitteilungen benötigen.","pt":"Perfeito para Agentes de Codificação que precisam de atualizações automatizadas do Cargo.toml e mensagens de commit limpas.","ru":"Идеально для Кодирования Агентов, которым необходимы автоматические обновления Cargo.toml и чистые сообщения о коммитах.","ar":"مثالي لوفاء التشفير التي تحتاج إلى تحديثات أوتوماتيكية لملف Cargo.toml ورسائل الالتزام النظيفة."},"recommendation":{"en":"Empowers agents to automate updates to Cargo.toml, review full diffs including unrelated changes, and commit with clean messages using a parallel workspace manager, streamlining the workflow for developers working with Rust and Cargo.","zh":"赋予代理自动更新 Cargo.toml、查看包括无关更改的完整差异、并使用并行工作空间管理器以清洁的消息提交的能力，简化了使用Rust和Cargo的开发者的工作流程。","ja":"エージェントがCargo.tomlを自動更新し、無関係な変更を含む完全な差分を確認し、パラレルワークスペースマネージャーを使用してクリーンなメッセージでコミットできるようにし、RustとCargoを使用する開発者のワークフローを合理化します。","ko":"에이전트가 Cargo.toml을 자동으로 업데이트하고 관련이 없는 변경 사항을 포함한 전체 차이점을 검토하고 병렬 작업 공간 관리자를 사용하여 깨끗한 메시지로 커밋할 수 있게 함으로써 Rust와 Cargo를 사용하는 개발者の 워크플로우를 최적화합니다.","es":"Habilita a los agentes a automatizar las actualizaciones de Cargo.toml, a revisar diffs completos incluyendo cambios no relacionados y a confirmar con mensajes limpios utilizando un administrador de espacio de trabajo paralelo, optimizando el flujo de trabajo para los desarrolladores que trabajan con Rust y Cargo.","fr":"Permet aux agents d''automatiser les mises à jour de Cargo.toml, de passer en revue les diffs complets y compris les modifications non liées et de valider avec des messages propres en utilisant un gestionnaire d''espace de travail parallèle, rationalisant ainsi le flux de travail pour les développeurs travaillant avec Rust et Cargo.","de":"Ermächtigt Agenten, Updates von Cargo.toml zu automatisieren, vollständige Diffs einschließlich nicht damit zusammenhängender Änderungen zu überprüfen und mit sauberen Nachrichten zu committen, indem ein paralleler Arbeitsbereichs-Manager verwendet wird, wodurch der Arbeitsablauf für Entwickler, die mit Rust und Cargo arbeiten, gestreamt wird.","pt":"Habilita os agentes a automatizar atualizações para o Cargo.toml, revisar diferenças completas incluindo alterações não relacionadas e fazer commit com mensagens limpas usando um gerenciador de espaço de trabalho paralelo, otimizando o fluxo de trabalho para desenvolvedores que trabalham com Rust e Cargo.","ru":"Наделяет агентов возможностью автоматизировать обновления Cargo.toml, просматривать полные различия, включая несвязанные изменения, и совершать коммиты с чистыми сообщениями, используя параллельный менеджер рабочих пространств, оптимизируя рабочий процесс для разработчиков, работающих с Rust и Cargo.","ar":"يمنح الوكلاء القدرة على توفير تحديثات أوتوماتيكية لملف Cargo.toml ومراجعة الفروق الكاملة بما في ذلك التغييرات غير المرتبطة والالتزام برسائل نظيفة باستخدام مدير مساحة عمل متوازي، ويعزز تدفق العمل لمن يعملون مع Rust وCargo."},"useCases":{"en":["Automating Cargo.toml updates for Rust projects","Generating clean commit messages for changelogs","Streamlining workflow for developers using Cargo"],"zh":["自动更新Rust项目的Cargo.toml","为变更日志生成清洁的提交消息","简化使用Cargo的开发者的工作流程"],"ja":["RustプロジェクトのCargo.tomlを自動更新する","変更ログのためのクリーンなコミットメッセージを生成する","Cargoを使用する開発者のワークフローを合理化する"],"ko":["Rust 프로젝트의 Cargo.toml을 자동으로 업데이트하는 것","변경 로그를 위한 깨끗한 커밋 메시지를 생성하는 것","Cargo를 사용하는 개발者の 워크플로우를 최적화하는 것"],"es":["Automatizar actualizaciones de Cargo.toml para proyectos Rust","Generar mensajes de confirmación limpios para registros de cambios","Optimizar el flujo de trabajo para desarrolladores que utilizan Cargo"],"fr":["Automatiser les mises à jour de Cargo.toml pour les projets Rust","Générer des messages de validation propres pour les journaux des modifications","Rationaliser le flux de travail pour les développeurs utilisant Cargo"],"de":["Automatisieren von Cargo.toml-Updates für Rust-Projekte","Erzeugen von sauberen Commit-Mitteilungen für Änderungsprotokolle","Optimieren des Arbeitsablaufs für Entwickler, die Cargo verwenden"],"pt":["Automatizar atualizações do Cargo.toml para projetos Rust","Gerar mensagens de commit limpas para registros de alterações","Otimizar o fluxo de trabalho para desenvolvedores que usam Cargo"],"ru":["Автоматизировать обновления Cargo.toml для проектов Rust","Генерировать чистые сообщения о коммитах для журналов изменений","Оптимизировать рабочий процесс для разработчиков, использующих Cargo"],"ar":["توفير تحديثات أوتوماتيكية لملف Cargo.toml لمشاريع Rust","توليد رسائل الالتزام النظيفة لسجلات التغييرات","تحسين تدفق العمل للمطورين الذين يستخدمون Cargo"]},"limitations":{"en":["Requires Rust and Cargo setup","Limited to updating Cargo.toml files","No confirmation prompt for target version unless explicitly asked for major/minor version"],"zh":["需要Rust和Cargo的设置","仅限更新Cargo.toml文件","除非明确要求大版本/小版本，否则不提示目标版本确认"],"ja":["RustとCargoのセットアップが必要","Cargo.tomlファイルの更新のみ","メジャー/マイナーバージョンを明示的に要求しない限り、ターゲットバージョンの確認プロンプトがない"],"ko":["Rust와 Cargo 설정이 필요함","Cargo.toml 파일을 업데이트하는 것만 가능","메이저/마이너 버전을 명시적으로 요청하지 않는 한 대상 버전 확인 프롬프트 없음"],"es":["Requiere configuración de Rust y Cargo","Limitado a la actualización de archivos Cargo.toml","No hay mensaje de confirmación para la versión de destino a menos que se solicite explícitamente una versión mayor o menor"],"fr":["Nécessite une configuration Rust et Cargo","Limité à la mise à jour des fichiers Cargo.toml","Pas de message de confirmation pour la version cible à moins que la version majeure ou mineure ne soit explicitement demandée"],"de":["Benötigt Rust- und Cargo-Setup","Begrenzt auf das Aktualisieren von Cargo.toml-Dateien","Keine Bestätigungsmeldung für die Zielversion, es sei denn, eine Haupt- oder Nebenversion wird explizit angefordert"],"pt":["Requer configuração do Rust e Cargo","Limitado à atualização de arquivos Cargo.toml","Sem prompt de confirmação para versão alvo, a menos que seja solicitado explicitamente para versão major/minor"],"ru":["Требует настройки Rust и Cargo","Ограничен обновлением файлов Cargo.toml","Не имеет запроса на подтверждение для целевой версии, если не запрошено явно для основной/второстепенной версии"],"ar":["يتطلب إعداد Rust وCargo","محدود بالتحديث لملفات Cargo.toml","لا يوجد ترويسة تأكيد للإصدار المستهدف إلا إذا طُلب явًا للإصدار الرئيسي/الثانوي"]},"version":4},"contentHash":"3f930a3059421294e1843bffd1d10fb5e199953e0589da43749498fe406a9027","qualityScore":38}');
