INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Hantu-Raya/Deadlock-mods-collection/upstash-qstash', 'upstash-qstash', 'Hantu-Raya', 'Deadlock-mods-collection', 'community', 'upstash-qstash Hantu-Raya Deadlock-mods-collection community Upstash QStash is a serverless messaging solution that enables reliable message scheduling and delivery. It benefits developers who need to handle large volumes of messages without infrastructure management. Upstash QStash 是一个可靠的无服务器消息队列，提供 HTTP 入出和消息调度功能。它可以帮助您构建可靠的 webhook 交付系统 Upstash QStash は、インフラ管理不要の信頼性あるメッセージングを提供するサーバーレスメッセージキューです。HTTP 入出と cron ジョブの設定が可能 Upstash QStash 는 서버리스 메시징을 위한 리얼 타임 큐로، HTTP 入出과 reliability 를 제공합니다.cron 작업을 설정하고 webhook 배달 시스템을 구축할 수 있습니다 Upstash QStash es una herramienta de mensajería servidorless que permite enviar mensajes HTTP de forma confiable y escalable Upstash QStash est un outil de messagerie sans serveur qui permet d''envoyer des messages HTTP de manière fiable et évolutiv Upstash QStash ist ein Serverless-Messaging-Tool, das zuverlässige und skalierbare HTTP-Nachrichten ermöglicht Upstash QStash é uma ferramenta de mensagens serverless que permite criar cron jobs e sistemas de entrega de webhooks confiáveis. Com o QStash, você pode agendar milhões de mensagens e garantir a entrega sem perda. Upstash QStash — это инструмент для серверной связи, который позволяет создавать cron задания и системы доставки вебхуков без потери сообщений. С помощью QStash вы можете запланировать миллионы сообщений и гарантировать доставку. Upstash QStash هو أداة لرسائل الخادم أقل التي تمكنك من إنشاء مهام cron وأنظمة تسليم الويب هوك موثوقة. مع QStash ، يمكنك جدولة ملايين الرسائل وضمان التسليم بدون فقدان. how to use upstash-qstash upstash-qstash alternative upstash-qstash setup guide what is upstash-qstash upstash-qstash vs competitors upstash-qstash install reliable serverless messaging http-based messaging cron job scheduling Upstash QStash 无服务器消息队列 HTTP 入出 可靠的消息调度 cron 作业 webhook 交付系统 服务器-less 架构 AI エージェント 云计算 Schedules millions of messages with reliability Sets up cron jobs that run for years Builds webhook delivery systems that never drop a message Uses HTTP in and out for simplicity Provides reliable message delivery with minimal infrastructure management upstash-qstash is a serverless messaging system that provides reliable HTTP-based message scheduling and delivery with simplicity and scalability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tristanpoland/Tripwire/generate-component-story', 'community', 'tristanpoland', 'Tripwire', 'tristanpoland/Tripwire', 'generate-component-story', 1, 0, 38, '2026-02-20T01:58:15Z', '2026-03-07T12:50:08.179Z', 'e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa', '{"id":"tristanpoland/Tripwire/generate-component-story","name":"generate-component-story","description":{"en":"The generate-component-story skill helps developers create detailed component stories by following existing patterns and using sections for organization. It benefits developers working with crates and story src.","zh":"generate-component-story技能用于创建组件故事，包括基本用法、变体和交互示例","ja":"generate-component-storyスキルは、コンポーネントストーリーの作成に使用され、基本的な使用方法、バリアント、およびインタラクティブな例を含みます","ko":"generate-component-story 스킬은 컴포넌트 스토리를 생성하는 데 사용되며, 기본 사용법, 변형 및 상호 작용 예를 포함합니다","es":"generate-component-story es una habilidad para crear historias de componentes siguiendo patrones existentes y utilizando secciones para una cobertura integral","fr":"generate-component-story est une compétence pour créer des histoires de composants en suivant les modèles existants et en utilisant des sections pour une couverture complète","de":"generate-component-story ist eine Fähigkeit, um Komponenten-Geschichten zu erstellen, indem bestehende Muster befolgt und Abschnitte für eine umfassende Abdeckung verwendet werden","pt":"O generate-component-story é uma ferramenta para criar histórias de componentes, incluindo exemplos básicos e avançados","ru":"Generate-component-story - это инструмент для создания историй компонентов, включая базовые и продвинутые примеры","ar":"generate-component-story هو أداة لإنشاء قصص المكونات، بما في ذلك الأمثلة الأساسية والمتقدمة"},"seo":{"title":{"en":"generate-component-story: Component Story Generation Setu...","zh":"生成组件故事的最佳实践","ja":"コンポーネントストーリーの生成ガイド - AIエージェント","ko":"컴포넌트 스토리 생성하기 - AI 도구","es":"Guía de configuración para generate-component-story con p...","fr":"Meilleures pratiques pour generate-component-story avec d...","de":"Einrichtungsleitfaden für generate-component-story mit um...","pt":"Guia de Configuração do generate-component-story","ru":"ИИ Агенты: Настройка generate-component-story","ar":"دليل ضبط generate-component-story للوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to create comprehensive component stories with generate-component-story. Learn to organize stories with section! calls and include all options, ...","zh":"了解如何使用generate-component-story技能创建组件故事，包括基本用法、变体和交互示例","ja":"generate-component-storyスキルを使ってコンポーネントストーリーを作成する方法を学びましょう - AIエージェント","ko":"generate-component-story 스킬을 사용하여 컴포넌트 스토리를 생성하는 방법을 알아보세요 - AI 도구","es":"Aprende a crear historias de componentes con generate-component-story, incluyendo patrones existentes y secciones organizadas para una cobertura integral","fr":"Découvrez comment créer des histoires de composants avec generate-component-story, en suivant les modèles existants et en utilisant des sections pour une cou...","de":"Erfahren Sie, wie Sie mit generate-component-story Komponenten-Geschichten erstellen, einschließlich bestehender Muster und organisierter Abschnitte für eine...","pt":"Aprenda a criar histórias de componentes com o generate-component-story, incluindo padrões, seções e cobertura abrangente","ru":"Откройте для себя, как создавать истории компонентов с помощью generate-component-story, включая шаблоны, разделы и полное покрытие","ar":"تعرف على كيفية إنشاء قصص المكونات باستخدام generate-component-story، بما في ذلك الأنماط والاقسام والتغطية الشاملة"},"definition":{"en":"generate-component-story is a skill that enables developers to generate component stories based on existing styles and patterns, utilizing section! calls for organization.","zh":"generate-component-story是一种用于创建组件故事的技能","ja":"generate-component-storyは、コンポーネントストーリーを作成するためのスキルです","ko":"generate-component-story는 컴포넌트 스토리를 생성하는 스킬입니다","es":"generate-component-story es una herramienta de AI que ayuda a crear historias de componentes","fr":"generate-component-story est un outil d''IA qui aide à créer des histoires de composants","de":"generate-component-story ist ein AI-Tool, das beim Erstellen von Komponenten-Geschichten hilft","pt":"O generate-component-story é uma ferramenta de código aberto para criar histórias de componentes","ru":"Generate-component-story - это открытое программное обеспечение для создания историй компонентов","ar":"generate-component-story هو برنامج مفتوح المصدر لإنشاء قصص المكونات"},"features":{"en":["Follows existing patterns found in crates/story/src/stories","Utilizes section! calls for organizing story sections","Includes comprehensive coverage of all options, variants, and usage examples","Supports creation of basic usage examples and different variants and states","Enables interactive story creation with examples"],"zh":["基于现有模式创建组件故事","使用section!调用组织故事","涵盖组件的所有选项、变体和使用示例","支持基本用法、变体和交互示例","易于使用和扩展"],"ja":["既存のパターンに基づいたコンポーネントストーリーの作成","section!呼び出しを使用してストーリーを組織する","コンポーネントのすべてのオプション、バリアント、および使用例をカバーする","基本的な使用方法、バリアント、およびインタラクティブな例をサポートする","使用しやすく拡張可能"],"ko":["기존 패턴을 기반으로 컴포넌트 스토리를 생성","section! 호출을 사용하여 스토리를 구성","컴포넌트의 모든 옵션, 변형 및 사용 예를 포함","기본 사용법, 변형 및 상호 작용 예를 지원","사용하기 쉽고 확장 가능"],"es":["Seguir patrones existentes en crates/story/src/stories","Uso de secciones organizadas con llamadas a section!","Cobertura integral de opciones, variantes y ejemplos de uso","Inclusión de ejemplos básicos y de variantes","Soporte para diferentes estados y variantes de componentes"],"fr":["Suivre les modèles existants dans crates/story/src/stories","Utilisation de sections organisées avec des appels à section!","Couverture complète des options, variantes et exemples d''utilisation","Inclusion d''exemples de base et de variants","Prise en charge de différents états et variants de composants"],"de":["Befolgen bestehender Muster in crates/story/src/stories","Verwendung organisierter Abschnitte mit Aufrufen von section!","Umfassende Abdeckung von Optionen, Varianten und Verwendungsexemplen","Einbeziehung von Basisbeispielen und Varianten","Unterstützung für verschiedene Zustände und Varianten von Komponenten"],"pt":["Segue padrões existentes","Organiza histórias com seções","Cobertura abrangente de opções e variantes","Inclui exemplos básicos e avançados","Suporta criação de histórias de componentes personalizadas"],"ru":["Следует существующим шаблонам","Организует истории с разделами","Полное покрытие опций и вариантов","Включает базовые и продвинутые примеры","Поддерживает создание пользовательских историй компонентов"],"ar":["يتبع الأنماط الحالية","ينظم القصص مع الأقسام","التغطية الشاملة للخيارات والمتغيرات","يشمل الأمثلة الأساسية والمتقدمة","يدعم إنشاء قصص مكونات مخصصة"]},"keywords":{"en":["how to use generate-component-story","generate-component-story setup guide","what is generate-component-story","generate-component-story alternative","generate-component-story vs storybook","generate-component-story install","crate story src examples","section! call usage"],"zh":["generate-component-story","组件故事","AI工具","组件开发","storybook","前端开发","UI组件"],"ja":["generate-component-story","コンポーネントストーリー","AIエージェント","コンポーネント開発","storybook","フロントエンド開発","UIコンポーネント"],"ko":["generate-component-story","컴포넌트 스토리","AI 도구","컴포넌트 개발","storybook","프론트엔드 개발","UI 컴포넌트"],"es":["generate-component-story","herramientas de AI para desarrolladores","patrones de componentes","secciones organizadas","cobertura integral de componentes","ejemplos de uso de componentes","variantes de componentes","estados de componentes","AI Agentes para desarrolladores"],"fr":["generate-component-story","outils d''IA pour les développeurs","modèles de composants","sections organisées","couverture complète des composants","exemples d''utilisation de composants","variants de composants","états de composants","Agents d''IA pour les développeurs"],"de":["generate-component-story","AI-Tools für Entwickler","Muster von Komponenten","organisierte Abschnitte","umfassende Abdeckung von Komponenten","Verwendungsexemplen von Komponenten","Varianten von Komponenten","Zustände von Komponenten","AI-Agents für Entwickler"],"pt":["generate-component-story","criar histórias de componentes","componentes React","ferramentas de código aberto","desenvolvimento de software","criação de histórias de componentes personalizadas"],"ru":["generate-component-story","создание историй компонентов","компоненты React","открытое программное обеспечение","разработка программного обеспечения","создание пользовательских историй компонентов"],"ar":["generate-component-story","إنشاء قصص المكونات","مكونات React","برامج مفتوحة المصدر","تطوير البرمجيات","إنشاء قصص مكونات مخصصة"]}},"owner":"tristanpoland","repo":"Tripwire","repoPath":"tristanpoland/Tripwire","stars":1,"forks":0,"updatedAt":"2026-02-20T01:58:15Z","topics":[],"category":"community","skillMd":{"name":"generate-component-story","description":"Create story examples for components. Use when writing stories, creating examples, or demonstrating component usage.","bodyPreview":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactiv","body":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactive examples\n- Edge cases and error states\n"},"lastSynced":"2026-03-07T12:50:08.179Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing structured component story generation for crates and story src.","zh":"非常适合需要为箱和故事源生成结构化组件故事的前端代理","ja":"フロントエンドエージェントがクレートやストーリーソースの構造化されたコンポーネントストーリーを生成する必要がある場合に最適","ko":"프론트엔드 에이전트가 크레이트 및 스토리 소스에 대한 구조화된 구성 요소 스토리를 생성해야 하는 경우에 적합합니다","es":"Perfecto para agentes Frontend que necesitan generación de historias de componentes estructuradas para crates y story src.","fr":"Parfait pour les agents Frontend nécessitant une génération de récits de composants structurés pour les crates et la source de l''histoire.","de":"Perfekt für Frontend-Agents, die eine strukturierte Komponentenstory-Generierung für Crates und Story-Quellen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de geração de história de componentes estruturada para crates e story src.","ru":"Идеально для Фронтенд-агентов, которым необходима структурированная генерация истории компонентов для crates и story src.","ar":"مثالي لعميل الواجهة الأمامية الذي يحتاج إلى توليد قصة مكونات منظم للصناديق ومصدر القصة."},"recommendation":{"en":"Empowers agents to create detailed component stories by following existing patterns and using sections for organization, leveraging crates and story src for comprehensive coverage of component options and variants.","zh":"赋予代理创建详细组件故事的能力，通过遵循现有的模式并使用部分进行组织，利用箱和故事源来全面覆盖组件选项和变体","ja":"エージェントが既存のパターンに従って詳細なコンポーネントストーリーを作成し、セクションを使用して組織化し、コンポーネントオプションとバリアントの包括的なカバーを実現するためのクレートとストーリーソースを利用できるようにする","ko":"에이전트가 기존 패턴을 따르고 섹션을 사용하여 구성 요소를 조직화하여 구성 요소 스토리를 자세히 만들 수 있도록 하며, 구성 요소 옵션 및 변형의 포괄적인 범위를 위한 크레이트 및 스토리 소스를 활용할 수 있습니다","es":"Habilita a los agentes a crear historias de componentes detalladas siguiendo patrones existentes y utilizando secciones para la organización, aprovechando crates y story src para una cobertura integral de las opciones y variantes de los componentes.","fr":"Permet aux agents de créer des récits de composants détaillés en suivant des modèles existants et en utilisant des sections pour l''organisation, en exploitant les crates et la source de l''histoire pour une couverture complète des options et des variantes de composants.","de":"Ermächtigt Agents, detaillierte Komponentenstories zu erstellen, indem sie bestehende Muster befolgen und Abschnitte für die Organisation verwenden, Crates und Story-Quellen nutzen, um eine umfassende Abdeckung von Komponentenoptionen und -varianten zu gewährleisten.","pt":"Habilita os agentes a criar histórias de componentes detalhadas seguindo padrões existentes e usando seções para organização, aproveitando crates e story src para cobertura abrangente de opções e variantes de componentes.","ru":"Наделяет агентов возможностью создавать подробные истории компонентов, следуя существующим шаблонам и используя разделы для организации, используя crates и story src для всестороннего охвата вариантов и опций компонентов.","ar":"يمنح الوكلاء إمكانية إنشاء قصص مكونات مفصلة باتباع الأنماط الموجودة واستخدام الأقسام للت组织، واستغلال الصناديق ومصدر القصة لتغطية شاملة لخيارات ومتغيرات المكونات."},"useCases":{"en":["Generating component stories with basic usage examples","Creating stories with different variants and states","Organizing component stories with section! calls"],"zh":["生成具有基本用法示例的组件故事","创建具有不同变体和状态的故事","使用部分调用组织组件故事"],"ja":["基本的な使用方法の例を含むコンポーネントストーリーの生成","異なるバリアントや状態を持つストーリーの作成","セクション呼び出しを使用したコンポーネントストーリーの組織化"],"ko":["기본 사용 예를 포함하는 구성 요소 스토리 생성","다른 변형 및 상태를 가진 스토리 생성","섹션 호출을 사용한 구성 요소 스토리 구성"],"es":["Generación de historias de componentes con ejemplos de uso básico","Creación de historias con diferentes variantes y estados","Organización de historias de componentes con llamadas a secciones"],"fr":["Génération de récits de composants avec des exemples d''utilisation de base","Création de récits avec différentes variantes et états","Organisation de récits de composants avec des appels de sections"],"de":["Generierung von Komponentenstories mit grundlegenden Nutzungsexamples","Erstellung von Stories mit verschiedenen Varianten und Zuständen","Organisation von Komponentenstories mit Abschnittaufrufen"],"pt":["Geração de histórias de componentes com exemplos de uso básico","Criação de histórias com variantes e estados diferentes","Organização de histórias de componentes com chamadas de seção!"],"ru":["Генерация историй компонентов с основными примерами использования","Создание историй с разными вариантами и состояниями","Организация историй компонентов с помощью вызовов разделов!"],"ar":["توليد قصص مكونات مع أمثلة استخدام أساسية","إنشاء قصص مع متغيرات و 상태 مختلفة","تنظيم قصص مكونات باستخدام مكالمات القسم!"]},"limitations":{"en":["Requires access to crates/story/src/stories directory","Limited to story src format"],"zh":["需要访问箱/故事/源/故事目录","仅限故事源格式"],"ja":["crates/story/src/stories ディレクトリへのアクセスが必要","ストーリーソース形式に限定される"],"ko":["크레이트/스토리/소스/스토리 디렉토리에 대한 액세스가 필요합니다","스토리 소스 형식으로 제한됩니다"],"es":["Requiere acceso al directorio crates/story/src/stories","Limitado al formato story src"],"fr":["Nécessite l''accès au répertoire crates/story/src/stories","Limité au format source de l''histoire"],"de":["Erfordert Zugriff auf das Verzeichnis crates/story/src/stories","Begrenzt auf das Story-Quellenformat"],"pt":["Requer acesso ao diretório crates/story/src/stories","Limitado ao formato story src"],"ru":["Требует доступа к каталогу crates/story/src/stories","Ограничен форматом story src"],"ar":["يتطلب الوصول إلى الدليل crates/story/src/stories","محدود بتنسيق مصدر القصة"]},"version":4},"contentHash":"e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa","qualityScore":38}');
