INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tristanpoland/Tripwire/generate-component-story', 'generate-component-story', 'tristanpoland', 'Tripwire', 'community', 'generate-component-story tristanpoland Tripwire community The generate-component-story skill helps developers create detailed component stories by following existing patterns and using sections for organization. It benefits developers working with crates and story src. generate-component-story技能用于创建组件故事，包括基本用法、变体和交互示例 generate-component-storyスキルは、コンポーネントストーリーの作成に使用され、基本的な使用方法、バリアント、およびインタラクティブな例を含みます generate-component-story 스킬은 컴포넌트 스토리를 생성하는 데 사용되며, 기본 사용법, 변형 및 상호 작용 예를 포함합니다 generate-component-story es una habilidad para crear historias de componentes siguiendo patrones existentes y utilizando secciones para una cobertura integral generate-component-story est une compétence pour créer des histoires de composants en suivant les modèles existants et en utilisant des sections pour une couverture complète generate-component-story ist eine Fähigkeit, um Komponenten-Geschichten zu erstellen, indem bestehende Muster befolgt und Abschnitte für eine umfassende Abdeckung verwendet werden O generate-component-story é uma ferramenta para criar histórias de componentes, incluindo exemplos básicos e avançados Generate-component-story - это инструмент для создания историй компонентов, включая базовые и продвинутые примеры generate-component-story هو أداة لإنشاء قصص المكونات، بما في ذلك الأمثلة الأساسية والمتقدمة how to use generate-component-story generate-component-story setup guide what is generate-component-story generate-component-story alternative generate-component-story vs storybook generate-component-story install crate story src examples section! call usage generate-component-story 组件故事 AI工具 组件开发 storybook 前端开发 UI组件 Follows existing patterns found in crates/story/src/stories Utilizes section! calls for organizing story sections Includes comprehensive coverage of all options, variants, and usage examples Supports creation of basic usage examples and different variants and states Enables interactive story creation with examples generate-component-story is a skill that enables developers to generate component stories based on existing styles and patterns, utilizing section! calls for organization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nicolad/nomadically.work/sdd-verify', 'community', 'nicolad', 'nomadically.work', 'nicolad/nomadically.work', 'sdd-verify', 1, 0, 38, '2026-02-26T14:18:00Z', '2026-03-06T07:13:36.425Z', '6fcc2a37fe14cff93faec7e767ee32f451395f9c0cc9991b93a62f580e92c2b3', '{"id":"nicolad/nomadically.work/sdd-verify","name":"sdd-verify","description":{"en":"sdd-verify is a sub-agent responsible for verification, comparing actual implementation against specs, design, and tasks to find gaps. It benefits AI agent developers by ensuring quality gates.","zh":"sdd-verify是用于验证的AIエージェント，用于比较实际实现与规范、设计和任务以找到差异、不匹配和问题","ja":"sdd-verifyは検証用のAIエージェントであり、実際の実装と仕様、設計、タスクを比較してギャップ、不一致、問題を発見する","ko":"sdd-verify는 검증을 위한 AI 에이전트로서 실제 구현과 사양, 설계, 태스크를 비교하여 차이, 불일치, 문제를 찾습니다","es":"sdd-verify es un subagente responsable de la verificación de implementaciones contra specs, diseño y tareas. Aprenda a configurarlo para mejorar la calidad","fr":"sdd-verify est un sous-agent responsable de la vérification des mises en œuvre par rapport aux specs, conception et tâches. Découvrez comment le configurer pour améliorer la qualité","de":"sdd-verify ist ein Subagent, der für die Überprüfung von Implementierungen gegen Spezifikationen, Design und Aufgaben verantwortlich ist. Erfahren Sie, wie Sie es konfigurieren, um die Qualität zu verbessern","pt":"O sdd-verify é uma ferramenta de verificação de implementação que compara a implementação real com os specs, design e tarefas para encontrar lacunas e problemas","ru":"Sdd-verify - это ИИ Агент для верификации реализации, который сравнивает фактическую реализацию с спецификациями, дизайном и задачами для выявления пробелов и проблем","ar":"sdd-verify هي أداة تحقق من التنفيذ التي تقارن التنفيذ الفعلي بالمواصفات والتصميم والمهام لتحديد الفجوات والمشكلات"},"seo":{"title":{"en":"sdd-verify: Verification Setup Guide 