INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nicolad/nomadically.work/sdd-verify', 'sdd-verify', 'nicolad', 'nomadically.work', 'community', 'sdd-verify nicolad nomadically.work community sdd-verify is a sub-agent responsible for verification, comparing actual implementation against specs, design, and tasks to find gaps. It benefits AI agent developers by ensuring quality gates. sdd-verify是用于验证的AIエージェント，用于比较实际实现与规范、设计和任务以找到差异、不匹配和问题 sdd-verifyは検証用のAIエージェントであり、実際の実装と仕様、設計、タスクを比較してギャップ、不一致、問題を発見する sdd-verify는 검증을 위한 AI 에이전트로서 실제 구현과 사양, 설계, 태스크를 비교하여 차이, 불일치, 문제를 찾습니다 sdd-verify es un subagente responsable de la verificación de implementaciones contra specs, diseño y tareas. Aprenda a configurarlo para mejorar la calidad sdd-verify est un sous-agent responsable de la vérification des mises en œuvre par rapport aux specs, conception et tâches. Découvrez comment le configurer pour améliorer la qualité sdd-verify ist ein Subagent, der für die Überprüfung von Implementierungen gegen Spezifikationen, Design und Aufgaben verantwortlich ist. Erfahren Sie, wie Sie es konfigurieren, um die Qualität zu verbessern O sdd-verify é uma ferramenta de verificação de implementação que compara a implementação real com os specs, design e tarefas para encontrar lacunas e problemas Sdd-verify - это ИИ Агент для верификации реализации, который сравнивает фактическую реализацию с спецификациями, дизайном и задачами для выявления пробелов и проблем sdd-verify هي أداة تحقق من التنفيذ التي تقارن التنفيذ الفعلي بالمواصفات والتصميم والمهام لتحديد الفجوات والمشكلات how to use sdd-verify sdd-verify setup guide what is sdd-verify sdd-verify alternative sdd-verify vs other verification tools sdd-verify install verification sub-agent AI agent quality gates spec verification sdd-verify AIエージェント 验证工具 实际实现 规范 设计 任务 项目配置 openspec/config.yaml Verifies ALL implementation against specs, design, and tasks Compares delta specs from specs/ directory Checks completeness using project config from openspec/config.yaml Receives proposal.md content and tasks.md content with completion status Acts as a quality gate to find gaps, mismatches, and issues sdd-verify is a verification sub-agent that checks completeness and compares implementation against specs, design, and tasks to find mismatches and issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Senury/lawyer-ai/frontend-responsive', 'community', 'Senury', 'lawyer-ai', 'Senury/lawyer-ai', 'frontend-responsive', 1, 0, 38, '2026-03-02T12:54:11Z', '2026-03-06T07:17:10.901Z', 'debe4598217dfd3be8bc0f040d8159db8cd327606ad620c4c1da4e378181267a', '{"id":"Senury/lawyer-ai/frontend-responsive","name":"frontend-responsive","description":{"en":"The frontend-responsive skill provides guidance on coding standards for responsive frontend development, benefiting developers working with React, CSS, and Tailwind CSS. It helps create responsive layouts and mobile-first designs.","zh":"前端响应式设计是一种确保Web应用在不同设备和屏幕尺寸上表现良好的技术。使用React组件、CSS Grid和Flexbox等技术来实现响应式布局","ja":"フロントエンドレスポンシブ設計は、Webアプリケーションを様々なデバイスや画面サイズで適切に表示するための技術です。Reactコンポーネント、CSS Grid、Flexboxなどの技術を使用してレスポンシブなレイアウトを実現します","ko":"프런트엔드 반응형 설계는 웹 애플리케이션이 다양한 기기와 화면 크기에서 잘 보이는 기술입니다. React 컴포넌트, CSS Grid, Flexbox 등을 사용하여 반응형 레이아웃을 구현합니다","es":"El Skill frontend-responsive proporciona orientación específica para crear componentes React responsivos con Claude Code","fr":"Le Skill frontend-responsive fournit des conseils spécifiques pour créer des composants React responsifs avec Claude Code","de":"Das Skill frontend-responsive bietet spezifische Anleitung zur Erstellung responsiver React-Komponenten mit Claude Code","pt":"O frontend responsivo é uma habilidade que fornece orientação sobre como criar layouts responsivos com React e CSS","ru":"Адаптивный frontend - это навык, который предоставляет рекомендации по созданию адаптивных макетов с помощью React и CSS для ИИ Агентов","ar":"الواجهة الأمامية الايجابية هي مهارة توفر إرشادات حول كيفية إنشاء تصميمات متجاوبة مع React و CSS لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"frontend-responsive: Best Practices for AI Agents | AI Ag...","zh":"前端响应式设计setup指南","ja":"フロントエンドレスポンシブ設計ベストプラクティス","ko":"프런트엔드 반응형 설계 가이드","es":"Guía de configuración para frontend responsive con Claude...","fr":"Mise en place de frontend responsive avec Claude Code","de":"Einrichtungsleitfaden für frontend-responsive mit Claude ...","pt":"Guia de Configuração de Frontend Responsivo com React e CSS","ru":"Настройка адаптивного frontend с помощью React и CSS для ...","ar":"دليل إعداد الواجهة الأمامية الايجابية مع React و CSS لأدو..."},"description":{"en":"Unlock responsive frontend development with our AI agent skill. Learn how to implement mobile-first design patterns and responsive layouts using CSS Grid, Fl...","zh":"了解前端响应式设计的技术细节，包括React组件、CSS Grid、Flexbox和Tailwind CSS","ja":"フロントエンドレスポンシブ設計のテクニカルな詳細を学ぶ，Reactコンポーネント、CSS Grid、Flexbox、Tailwind CSSなど","ko":"프런트엔드 반응형 설계의 기술적 세부 정보를 알아보세요. React 컴포넌트, CSS Grid, Flexbox, Tailwind CSS 등","es":"Aprende a implementar diseños responsivos con Claude Code, utilizando React, CSS Grid, Flexbox y Tailwind CSS","fr":"Découvrez comment mettre en place des conceptions responsives avec Claude Code, en utilisant React, CSS Grid, Flexbox et Tailwind CSS","de":"Erfahren Sie, wie Sie responsive Designs mit Claude Code umsetzen, unter Verwendung von React, CSS Grid, Flexbox und Tailwind CSS","pt":"Aprenda a criar layouts responsivos com React, CSS Grid, Flexbox e Tailwind CSS para melhorar a experiência do usuário","ru":"Узнайте, как создавать адаптивные макеты с помощью React, CSS Grid, Flexbox и Tailwind CSS для ИИ Агентов","ar":"تعرف على كيفية إنشاء تصميمات متجاوبة مع React و CSS Grid و Flexbox و Tailwind CSS لتطوير تجربة المستخدم"},"definition":{"en":"frontend-responsive is a skill that enables AI agents to provide guidance on responsive frontend development, including CSS Grid, Flexbox, and Tailwind CSS best practices.","zh":"前端响应式设计是指使用CSS Grid、Flexbox和Tailwind CSS等技术来创建适应不同屏幕尺寸和设备的Web页面","ja":"フロントエンドレスポンシブ設計とは、CSS Grid、Flexbox、Tailwind CSSなどの技術を使用して、様々な画面サイズやデバイスに対応したWebページを作成すること","ko":"프런트엔드 반응형 설계란 CSS Grid, Flexbox, Tailwind CSS 등을 사용하여 다양한 화면 크기와 기기에 대응하는 웹 페이지를 생성하는 것을 말합니다","es":"Frontend responsive se refiere a la capacidad de adaptar diseños web a diferentes tamaños de pantalla y dispositivos","fr":"Frontend responsive fait référence à la capacité d''adapter les conceptions web à différentes tailles d''écran et d''appareils","de":"Frontend-responsive bezeichnet die Fähigkeit, Webdesigns an verschiedene Bildschirmgrößen und Geräte anzupassen","pt":"Frontend responsivo é uma técnica de design que se adapta a diferentes tamanhos de tela e dispositivos","ru":"Адаптивный frontend - это техника дизайна, которая адаптируется к разным размерам экрана и устройствам","ar":"الواجهة الأمامية الايجابية هي تقنية تصميم تتناسب مع أحجام شاشات وأجهزة مختلفة"},"features":{"en":["Provides guidance on creating responsive layouts using CSS Grid and Flexbox","Supports implementation of mobile-first design patterns","Generates responsive utility classes using Tailwind CSS (sm:, md:, lg:, xl:, 2xl:)","Helps with creating navigation menus for responsive designs","Offers best practices for editing React components in .tsx or .jsx files"],"zh":["使用React组件创建响应式布局","实现CSS Grid和Flexbox的响应式设计","使用Tailwind CSS的响应式utility类","支持移动优先的设计模式","创建响应式的导航菜单"],"ja":["Reactコンポーネントを使用してレスポンシブなレイアウトを作成","CSS GridとFlexboxのレスポンシブ設計を実現","Tailwind CSSのレスポンシブutilityクラスを使用","モバイルファーストのデザインパターンをサポート","レスポンシブなナビゲーションメニューを作成"],"ko":["React 컴포넌트를 사용하여 반응형 레이아웃을 생성","CSS Grid와 Flexbox의 반응형 디자인을 구현","Tailwind CSS의 반응형 utility 클래스를 사용","모바일 우선의 디자인 패턴을 지원","반응형 네비게이션 메뉴를 생성"],"es":["Implementación de diseños responsivos con CSS Grid y Flexbox","Uso de utilidades de Tailwind CSS para diseños responsivos","Creación de componentes React responsivos en archivos .tsx y .jsx","Diseño móvil primero con Claude Code","Creación de menús de navegación responsivos"],"fr":["Mise en place de conceptions responsives avec CSS Grid et Flexbox","Utilisation des utilités de Tailwind CSS pour les conceptions responsives","Création de composants React responsifs dans les fichiers .tsx et .jsx","Conception mobile d''abord avec Claude Code","Création de menus de navigation responsifs"],"de":["Umsetzung responsiver Designs mit CSS Grid und Flexbox","Verwendung von Tailwind CSS-Utilities für responsive Designs","Erstellung responsiver React-Komponenten in Dateien .tsx und .jsx","Mobiles Design zuerst mit Claude Code","Erstellung responsiver Navigationsmenüs"],"pt":["Criação de layouts responsivos com React e CSS","Uso de CSS Grid e Flexbox para design de layouts","Implementação de utility classes responsivas do Tailwind CSS","Desenvolvimento de padrões de design mobile-first","Criação de menus de navegação responsivos"],"ru":["Создание адаптивных макетов с помощью React и CSS для ИИ Агентов","Использование CSS Grid и Flexbox для дизайна макетов","Реализация адаптивных утилитных классов Tailwind CSS","Разработка мобильных шаблонов дизайна","Создание адаптивных меню навигации"],"ar":["إنشاء تصميمات متجاوبة مع React و CSS لأدوات الذكاء الاصطناعي","استخدام CSS Grid و Flexbox لتصميم التصميمات","تنفيذ فصولtility متجاوبة من Tailwind CSS","تطوير أنماط تصميم الهاتف المحمول أولاً","إنشاء قوائم导航 متجاوبة"]},"keywords":{"en":["how to use frontend-responsive","frontend-responsive setup guide","responsive frontend development best practices","frontend-responsive vs responsive web design","frontend-responsive install for AI agents","what is frontend-responsive in AI development","frontend-responsive alternative for React developers","frontend-responsive and Tailwind CSS integration","frontend-responsive for mobile-first design"],"zh":["前端响应式设计","React响应式组件","CSS Grid响应式设计","Flexbox响应式布局","Tailwind CSS响应式utility类","移动优先设计模式","响应式导航菜单","AIエージェント","AI工具"],"ja":["フロントエンドレスポンシブ設計","Reactレスポンシブコンポーネント","CSS Gridレスポンシブ設計","Flexboxレスポンシブレイアウト","Tailwind CSSレスポンシブutilityクラス","モバイルファーストデザインパターン","レスポンシブナビゲーションメニュー","AIエージェント","AIツール"],"ko":["프런트엔드 반응형 설계","React 반응형 컴포넌트","CSS Grid 반응형 디자인","Flexbox 반응형 레이아웃","Tailwind CSS 반응형 utility 클래스","모바일 우선 디자인 패턴","반응형 네비게이션 메뉴","AI 에이전트","AI 도구"],"es":["frontend responsive","diseños responsivos","React","CSS Grid","Flexbox","Tailwind CSS"," Claude Code","desarrollo web responsivo","componentes React responsivos"],"fr":["frontend responsive","conceptions responsives","React","CSS Grid","Flexbox","Tailwind CSS","Claude Code","développement web responsif","composants React responsifs"],"de":["frontend-responsive","responsive Designs","React","CSS Grid","Flexbox","Tailwind CSS","Claude Code","responsive Webentwicklung","responsive React-Komponenten"],"pt":["frontend responsivo","react","css","css grid","flexbox","tailwind css","design responsivo","mobile-first","navegação responsiva"],"ru":["адаптивный frontend","react","css","css grid","flexbox","tailwind css","адаптивный дизайн","мобильные шаблоны","навигация адаптивная","ИИ Агенты"],"ar":["الواجهة الأمامية الايجابية","react","css","css grid","flexbox","tailwind css","تصميم متجاوب","هاتف محمول أولاً","قوائم导航 متجاوبة","أدوات الذكاء الاصطناعي"]}},"owner":"Senury","repo":"lawyer-ai","repoPath":"Senury/lawyer-ai","stars":1,"forks":0,"updatedAt":"2026-03-02T12:54:11Z","topics":[],"category":"community","skillMd":{"name":"frontend-responsive","description":"Implement mobile-first responsive designs with fluid layouts, breakpoints, relative units, and touch-friendly interfaces that work across all device sizes. Use this skill when writing or modifying React components (.tsx, .jsx files), when implementing CSS or Tailwind responsive utilities (sm:, md:, lg:, xl: breakpoints), when working on layout components, navigation menus, grid systems, when optimizing for mobile devices, tablets, or desktop screens, when implementing media queries, when ensuring touch-friendly UI elements, or when testing cross-device compatibility.","bodyPreview":"# Frontend Responsive\n\nThis Skill provides Claude Code with specific guidance on how to adhere to coding standards as they relate to how it should handle frontend responsive.\n\n## When to use this skill\n\n- When creating or editing React components in `.tsx` or `.jsx` files\n- When implementing responsive layouts using CSS Grid or Flexbox\n- When writing Tailwind CSS responsive utility classes (sm:, md:, lg:, xl:, 2xl:)\n- When implementing mobile-first design patterns\n- When creating navigation menu","body":"# Frontend Responsive\n\nThis Skill provides Claude Code with specific guidance on how to adhere to coding standards as they relate to how it should handle frontend responsive.\n\n## When to use this skill\n\n- When creating or editing React components in `.tsx` or `.jsx` files\n- When implementing responsive layouts using CSS Grid or Flexbox\n- When writing Tailwind CSS responsive utility classes (sm:, md:, lg:, xl:, 2xl:)\n- When implementing mobile-first design patterns\n- When creating navigation menus that adapt to different screen sizes\n- When working on responsive typography that scales across breakpoints\n- When implementing touch-friendly UI elements (buttons, tap targets, gestures)\n- When optimizing images and assets for different screen sizes and resolutions\n- When testing UI components across mobile, tablet, and desktop breakpoints\n- When using relative units (rem, em, %, vh, vw) instead of fixed pixels\n- When implementing responsive spacing, padding, or margins\n- When creating fluid container layouts that adapt to viewport size\n\n## Instructions\n\nFor details, refer to the information provided in this file:\n[frontend responsive](../../../agent-os/standards/frontend/responsive.md)\n"},"lastSynced":"2026-03-06T07:17:10.901Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT that require expertise in responsive frontend development using React, CSS, and Tailwind CSS.","zh":"适用于需要响应式前端开发专业知识的AI代理，如Claude Code和AutoGPT，使用React、CSS和Tailwind CSS。","ja":"React、CSS、Tailwind CSSを使用したレスポンシブフロントエンド開発の専門知識を必要とするClaude CodeやAutoGPTなどのAIエージェントに適しています。","ko":"React, CSS, Tailwind CSS를 사용한 반응형 프론트엔드 개발 전문 지식을 요구하는 Claude Code 및 AutoGPT와 같은 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Claude Code y AutoGPT que requieren experiencia en desarrollo de frontend receptivo utilizando React, CSS y Tailwind CSS.","fr":"Idéal pour les agents IA comme Claude Code et AutoGPT qui nécessitent une expertise en développement de frontend réactif utilisant React, CSS et Tailwind CSS.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die Expertenwissen im Bereich responsives Frontend-Entwicklung mit React, CSS und Tailwind CSS erfordern.","pt":"Ideal para Agentes de IA como Claude Code e AutoGPT que requerem especialização em desenvolvimento de frontend responsivo usando React, CSS e Tailwind CSS.","ru":"Идеально для агентов ИИ, таких как Claude Code и AutoGPT, которые требуют опыта в разработке отзывчивого frontend с использованием React, CSS и Tailwind CSS.","ar":"مثالية لعمليات وكيل الذكاء الاصطناعي مثل Claude Code و AutoGPT التي تتطلب الخبرة في تطوير الواجهة الأمامية الاستجابة باستخدام React و CSS و Tailwind CSS."},"recommendation":{"en":"Empowers agents to create responsive layouts and mobile-first designs using CSS Grid, Flexbox, and Tailwind CSS utility classes, streamlining the development of adaptive user interfaces for various screen sizes and devices.","zh":"赋予代理创建响应式布局和移动优先设计的能力，使用CSS Grid、Flexbox和Tailwind CSS实用程序类，简化了适应不同屏幕尺寸和设备的自适应用户界面的开发。","ja":"CSS Grid、Flexbox、Tailwind CSSユーティリティクラスを使用して、レスポンシブレイアウトとモバイルファーストデザインを作成する機能をエージェントに与え、さまざまな画面サイズとデバイスに対応したアダプティブユーザーインターフェイスの開発を簡素化します。","ko":"CSS Grid, Flexbox, Tailwind CSS 유틸리티 클래스를 사용하여 반응형 레이아웃과 모바일 우선 디자인을 생성하는 기능을 에이전트에 부여하여 다양한 화면 크기와 장치에 대한 적응형 사용자 인터페이스의 개발을 간소화합니다.","es":"Permite a los agentes crear diseños receptivos y diseños para móviles en primer lugar utilizando CSS Grid, Flexbox y clases de utilidad de Tailwind CSS, lo que simplifica el desarrollo de interfaces de usuario adaptativas para varios tamaños de pantalla y dispositivos.","fr":"Permet aux agents de créer des mises en page réactives et des conceptions mobiles en premier lieu en utilisant CSS Grid, Flexbox et les classes d''utilité de Tailwind CSS, ce qui simplifie le développement d''interfaces utilisateur adaptatives pour différentes tailles d''écran et appareils.","de":"Ermöglicht es Agents, responsive Layouts und mobile-first-Designs mit CSS Grid, Flexbox und Tailwind-CSS-Utility-Klassen zu erstellen, wodurch die Entwicklung adaptiver Benutzeroberflächen für verschiedene Bildschirmgrößen und Geräte vereinfacht wird.","pt":"Habilita os agentes a criarem layouts responsivos e designs para dispositivos móveis em primeiro lugar usando CSS Grid, Flexbox e classes de utilidade do Tailwind CSS, simplificando o desenvolvimento de interfaces de usuário adaptáveis para vários tamanhos de tela e dispositivos.","ru":"Наделяет агентов возможностью создавать отзывчивые макеты и мобильные дизайны с использованием CSS Grid, Flexbox и утилитных классов Tailwind CSS, что упрощает разработку адаптивных пользовательских интерфейсов для различных размеров экрана и устройств.","ar":"تمكّن الوكيل من إنشاء تصاميم استجابة وتصميمات للهواتف النقالة أولاً باستخدام شبكة CSS والصندوق المرن و فئات المرافق من Tailwind CSS، وتبسيط تطوير واجهات المستخدم القابلة للتكيف مع أحجام الشاشة والأجهزة المختلفة."},"useCases":{"en":["Implementing responsive navigation menus for web applications","Generating mobile-first designs for React components using Tailwind CSS","Optimizing CSS layouts for cross-device compatibility"],"zh":["为Web应用程序实现响应式导航菜单","使用Tailwind CSS为React组件生成移动优先设计","优化CSS布局以实现跨设备兼容性"],"ja":["Webアプリケーションのレスポンシブナビゲーションメニューを実装する","Tailwind CSSを使用してReactコンポーネントのモバイルファーストデザインを生成する","CSSレイアウトを最適化してクロスデバイスの互換性を実現する"],"ko":["웹 애플리케이션을 위한 반응형 내비게이션 메뉴 구현","Tailwind CSS를 사용하여 React 컴포넌트의 모바일 우선 디자인 생성","CSS 레이아웃을 최적화하여 크로스 디바이스 호환성 달성"],"es":["Implementar menús de navegación receptivos para aplicaciones web","Generar diseños para móviles en primer lugar para componentes de React utilizando Tailwind CSS","Optimizar diseños de CSS para la compatibilidad entre dispositivos"],"fr":["Mettre en œuvre des menus de navigation réactifs pour les applications web","Générer des conceptions mobiles en premier lieu pour les composants React en utilisant Tailwind CSS","Optimiser les mises en page CSS pour la compatibilité entre les appareils"],"de":["Implementierung responsiver Navigationsmenüs für Webanwendungen","Erstellung von mobile-first-Designs für React-Komponenten mit Tailwind CSS","Optimierung von CSS-Layouts für die Kompatibilität zwischen Geräten"],"pt":["Implementação de menus de navegação responsivos para aplicações web","Geração de designs para dispositivos móveis em primeiro lugar para componentes React usando Tailwind CSS","Otimização de layouts CSS para compatibilidade entre dispositivos"],"ru":["Реализация отзывчивых меню навигации для веб-приложений","Генерация мобильных дизайнов в первую очередь для компонентов React с использованием Tailwind CSS","Оптимизация макетов CSS для кросс-устройственной совместимости"],"ar":["تنفيذ قوائم التنقل القابلة للتكيف لتقديم التطبيقات على الويب","генерация تصاميم للهواتف النقالة أولاً لمكونات React باستخدام Tailwind CSS","تحسين تخطيطات CSS للتوافق بين الأجهزة"]},"limitations":{"en":["Requires knowledge of React, CSS, and Tailwind CSS","Limited to frontend development tasks","May require additional setup for complex responsive designs"],"zh":["需要React、CSS和Tailwind CSS的知识","仅限于前端开发任务","可能需要为复杂的响应式设计进行额外的设置"],"ja":["React、CSS、Tailwind CSSの知識が必要","フロントエンド開発タスクのみに限定される","複雑なレスポンシブデザインの場合、追加の設定が必要になる可能性がある"],"ko":["React, CSS, Tailwind CSS에 대한 지식이 필요","프론트엔드 개발 작업에만 제한","복잡한 반응형 디자인의 경우 추가 설정이 필요할 수 있음"],"es":["Requiere conocimiento de React, CSS y Tailwind CSS","Limitado a tareas de desarrollo de frontend","Puede requerir configuración adicional para diseños receptivos complejos"],"fr":["Nécessite des connaissances en React, CSS et Tailwind CSS","Limité aux tâches de développement de frontend","Peut nécessiter une configuration supplémentaire pour des conceptions réactives complexes"],"de":["Benötigt Kenntnisse von React, CSS und Tailwind CSS","Begrenzt auf Frontend-Entwicklungsaufgaben","Kann eine zusätzliche Einrichtung für komplexe responsive Designs erfordern"],"pt":["Exige conhecimento de React, CSS e Tailwind CSS","Limitado a tarefas de desenvolvimento de frontend","Pode exigir configuração adicional para designs responsivos complexos"],"ru":["Требует знания React, CSS и Tailwind CSS","Ограничен задачами разработки frontend","Может потребовать дополнительной настройки для сложных отзывчивых дизайнов"],"ar":["يتطلب معرفة React و CSS و Tailwind CSS","محدود بمهام تطوير الواجهة الأمامية","يمكن أن يتطلب إعدادًا إضافيًا لتصميمات استجابة معقدة"]},"version":4},"contentHash":"debe4598217dfd3be8bc0f040d8159db8cd327606ad620c4c1da4e378181267a","qualityScore":38}');
