INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Senury/lawyer-ai/frontend-responsive', 'frontend-responsive', 'Senury', 'lawyer-ai', 'community', 'frontend-responsive Senury lawyer-ai community The frontend-responsive skill provides guidance on coding standards for responsive frontend development, benefiting developers working with React, CSS, and Tailwind CSS. It helps create responsive layouts and mobile-first designs. 前端响应式设计是一种确保Web应用在不同设备和屏幕尺寸上表现良好的技术。使用React组件、CSS Grid和Flexbox等技术来实现响应式布局 フロントエンドレスポンシブ設計は、Webアプリケーションを様々なデバイスや画面サイズで適切に表示するための技術です。Reactコンポーネント、CSS Grid、Flexboxなどの技術を使用してレスポンシブなレイアウトを実現します 프런트엔드 반응형 설계는 웹 애플리케이션이 다양한 기기와 화면 크기에서 잘 보이는 기술입니다. React 컴포넌트, CSS Grid, Flexbox 등을 사용하여 반응형 레이아웃을 구현합니다 El Skill frontend-responsive proporciona orientación específica para crear componentes React responsivos con Claude Code Le Skill frontend-responsive fournit des conseils spécifiques pour créer des composants React responsifs avec Claude Code Das Skill frontend-responsive bietet spezifische Anleitung zur Erstellung responsiver React-Komponenten mit Claude Code O frontend responsivo é uma habilidade que fornece orientação sobre como criar layouts responsivos com React e CSS Адаптивный frontend - это навык, который предоставляет рекомендации по созданию адаптивных макетов с помощью React и CSS для ИИ Агентов الواجهة الأمامية الايجابية هي مهارة توفر إرشادات حول كيفية إنشاء تصميمات متجاوبة مع React و CSS لأدوات الذكاء الاصطناعي how to use frontend-responsive frontend-responsive setup guide responsive frontend development best practices frontend-responsive vs responsive web design frontend-responsive install for AI agents what is frontend-responsive in AI development frontend-responsive alternative for React developers frontend-responsive and Tailwind CSS integration frontend-responsive for mobile-first design 前端响应式设计 React响应式组件 CSS Grid响应式设计 Flexbox响应式布局 Tailwind CSS响应式utility类 移动优先设计模式 响应式导航菜单 AIエージェント AI工具 Provides guidance on creating responsive layouts using CSS Grid and Flexbox Supports implementation of mobile-first design patterns Generates responsive utility classes using Tailwind CSS (sm:, md:, lg:, xl:, 2xl:) Helps with creating navigation menus for responsive designs Offers best practices for editing React components in .tsx or .jsx files frontend-responsive is a skill that enables AI agents to provide guidance on responsive frontend development, including CSS Grid, Flexbox, and Tailwind CSS best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yuya296/grooper/scrum-planning', 'community', 'yuya296', 'grooper', 'yuya296/grooper', 'scrum-planning', 1, 0, 38, '2026-02-15T06:28:16Z', '2026-03-06T13:12:51.293Z', '8eb4e246730b78bcadcda69aea23e9f29c077152aa66dd0046a2359a02d87546', '{"id":"yuya296/grooper/scrum-planning","name":"scrum-planning","description":{"en":"Scrum-planning is a rule-based approach for managing Product Backlog Items (PBIs) in a scrum framework. It benefits developers and project managers by enforcing value-per-PBI and correct ordering.","zh":"Scrum Planning是一个规则基于的tab分组工具，帮助开发团队创建和维护PBI文件夹和规范的项目管理","ja":"Scrum Planningは、AIエージェントを使用したタブグループ化を実現するワークフロー管理ツールです","ko":"Scrum Planning은 개발 팀을 위한 규칙 기반의 탭 그룹화 도구로, PBI 폴더 생성과 관리를 지원합니다","es":"La planificación Scrum con Agentes de IA permite crear y mantener carpetas de PBI con archivos de especificación, tareas pendientes y pruebas","fr":"La planification Scrum avec les outils d''IA permet de créer et de maintenir des dossiers de PBI avec des fichiers de spécification, des tâches en attente et des tests","de":"Die Scrum-Planung mit KI-Tools ermöglicht die Erstellung und Wartung von PBI-Ordnern mit Spezifikations-, Todo- und Testdateien","pt":"O planejamento Scrum é uma abordagem que envolve a criação de pastas PBI com arquivos spec.md, todo.md e test.md para entrega de valor","ru":"Планирование Scrum - это подход, который включает создание папок PBI с файлами spec.md, todo.md и test.md для доставки ценности","ar":"تخطيط Scrum هو نهج ي涉ل إنشاء مجلدات PBI مع ملفات spec.md و todo.md و test.md لتسليم القيمة"},"seo":{"title":{"en":"Scrum-Planning: PBI Folder Setup Guide | AI Agent Skill","zh":"Scrum Planning Setup Guide: Rule-based Tab Grouping for D...","ja":"Scrum Planning ベストプラクティス: AIエージェントを使用したタブグループ化","ko":"Scrum Planning 설정 가이드: 개발 팀을 위한 규칙 기반 탭 그룹화","es":"Guía de configuración de planificación Scrum con Agentes ...","fr":"Guide de mise en place de la planification Scrum avec les...","de":"Einrichtungsleitfaden für Scrum-Planung mit KI-Tools","pt":"Guia de Configuração de Planejamento Scrum com Ferramenta...","ru":"Настройка планирования Scrum с ИИ Агентами","ar":"دليل إعداد تخطيط Scrum باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how scrum-planning streamlines PBI management. Learn to create and maintain PBI folders with spec.md, todo.md, and test.md files. Get started now!","zh":"了解Scrum Planning的技术细节，包括PBI文件夹创建和维护，实现规范的项目管理","ja":"Scrum Planningのワークフローを理解し、AIエージェントを使用してタブグループ化を実現する","ko":"Scrum Planning의 기술적인 내용을 살펴보고, 규칙 기반의 탭 그룹화로 개발 팀의 생산성을 향상시키는 방법","es":"Aprende a implementar la planificación Scrum con Agentes de IA para mejorar la eficiencia y productividad de tu equipo de desarrollo","fr":"Découvrez comment mettre en place la planification Scrum avec les outils d''IA pour améliorer l''efficacité et la productivité de votre équipe de développement","de":"Erfahren Sie, wie Sie die Scrum-Planung mit KI-Tools implementieren können, um die Effizienz und Produktivität Ihres Entwicklungsteams zu verbessern","pt":"Aprenda a configurar o planejamento Scrum com pastas PBI e arquivos spec.md, todo.md e test.md para entrega de valor","ru":"Узнайте, как настроить планирование Scrum с папками PBI и файлами spec.md, todo.md и test.md для доставки ценности","ar":"تعلم كيفية إعداد تخطيط Scrum باستخدام مجلدات PBI وملفات spec.md و todo.md و test.md لتسليم القيمة"},"definition":{"en":"Scrum-planning is a methodology for creating and maintaining PBI folders with standardized files, ensuring efficient project management and implementation.","zh":"Scrum Planning是一种使用规则基于的tab分组来管理项目的方法","ja":"Scrum Planningは、タブグループ化を使用してプロジェクトを管理するワークフロー管理手法です","ko":"Scrum Planning은 규칙 기반의 탭 그룹화를 사용하여 프로젝트를 관리하는 방법입니다","es":"La planificación Scrum con Agentes de IA es una técnica para crear y mantener carpetas de PBI con reglas de valor y orden","fr":"La planification Scrum avec les outils d''IA est une technique pour créer et maintenir des dossiers de PBI avec des règles de valeur et d''ordre","de":"Die Scrum-Planung mit KI-Tools ist eine Technik zur Erstellung und Wartung von PBI-Ordnern mit Wert- und Reihenfolgeregel","pt":"Planejamento Scrum é uma técnica de gerenciamento de projetos que utiliza pastas PBI e arquivos para entrega de valor","ru":"Планирование Scrum - это техника управления проектами, которая использует папки PBI и файлы для доставки ценности","ar":"تخطيط Scrum هو تقنية لإدارة المشاريع التي تستخدم مجلدات PBI وملفات لتسليم القيمة"},"features":{"en":["Creates PBI folders under docs/features/pbi-0000-hoge with spec.md, todo.md, and test.md files","Enforces value-per-PBI to ensure efficient project management","Maintains correct ordering of PBIs for streamlined implementation","Supports user approval for implementation to ensure quality control","Splits large requests into multiple PBIs for manageable development","Proposes PBI splitting for optimal project planning"],"zh":["创建和维护PBI文件夹","规范的项目管理","规则基于的tab分组","实现价值交付的顺序","无需用户批准的实现"],"ja":["PBIフォルダーの作成と管理","規範的なプロジェクト管理","ルールベースのタブグループ化","価値の提供の順序の実現","ユーザーの承認なしでの実装"],"ko":["PBI 폴더 생성 및 관리","규칙 기반의 탭 그룹화","값을 제공하는 순서의 구현","사용자 승인 없이 구현","개발 팀의 생산성 향상"],"es":["Creación de carpetas de PBI con archivos de especificación, tareas pendientes y pruebas","Implementación de reglas de valor y orden para garantizar la calidad","Automatización de tareas para mejorar la eficiencia","Integración con herramientas de desarrollo para una mayor productividad","Seguimiento y control de los progresos del equipo"," Mejora de la colaboración y comunicación entre los miembros del equipo"],"fr":["Création de dossiers de PBI avec des fichiers de spécification, des tâches en attente et des tests","Mise en place de règles de valeur et d''ordre pour garantir la qualité","Automatisation de tâches pour améliorer l''efficacité","Intégration avec des outils de développement pour une plus grande productivité","Suivi et contrôle des progrès de l''équipe","Amélioration de la collaboration et de la communication entre les membres de l''équipe"],"de":["Erstellung von PBI-Ordnern mit Spezifikations-, Todo- und Testdateien","Implementierung von Wert- und Reihenfolgeregel für die Qualitätssicherung","Automatisierung von Aufgaben für eine höhere Effizienz","Integration mit Entwicklungstools für eine höhere Produktivität","Verfolgung und Kontrolle der Teamfortschritte","Verbesserung der Zusammenarbeit und Kommunikation zwischen den Teammitgliedern"],"pt":["Criação de pastas PBI com arquivos spec.md, todo.md e test.md","Entrega de valor com ordenação correta e aprovação do usuário","Divisão de solicitações em múltiplos PBIs para entrega de valor","Uso de regras para garantir a entrega de valor","Integração com ferramentas de Inteligência Artificial para automação","Suporte a múltiplos formatos de arquivo para flexibilidade"],"ru":["Создание папок PBI с файлами spec.md, todo.md и test.md","Доставка ценности с правильной сортировкой и одобрением пользователя","Разделение запросов на несколько PBI для доставки ценности","Использование правил для обеспечения доставки ценности","Интеграция с ИИ Агентами для автоматизации","Поддержка нескольких форматов файлов для гибкости"],"ar":["إنشاء مجلدات PBI مع ملفات spec.md و todo.md و test.md","تسليم القيمة مع الترتيب الصحيح وموافقة المستخدم","تقسيم الطلبات إلى PBIs متعددة لتسليم القيمة","استخدام القواعد لضمان تسليم القيمة","التكامل مع أدوات الذكاء الاصطناعي للآلية","دعم صيغ ملفات متعددة للمرونة"]},"keywords":{"en":["how to use scrum-planning","scrum-planning setup guide","scrum-planning alternative","scrum-planning vs agile planning","scrum-planning install","what is scrum-planning","scrum-planning best practices","scrum-planning for AI agents","scrum-planning workflow optimization"],"zh":["Scrum Planning","规则基于的tab分组","PBI文件夹","项目管理","开发团队","规则基于的工作流","AI工具","项目规划"],"ja":["Scrum Planning","ルールベースのタブグループ化","PBIフォルダー","プロジェクト管理","開発チーム","ルールベースのワークフロー","AIエージェント","プロジェクト計画"],"ko":["Scrum Planning","규칙 기반의 탭 그룹화","PBI 폴더","프로젝트 관리","개발 팀","규칙 기반의 워크플로","AI 도구","프로젝트 계획"],"es":["planificación Scrum","Agentes de IA","desarrollo de software","gestión de proyectos","productividad","eficiencia","colaboración","comunicación","herramientas de desarrollo","integración de herramientas"],"fr":["planification Scrum","outils d''IA","développement de logiciels","gestion de projets","productivité","efficacité","collaboration","communication","outils de développement","intégration d''outils"],"de":["Scrum-Planung","KI-Tools","Software-Entwicklung","Projektmanagement","Produktivität","Effizienz","Zusammenarbeit","Kommunikation","Entwicklungstools","Tool-Integration"],"pt":["planejamento Scrum","ferramentas de Inteligência Artificial","pastas PBI","arquivos spec.md","entrega de valor","gerenciamento de projetos","técnica de gerenciamento","automatização de processos","Inteligência Artificial no gerenciamento de projetos"],"ru":["планирование Scrum","ИИ Агенты","папки PBI","файлы spec.md","доставка ценности","управление проектами","техника управления","автоматизация процессов","ИИ в управлении проектами"],"ar":["تخطيط Scrum","أدوات الذكاء الاصطناعي","مجلدات PBI","ملفات spec.md","تسليم القيمة","إدارة المشاريع","تقنية الإدارة","آلية العمليات","الذكاء الاصطناعي في إدارة المشاريع"]}},"owner":"yuya296","repo":"grooper","repoPath":"yuya296/grooper","stars":1,"forks":0,"updatedAt":"2026-02-15T06:28:16Z","topics":[],"category":"community","skillMd":{"name":"scrum-planning","description":"Create Scrum planning PBIs and docs under docs/features. Use when the user asks to plan work, split backlog items, or says phrases like PBI作って, スクラムのプランニングして, or Backlog切って. Produces PBI folders with spec.md, todo.md, and test.md without implementing code.","bodyPreview":"# Scrum Planning\n\n## Overview\n\nCreate and maintain PBI folders under `docs/features/pbi-0000-hoge` with three files: `spec.md`, `todo.md`, and `test.md`. Enforce value-per-PBI, correct ordering, and no implementation without user approval.\n\n## Workflow\n\n### 1) Understand the request\n\n- Restate the requested outcome in one sentence.\n- Identify the smallest user-visible value that can be shipped.\n- If the request is too large, propose a split into multiple PBIs.\n- If a PBI cannot deliver standalon","body":"# Scrum Planning\n\n## Overview\n\nCreate and maintain PBI folders under `docs/features/pbi-0000-hoge` with three files: `spec.md`, `todo.md`, and `test.md`. Enforce value-per-PBI, correct ordering, and no implementation without user approval.\n\n## Workflow\n\n### 1) Understand the request\n\n- Restate the requested outcome in one sentence.\n- Identify the smallest user-visible value that can be shipped.\n- If the request is too large, propose a split into multiple PBIs.\n- If a PBI cannot deliver standalone value, reject it and suggest a value-bearing alternative.\n\n### 2) Propose PBI list\n\n- Create a numbered list of candidate PBIs with short titles and one-line value statements.\n- If there are dependencies, assign numbers so dependency order is preserved (no reverse numbering).\n- If no dependencies, order by perceived importance (highest value first).\n- Ask for confirmation before writing any files.\n\n### 3) Create PBI folders and files (after approval only)\n\n- Determine next PBI number by scanning `docs/features/` for existing `pbi-####-*` directories and picking the next available number.\n- Use 4-digit zero padding for PBI numbers.\n- Use a short kebab-case slug for the folder name.\n- Create:\n  - `docs/features/pbi-####-slug/spec.md`\n  - `docs/features/pbi-####-slug/todo.md`\n  - `docs/features/pbi-####-slug/test.md`\n- Base file contents on the templates in `assets/templates/`.\n- Keep `todo.md` as a checklist and update it as work progresses (only after user approval to implement).\n\n### 4) Guardrails\n\n- Never implement code without explicit user approval.\n- If the request is too large, propose a split before any file creation.\n- Do not create a PBI that cannot deliver standalone value.\n- Respect ordering: dependencies must have lower numbers; independent items sorted by importance.\n\n## Output Expectations\n\n- Always present the PBI proposal first, then ask for confirmation.\n- Use concrete file paths when listing created artifacts.\n- Keep text concise and in Japanese unless the user requests otherwise.\n\n## Resources\n\n### assets/templates/\n\n- `spec.md`: Requirement and acceptance criteria\n- `todo.md`: Task checklist with updates section\n- `test.md`: CLI/Browser test plan suitable for Codex autonomy\n"},"lastSynced":"2026-03-06T13:12:51.293Z","agentAnalysis":{"suitability":{"en":"Ideal for Agile Agents requiring structured Product Backlog Item management and scrum framework enforcement.","zh":"适用于需要结构化产品待办事项管理和Scrum框架强制执行的敏捷代理。","ja":"アジャイルエージェントが構造化されたプロダクトバックログアイテム管理とScrumフレームワークの適用を必要とする場合に最適です。","ko":"구조화된 제품 백로그 항목 관리 및 Scrum 프레임워크 시행이 필요한敏捷 에이전트에 적합합니다.","es":"Ideal para Agentes Ágiles que requieren una gestión estructurada de elementos de producto y aplicación del marco de trabajo scrum.","fr":"Idéal pour les agents Agile nécessitant une gestion structurée des éléments de produit et l''application du cadre de travail scrum.","de":"Ideal für Agile Agenten, die eine strukturierte Verwaltung von Produkt-Backlog-Elementen und die Einhaltung des Scrum-Frameworks erfordern.","pt":"Ideal para Agentes Ágeis que requerem gestão estruturada de itens da Product Backlog e aplicação do framework scrum.","ru":"Идеально для агентов Agile, требующих структурированного управления элементами Product Backlog и обеспечения соблюдения фреймворка scrum.","ar":"مثالي للوكلاء المتأقلمين الذين يتطلبون إدارة منظمة لعناصر Product Backlog وتنفيذ إطار العمل scrum."},"recommendation":{"en":"Empowers agents to enforce value-per-PBI, correct ordering, and user approval for implementation, utilizing markdown files such as `spec.md`, `todo.md`, and `test.md` for precise project management.","zh":"赋予代理人执行每个PBI的价值、正确排序和用户批准以进行实施的能力，利用诸如`spec.md`、`todo.md`和`test.md`的markdown文件进行精确的项目管理。","ja":"エージェントがPBIごとの価値、正しい順序付け、実装のためのユーザー承認を適用できるようにし、`spec.md`、`todo.md`、`test.md`などのMarkdownファイルを使用して、正確なプロジェクト管理を行う。","ko":"에이전트가 각 PBI의 가치, 올바른 정렬 및 구현을 위한 사용자 승인을 시행할 수 있도록 하며, `spec.md`, `todo.md` 및 `test.md`와 같은 마크다운 파일을 사용하여 精确한 프로젝트 관리를 수행합니다.","es":"Habilita a los agentes a hacer cumplir el valor por elemento de producto, el orden correcto y la aprobación del usuario para la implementación, utilizando archivos markdown como `spec.md`, `todo.md` y `test.md` para una gestión de proyecto precisa.","fr":"Permet aux agents d''appliquer la valeur par élément de produit, le bon ordre et l''approbation de l''utilisateur pour la mise en œuvre, en utilisant des fichiers markdown tels que `spec.md`, `todo.md` et `test.md` pour une gestion de projet précise.","de":"Ermächtigt die Agenten, den Wert pro Produkt-Backlog-Element, die korrekte Reihenfolge und die Benutzerzustimmung für die Implementierung durchzusetzen, indem Markdown-Dateien wie `spec.md`, `todo.md` und `test.md` für eine präzise Projektverwaltung verwendet werden.","pt":"Habilita os agentes a impor valor por PBI, ordenação correta e aprovação do usuário para implementação, utilizando arquivos markdown como `spec.md`, `todo.md` e `test.md` para gerenciamento de projeto preciso.","ru":"Наделяет агентов возможностью обеспечить соблюдение стоимости за PBI, правильного порядка и одобрения пользователя для реализации, используя файлы markdown, такие как `spec.md`, `todo.md` и `test.md`, для точного управления проектом.","ar":"يمنح الوكلاء القدرة على فرض القيمة لكل PBI والترتيب الصحيح والموافقة المستخدمة للتنفيذ، باستخدام ملفات markdown مثل `spec.md` و `todo.md` و `test.md` لإدارة المشروع بدقة."},"useCases":{"en":["Automating PBI folder creation under `docs/features/pbi-0000-hoge`","Generating `spec.md` and `todo.md` files for new PBIs","Validating user requests against smallest user-visible value delivery"],"zh":["自动创建PBI文件夹，例如`docs/features/pbi-0000-hoge`","为新PBI生成`spec.md`和`todo.md`文件","验证用户请求与最小的用户可见值交付"],"ja":["PBIフォルダの自動作成、例:`docs/features/pbi-0000-hoge`","新しいPBIの`spec.md`と`todo.md`ファイルの生成","ユーザー要求の検証と最小のユーザー可視値の提供"],"ko":["PBI 폴더 자동 생성, 예: `docs/features/pbi-0000-hoge`","새로운 PBI에 대한 `spec.md` 및 `todo.md` 파일 생성","사용자 요청에 대한 검증 및 최소한의 사용자 가시적 가치 전달"],"es":["Automatizar la creación de carpetas de elementos de producto bajo `docs/features/pbi-0000-hoge`","Generar archivos `spec.md` y `todo.md` para nuevos elementos de producto","Validar las solicitudes de los usuarios contra la entrega de valor más pequeña visible por el usuario"],"fr":["Automatiser la création de dossiers d''éléments de produit sous `docs/features/pbi-0000-hoge`","Générer des fichiers `spec.md` et `todo.md` pour les nouveaux éléments de produit","Valider les demandes des utilisateurs par rapport à la livraison de valeur la plus petite visible par l''utilisateur"],"de":["Automatisieren der Erstellung von Ordnern für Produkt-Backlog-Elemente unter `docs/features/pbi-0000-hoge`","Generieren von Dateien `spec.md` und `todo.md` für neue Produkt-Backlog-Elemente","Validieren von Benutzersuchen gegenüber der kleinsten sichtbaren Wertlieferung"],"pt":["Automatizar a criação de pastas de PBI em `docs/features/pbi-0000-hoge`","Gerar arquivos `spec.md` e `todo.md` para novos PBIs","Validar solicitações de usuário contra a entrega de valor menor visível ao usuário"],"ru":["Автоматизировать создание папок PBI в `docs/features/pbi-0000-hoge`","Генерировать файлы `spec.md` и `todo.md` для новых PBI","Проверять запросы пользователя против наименьшей видимой пользователю доставки ценности"],"ar":["التحكم الآلي في إنشاء مجلدات PBI في `docs/features/pbi-0000-hoge`","إنشاء ملفات `spec.md` و `todo.md` للعناصر الجديدة من Product Backlog","التحقق من الطلبات المستخدمة مقابل أصغر توصيل قيمة مرئية للمستخدم"]},"limitations":{"en":["Requires strict adherence to scrum framework","Enforces no implementation without user approval","Limited to managing Product Backlog Items"],"zh":["需要严格遵守Scrum框架","执行无用户批准的实现不可用","仅限于管理产品待办事项"],"ja":["Scrumフレームワークの厳格な遵守が必要","ユーザー承認なしの実装はできません","プロダクトバックログアイテムの管理のみ"],"ko":["Scrum 프레임워크의 엄격한 준수를 필요로 함","사용자 승인 없이 구현할 수 없음","제품 백로그 항목 관리에만 제한됨"],"es":["Requiere una estricta adhesión al marco de trabajo scrum","Hace cumplir que no se realice ninguna implementación sin la aprobación del usuario","Limitado a la gestión de elementos de producto"],"fr":["Nécessite une stricte adhésion au cadre de travail scrum","Fait respecter qu''aucune mise en œuvre ne soit effectuée sans l''approbation de l''utilisateur","Limité à la gestion des éléments de produit"],"de":["Erfordert eine strikte Einhaltung des Scrum-Frameworks","Zwingt die Einhaltung, dass ohne Benutzerzustimmung keine Implementierung durchgeführt wird","Begrenzt auf die Verwaltung von Produkt-Backlog-Elementen"],"pt":["Exige adesão estrita ao framework scrum","Exige aprovação do usuário para qualquer implementação","Limitado à gestão de itens da Product Backlog"],"ru":["Требует строгого соблюдения фреймворка scrum","Требует одобрения пользователя для любой реализации","Ограничен управлением элементами Product Backlog"],"ar":["يتطلب اتباعًا صارمًا لإطار العمل scrum","يتطلب موافقة المستخدم على أي تنفيذ","محدود بإدارة عناصر Product Backlog"]},"version":4},"contentHash":"8eb4e246730b78bcadcda69aea23e9f29c077152aa66dd0046a2359a02d87546","qualityScore":38}');
