INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yuya296/grooper/scrum-planning', 'scrum-planning', 'yuya296', 'grooper', 'community', 'scrum-planning yuya296 grooper community Scrum-planning is a rule-based approach for managing Product Backlog Items (PBIs) in a scrum framework. It benefits developers and project managers by enforcing value-per-PBI and correct ordering. Scrum Planning是一个规则基于的tab分组工具，帮助开发团队创建和维护PBI文件夹和规范的项目管理 Scrum Planningは、AIエージェントを使用したタブグループ化を実現するワークフロー管理ツールです Scrum Planning은 개발 팀을 위한 규칙 기반의 탭 그룹화 도구로, PBI 폴더 생성과 관리를 지원합니다 La planificación Scrum con Agentes de IA permite crear y mantener carpetas de PBI con archivos de especificación, tareas pendientes y pruebas La planification Scrum avec les outils d''IA permet de créer et de maintenir des dossiers de PBI avec des fichiers de spécification, des tâches en attente et des tests Die Scrum-Planung mit KI-Tools ermöglicht die Erstellung und Wartung von PBI-Ordnern mit Spezifikations-, Todo- und Testdateien O planejamento Scrum é uma abordagem que envolve a criação de pastas PBI com arquivos spec.md, todo.md e test.md para entrega de valor Планирование Scrum - это подход, который включает создание папок PBI с файлами spec.md, todo.md и test.md для доставки ценности تخطيط Scrum هو نهج ي涉ل إنشاء مجلدات PBI مع ملفات spec.md و todo.md و test.md لتسليم القيمة how to use scrum-planning scrum-planning setup guide scrum-planning alternative scrum-planning vs agile planning scrum-planning install what is scrum-planning scrum-planning best practices scrum-planning for AI agents scrum-planning workflow optimization Scrum Planning 规则基于的tab分组 PBI文件夹 项目管理 开发团队 规则基于的工作流 AI工具 项目规划 Creates PBI folders under docs/features/pbi-0000-hoge with spec.md, todo.md, and test.md files Enforces value-per-PBI to ensure efficient project management Maintains correct ordering of PBIs for streamlined implementation Supports user approval for implementation to ensure quality control Splits large requests into multiple PBIs for manageable development Proposes PBI splitting for optimal project planning Scrum-planning is a methodology for creating and maintaining PBI folders with standardized files, ensuring efficient project management and implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DevanB/lucidlog/Frontend CSS', 'community', 'DevanB', 'lucidlog', 'DevanB/lucidlog', 'Frontend CSS', 0, 0, 38, '2026-03-07T01:49:01.779Z', '2026-03-07T03:16:19.342Z', '81534cb71caba56258cb46eddb1a30b40c310150a149468e802bf34ac2f6646f', '{"id":"DevanB/lucidlog/Frontend CSS","name":"Frontend CSS","description":{"en":"Frontend CSS provides specific guidance on coding standards for handling frontend CSS, benefiting developers working with React components and Tailwind CSS. It helps with writing and editing CSS files, applying utility classes, and implementing design system tokens.","zh":"前端CSS技能提供了具体的编码标准指南，用于处理前端CSS，包括Tailwind CSS和设计系统令牌","ja":"フロントエンドCSSスキルは、Tailwind CSSやデザインシステムトークンを含むフロントエンドCSSのハンドリングに関する具体的なコード規定ガイドを提供する","ko":"프론트엔드 CSS 스킬은 Tailwind CSS 및 디자인 시스템 토큰을 포함한 프론트엔드 CSS 처리에 대한 구체적인 코딩 표준 가이드를 제공합니다","es":"Frontend CSS es una habilidad que proporciona orientación sobre cómo adherirse a los estándares de codificación para CSS frontend","fr":"Frontend CSS est une compétence qui fournit des conseils sur la façon de respecter les normes de codage pour le CSS frontend","de":"Frontend CSS ist eine Fähigkeit, die Anleitung bietet, wie man den Kodierungsstandards für Frontend-CSS entspricht","pt":"O Frontend CSS é uma habilidade que fornece orientação sobre como seguir padrões de codificação para CSS","ru":"Frontend CSS - это навык, который предоставляет руководство по соблюдению стандартов кодирования для CSS","ar":"Frontend CSS هو مهارة توفر إرشادات حول كيفية اتباع معايير الترميز ل CSS"},"seo":{"title":{"en":"Frontend CSS: Best Practices for AI Agents | AI Agent Skill","zh":"前端CSS最佳实践指南 - AI工具","ja":"フロントエンドCSS設定ガイド - AIエージェント","ko":"프론트엔드 CSS 구현 가이드 - AI 에이전트","es":"Guía de configuración de Frontend CSS para desarrolladores","fr":"Guide de mise en place de Frontend CSS pour les développeurs","de":"Einrichtungsleitfaden für Frontend CSS-Entwickler","pt":"Guia de Configuração Frontend CSS para Desenvolvedores","ru":"Руководство по Настройке Frontend CSS для ИИ Агентов","ar":"دليل إعداد Frontend CSS للРазработين"},"description":{"en":"Unlock expert guidance on handling frontend CSS with Tailwind utility classes and design system tokens. Learn how to configure theme extensions and optimize ...","zh":"了解前端CSS的技术细节和最佳实践，包括Tailwind CSS和设计系统令牌","ja":"フロントエンドCSSのテクニカル詳細とベストプラクティスを学ぶ、Tailwind CSSやデザインシステムトークンを含む","ko":"프론트엔드 CSS의 기술 세부 정보와 최선의 실践을 알아보세요. Tailwind CSS 및 디자인 시스템 토큰 포함","es":"Aprenda a utilizar Frontend CSS de manera efectiva con nuestra guía de mejores prácticas para desarrolladores","fr":"Découvrez comment utiliser Frontend CSS de manière efficace avec notre guide de bonnes pratiques pour les développeurs","de":"Erfahren Sie, wie Sie Frontend CSS effektiv einsetzen, mit unserem Leitfaden für Entwickler","pt":"Aprenda a utilizar o Frontend CSS com Tailwind CSS e design system tokens para melhorar a experiência do usuário","ru":"Узнайте, как использовать Frontend CSS с Tailwind CSS и токенами дизайн-системы для улучшения пользовательского опыта","ar":"تعرف على كيفية استخدام Frontend CSS مع Tailwind CSS وأسس التصميم لتحسين تجربة المستخدم"},"definition":{"en":"Frontend CSS is a skill that provides guidance on coding standards for handling frontend CSS, including best practices for writing and editing CSS files, using Tailwind utility classes, and implementing design system tokens.","zh":"前端CSS是指用于构建Web应用程序用户界面的样式和布局技术","ja":"フロントエンドCSSは、Webアプリケーションのユーザーインターフェースを構築するために使用されるスタイルとレイアウトの技術","ko":"프론트엔드 CSS는 웹 애플리케이션의 사용자 인터페이스를 구축하는 데 사용되는 스타일 및 레이아웃 기술","es":"Frontend CSS es una habilidad que ayuda a los desarrolladores a aplicar estándares de codificación para CSS","fr":"Frontend CSS est une compétence qui aide les développeurs à appliquer les normes de codage pour le CSS","de":"Frontend CSS ist eine Fähigkeit, die Entwicklern hilft, Kodierungsstandards für CSS anzuwenden","pt":"Frontend CSS é uma habilidade que ajuda a manter a consistência no código CSS","ru":"Frontend CSS - это навык, который помогает поддерживать согласованность в коде CSS","ar":"Frontend CSS هو مهارة تساعد على الحفاظ على التماسك في код CSS"},"features":{"en":["Provides guidance on writing and editing CSS files","Supports applying Tailwind CSS utility classes in React components","Helps with implementing design system tokens, including colors, spacing, and typography","Configures Tailwind theme extensions using the @theme directive","Offers best practices for deciding between using different frontend CSS approaches"],"zh":["支持Tailwind CSS实用程序类","实现设计系统令牌（颜色、间距、字体）","配置Tailwind主题扩展使用@theme指令","决定在React组件中使用实用程序类还是内联样式","处理CSS文件和React组件的编码标准"],"ja":["Tailwind CSSユーティリティクラスのサポート","デザインシステムトークン（色、間隔、フォント）の実装","Tailwindテーマ拡張の設定@themeディレクティブを使用","Reactコンポーネントでユーティリティクラスとインラインスタイルを使用するかどうかの決定","CSSファイルとReactコンポーネントのコード規定の処理"],"ko":["Tailwind CSS 유틸리티 클래스 지원","디자인 시스템 토큰(색상, 간격, 글꼴) 구현","Tailwind 테마 확장 구성 @theme 지시문을 사용","React 구성 요소에서 유틸리티 클래스 또는 인라인 스타일을 사용할지 여부를 결정","CSS 파일 및 React 구성 요소의 코딩 표준 처리"],"es":["Aplicación de clases de utilidad de Tailwind CSS en componentes React","Implementación de tokens de diseño de sistema para colores, espaciado y tipografía","Configuración de extensiones de temas de Tailwind utilizando la directiva @theme","Adhesión a los estándares de codificación para CSS frontend","Uso de ficheros CSS y TSX/JSX para el desarrollo de aplicaciones web"],"fr":["Application de classes d''utilité de Tailwind CSS dans les composants React","Mise en œuvre de jetons de conception de système pour les couleurs, l''espacement et la typographie","Configuration d''extensions de thèmes de Tailwind à l''aide de la directive @theme","Respect des normes de codage pour le CSS frontend","Utilisation de fichiers CSS et TSX/JSX pour le développement d''applications web"],"de":["Anwendung von Tailwind-CSS-Utility-Klassen in React-Komponenten","Implementierung von Design-System-Tokens für Farben, Abstände und Typografie","Konfiguration von Tailwind-Theme-Erweiterungen mit der @theme-Direktive","Einhaltung der Kodierungsstandards für Frontend-CSS","Verwendung von CSS- und TSX/JSX-Dateien für die Entwicklung von Webanwendungen"],"pt":["Suporte a Tailwind CSS","Implementação de design system tokens","Configuração de temas com @theme","Uso de utility classes em React","Manutenção de padrões de codificação CSS"],"ru":["Поддержка Tailwind CSS","Реализация токенов дизайн-системы","Настройка тем с @theme","Использование утилитных классов в React","Соблюдение стандартов кодирования CSS"],"ar":["دعم Tailwind CSS","تنفيذ أسس التصميم","تكوين السمات مع @theme","استخدام فئات الخدمات في React","الحفاظ على معايير الترميز ل CSS"]},"keywords":{"en":["how to use Frontend CSS","what is Frontend CSS","Frontend CSS alternative","Frontend CSS vs CSS-in-JS","Frontend CSS install","Frontend CSS setup guide","Tailwind CSS utility classes","design system tokens","React components CSS"],"zh":["前端CSS","Tailwind CSS","设计系统令牌","React组件","CSS编码标准","AI工具","前端开发","Web开发","CSS实践"],"ja":["フロントエンドCSS","Tailwind CSS","デザインシステムトークン","Reactコンポーネント","CSSコード規定","AIエージェント","フロントエンド開発","Web開発","CSSベストプラクティス"],"ko":["프론트엔드 CSS","Tailwind CSS","디자인 시스템 토큰","React 구성 요소","CSS 코딩 표준","AI 에이전트","프론트엔드 개발","웹 개발","CSS 최선의 실践"],"es":["Frontend CSS","Desarrollo web","Tailwind CSS","React","CSS frontend","Estándares de codificación","Tokens de diseño de sistema","Configuración de temas de Tailwind"],"fr":["Frontend CSS","Développement web","Tailwind CSS","React","CSS frontend","Normes de codage","Jetons de conception de système","Configuration de thèmes de Tailwind"],"de":["Frontend CSS","Webentwicklung","Tailwind CSS","React","Frontend-CSS","Kodierungsstandards","Design-System-Tokens","Konfiguration von Tailwind-Themen"],"pt":["Frontend CSS","Tailwind CSS","design system tokens","React","CSS","padrões de codificação","desenvolvimento web","ИИ Агенты"],"ru":["Frontend CSS","Tailwind CSS","токены дизайн-системы","React","CSS","стандарты кодирования","веб-разработка","ИИ Агенты"],"ar":["Frontend CSS","Tailwind CSS","أسس التصميم","React","CSS","معايير الترميز","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"DevanB","repo":"lucidlog","repoPath":"DevanB/lucidlog","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.779Z","topics":[],"category":"community","skillMd":{"name":"Frontend CSS","description":"Write consistent, maintainable CSS following the projects methodology (Tailwind utility classes) while minimizing custom CSS and adhering to design system tokens. Use this skill when writing or editing CSS files, Tailwind classes in React components (.tsx, .jsx files), when implementing design system colors/spacing/typography, when using Tailwind utility classes, when deciding between framework utilities vs. custom CSS, when optimizing CSS for production with tree-shaking, when configuring Tailwind theme extensions, or when maintaining design consistency across the application.","bodyPreview":"# Frontend CSS\n\nThis Skill provides Claude Code with specific guidance on how to adhere to coding standards as they relate to how it should handle frontend CSS.\n\n## When to use this skill\n\n- When writing or editing CSS files in the project\n- When applying Tailwind CSS utility classes in React components (.tsx, .jsx files)\n- When implementing design system tokens (colors, spacing, typography)\n- When configuring Tailwind theme extensions using the `@theme` directive\n- When deciding between using f","body":"# Frontend CSS\n\nThis Skill provides Claude Code with specific guidance on how to adhere to coding standards as they relate to how it should handle frontend CSS.\n\n## When to use this skill\n\n- When writing or editing CSS files in the project\n- When applying Tailwind CSS utility classes in React components (.tsx, .jsx files)\n- When implementing design system tokens (colors, spacing, typography)\n- When configuring Tailwind theme extensions using the `@theme` directive\n- When deciding between using framework utilities vs. writing custom CSS\n- When maintaining consistent styling patterns across components\n- When optimizing CSS for production with purging/tree-shaking\n- When avoiding unnecessary framework style overrides\n- When working with the project''s CSS methodology (Tailwind, BEM, utility-first, etc.)\n- When implementing responsive styles using Tailwind breakpoints\n- When ensuring CSS performance and bundle size optimization\n\n## Instructions\n\nFor details, refer to the information provided in this file:\n[frontend CSS](../../../agent-os/standards/frontend/css.md)\n"},"lastSynced":"2026-03-07T03:16:19.342Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Development Agents requiring standardized frontend styling with Tailwind CSS and React components.","zh":"适合需要使用Tailwind CSS和React组件进行标准化前端样式的Web开发代理。","ja":"Tailwind CSSとReactコンポーネントを使用した標準化されたフロントエンドスタイリングを必要とするWeb開発エージェントに適しています。","ko":"Tailwind CSS와 React 컴포넌트를 사용하여 표준화된 프론트엔드 스타일링이 필요한 웹 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo web que requieren estilismo de frontend estandarizado con Tailwind CSS y componentes de React.","fr":"Idéal pour les agents de développement Web nécessitant un stylisme de frontend standardisé avec Tailwind CSS et des composants React.","de":"Ideal für Webentwicklungsagenten, die ein standardisiertes Frontend-Styling mit Tailwind CSS und React-Komponenten erfordern.","pt":"Ideal para Agentes de Desenvolvimento Web que exigem estilização de frontend padronizada com Tailwind CSS e componentes React.","ru":"Идеально для агентов веб-разработки, требующих стандартизированного стиля frontend с использованием Tailwind CSS и компонентов React.","ar":"مثالي لعميل التطوير الويب الذي يتطلب تنسيق واجهة المستخدم الموحدة باستخدام Tailwind CSS ومكونات React."},"recommendation":{"en":"Empowers agents to write and edit CSS files efficiently, applying utility classes and implementing design system tokens with precision, utilizing React components and Tailwind CSS for seamless frontend development.","zh":"赋予代理编写和编辑CSS文件的能力，高效地应用实用类并使用React组件和Tailwind CSS精确地实现设计系统令牌，从而实现无缝的前端开发。","ja":"エージェントがCSSファイルを書き込んで編集する能力を与え、効率的にユーティリティクラスを適用し、ReactコンポーネントとTailwind CSSを使用してデザインシステムトークンを正確に実装し、シームレスなフロントエンド開発を実現します。","ko":"에이전트가 CSS 파일을 작성하고 편집할 수 있는 능력을 부여하여 유틸리티 클래스를 효율적으로 적용하고 React 컴포넌트와 Tailwind CSS를 사용하여 디자인 시스템 토큰을 정밀하게 구현하여 무шов한 프론트엔드 개발을 가능하게 합니다.","es":"Habilita a los agentes a escribir y editar archivos CSS de manera eficiente, aplicando clases de utilidad e implementando tokens de sistema de diseño con precisión, utilizando componentes de React y Tailwind CSS para un desarrollo de frontend sin problemas.","fr":"Permet aux agents d''écrire et de modifier des fichiers CSS de manière efficace, en appliquant des classes d''utilité et en mettant en œuvre des jetons de système de conception avec précision, en utilisant des composants React et Tailwind CSS pour un développement de frontend sans interruption.","de":"Ermächtigt Agenten, CSS-Dateien effizient zu schreiben und zu bearbeiten, indem sie Utility-Klassen anwenden und Designsystem-Tokens mit Präzision implementieren, wobei React-Komponenten und Tailwind CSS für eine reibungslose Frontend-Entwicklung verwendet werden.","pt":"Habilita os agentes a escrever e editar arquivos CSS de forma eficiente, aplicando classes de utilidade e implementando tokens do sistema de design com precisão, utilizando componentes React e Tailwind CSS para desenvolvimento de frontend sem interrupções.","ru":"Наделяет агентов возможностью эффективно писать и редактировать файлы CSS, применяя утилитарные классы и реализуя токены дизайн-системы с точностью, используя компоненты React и Tailwind CSS для бесперебойного развития frontend.","ar":"يمنح الوكلاء القدرة على كتابة وتحرير ملفات CSS بفعالية، وتطبيق فئات المرافق وتنفيذ رموز نظام التصميم بدقة، باستخدام مكونات React و Tailwind CSS من أجل تطوير واجهة المستخدم دون انقطاع."},"useCases":{"en":["Writing and editing CSS files for project customization","Applying Tailwind CSS utility classes in React components for consistent styling","Implementing design system tokens for uniform design"],"zh":["为项目自定义编写和编辑CSS文件","在React组件中应用Tailwind CSS实用类以实现一致的样式","实现设计系统令牌以实现统一设计"],"ja":["プロジェクトのカスタマイズにCSSファイルを書き込んで編集する","ReactコンポーネントでTailwind CSSユーティリティクラスを適用して一貫したスタイリングを行う","デザインシステムトークンを実装して統一されたデザインを実現する"],"ko":["프로젝트 사용자 정의를 위해 CSS 파일을 작성하고 편집한다","React 컴포넌트에서 Tailwind CSS 유틸리티 클래스를 적용하여 일관된 스타일링을 구현한다","디자인 시스템 토큰을 구현하여 통일된 디자인을 달성한다"],"es":["Escribir y editar archivos CSS para la personalización de proyectos","Aplicar clases de utilidad de Tailwind CSS en componentes de React para un estilismo coherente","Implementar tokens de sistema de diseño para un diseño uniforme"],"fr":["Écrire et modifier des fichiers CSS pour la personnalisation de projets","Appliquer des classes d''utilité de Tailwind CSS dans des composants React pour un stylisme cohérent","Mettre en œuvre des jetons de système de conception pour une conception uniforme"],"de":["Schreiben und Bearbeiten von CSS-Dateien für die Projektanpassung","Anwenden von Tailwind-CSS-Utility-Klassen in React-Komponenten für ein konsistentes Styling","Implementieren von Designsystem-Tokens für ein einheitliches Design"],"pt":["Escrita e edição de arquivos CSS para personalização de projetos","Aplicação de classes de utilidade do Tailwind CSS em componentes React para estilização consistente","Implementação de tokens do sistema de design para design uniforme"],"ru":["Написание и редактирование файлов CSS для настройки проектов","Применение утилитарных классов Tailwind CSS в компонентах React для согласованного стиля","Реализация токенов дизайн-системы для унифицированного дизайна"],"ar":["كتابة وتحرير ملفات CSS لتخصيص المشاريع","تطبيق فئات المرافق من Tailwind CSS في مكونات React من أجل تنسيق متسق","تنفيذ رموز نظام التصميم من أجل تصميم موحد"]},"limitations":{"en":["Requires knowledge of React and Tailwind CSS","Limited to frontend CSS development"],"zh":["需要React和Tailwind CSS的知识","仅限于前端CSS开发"],"ja":["ReactとTailwind CSSの知識が必要","フロントエンドCSS開発に限られる"],"ko":["React와 Tailwind CSS에 대한 지식이 필요하다","프론트엔드 CSS 개발에만 제한된다"],"es":["Requiere conocimiento de React y Tailwind CSS","Limitado al desarrollo de CSS de frontend"],"fr":["Nécessite des connaissances en React et Tailwind CSS","Limité au développement de CSS de frontend"],"de":["Benötigt Kenntnisse von React und Tailwind CSS","Begrenzt auf die Frontend-CSS-Entwicklung"],"pt":["Exige conhecimento de React e Tailwind CSS","Limitado ao desenvolvimento de frontend CSS"],"ru":["Требует знания React и Tailwind CSS","Ограничен разработкой frontend CSS"],"ar":["يتطلب معرفة ب React و Tailwind CSS","محدود بتطوير CSS لواجهة المستخدم"]},"version":4},"contentHash":"81534cb71caba56258cb46eddb1a30b40c310150a149468e802bf34ac2f6646f","qualityScore":38}');
