INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DevanB/lucidlog/Frontend CSS', 'Frontend CSS', 'DevanB', 'lucidlog', 'community', 'Frontend CSS DevanB lucidlog community Frontend CSS provides specific guidance on coding standards for handling frontend CSS, benefiting developers working with React components and Tailwind CSS. It helps with writing and editing CSS files, applying utility classes, and implementing design system tokens. 前端CSS技能提供了具体的编码标准指南，用于处理前端CSS，包括Tailwind CSS和设计系统令牌 フロントエンドCSSスキルは、Tailwind CSSやデザインシステムトークンを含むフロントエンドCSSのハンドリングに関する具体的なコード規定ガイドを提供する 프론트엔드 CSS 스킬은 Tailwind CSS 및 디자인 시스템 토큰을 포함한 프론트엔드 CSS 처리에 대한 구체적인 코딩 표준 가이드를 제공합니다 Frontend CSS es una habilidad que proporciona orientación sobre cómo adherirse a los estándares de codificación para CSS frontend Frontend CSS est une compétence qui fournit des conseils sur la façon de respecter les normes de codage pour le CSS frontend Frontend CSS ist eine Fähigkeit, die Anleitung bietet, wie man den Kodierungsstandards für Frontend-CSS entspricht O Frontend CSS é uma habilidade que fornece orientação sobre como seguir padrões de codificação para CSS Frontend CSS - это навык, который предоставляет руководство по соблюдению стандартов кодирования для CSS Frontend CSS هو مهارة توفر إرشادات حول كيفية اتباع معايير الترميز ل CSS how to use Frontend CSS what is Frontend CSS Frontend CSS alternative Frontend CSS vs CSS-in-JS Frontend CSS install Frontend CSS setup guide Tailwind CSS utility classes design system tokens React components CSS 前端CSS Tailwind CSS 设计系统令牌 React组件 CSS编码标准 AI工具 前端开发 Web开发 CSS实践 Provides guidance on writing and editing CSS files Supports applying Tailwind CSS utility classes in React components Helps with implementing design system tokens, including colors, spacing, and typography Configures Tailwind theme extensions using the @theme directive Offers best practices for deciding between using different frontend CSS approaches Frontend CSS is a skill that provides guidance on coding standards for handling frontend CSS, including best practices for writing and editing CSS files, using Tailwind utility classes, and implementing design system tokens.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GabrielTheDEV/My_AIOS_BRAIN/aios-sm', 'community', 'GabrielTheDEV', 'My_AIOS_BRAIN', 'GabrielTheDEV/My_AIOS_BRAIN', 'aios-sm', 0, 0, 38, '2026-02-21T02:54:28Z', '2026-03-07T03:54:51.531Z', 'f340516e649f508f4ed9fb832a1517f42955849f9b3dad760ad1fbcc1f3df382', '{"id":"GabrielTheDEV/My_AIOS_BRAIN/aios-sm","name":"aios-sm","description":{"en":"The aios-sm skill facilitates agile project management by automating user story creation, validation, and sprint planning. It benefits development teams seeking to optimize their Scrum processes.","zh":"AIOS Scrum Master Activator 是一个用于敏捷开发的 AI 工具，提供用户故事创建、验证和完善等功能","ja":"AIエージェント AIOS Scrum Master Activator は、アジャイル開発を支援する AI ツールです","ko":"AIOS Scrum Master Activator는 사용자 스토리 생성, 검증 및 완善 등을 제공하는 애자일 개발을 위한 AI 도구입니다","es":"aios-sm es un activador de Scrum Master que facilita la creación de historias de usuario y la planificación de sprint","fr":"aios-sm est un activateur de Scrum Master qui facilite la création d''histoires utilisateur et la planification de sprint","de":"aios-sm ist ein Scrum Master Activator, der die Erstellung von Benutzerstories und die Sprintplanung erleichtert","pt":"O AIOS Scrum Master Activator é um agente que ajuda a criar histórias de usuário, validar e refinar histórias, planejar sprints e realizar retrospectivas.","ru":"ИИ Агент AIOS Scrum Master Activator помогает создавать пользовательские истории, проверять и уточнять истории, планировать спринты и проводить ретроспективы.","ar":"AIOS Scrum Master Activator هو وكيل يساعد في إنشاء قصص المستخدم، التحقق منها وتنقيحها، وتخطيط السبرينتس وإجراء الاستعراضات"},"seo":{"title":{"en":"aios-sm: Agile Project Management Setup Guide | AI Agent ...","zh":"AIOS Scrum Master Activator Setup Guide","ja":"AIエージェント AIOS Scrum Master Activator を始める","ko":"AIOS Scrum Master Activator 설정 가이드","es":"Guía de configuración de aios-sm: Activador de Scrum Master","fr":"Guide de configuration d''aios-sm : Activateur de Scrum Ma...","de":"Konfigurationsleitfaden für aios-sm: Scrum Master Activator","pt":"Guia de Configuração do AIOS Scrum Master Activator","ru":"Настройка ИИ Агента AIOS Scrum Master Activator","ar":"دليل إعداد AIOS Scrum Master Activator"},"description":{"en":"Unlock efficient sprint planning and backlog grooming with aios-sm. Discover how to activate this AIOS Scrum Master Activator for streamlined agile workflows.","zh":"了解 AIOS Scrum Master Activator 的功能和特点，提高您的敏捷开发效率","ja":"AIエージェント AIOS Scrum Master Activator の機能と特徴を紹介します","ko":"AIOS Scrum Master Activator의 기능과 특징을 알아보세요","es":"Descubre cómo configurar aios-sm para la creación de historias de usuario, validación y definición de criterios de aceptación","fr":"Découvrez comment configurer aios-sm pour la création d''histoires utilisateur, la validation et la définition des critères d''acceptation","de":"Erfahren Sie, wie Sie aios-sm für die Erstellung von Benutzerstories, Validierung und Definition von Akzeptanzkriterien konfigurieren","pt":"Aprenda a configurar o AIOS Scrum Master Activator para criar histórias de usuário, validar e refinar histórias, planejar sprints e mais","ru":"Узнайте, как настроить ИИ Агента AIOS Scrum Master Activator для создания пользовательских историй, проверки и уточнения историй, планирования спринтов и мно...","ar":"تعرف على كيفية إعداد AIOS Scrum Master Activator لإنشاء قصص المستخدم، التحقق منها وتنقيحها، وتخطيط السبرينتس والمزيد"},"definition":{"en":"aios-sm is an AIOS Scrum Master Activator that automates tasks such as user story creation, story validation, and sprint planning using node scripts and markdown files.","zh":"AIOS Scrum Master Activator 是一个用于辅助敏捷开发的 AI 工具","ja":"AIエージェント AIOS Scrum Master Activator は、アジャイル開発を支援する AI ツールです","ko":"AIOS Scrum Master Activator는 애자일 개발을 지원하는 AI 도구입니다","es":"aios-sm es un agente de AI que ayuda a los equipos de desarrollo a crear historias de usuario y a planificar sprints","fr":"aios-sm est un agent d''IA qui aide les équipes de développement à créer des histoires utilisateur et à planifier des sprints","de":"aios-sm ist ein KI-Agent, der Entwicklungsteams hilft, Benutzerstories zu erstellen und Sprints zu planen","pt":"O que é AIOS Scrum Master Activator? É um agente que auxilia no processo de desenvolvimento de software","ru":"Что такое ИИ Агент AIOS Scrum Master Activator? Это агент, который помогает в процессе разработки программного обеспечения","ar":"ما هو AIOS Scrum Master Activator؟ هو وكيل يساعد في عملية تطوير البرمجيات"},"features":{"en":["Loads `.aios-core/development/agents/sm.md` as the source of truth for Scrum master activities","Adopts the agent persona and command system for streamlined workflow management","Generates greetings via `node .aios-core/development/scripts` for personalized interactions","Facilitates daily standup meetings and retrospectives for continuous improvement","Supports backlog grooming and acceptance criteria definition for refined user stories"],"zh":["用户故事创建和验证","故事完善和验收标准定义","冲刺计划和待办事项梳理","每日站立会议辅助","Node.js 脚本支持"],"ja":["ユーザーストーリーの作成と検証","ストーリーの完善と受け入れ基準の定義","スプリント計画とバックログの整理","デイリースタンドアップミーティングの支援","Node.js スクリプトのサポート"],"ko":["사용자 스토리 생성과 검증","스토리 완善과 수락 기준 정의","스프린트 계획과 백로그 정리","데일리 스탠드업 회의 지원","Node.js 스크립트 지원"],"es":["Creación de historias de usuario a partir de PRD","Validación y comprobación de la completitud de las historias","Definición de criterios de aceptación","Planificación de sprint y refinamiento de historias","Facilitación de reuniones diarias y retrospectivas"],"fr":["Création d''histoires utilisateur à partir de PRD","Validation et vérification de la complétude des histoires","Définition des critères d''acceptation","Planification de sprint et raffinement d''histoires","Facilitation de réunions quotidiennes et de rétrospectives"],"de":["Erstellung von Benutzerstories aus PRD","Validierung und Überprüfung der Vollständigkeit von Benutzerstories","Definition von Akzeptanzkriterien","Sprintplanung und Feinabstimmung von Benutzerstories","Facilitation von täglichen Meetings und Retrospektiven"],"pt":["Criação de histórias de usuário a partir de PRD","Validação e refinamento de histórias","Definição de critérios de aceitação","Planejamento de sprints","Realização de retrospectivas","Facilitação de daily standup"],"ru":["Создание пользовательских историй из PRD","Проверка и уточнение историй","Определение критериев приемки","Планирование спринтов","Проведение ретроспектив","Фасилитация daily standup"],"ar":["إنشاء قصص المستخدم من PRD","التحقق من قصص المستخدم وتنقيحها","تحديد معايير القبول","تخطيط السبرينتس","إجراء الاستعراضات","تسهيل daily standup"]},"keywords":{"en":["how to use aios-sm","aios-sm setup guide","aios-sm vs jira","aios-sm install","what is aios-sm","aios-sm alternative","aios-sm agile project management","aios-sm sprint planning","aios-sm backlog grooming"],"zh":["AIOS Scrum Master Activator","AI 工具","敏捷开发","用户故事创建","故事完善","Node.js","CLI"],"ja":["AIエージェント","AIOS Scrum Master Activator","アジャイル開発","ユーザーストーリーの作成","ストーリーの完善","Node.js","CLI"],"ko":["AIOS Scrum Master Activator","AI 도구","애자일 개발","사용자 스토리 생성","스토리 완善","Node.js","CLI"],"es":["aios-sm","agente de AI","Scrum Master","creación de historias de usuario","planificación de sprint","validación de historias","definición de criterios de aceptación","herramientas de desarrollo ágil"],"fr":["aios-sm","agent d''IA","Scrum Master","création d''histoires utilisateur","planification de sprint","validation d''histoires","définition des critères d''acceptation","outils de développement agile"],"de":["aios-sm","KI-Agent","Scrum Master","Erstellung von Benutzerstories","Sprintplanung","Validierung von Benutzerstories","Definition von Akzeptanzkriterien","Agile-Entwicklungstools"],"pt":["AIOS Scrum Master Activator","Agente de desenvolvimento de software","Criação de histórias de usuário","Validação de histórias","Planejamento de sprints","Retrospectivas","Ferramentas de desenvolvimento de software"],"ru":["ИИ Агент AIOS Scrum Master Activator","Агент разработки программного обеспечения","Создание пользовательских историй","Проверка историй","Планирование спринтов","Ретроспективы","Инструменты разработки программного обеспечения"],"ar":["AIOS Scrum Master Activator","وكيل تطوير البرمجيات","إنشاء قصص المستخدم","التحقق من قصص المستخدم","تخطيط السبرينتس","الاستعراضات","أدوات تطوير البرمجيات"]}},"owner":"GabrielTheDEV","repo":"My_AIOS_BRAIN","repoPath":"GabrielTheDEV/My_AIOS_BRAIN","stars":0,"forks":0,"updatedAt":"2026-02-21T02:54:28Z","topics":[],"category":"community","skillMd":{"name":"aios-sm","description":"Scrum Master (River). Use for user story creation from PRD, story validation and completeness checking, acceptance criteria definition, story refinement, sprint planning, backlo...","bodyPreview":"# AIOS Scrum Master Activator\n\n## When To Use\nUse for user story creation from PRD, story validation and completeness checking, acceptance criteria definition, story refinement, sprint planning, backlog grooming, retrospectives, daily standup facilitation, and lo...\n\n## Activation Protocol\n1. Load `.aios-core/development/agents/sm.md` as source of truth (fallback: `.codex/agents/sm.md`).\n2. Adopt this agent persona and command system.\n3. Generate greeting via `node .aios-core/development/scripts","body":"# AIOS Scrum Master Activator\n\n## When To Use\nUse for user story creation from PRD, story validation and completeness checking, acceptance criteria definition, story refinement, sprint planning, backlog grooming, retrospectives, daily standup facilitation, and lo...\n\n## Activation Protocol\n1. Load `.aios-core/development/agents/sm.md` as source of truth (fallback: `.codex/agents/sm.md`).\n2. Adopt this agent persona and command system.\n3. Generate greeting via `node .aios-core/development/scripts/generate-greeting.js sm` and show it first.\n4. Stay in this persona until the user asks to switch or exit.\n\n## Starter Commands\n- `*help` - Show all available commands with descriptions\n- `*draft` - Create next user story\n- `*story-checklist` - Run story draft checklist\n- `*guide` - Show comprehensive usage guide for this agent\n\n## Non-Negotiables\n- Follow `.aios-core/constitution.md`.\n- Execute workflows/tasks only from declared dependencies.\n- Do not invent requirements outside the project artifacts.\n"},"lastSynced":"2026-03-07T03:54:51.531Z","agentAnalysis":{"suitability":{"en":"Ideal for Agile-focused AI Agents seeking to streamline Scrum processes through automated user story creation and sprint planning.","zh":"适用于专注于敏捷方法的AI代理，旨在通过自动化用户故事创建和迭代规划来简化Scrum流程。","ja":"アジャイルに焦点を当てたAIエージェントがScrumプロセスを自動化されたユーザーストーリーの作成とスプリント計画を通じて合理化できるように設計されています。","ko":"Agile에 초점을 둔 AI 에이전트가 자동화된 사용자 스토리 생성 및 스프린트 계획을 통해 Scrum 프로세스를 간소화할 수 있도록 설계되었습니다.","es":"Ideal para agentes de inteligencia artificial centrados en Agile que buscan optimizar los procesos de Scrum a través de la creación automatizada de historias de usuario y la planificación de sprint.","fr":"Idéal pour les agents d''intelligence artificielle axés sur Agile cherchant à rationaliser les processus Scrum grâce à la création automatisée d''histoires utilisateur et à la planification de sprint.","de":"Ideal für agil-fokussierte KI-Agents, die Scrum-Prozesse durch automatisierte Erstellung von Benutzerstorys und Sprint-Planung optimieren möchten.","pt":"Ideal para Agentes de IA focados em Agile que buscam simplificar os processos Scrum por meio da criação automática de histórias de usuário e planejamento de sprint.","ru":"Идеально для агентов ИИ, ориентированных на Agile, которые стремятся оптимизировать процессы Scrum посредством автоматизации создания пользовательских историй и планирования спринта.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يركز على Agile ويستهدف تسهيل عمليات Scrum من خلال إنشاء قصة مستخدم آلية وتخطيط السبرينت."},"recommendation":{"en":"Empowers agents to automate user story creation from PRD, validate story completeness, and define acceptance criteria using Markdown files like `.aios-core/development/agents/sm.md`. It facilitates efficient sprint planning, backlog grooming, and retrospective analysis by leveraging command systems and node scripts.","zh":"赋予代理自动化从PRD创建用户故事、验证故事完整性，并使用Markdown文件（如`.aios-core/development/agents/sm.md`）定义接受标准的能力。它通过利用命令系统和node脚本来实现高效的迭代规划、待办事项梳理和回顾分析。","ja":"エージェントにPRDからユーザーストーリーを作成し、ストーリーの完全性を検証し、Markdownファイル（例：`.aios-core/development/agents/sm.md`）を使用して受け入れ基準を定義する能力を付与します。コマンドシステムとノードスクリプトを利用して、効率的なスプリント計画、バックログの整理、回顧分析を実現します。","ko":"에이전트가 PRD에서 사용자 스토리를 자동으로 생성하고 스토리의 완전성을 검증하며 Markdown 파일(예: `.aios-core/development/agents/sm.md`)을 사용하여 수락 기준을 정의할 수 있도록 합니다. 명령 시스템과 노드 스크립트를 활용하여 효율적인 스프린트 계획, 백로그 정리, 회고 분석을 지원합니다.","es":"Habilita a los agentes a automatizar la creación de historias de usuario desde PRD, validar la completitud de las historias y definir criterios de aceptación utilizando archivos Markdown como `.aios-core/development/agents/sm.md`. Facilita la planificación de sprint eficiente, el mantenimiento del backlog y el análisis retrospectivo mediante el aprovechamiento de sistemas de comandos y scripts de nodo.","fr":"Permet aux agents d''automatiser la création d''histoires utilisateur à partir de PRD, de valider la complétude des histoires et de définir des critères d''acceptation en utilisant des fichiers Markdown tels que `.aios-core/development/agents/sm.md`. Elle facilite une planification de sprint efficace, un entretien de backlog et une analyse rétrospective en exploitant les systèmes de commandes et les scripts de nœud.","de":"Ermächtigt Agents, die Erstellung von Benutzerstorys aus PRD zu automatisieren, die Vollständigkeit von Storys zu überprüfen und Akzeptanzkriterien mithilfe von Markdown-Dateien wie `.aios-core/development/agents/sm.md` zu definieren. Sie ermöglicht eine effiziente Sprint-Planung, Backlog-Pflege und retrospektive Analyse durch die Nutzung von Befehlsystemen und Knotenskripten.","pt":"Habilita agentes a automatizar a criação de histórias de usuário a partir do PRD, validar a completude da história e definir critérios de aceitação usando arquivos Markdown como `.aios-core/development/agents/sm.md`. Isso facilita o planejamento de sprint eficiente, limpeza de backlog e análise retrospectiva ao aproveitar sistemas de comando e scripts de node.","ru":"Позволяет агентам автоматизировать создание пользовательских историй из PRD, проверять полноту истории и определять критерии приемки с помощью файлов Markdown, таких как `.aios-core/development/agents/sm.md`. Это обеспечивает эффективное планирование спринта, обслуживание бэклога и ретроспективный анализ путем использования командных систем и скриптов node.","ar":"يمنح الوكلاء القدرة على توفير إنشاء قصة مستخدم آلية من وثائق متطلبات المنتج (PRD) ، والتحقق من اكتمال القصة ، وتحديد معايير القبول باستخدام ملفات Markdown مثل `.aios-core/development/agents/sm.md`. هذا يسهل التخطيط السبرينت الفعال ، وتنقية.Backlog ، وتحليل استعادي من خلال استخدام أنظمة الأوامر وبرامج العقدة."},"useCases":{"en":["Automating user story creation from Product Requirements Documents (PRD)","Validating and refining user stories for completeness and clarity","Facilitating sprint planning and backlog grooming through data-driven insights"],"zh":["自动化从产品需求文档（PRD）创建用户故事","验证和完善用户故事以确保完整性和清晰性","通过数据驱动的洞察力促进迭代规划和待办事项梳理"],"ja":["プロダクト要件文書（PRD）からユーザーストーリーを作成する自動化","ユーザーストーリーの完全性と明確性を検証して洗練する","データドリブンの洞察を利用してスプリント計画とバックログの整理を促進する"],"ko":["제품 요구 문서(PRD)에서 사용자 스토리를 자동으로 생성하는 것","사용자 스토리의 완전성과 명확성을 검증하고 정제하는 것","데이터 驅動의洞察력을 통해 스프린트 계획과 백로그 정리를 지원하는 것"],"es":["Automatizar la creación de historias de usuario a partir de Documentos de Requisitos de Producto (PRD)","Validar y perfeccionar historias de usuario para garantizar la completitud y claridad","Facilitar la planificación de sprint y el mantenimiento del backlog a través de información basada en datos"],"fr":["Automatiser la création d''histoires utilisateur à partir de Documents de Spécifications de Produit (PRD)","Valider et affiner les histoires utilisateur pour garantir la complétude et la clarté","Faciliter la planification de sprint et l''entretien de backlog grâce à des informations basées sur les données"],"de":["Automatisieren der Erstellung von Benutzerstorys aus Produktanforderungsdokumenten (PRD)","Überprüfen und Verfeinern von Benutzerstorys, um Vollständigkeit und Klarheit sicherzustellen","Ermöglichen einer effizienten Sprint-Planung und Backlog-Pflege durch datengetriebene Erkenntnisse"],"pt":["Automatizar a criação de histórias de usuário a partir de Documentos de Requisitos de Produto (PRD)","Validar e refinar as histórias de usuário para completude e clareza","Facilitar o planejamento de sprint e a limpeza de backlog por meio de insights baseados em dados"],"ru":["Автоматизировать создание пользовательских историй из документов требований продукта (PRD)","Проверять и уточнять пользовательские истории для полноты и ясности","Обеспечивать эффективное планирование спринта и обслуживание бэклога посредством данных, основанных на инсайтах"],"ar":["توفير إنشاء قصة مستخدم آلية من وثائق متطلبات المنتج (PRD) ","التحقق من صحة القصة وتطويرها لضمان اكتمالها ووضوحها","تسهيل التخطيط السبرينت والتنقية.Backlog من خلال رؤى مبنية على البيانات"]},"limitations":{"en":["Requires access to `.aios-core/development/agents/sm.md` or fallback `.codex/agents/sm.md` files","Dependent on node scripts for execution"],"zh":["需要访问`.aios-core/development/agents/sm.md`或回退`.codex/agents/sm.md`文件","执行依赖于node脚本"],"ja":["`.aios-core/development/agents/sm.md`またはフォールバック`.codex/agents/sm.md`ファイルへのアクセスが必要","実行はノードスクリプトに依存する"],"ko":["`.aios-core/development/agents/sm.md` 또는 폴백 `.codex/agents/sm.md` 파일에 접근할 수 있어야 함","실행은 노드 스크립트에 의존함"],"es":["Requiere acceso a archivos `.aios-core/development/agents/sm.md` o archivos de reserva `.codex/agents/sm.md`","Dependiente de scripts de nodo para la ejecución"],"fr":["Nécessite un accès aux fichiers `.aios-core/development/agents/sm.md` ou aux fichiers de secours `.codex/agents/sm.md`","Dépendant des scripts de nœud pour l''exécution"],"de":["Erfordert Zugriff auf Dateien `.aios-core/development/agents/sm.md` oder Fallback-Dateien `.codex/agents/sm.md`","Abhängig von Knotenskripten für die Ausführung"],"pt":["Exige acesso aos arquivos `.aios-core/development/agents/sm.md` ou arquivos de fallback `.codex/agents/sm.md`","Dependente de scripts de node para execução"],"ru":["Требует доступа к файлам `.aios-core/development/agents/sm.md` или файлам fallback `.codex/agents/sm.md`","Зависит от скриптов node для выполнения"],"ar":["يتطلب الوصول إلى الملفات `.aios-core/development/agents/sm.md` أو ملفات fallback `.codex/agents/sm.md`","يعتمد على برامج العقدة للتنفيذ"]},"version":4},"contentHash":"f340516e649f508f4ed9fb832a1517f42955849f9b3dad760ad1fbcc1f3df382","qualityScore":38}');
