INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GabrielTheDEV/My_AIOS_BRAIN/aios-sm', 'aios-sm', 'GabrielTheDEV', 'My_AIOS_BRAIN', 'community', 'aios-sm GabrielTheDEV My_AIOS_BRAIN community The aios-sm skill facilitates agile project management by automating user story creation, validation, and sprint planning. It benefits development teams seeking to optimize their Scrum processes. AIOS Scrum Master Activator 是一个用于敏捷开发的 AI 工具，提供用户故事创建、验证和完善等功能 AIエージェント AIOS Scrum Master Activator は、アジャイル開発を支援する AI ツールです AIOS Scrum Master Activator는 사용자 스토리 생성, 검증 및 완善 등을 제공하는 애자일 개발을 위한 AI 도구입니다 aios-sm es un activador de Scrum Master que facilita la creación de historias de usuario y la planificación de sprint aios-sm est un activateur de Scrum Master qui facilite la création d''histoires utilisateur et la planification de sprint aios-sm ist ein Scrum Master Activator, der die Erstellung von Benutzerstories und die Sprintplanung erleichtert O AIOS Scrum Master Activator é um agente que ajuda a criar histórias de usuário, validar e refinar histórias, planejar sprints e realizar retrospectivas. ИИ Агент AIOS Scrum Master Activator помогает создавать пользовательские истории, проверять и уточнять истории, планировать спринты и проводить ретроспективы. AIOS Scrum Master Activator هو وكيل يساعد في إنشاء قصص المستخدم، التحقق منها وتنقيحها، وتخطيط السبرينتس وإجراء الاستعراضات how to use aios-sm aios-sm setup guide aios-sm vs jira aios-sm install what is aios-sm aios-sm alternative aios-sm agile project management aios-sm sprint planning aios-sm backlog grooming AIOS Scrum Master Activator AI 工具 敏捷开发 用户故事创建 故事完善 Node.js CLI Loads `.aios-core/development/agents/sm.md` as the source of truth for Scrum master activities Adopts the agent persona and command system for streamlined workflow management Generates greetings via `node .aios-core/development/scripts` for personalized interactions Facilitates daily standup meetings and retrospectives for continuous improvement Supports backlog grooming and acceptance criteria definition for refined user stories aios-sm is an AIOS Scrum Master Activator that automates tasks such as user story creation, story validation, and sprint planning using node scripts and markdown files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('automacoescomerciaisintegradas/xyzaios/aios-sm', 'community', 'automacoescomerciaisintegradas', 'xyzaios', 'automacoescomerciaisintegradas/xyzaios', 'aios-sm', 0, 0, 38, '2026-02-21T20:45:20Z', '2026-03-07T03:55:07.236Z', 'f340516e649f508f4ed9fb832a1517f42955849f9b3dad760ad1fbcc1f3df382', '{"id":"automacoescomerciaisintegradas/xyzaios/aios-sm","name":"aios-sm","description":{"en":"aios-sm is a core framework for full-stack development, facilitating user story creation, validation, and sprint planning. It benefits developers and teams seeking to enhance their Agile workflow.","zh":"AIOS SM是AI智能代理工具，用于Full Stack开发，提供用户故事创建、验证和完善等功能","ja":"AIOS SMはAIエージェントツールで、フルスタック開発に使用され、ユーザーストーリーの作成、検証、完善などを提供する","ko":"AIOS SM은 Full Stack 개발을 위한 AI 에이전트 툴로, 사용자 스토리 생성, 검증 및 완善 등을 제공합니다","es":"AIOS-SM es un agente de orquestación para full stack development que facilita la creación de historias de usuario, la validación y la planificación de sprint.","fr":"AIOS-SM est un agent d''orchestration pour le développement full stack qui facilite la création d''histoires utilisateur, la validation et la planification de sprint.","de":"AIOS-SM ist ein KI-Orchestrierungsagent für Full-Stack-Entwicklung, der die Erstellung von Benutzerstories, die Validierung und die Sprintplanung erleichtert.","pt":"O AIOS Scrum Master Activator é um framework de desenvolvimento full stack que ajuda a criar histórias de usuário, validar e refinar histórias. Saiba mais sobre como configurá-lo","ru":"AIOS Scrum Master Activator - это фреймворк для полного стека разработки, который помогает создавать пользовательские истории, проверять и дорабатывать истории. Узнайте больше о его настройке","ar":"AIOS Scrum Master Activator هو إطار عمل للتنمية الشاملة يساعد على إنشاء قصص المستخدم، التحقق والتحسين من القصص. تعلم المزيد عن كيفية إعدادها"},"seo":{"title":{"en":"aios-sm: AI-Orchestrated System Setup Guide | AI Agent Skill","zh":"AIOS SM集成指南：AI智能代理工具","ja":"AIOS SMセットアップガイド：AIエージェントのベストプラクティス","ko":"AIOS SM 설정 가이드: AI 에이전트 툴","es":"Guía de configuración de AIOS-SM: Agente de orquestación ...","fr":"Guide d''installation d''AIOS-SM : Agent d''orchestration po...","de":"Einrichtungsleitfaden für AIOS-SM: KI-Orchestrierungsagen...","pt":"Guia de Configuração do AIOS Scrum Master Activator","ru":"Настройка AIOS Scrum Master Activator: ИИ Агенты для Full...","ar":"دليل إعداد AIOS Scrum Master Activator: أدوات الذكاء الاص..."},"description":{"en":"Unlock efficient full-stack development with aios-sm. Learn how to activate the AIOS Scrum Master Activator and streamline your workflow today!","zh":"了解AIOS SM的功能和特点，优化您的Full Stack开发流程","ja":"AIOS SMの機能と特徴を学び、フルスタック開発プロセスを最適化する","ko":"AIOS SM의 기능과 특징을 알아보고 Full Stack 개발 프로세스를 최적화하세요","es":"Aprende a configurar y utilizar AIOS-SM, el agente de orquestación para full stack development. Descubre sus características y beneficios.","fr":"Découvrez comment configurer et utiliser AIOS-SM, l''agent d''orchestration pour le développement full stack. Consultez ses fonctionnalités et avantages.","de":"Erfahren Sie, wie Sie AIOS-SM, den KI-Orchestrierungsagent für Full-Stack-Entwicklung, konfigurieren und verwenden. Entdecken Sie seine Funktionen und Vorteile.","pt":"Aprenda a configurar o AIOS Scrum Master Activator para criar histórias de usuário, validar e refinar histórias, planejar sprints e mais","ru":"Узнайте, как настроить AIOS Scrum Master Activator для создания пользовательских историй, проверки и доработки историй, планирования спринтов и т. д.","ar":"تعلم كيفية إعداد AIOS Scrum Master Activator لإنشاء قصص المستخدم، التحقق والتحسين من القصص، تخطيط السبرينتات والمزيد"},"definition":{"en":"aios-sm is an AI-Orchestrated System for Full Stack Development, utilizing a core framework for streamlined development processes.","zh":"AIOS SM是AI智能代理工具，用于优化Full Stack开发流程","ja":"AIOS SMはAIエージェントツールで、フルスタック開発プロセスを最適化する","ko":"AIOS SM은 Full Stack 개발 프로세스를 최적화하는 AI 에이전트 툴입니다","es":"AIOS-SM es un agente de orquestación que utiliza tecnologías de inteligencia artificial para automatizar tareas de desarrollo full stack.","fr":"AIOS-SM est un agent d''orchestration qui utilise des technologies d''intelligence artificielle pour automatiser les tâches de développement full stack.","de":"AIOS-SM ist ein KI-Orchestrierungsagent, der Technologien der künstlichen Intelligenz verwendet, um Aufgaben der Full-Stack-Entwicklung zu automatisieren.","pt":"O AIOS Scrum Master Activator é um agente de IA que ajuda a criar e gerenciar histórias de usuário no desenvolvimento full stack","ru":"AIOS Scrum Master Activator - это ИИ агент, который помогает создавать и управлять пользовательскими историями в полном стеке разработки","ar":"AIOS Scrum Master Activator هو عامل ذكاء اصطناعي يساعد على إنشاء وإدارة قصص المستخدم في التنمية الشاملة"},"features":{"en":["Activates AIOS Scrum Master Activator for user story creation and validation","Loads `.aios-core/development/agents/sm.md` as the source of truth for agent persona and command system","Generates greeting via `node .aios-core/development/scripts` for personalized interaction","Facilitates sprint planning, backlog grooming, retrospectives, and daily standup meetings","Supports story refinement and acceptance criteria definition for improved development clarity"],"zh":["用户故事创建","故事验证和完善","接受标准定义","冲刺规划","积压清理","日常站立会议促进"],"ja":["ユーザーストーリーの作成","ストーリーの検証と完善","受け入れ基準の定義","スプリント計画","バックログの整理","デイリースタンドアップの促進"],"ko":["사용자 스토리 생성","스토리 검증 및 완善","수락 기준 정의","스프린트 계획","백로그 정리","일일 스탠드업 촉진"],"es":["Creación de historias de usuario a partir de PRD","Validación y verificación de historias de usuario","Definición de criterios de aceptación","Planificación de sprint y gestión de backlog","Facilitación de reuniones diarias y retrospectivas","Integración con Node.js y scripts personalizados"],"fr":["Création d''histoires utilisateur à partir de PRD","Validation et vérification d''histoires utilisateur","Définition de critères d''acceptation","Planification de sprint et gestion de backlog","Facilitation de réunions quotidiennes et rétrospectives","Intégration avec Node.js et scripts personnalisés"],"de":["Erstellung von Benutzerstories aus PRD","Validierung und Überprüfung von Benutzerstories","Definition von Akzeptanzkriterien","Sprintplanung und Backlog-Verwaltung","Facilitation von täglichen Meetings und Retrospektiven","Integration mit Node.js und benutzerdefinierten Skripten"],"pt":["Criação de histórias de usuário a partir de PRD","Validação e verificação de histórias","Definição de critérios de aceitação","Refinamento de histórias","Planejamento de sprints","Facilitação de standup diário"],"ru":["Создание пользовательских историй из PRD","Проверка и верификация историй","Определение критериев приемки","Доработка историй","Планирование спринтов","Фасилитация ежедневного стендапа"],"ar":["إنشاء قصص المستخدم من PRD","التحقق والتحقيق من القصص","تحديد معايير القبول","تحسين القصص","تخطيط السبرينتات","تسهيل الستاند أب اليومي"]},"keywords":{"en":["aios-sm setup guide","how to use aios-sm","aios-sm alternative","aios-sm vs agile methodologies","aios-sm install","what is aios-sm","aios-sm core framework","aios-sm for full-stack development","aios-sm scrum master activator"],"zh":["AI智能代理工具","Full Stack开发","用户故事创建","故事验证","接受标准定义","AIOS SM集成","AIOS SM设置","AIOS SM功能"],"ja":["AIエージェントツール","フルスタック開発","ユーザーストーリーの作成","ストーリーの検証","受け入れ基準の定義","AIOS SMセットアップ","AIOS SMの機能","AIOS SMのベストプラクティス"],"ko":["AI 에이전트 툴","Full Stack 개발","사용자 스토리 생성","스토리 검증","수락 기준 정의","AIOS SM 설정","AIOS SM 기능","AIOS SM 최적화"],"es":["AIOS-SM","agente de orquestación","desarrollo full stack","creación de historias de usuario","validación de historias de usuario","planificación de sprint","gestión de backlog","inteligencia artificial en desarrollo de software"],"fr":["AIOS-SM","agent d''orchestration","développement full stack","création d''histoires utilisateur","validation d''histoires utilisateur","planification de sprint","gestion de backlog","intelligence artificielle dans le développement de logiciels"],"de":["AIOS-SM","KI-Orchestrierungsagent","Full-Stack-Entwicklung","Erstellung von Benutzerstories","Validierung von Benutzerstories","Sprintplanung","Backlog-Verwaltung","künstliche Intelligenz in der Softwareentwicklung"],"pt":["aios sm","scrum master activator","desenvolvimento full stack","criação de histórias de usuário","validação de histórias","planejamento de sprints","ferramentas de ia para desenvolvimento","aios core framework"],"ru":["aios sm","scrum master activator","полный стек разработки","создание пользовательских историй","проверка историй","планирование спринтов","инструменты ИИ для разработки","aios core фреймворк"],"ar":["aios sm","scrum master activator","التنمية الشاملة","إنشاء قصص المستخدم","التحقق من القصص","تخطيط السبرينتات","أدوات الذكاء الاصطناعي للتنمية","إطار عمل aios الاصلي"]}},"owner":"automacoescomerciaisintegradas","repo":"xyzaios","repoPath":"automacoescomerciaisintegradas/xyzaios","stars":0,"forks":0,"updatedAt":"2026-02-21T20:45:20Z","topics":[],"category":"community","skillMd":{"name":"aios-sm","description":"Scrum Master (River). Use for user story creation from PRD, story validation and completeness checking, acceptance criteria definition, story refinement, sprint planning, backlo...","bodyPreview":"# AIOS Scrum Master Activator\n\n## When To Use\nUse for user story creation from PRD, story validation and completeness checking, acceptance criteria definition, story refinement, sprint planning, backlog grooming, retrospectives, daily standup facilitation, and lo...\n\n## Activation Protocol\n1. Load `.aios-core/development/agents/sm.md` as source of truth (fallback: `.codex/agents/sm.md`).\n2. Adopt this agent persona and command system.\n3. Generate greeting via `node .aios-core/development/scripts","body":"# AIOS Scrum Master Activator\n\n## When To Use\nUse for user story creation from PRD, story validation and completeness checking, acceptance criteria definition, story refinement, sprint planning, backlog grooming, retrospectives, daily standup facilitation, and lo...\n\n## Activation Protocol\n1. Load `.aios-core/development/agents/sm.md` as source of truth (fallback: `.codex/agents/sm.md`).\n2. Adopt this agent persona and command system.\n3. Generate greeting via `node .aios-core/development/scripts/generate-greeting.js sm` and show it first.\n4. Stay in this persona until the user asks to switch or exit.\n\n## Starter Commands\n- `*help` - Show all available commands with descriptions\n- `*draft` - Create next user story\n- `*story-checklist` - Run story draft checklist\n- `*guide` - Show comprehensive usage guide for this agent\n\n## Non-Negotiables\n- Follow `.aios-core/constitution.md`.\n- Execute workflows/tasks only from declared dependencies.\n- Do not invent requirements outside the project artifacts.\n"},"lastSynced":"2026-03-07T03:55:07.236Z","agentAnalysis":{"suitability":{"en":"Ideal for Agile-focused AI Agents requiring streamlined user story creation and sprint planning capabilities.","zh":"适合于需要简化用户故事创建和冲刺规划功能的敏捷焦点AI代理。","ja":"アジャイルに焦点を当てたAIエージェントがユーザーストーリーの作成とスプリント計画機能を簡素化するために最適です。","ko":"사용자 스토리 생성과 스프린트 계획 기능을 간소화해야 하는 애자일 중심 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA con enfoque en Agile que requieren la creación de historias de usuario simplificada y capacidades de planificación de sprint.","fr":"Idéal pour les agents d''IA axés sur Agile nécessitant une création de stories utilisateur simplifiée et des capacités de planification de sprint.","de":"Ideal für agil ausgerichtete KI-Agents, die eine vereinfachte Erstellung von Benutzerstories und Sprint-Planungsfunktionen erfordern.","pt":"Ideal para Agentes de IA focados em Agile que requerem criação de histórias de usuário e planejamento de sprint de forma otimizada.","ru":"Идеально подходит для агентов ИИ, ориентированных на Agile, требующих упрощенного создания пользовательских историй и планирования спринта.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يركز على Agile والذي يتطلب إنشاء قصة مستخدم وخطط السبرينت بشكل متدفق."},"recommendation":{"en":"Empowers agents to facilitate daily standup meetings, retrospectives, and backlog grooming using Markdown files and node scripts, while leveraging the .aios-core framework for comprehensive content analysis and validation.","zh":"赋予代理人使用Markdown文件和节点脚本进行每日站立会议、回顾和待办事项梳理的能力，同时利用.aios-core框架进行全面内容分析和验证。","ja":"Markdownファイルとノードスクリプトを使用して毎日の立ち上がり会議、回顧、バックログの整理を促進し、同時に.aios-coreフレームワークを使用して包括的なコンテンツ分析と検証を行うことができます。","ko":"매일立ち上がり 회의, 회고, 백로그 정리를 위한 Markdown 파일 및 노드 스크립트를 사용할 수 있도록 에이전트를 활성화하고, 동시에 .aios-core 프레임워크를 사용하여 포괄적인 콘텐츠 분석 및 검증을 수행합니다.","es":"Habilita a los agentes a facilitar reuniones diarias de standup, retrospectivas y poda de backlog utilizando archivos Markdown y scripts de node, mientras aprovecha el framework .aios-core para un análisis y validación de contenido integral.","fr":"Permet aux agents de faciliter les réunions quotidiennes de standup, les rétrospectives et l''élagage du backlog en utilisant des fichiers Markdown et des scripts de node, tout en exploitant le framework .aios-core pour une analyse et une validation de contenu complètes.","de":"Ermächtigt die Agents, tägliche Standup-Meetings, Retrospektiven und Backlog-Pflege mithilfe von Markdown-Dateien und Node-Skripten zu erleichtern, während es den .aios-core-Framework für eine umfassende Inhaltsanalyse und -validierung nutzt.","pt":"Habilita os agentes a facilitar reuniões diárias, retrospectivas e limpeza de backlog usando arquivos Markdown e scripts de node, aproveitando o framework .aios-core para análise e validação de conteúdo abrangente.","ru":"Позволяет агентам облегчить проведение ежедневных встреч, ретроспектив и уход за бэклогом, используя файлы Markdown и скрипты узла, а также использует фреймворк .aios-core для всестороннего анализа и проверки контента.","ar":"يمنح الوكلاء القدرة على تسهيل اجتماعات يومية ومراجعات وتنقية قائمة العمل باستخدام ملفات Markdown وبرامج نصية للعقد، مع الاستفادة من الإطار .aios-core لتحليل المحتوى والتأكد منه بشكل شامل."},"useCases":{"en":["Automating user story creation from PRD","Validating and refining acceptance criteria","Facilitating sprint planning and backlog grooming"],"zh":["从PRD自动创建用户故事","验证和完善接受标准","促进冲刺规划和待办事项梳理"],"ja":["PRDからユーザーストーリーを自動生成する","受け入れ基準を検証して精密化する","スプリント計画とバックログの整理を促進する"],"ko":["PRD로부터 사용자 스토리를 자동 생성","수락 기준을 검증하고 정제","스프린트 계획 및 백로그 정리를 지원"],"es":["Automatización de la creación de historias de usuario desde PRD","Validación y refinamiento de los criterios de aceptación","Facilitación de la planificación de sprint y la poda de backlog"],"fr":["Automatisation de la création d''histoires utilisateur à partir de PRD","Validation et raffinement des critères d''acceptation","Facilitation de la planification de sprint et de l''élagage du backlog"],"de":["Automatisierung der Erstellung von Benutzerstories aus PRD","Validierung und Verfeinerung der Akzeptanzkriterien","Erleichterung der Sprint-Planung und der Backlog-Pflege"],"pt":["Automating user story creation from PRD","Validando e refinando critérios de aceitação","Facilitating sprint planning and backlog grooming"],"ru":["Автоматизация создания пользовательских историй из PRD","Проверка и уточнение критериев приемки","Облегчение планирования спринта и ухода за бэклогом"],"ar":["تأتمة إنشاء قصة المستخدم من PRD","التحقق من صحة ومعايير القبول","تسهيل تخطيط السبرينت وتنقية قائمة العمل"]},"limitations":{"en":["Requires access to .aios-core/development/agents/sm.md or .codex/agents/sm.md","Node script execution necessary for greeting generation"],"zh":["需要访问.aios-core/development/agents/sm.md或.codex/agents/sm.md","节点脚本执行必要用于问候生成"],"ja":[".aios-core/development/agents/sm.mdまたは.codex/agents/sm.mdへのアクセスが必要","グリーティング生成のためにノードスクリプトの実行が必要"],"ko":[".aios-core/development/agents/sm.md 또는 .codex/agents/sm.md에 접근해야 함","인사말 생성을 위해 노드 스크립트 실행이 필요"],"es":["Requiere acceso a .aios-core/development/agents/sm.md o .codex/agents/sm.md","La ejecución de scripts de node es necesaria para la generación de saludos"],"fr":["Nécessite un accès à .aios-core/development/agents/sm.md ou .codex/agents/sm.md","L''exécution de scripts de node est nécessaire pour la génération de salutations"],"de":["Erfordert Zugriff auf .aios-core/development/agents/sm.md oder .codex/agents/sm.md","Die Ausführung von Node-Skripten ist für die Generierung von Begrüßungen erforderlich"],"pt":["Requer acesso a .aios-core/development/agents/sm.md ou .codex/agents/sm.md","Execução de script de node necessária para geração de saudação"],"ru":["Требуется доступ к .aios-core/development/agents/sm.md или .codex/agents/sm.md","Необходимо выполнение скрипта узла для генерации приветствия"],"ar":["يتطلب الوصول إلى .aios-core/development/agents/sm.md أو .codex/agents/sm.md","يتطلب تشغيل برنامج نصي للعقد لإنشاء تحية"]},"version":4},"contentHash":"f340516e649f508f4ed9fb832a1517f42955849f9b3dad760ad1fbcc1f3df382","qualityScore":38}');
