INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('automacoescomerciaisintegradas/xyzaios/aios-sm', 'aios-sm', 'automacoescomerciaisintegradas', 'xyzaios', 'community', 'aios-sm automacoescomerciaisintegradas xyzaios community aios-sm is a core framework for full-stack development, facilitating user story creation, validation, and sprint planning. It benefits developers and teams seeking to enhance their Agile workflow. AIOS SM是AI智能代理工具，用于Full Stack开发，提供用户故事创建、验证和完善等功能 AIOS SMはAIエージェントツールで、フルスタック開発に使用され、ユーザーストーリーの作成、検証、完善などを提供する AIOS SM은 Full Stack 개발을 위한 AI 에이전트 툴로, 사용자 스토리 생성, 검증 및 완善 등을 제공합니다 AIOS-SM es un agente de orquestación para full stack development que facilita la creación de historias de usuario, la validación y la planificación de sprint. AIOS-SM est un agent d''orchestration pour le développement full stack qui facilite la création d''histoires utilisateur, la validation et la planification de sprint. AIOS-SM ist ein KI-Orchestrierungsagent für Full-Stack-Entwicklung, der die Erstellung von Benutzerstories, die Validierung und die Sprintplanung erleichtert. O AIOS Scrum Master Activator é um framework de desenvolvimento full stack que ajuda a criar histórias de usuário, validar e refinar histórias. Saiba mais sobre como configurá-lo AIOS Scrum Master Activator - это фреймворк для полного стека разработки, который помогает создавать пользовательские истории, проверять и дорабатывать истории. Узнайте больше о его настройке AIOS Scrum Master Activator هو إطار عمل للتنمية الشاملة يساعد على إنشاء قصص المستخدم، التحقق والتحسين من القصص. تعلم المزيد عن كيفية إعدادها aios-sm setup guide how to use aios-sm aios-sm alternative aios-sm vs agile methodologies aios-sm install what is aios-sm aios-sm core framework aios-sm for full-stack development aios-sm scrum master activator AI智能代理工具 Full Stack开发 用户故事创建 故事验证 接受标准定义 AIOS SM集成 AIOS SM设置 AIOS SM功能 Activates AIOS Scrum Master Activator for user story creation and validation Loads `.aios-core/development/agents/sm.md` as the source of truth for agent persona and command system Generates greeting via `node .aios-core/development/scripts` for personalized interaction Facilitates sprint planning, backlog grooming, retrospectives, and daily standup meetings Supports story refinement and acceptance criteria definition for improved development clarity aios-sm is an AI-Orchestrated System for Full Stack Development, utilizing a core framework for streamlined development processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cacack/my-family/audit-domain', 'community', 'cacack', 'my-family', 'cacack/my-family', 'audit-domain', 0, 1, 38, '2026-02-28T22:51:39Z', '2026-03-07T03:55:49.025Z', 'd340e538cf1229fd79832abb4ef3bf2e1efb509be1fc5cd6e2f7c2ea341f27d7', '{"id":"cacack/my-family/audit-domain","name":"audit-domain","description":{"en":"audit-domain is a self-hosted genealogy software that combines GPS-compliant research with engaging storytelling, benefiting professional genealogists.","zh":"audit-domain是一种自托管的家谱软件，结合GPS-compliant研究和引人入胜的故事讲述。它提供了域模型审核和GEDCOM处理代码的评估","ja":"audit-domainは、GPS準拠の家系研究とエージェントのストーリーテリングを組み合わせた自ホスト型家系ソフトウェアです。ドメインモデルとGEDCOMハンドリングコードの評価を提供します","ko":"audit-domain은 GPS 준수 가계 연구 및 스토리 텔링을 결합한 자체 호스팅 가계 소프트웨어입니다. 도메인 모델 및 GEDCOM 처리 코드의 평가를 제공합니다","es":"audit-domain es una herramienta de agente de IA para genealogía que evalúa la corrección y el cumplimiento de estándares en modelos de dominio.","fr":"audit-domain est un outil d''agent IA pour la généalogie qui évalue la correction et le respect des normes dans les modèles de domaine.","de":"audit-domain ist ein KI-Tool für Genealogie, das die Richtigkeit und die Einhaltung von Standards in Domain-Modellen bewertet.","pt":"O audit-domain é uma ferramenta de genealogia que combina pesquisas compatíveis com GPS com narrativas atraentes, garantindo a correção e o cumprimento dos padrões genealógicos.","ru":"ИИ Агент audit-domain - это инструмент для генеалогии, который сочетает исследования, соответствующие GPS, с увлекательными историями, обеспечивая корректность и соответствие генеалогическим стандартам.","ar":"أداة الذكاء الاصطناعي audit-domain هي أداة للنسابية التي تجمع بين البحوث المتوافقة مع نظام التموضع العالمي مع قصص جذابة، مما يضمن الدقة والامتثال للمعايير النسابية."},"seo":{"title":{"en":"audit-domain: Genealogy Audit Setup Guide | AI Agent Skill","zh":"audit-domain Setup Guide: 基于GPS的家谱研究与故事讲述","ja":"audit-domain ベストプラクティス: GPS準拠の家系研究とエージェント","ko":"audit-domain 설정 가이드: GPS 준수 가계 연구 및 스토리 텔링","es":"Guía de Configuración de audit-domain: Herramientas de Ag...","fr":"Guide de Configuration de audit-domain: Outils d''Agent IA...","de":"Konfigurationsleitfaden für audit-domain: KI-Tools für Ge...","pt":"Guia de Configuração do audit-domain para Genealogia","ru":"Настройка ИИ Агента audit-domain для Генеалогии","ar":"إعداد أداة الذكاء الاصطناعي audit-domain للنسابية"},"description":{"en":"Discover how to evaluate genealogical correctness with audit-domain. Learn to read domain models and GEDCOM handling code for standards compliance.","zh":"了解audit-domain技能，用于自托管的家谱软件，结合GPS-compliant研究和引人入胜的故事讲述，提升您的家谱研究","ja":"audit-domainスキルを使用して、GPS準拠の家系研究とエージェントのストーリーテリングを組み合わせた自ホスト型家系ソフトウェアを実現します","ko":"audit-domain 스킬을 사용하여 GPS 준수 가계 연구 및 스토리 텔링을 결합한 자체 호스팅 가계 소프트웨어를 구축합니다","es":"Aprende a configurar audit-domain, una herramienta de agente de IA para genealogía que combina investigación GPS-compliant con narración atractiva.","fr":"Découvrez comment configurer audit-domain, un outil d''agent IA pour la généalogie qui combine recherche GPS-compliant avec narration engageante.","de":"Erfahren Sie, wie Sie audit-domain konfigurieren, ein KI-Tool für Genealogie, das GPS-kompatible Forschung mit ansprechender Erzählung kombiniert.","pt":"Aprenda a configurar o audit-domain para garantir a correção e o cumprimento dos padrões genealógicos em seu projeto","ru":"Узнайте, как настроить ИИ Агент audit-domain для обеспечения корректности и соответствия генеалогическим стандартам в вашем проекте","ar":"تعرف على كيفية إعداد أداة الذكاء الاصطناعي audit-domain لضمان الدقة والامتثال للمعايير النسابية في مشروعك"},"definition":{"en":"audit-domain is a genealogy audit tool that evaluates domain models for genealogical correctness and standards compliance.","zh":"audit-domain是一种用于审核域模型和GEDCOM处理代码的自托管家谱软件","ja":"audit-domainは、ドメインモデルとGEDCOMハンドリングコードを評価する自ホスト型家系ソフトウェアです","ko":"audit-domain은 도메인 모델 및 GEDCOM 처리 코드를 평가하는 자체 호스팅 가계 소프트웨어입니다","es":"¿Qué es audit-domain? Es una herramienta de agente de IA que audita modelos de dominio para genealogía.","fr":"Qu''est-ce que audit-domain ? C''est un outil d''agent IA qui audite les modèles de domaine pour la généalogie.","de":"Was ist audit-domain? Es ist ein KI-Tool, das Domain-Modelle für Genealogie auditiert.","pt":"O que é audit-domain? É uma ferramenta de genealogia que avalia a correção e o cumprimento dos padrões genealógicos em um projeto.","ru":"Что такое ИИ Агент audit-domain? Это инструмент для генеалогии, который оценивает корректность и соответствие генеалогическим стандартам в проекте.","ar":"ما هي أداة الذكاء الاصطناعي audit-domain؟ هي أداة للنسابية تقييم الدقة والامتثال للمعايير النسابية في مشروع."},"features":{"en":["Evaluates domain models against genealogical standards","Reads GEDCOM handling code for compliance","Loads context from ETHOS.md, ARCHITECTURAL-INVARIANTS.md, and INTEGRATION-MATRIX.md files","Supports genealogical research with GPS-compliant data","Engages users with storytelling capabilities"],"zh":["基于GPS的家谱研究","引人入胜的故事讲述","域模型审核","GEDCOM处理代码评估","自托管家谱软件"],"ja":["GPS準拠の家系研究","エージェントのストーリーテリング","ドメインモデル評価","GEDCOMハンドリングコードの評価","自ホスト型家系ソフトウェア"],"ko":["GPS 준수 가계 연구","스토리 텔링","도메인 모델 평가","GEDCOM 처리 코드 평가","자체 호스팅 가계 소프트웨어"],"es":["Carga de contexto con archivos ETHOS.md, ARCHITECTURAL-INVARIANTS.md e INTEGRATION-MATRIX.md","Evaluación de modelos de dominio contra estándares genealógicos","Análisis de GEDCOM para cumplimiento de estándares","Verificación de la corrección de la investigación GPS-compliant","Integración con entidades para garantizar la completitud","Compatibilidad con estándares de investigación genealógica"],"fr":["Chargement du contexte avec les fichiers ETHOS.md, ARCHITECTURAL-INVARIANTS.md et INTEGRATION-MATRIX.md","Évaluation des modèles de domaine contre les normes généalogiques","Analyse de GEDCOM pour le respect des normes","Vérification de la correction de la recherche GPS-compliant","Intégration avec des entités pour assurer la complétude","Compatibilité avec les normes de recherche généalogique"],"de":["Kontextladen mit Dateien ETHOS.md, ARCHITECTURAL-INVARIANTS.md und INTEGRATION-MATRIX.md","Bewertung von Domain-Modellen gegen Genealogie-Standards","Analyse von GEDCOM für Standard-Einhaltung","Überprüfung der Richtigkeit von GPS-kompatibler Forschung","Integration mit Entitäten für Vollständigkeit","Kompatibilität mit Genealogie-Forschungsstandards"],"pt":["Análise de modelo de domínio para genealogia","Verificação de compatibilidade com padrões genealógicos","Leitura de arquivos GEDCOM","Avaliação de entidades para completude","Integração com documentos de missão e diferenciadores"],"ru":["Анализ модели домена для генеалогии","Проверка соответствия генеалогическим стандартам","Чтение файлов GEDCOM","Оценка сущностей для полноты","Интеграция с документами миссии и дифференциаторами"],"ar":["تحليل نموذج المجال للنسابية","التحقق من التوافق مع المعايير النسابية","قراءة ملفات GEDCOM","تقييم الكيانات للكامل","التكامل مع وثائق المهمة والمميزات"]},"keywords":{"en":["how to use audit-domain","what is audit-domain","audit-domain alternative","audit-domain vs other genealogy tools","audit-domain install","audit-domain setup guide","genealogy audit software","GEDCOM handling code","GPS-compliant genealogy research"],"zh":["audit-domain","家谱软件","GPS-compliant","故事讲述","域模型审核","GEDCOM处理代码","自托管家谱软件","AIエージェント"],"ja":["audit-domain","家系ソフトウェア","GPS準拠","エージェント","ドメインモデル評価","GEDCOMハンドリングコード","自ホスト型家系ソフトウェア","AIエージェント"],"ko":["audit-domain","가계 소프트웨어","GPS 준수","스토리 텔링","도메인 모델 평가","GEDCOM 처리 코드","자체 호스팅 가계 소프트웨어","AI 에이전트"],"es":["herramientas de agente de IA para genealogía","configuración de audit-domain","investigación GPS-compliant","estándares genealógicos","GEDCOM","modelos de dominio","genealogía","agentes de IA","herramientas de genealogía"],"fr":["outils d''agent IA pour la généalogie","configuration de audit-domain","recherche GPS-compliant","normes généalogiques","GEDCOM","modèles de domaine","généalogie","agents IA","outils de généalogie"],"de":["KI-Tools für Genealogie","Konfiguration von audit-domain","GPS-kompatible Forschung","Genealogie-Standards","GEDCOM","Domain-Modelle","Genealogie","KI-Agenten","Genealogie-Tools"],"pt":["genealogia","audit-domain","gedcom","padrões genealógicos","modelo de domínio","desenvolvimento de software","ferramentas de genealogia","pesquisas genealógicas","correção de dados"],"ru":["генеалогия","ИИ Агент audit-domain","gedcom","генеалогические стандарты","модель домена","разработка программного обеспечения","инструменты генеалогии","генеалогические исследования","исправление данных"],"ar":["نسابية","أداة الذكاء الاصطناعي audit-domain","gedcom","معايير نسابية","نموذج المجال","تطوير البرمجيات","أدوات النسابية","البحوث النسابية","تصحيح البيانات"]}},"owner":"cacack","repo":"my-family","repoPath":"cacack/my-family","stars":0,"forks":1,"updatedAt":"2026-02-28T22:51:39Z","topics":[],"category":"community","skillMd":{"name":"audit-domain","description":"Domain audit — GPS compliance, person/relationship modeling, GEDCOM fidelity","bodyPreview":"# Domain / Genealogy Audit\n\nYou are a **Professional Genealogist** auditing the domain model for genealogical correctness and standards compliance.\n\n## What to Do\n\nRead the domain model and GEDCOM handling code, then evaluate against genealogical standards.\n\n### Step 1: Load Context\n\nRead these files:\n- `docs/ETHOS.md` — mission and differentiators\n- `docs/ARCHITECTURAL-INVARIANTS.md` — domain model invariants (DM-* and DI-*)\n- `docs/INTEGRATION-MATRIX.md` — entity completeness status\n\n### Step","body":"# Domain / Genealogy Audit\n\nYou are a **Professional Genealogist** auditing the domain model for genealogical correctness and standards compliance.\n\n## What to Do\n\nRead the domain model and GEDCOM handling code, then evaluate against genealogical standards.\n\n### Step 1: Load Context\n\nRead these files:\n- `docs/ETHOS.md` — mission and differentiators\n- `docs/ARCHITECTURAL-INVARIANTS.md` — domain model invariants (DM-* and DI-*)\n- `docs/INTEGRATION-MATRIX.md` — entity completeness status\n\n### Step 2: Analyze Person Model\n\nRead `internal/domain/` for person-related types:\n- Check name structure (given, surname, prefix, suffix, nickname support)\n- Check gender handling (enum values, extensibility)\n- Check if multiple name forms are supported (maiden, married, etc.)\n- Verify UUID-based identity (invariant DM-001)\n- Check for Validate() methods (invariant DM-002)\n\n### Step 3: Analyze Relationship Model\n\nRead family/relationship types in `internal/domain/`:\n- Check relationship typing (biological, adopted, step, foster)\n- Verify directional relationships are queryable\n- Look for edge case handling (unknown parentage, complex families)\n\n### Step 4: Analyze Date Handling\n\nSearch for date-related types:\n- Check for genealogical date types (exact, approximate, range, before/after, between)\n- Check for partial date support (year-only, month-year)\n- Look for calendar system considerations\n\n### Step 5: Analyze GEDCOM Handling\n\nRead `internal/gedcom/`:\n- Check import for data preservation (invariant DI-003 — lossless import)\n- Check export for valid GEDCOM output\n- Look for round-trip testing\n- Check edge case handling (Unicode, non-standard tags, large files)\n\n### Step 6: Analyze Citation/Source Model\n\nSearch for source/citation types:\n- Check if citations can attach to specific claims (not just people)\n- Look for source/repository/citation distinction\n- Evaluate against Evidence Explained patterns\n\n### Step 7: Check GPS Support\n\nEvaluate whether the data model supports the 5 GPS elements:\n1. Reasonably exhaustive search\n2. Complete citations\n3. Analysis and correlation\n4. Resolution of conflicts\n5. Soundly written conclusion\n\n## Output Format\n\n### Domain / Genealogy Audit Report\n\n#### Scorecard\n\n| Dimension | Score (0-5) | Notes |\n|-----------|-------------|-------|\n| GPS Support | | |\n| Person Model | | |\n| Relationship Model | | |\n| Date Handling | | |\n| Place Handling | | |\n| GEDCOM Fidelity | | |\n| Citation Model | | |\n\n#### Top Findings\n\nList up to 10 findings, risk-ranked. For each:\n- **Severity**: Critical / High / Medium / Low\n- **Category**: Which dimension\n- **Finding**: One-sentence summary\n- **Evidence**: Specific files, functions, line numbers\n- **Impact**: What breaks if unaddressed\n- **Suggestion**: Concrete fix\n\n#### Issue-Ready Tickets\n\nUp to 5 GitHub-issue-ready items with title, description, acceptance criteria, affected files.\n\n#### Manual Verification\n\nUp to 5 items requiring human judgment.\n"},"lastSynced":"2026-03-07T03:55:49.025Z","agentAnalysis":{"suitability":{"en":"Perfect for Genealogy Agents needing comprehensive domain model analysis and GEDCOM handling capabilities.","zh":"非常适合需要全面领域模型分析和 GEDCOM 处理能力的家谱代理","ja":"包括 GEDCOM 処理能力のある包括的なドメインモデル分析が必要な系図エージェントに最適","ko":"포괄적인 도메인 모델 분석 및 GEDCOM 처리 기능이 필요한 가계도 에이전트에 적합","es":"Perfecto para Agentes de Genealogía que necesitan un análisis de modelo de dominio integral y capacidades de manejo de GEDCOM.","fr":"Parfait pour les agents de généalogie qui ont besoin d''une analyse complète de modèle de domaine et de capacités de manipulation de GEDCOM.","de":"Perfekt für Genealogie-Agents, die eine umfassende Domänenmodellanalyse und GEDCOM-Handhabungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Genealogia que necessitam de análise abrangente do modelo de domínio e capacidades de manipulação do GEDCOM.","ru":"Идеально подходит для агентов генеалогии, которым требуется всесторонний анализ модели предметной области и возможности работы с GEDCOM.","ar":"مثالي للوكلاء الجينيولوجيين الذين يحتاجون إلى تحليل شاملة للنموذج المجال والقدرات التعامل مع GEDCOM."},"recommendation":{"en":"Empowers agents to evaluate domain models against genealogical standards, leveraging GPS-compliant research and GEDCOM handling code, and providing engaging storytelling capabilities through ETHOS-guided mission and differentiators.","zh":"赋予代理评估领域模型以符合家谱标准的能力，利用 GPS 兼容的研究和 GEDCOM 处理代码，并通过 ETHOS 指导的任务和区别提供吸引人的讲故事能力","ja":"エージェントが GPS 準拠の研究および GEDCOM 処理コードを活用して、系図の標準に従ったドメインモデルを評価する能力を付与し、ETHOS ガイドのミッションおよび違いを通じて魅力的なストーリーテリング機能を提供する","ko":"에이전트가 GPS 준수 연구 및 GEDCOM 처리 코드를 활용하여 가계도의 표준에 따라 도메인 모델을 평가할 수 있는 능력을 부여하고, ETHOS 가이드의 미션 및 차별점을 통해 매력적인 스토리텔링 기능을 제공","es":"Habilita a los agentes a evaluar modelos de dominio frente a estándares genealógicos, aprovechando la investigación compatible con GPS y el código de manejo de GEDCOM, y proporcionando capacidades de narración atractivas a través de la misión guiada por ETHOS y diferenciadores.","fr":"Permet aux agents d''évaluer les modèles de domaine par rapport aux normes généalogiques, en exploitant la recherche compatible GPS et le code de manipulation de GEDCOM, et en fournissant des capacités de narration engageantes grâce à la mission guidée par ETHOS et aux différenciateurs.","de":"Ermächtigt die Agenten, Domänenmodelle gegen genealogische Standards zu bewerten, indem sie GPS-konforme Forschung und GEDCOM-Handhabungscode nutzen und durch ETHOS-geleitete Mission und Differenzierungsmerkmale attraktive Erzählungsfähigkeiten bereitstellen.","pt":"Habilita os agentes a avaliar modelos de domínio contra padrões genealógicos, aproveitando a pesquisa compatível com GPS e o código de manipulação do GEDCOM, e fornecendo capacidades de contar histórias atraentes por meio da missão e dos diferenciais orientados por ETHOS.","ru":"Наделяет агентов возможностью оценивать модели предметной области по генеалогическим стандартам, используя исследование, соответствующее GPS, и код обработки GEDCOM, а также предоставляя возможности увлекательного рассказа через миссию и дифференциаторы, управляемые ETHOS.","ar":"تمكن الوكلاء من تقييم نماذج المجال مقابل المعايير الجينيولوجية، مستفيدا من البحث المتوافق مع نظام الملاحة العالمي و код التعامل مع GEDCOM، و تقديم قدرات سرديه جذابة من خلال المهمة و المميزات الموجهة بواسطة ETHOS."},"useCases":{"en":["Evaluating domain models for genealogical correctness","Analyzing GEDCOM handling code for standards compliance","Auditing entity completeness status using the INTEGRATION-MATRIX"],"zh":["评估领域模型的家谱正确性","分析 GEDCOM 处理代码的标准兼容性","使用 INTEGRATION-MATRIX 审计实体完整性状态"],"ja":["系図の正しさのためのドメインモデルの評価","GEDCOM 処理コードの標準準拠性の分析","INTEGRATION-MATRIX を使用したエンティティの完全性状態の監査"],"ko":["가계도의 정확성에 대한 도메인 모델의 평가","GEDCOM 처리 코드의 표준 준수성 분석","INTEGRATION-MATRIX를 사용한 엔티티 완전성 상태 감사"],"es":["Evaluar modelos de dominio para la corrección genealógica","Analizar el código de manejo de GEDCOM para la conformidad con los estándares","Auditar el estado de complejidad de la entidad utilizando la INTEGRATION-MATRIX"],"fr":["Évaluer les modèles de domaine pour la correction généalogique","Analyser le code de manipulation de GEDCOM pour la conformité aux normes","Auditer l''état de complétude de l''entité en utilisant la INTEGRATION-MATRIX"],"de":["Domänenmodelle für die genealogische Richtigkeit bewerten","GEDCOM-Handhabungscode für die Konformität mit den Standards analysieren","Den Vollständigkeitsstatus der Entität mithilfe der INTEGRATION-MATRIX auditen"],"pt":["Avaliar modelos de domínio para correção genealógica","Analisar código de manipulação do GEDCOM para conformidade com os padrões","Auditar status de completude da entidade usando a INTEGRATION-MATRIX"],"ru":["Оценка моделей предметной области на генеалогическую правильность","Анализ кода обработки GEDCOM на соответствие стандартам","Проверка статуса полноты сущности с помощью INTEGRATION-MATRIX"],"ar":["تقييم نماذج المجال لصحة الجينيولوجية","تحليل код التعامل مع GEDCOM لامتثالية للمعايير","مراجعة حالة اكتمال الكيانات باستخدام INTEGRATION-MATRIX"]},"limitations":{"en":["Requires access to domain model documentation (e.g., ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md)","Specific to genealogy domain, may not be applicable to other domains"],"zh":["需要访问领域模型文档（例如 ETHOS.md、ARCHITECTURAL-INVARIANTS.md、INTEGRATION-MATRIX.md）","仅限于家谱领域，可能不适用于其他领域"],"ja":["ドメインモデル文書（例：ETHOS.md、ARCHITECTURAL-INVARIANTS.md、INTEGRATION-MATRIX.md）へのアクセスが必要","系図ドメインに特有であり、他のドメインに適用できない可能性がある"],"ko":["도메인 모델 문서（예：ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md）에 대한 접근이 필요","가계도 도메인에 특화되어 있어 다른 도메인에 적용할 수 없는 가능성이 있음"],"es":["Requiere acceso a la documentación del modelo de dominio (p. ej., ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md)","Específico del dominio de la genealogía, puede que no sea aplicable a otros dominios"],"fr":["Nécessite un accès à la documentation du modèle de domaine (par exemple, ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md)","Spécifique au domaine de la généalogie, peut ne pas être applicable à d''autres domaines"],"de":["Erfordert Zugriff auf die Dokumentation des Domänenmodells (z. B. ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md)","Spezifisch für den Bereich der Genealogie, möglicherweise nicht auf andere Bereiche anwendbar"],"pt":["Requer acesso à documentação do modelo de domínio (por exemplo, ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md)","Específico para o domínio da genealogia, pode não ser aplicável a outros domínios"],"ru":["Требует доступа к документации модели предметной области (например, ETHOS.md, ARCHITECTURAL-INVARIANTS.md, INTEGRATION-MATRIX.md)","Специфично для области генеалогии, может не быть применимым для других областей"],"ar":["يتطلب الوصول إلى توثيق نموذج المجال (على سبيل المثال، ETHOS.md، ARCHITECTURAL-INVARIANTS.md، INTEGRATION-MATRIX.md)","محدد لمنطقة الجينيولوجيا، قد لا يتم تطبيقها على مجالات أخرى"]},"version":4},"contentHash":"d340e538cf1229fd79832abb4ef3bf2e1efb509be1fc5cd6e2f7c2ea341f27d7","qualityScore":38}');
