INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cacack/my-family/audit-domain', 'audit-domain', 'cacack', 'my-family', 'community', 'audit-domain cacack my-family community audit-domain is a self-hosted genealogy software that combines GPS-compliant research with engaging storytelling, benefiting professional genealogists. audit-domain是一种自托管的家谱软件，结合GPS-compliant研究和引人入胜的故事讲述。它提供了域模型审核和GEDCOM处理代码的评估 audit-domainは、GPS準拠の家系研究とエージェントのストーリーテリングを組み合わせた自ホスト型家系ソフトウェアです。ドメインモデルとGEDCOMハンドリングコードの評価を提供します audit-domain은 GPS 준수 가계 연구 및 스토리 텔링을 결합한 자체 호스팅 가계 소프트웨어입니다. 도메인 모델 및 GEDCOM 처리 코드의 평가를 제공합니다 audit-domain es una herramienta de agente de IA para genealogía que evalúa la corrección y el cumplimiento de estándares en modelos de dominio. audit-domain est un outil d''agent IA pour la généalogie qui évalue la correction et le respect des normes dans les modèles de domaine. audit-domain ist ein KI-Tool für Genealogie, das die Richtigkeit und die Einhaltung von Standards in Domain-Modellen bewertet. O audit-domain é uma ferramenta de genealogia que combina pesquisas compatíveis com GPS com narrativas atraentes, garantindo a correção e o cumprimento dos padrões genealógicos. ИИ Агент audit-domain - это инструмент для генеалогии, который сочетает исследования, соответствующие GPS, с увлекательными историями, обеспечивая корректность и соответствие генеалогическим стандартам. أداة الذكاء الاصطناعي audit-domain هي أداة للنسابية التي تجمع بين البحوث المتوافقة مع نظام التموضع العالمي مع قصص جذابة، مما يضمن الدقة والامتثال للمعايير النسابية. how to use audit-domain what is audit-domain audit-domain alternative audit-domain vs other genealogy tools audit-domain install audit-domain setup guide genealogy audit software GEDCOM handling code GPS-compliant genealogy research audit-domain 家谱软件 GPS-compliant 故事讲述 域模型审核 GEDCOM处理代码 自托管家谱软件 AIエージェント Evaluates domain models against genealogical standards Reads GEDCOM handling code for compliance Loads context from ETHOS.md, ARCHITECTURAL-INVARIANTS.md, and INTEGRATION-MATRIX.md files Supports genealogical research with GPS-compliant data Engages users with storytelling capabilities audit-domain is a genealogy audit tool that evaluates domain models for genealogical correctness and standards compliance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('takayatomose/tas-agent-skills/c', 'community', 'takayatomose', 'tas-agent-skills', 'takayatomose/tas-agent-skills', 'c', 0, 0, 38, '2026-03-05T07:07:30Z', '2026-03-07T04:01:38.209Z', '9ee7a7c45ca17202ad69a120b3d6c214d00a9b14315cd11f002784895949df1d', '{"id":"takayatomose/tas-agent-skills/c","name":"c","description":{"en":"The C skill enables developers to build safe and performant systems using procedural Clean Architecture, with a focus on modular design and memory safety. This skill benefits systems developers and architects.","zh":"C语言系统开发专家，构建安全、模块化和高性能的系统。","ja":"C言語システム開発の専門家が、高性能で安全なシステムを構築する。","ko":"C 시스템 개발 전문가가 안전하고 모듈식이며 고성능의 시스템을 구축합니다.","es":"Desarrolla sistemas seguros y modulares con C, utilizando una arquitectura limpia y procedural","fr":"Développez des systèmes sécurisés et modulaires avec C, en utilisant une architecture propre et procédurale","de":"Entwickeln Sie sichere und modulare Systeme mit C, indem Sie eine saubere und prozedurale Architektur verwenden","pt":"O Skill C Systems Development é especializado em construir sistemas C seguros, modulares e performáticos","ru":"Навык C Systems Development специализируется на создании безопасных, модульных и производительных систем C","ar":"مهارة تطوير أنظمة سي تختص ببناء أنظمة سي آمنة ومدولة وأداء"},"seo":{"title":{"en":"C: Procedural Clean Architecture Setup Guide | AI Agent S...","zh":"C语言系统开发最佳实践指南","ja":"C言語システム開発セットアップガイド - AIエージェント","ko":"C 시스템 개발 가이드 - 최고의 성능과 보안을 위한 팁","es":"Guía de configuración de C para desarrolladores","fr":"Guide de démarrage rapide pour le développement de systèm...","de":"C-Systems-Entwicklung: Leitfaden für eine sichere und per...","pt":"Desenvolvimento de Sistemas C: Guia de Configuração","ru":"ИИ Агенты для C: Руководство по Настройке","ar":"تطوير أنظمة سي: دليل الإعداد"},"description":{"en":"Unlock the power of C with our expert AI agent skill, featuring modular architecture and memory safety best practices - learn how to get started today!","zh":"了解C语言系统开发的专业知识，包括模块化架构、内存安全和错误处理。","ja":"C言語システム開発の専門知識を学び、モジュラーなアーキテクチャ、メモリ安全性、エラーハンドリングについて発見する。","ko":"C 시스템 개발의 전문 지식을 배우고, 모듈식 아키텍처, 메모리 안전성, 오류 처리에 대해 알아보세요.","es":"Aprende a desarrollar sistemas seguros y modulares con C, aprovechando al máximo las características de Clean Architecture y programación procedural","fr":"Découvrez comment développer des systèmes sécurisés et modulaires avec C, en exploitant les avantages de l''architecture Clean et de la programmation procédurale","de":"Erfahren Sie, wie Sie sichere und modulare Systeme mit C entwickeln können, indem Sie die Vorteile von Clean Architecture und prozeduraler Programmierung nutzen","pt":"Aprenda a construir sistemas C seguros, modulares e performáticos com foco em arquitetura limpa procedural","ru":"Изучите, как создавать безопасные, модульные и производительные системы C с фокусом на процедурной чистой архитектуре","ar":"تعلم كيفية بناء أنظمة سي آمنة ومدولة وأداء مع التركيز على هندسة إجرائية نظيفة"},"definition":{"en":"C is a skill for building safe, modular, and performant systems using the C programming language, with a focus on procedural Clean Architecture and strict ownership rules.","zh":"C语言系统开发是一种使用C语言构建安全、模块化和高性能系统的方法。","ja":"C言語システム開発は、C言語を使用して安全でモジュラーで高性能なシステムを構築する方法です。","ko":"C 시스템 개발은 C 언어를 사용하여 안전하고 모듈식이며 고성능의 시스템을 구축하는 방법입니다.","es":"C es un lenguaje de programación que permite desarrollar sistemas seguros y modulares con una arquitectura limpia","fr":"C est un langage de programmation qui permet de développer des systèmes sécurisés et modulaires avec une architecture propre","de":"C ist eine Programmiersprache, die die Entwicklung sicherer und modulare Systeme mit einer sauberen Architektur ermöglicht","pt":"O que é C Systems Development? É uma expertise em construir sistemas C com foco em modularidade e segurança","ru":"Что такое C Systems Development? Это экспертиза в создании систем C с фокусом на модульности и безопасности","ar":"ما هي تطوير أنظمة سي؟ هي خبرة في بناء أنظمة سي مع التركيز على المودولية والأمان"},"features":{"en":["Implements modular architecture using opaque pointers and header encapsulation","Ensures memory safety with strict ownership rules and buffer safety protocols","Supports clear layering for scalable and maintainable systems","Enforces error handling best practices using C idioms and rules","Utilizes procedural Clean Architecture for robust and efficient systems development"],"zh":["模块化架构","内存安全性","错误处理","清晰的层次结构","严格的所有权规则","缓冲区安全性"],"ja":["モジュラーなアーキテクチャ","メモリ安全性","エラーハンドリング","明確な階層構造","厳格な所有権ルール","バッファ安全性"],"ko":["모듈식 아키텍처","메모리 안전성","오류 처리","명확한 계층 구조","엄격한 소유권 규칙","버퍼 안전성"],"es":["Arquitectura modular con punteros opacos y encapsulación de cabeceras","Seguridad de memoria con reglas estrictas de propiedad y seguridad de búfer","Clean Architecture para una arquitectura limpia y mantenible","Programación procedural para una mayor eficiencia y legibilidad","Error Handling para una gestión eficaz de errores","C Idioms para una programación más eficiente y segura"],"fr":["Architecture modulaire avec des pointeurs opaques et une encapsulation d''en-tête","Sécurité de la mémoire avec des règles strictes de propriété et de sécurité des tampons","Clean Architecture pour une architecture propre et maintenable","Programmation procédurale pour une plus grande efficacité et lisibilité","Gestion des erreurs pour une gestion efficace des erreurs","C Idioms pour une programmation plus efficace et sécurisée"],"de":["Modulare Architektur mit undurchsichtigen Zeigern und Header-Encapsulation","Speichersicherheit mit strengen Eigentumsregeln und Puffer-Sicherheit","Clean Architecture für eine saubere und wartbare Architektur","Prozedurale Programmierung für eine höhere Effizienz und Lesbarkeit","Fehlerbehandlung für eine effektive Fehlerbehandlung","C-Idiome für eine effizientere und sicherere Programmierung"],"pt":["Arquitetura Modular com ponteiros opacos e encapsulamento de cabeçalhos","Segurança de Memória com regras de propriedade estritas e segurança de buffer","Implementação de Idiomas C com foco em HIGH impact","Tratamento de Erros com prioridade MEDIUM","Desenvolvimento de sistemas C com foco em procedimentos limpos"],"ru":["Модульная Архитектура с не透рачными указателями и инкапсуляцией заголовков","Безопасность Памяти с строгими правилами собственности и безопасностью буфера","Реализация Идиом C с фокусом на HIGH воздействие","Обработка Ошибок с приоритетом MEDIUM","Разработка систем C с фокусом на чистых процедурах"],"ar":["هندسة مودULAR مع مؤشرات غير شفافة وتغليف رأس","أمان الذاكرة بقواعد ملكية صارمة وأمان حزمة","تنفيذ لغات سي مع التركيز على HIGH التأثير","معالجة الأخطاء مع أولوية MEDIUM","تطوير أنظمة سي مع التركيز على الإجراءات النظيفة"]},"keywords":{"en":["how to use C for systems development","C programming language best practices","procedural Clean Architecture tutorial","C vs C++ for systems programming","C install guide for Linux","C setup guide for Windows","modular architecture in C","memory safety in C","C error handling techniques"],"zh":["C语言系统开发","模块化架构","内存安全性","错误处理","C语言编程","系统开发最佳实践","AI工具","C语言开发指南"],"ja":["C言語システム開発","モジュラーなアーキテクチャ","メモリ安全性","エラーハンドリング","C言語プログラミング","システム開発ベストプラクティス","AIエージェント","C言語開発ガイド"],"ko":["C 시스템 개발","모듈식 아키텍처","메모리 안전성","오류 처리","C 언어 프로그래밍","시스템 개발 가이드","AI 에이전트","C 언어 개발 팁"],"es":["desarrollo de sistemas C","arquitectura limpia","programación procedural","seguridad de memoria","error handling","C Idioms","punteros opacos","encapsulación de cabeceras","Clean Architecture"],"fr":["développement de systèmes C","architecture propre","programmation procédurale","sécurité de la mémoire","gestion des erreurs","C Idioms","pointeurs opaques","encapsulation d''en-tête","Clean Architecture"],"de":["C-Systems-Entwicklung","saubere Architektur","prozedurale Programmierung","Speichersicherheit","Fehlerbehandlung","C-Idiome","undurchsichtige Zeiger","Header-Encapsulation","Clean Architecture"],"pt":["desenvolvimento de sistemas c","arquitetura modular c","segurança de memória c","idiomas c","tratamento de erros c","procedimentos limpos c","c systems development","clean architecture c"],"ru":["разработка систем c","модульная архитектура c","безопасность памяти c","идиомы c","обработка ошибок c","чистые процедуры c","c systems development","чистая архитектура c"],"ar":["تطوير أنظمة سي","هندسة مودULAR سي","أمان الذاكرة سي","لغات سي","معالجة الأخطاء سي","إجراءات نظيفة سي","c systems development","هندسة نظيفة سي"]}},"owner":"takayatomose","repo":"tas-agent-skills","repoPath":"takayatomose/tas-agent-skills","stars":0,"forks":0,"updatedAt":"2026-03-05T07:07:30Z","topics":[],"category":"community","skillMd":{"name":"c","description":"Expert in procedural Clean Architecture, memory safety, and modular C development.","bodyPreview":"# Skill: C Systems Development\n\n## Overview\n\nExpert in building safe, modular, and performant systems using C with a focus on procedural Clean Architecture.\n\n## Rule Categories\n\n| Priority | Category | Impact |\n| :--- | :--- | :--- |\n| 1 | [C Idioms](rules/idioms.md) | HIGH |\n| 2 | [Error Handling](rules/errors.md) | MEDIUM |\n\n## Core Expertise\n\n- **Modular Architecture**: Opaque pointers, header encapsulation, and clear layering.\n- **Memory Safety**: Strict ownership rules, buffer safety, and m","body":"# Skill: C Systems Development\n\n## Overview\n\nExpert in building safe, modular, and performant systems using C with a focus on procedural Clean Architecture.\n\n## Rule Categories\n\n| Priority | Category | Impact |\n| :--- | :--- | :--- |\n| 1 | [C Idioms](rules/idioms.md) | HIGH |\n| 2 | [Error Handling](rules/errors.md) | MEDIUM |\n\n## Core Expertise\n\n- **Modular Architecture**: Opaque pointers, header encapsulation, and clear layering.\n- **Memory Safety**: Strict ownership rules, buffer safety, and mandatory NULL checks.\n- **Procedural Patterns**: Struct-based \"methods\" and explicit return codes.\n\n## Instructions for the Agent\n\n- **Consult Internal Rules**: Always refer to the `rules/` directory within this skill for C-specific idioms and error codes.\n- **Modularize**: Use headers to define interfaces and source files for private implementations.\n- **Buffer Safety**: Strictly avoid unsafe string/buffer functions; use length-bounded alternatives.\n"},"lastSynced":"2026-03-07T04:01:38.209Z","agentAnalysis":{"suitability":{"en":"Ideal for Systems Agents requiring high-performance and memory-safe coding practices with C","zh":"适合需要高性能和内存安全编码实践的C系统代理","ja":"Cを使用した高性能かつメモリセーフなコーディング慣行を必要とするシステムエージェントに最適","ko":"고성능과 메모리 안전 코딩 관행이 필요한 C 시스템 에이전트에 적합","es":"Ideal para Agentes de Sistemas que requieren prácticas de codificación de alto rendimiento y seguras en memoria con C","fr":"Idéal pour les agents de systèmes nécessitant des pratiques de codage hautes performances et sécurisées en mémoire avec C","de":"Ideal für Systemagenten, die hochleistungs- und speichersichere Codierungspraktiken mit C erfordern","pt":"Ideal para Agentes de Sistemas que requerem práticas de codificação de alto desempenho e seguras em termos de memória com C","ru":"Идеально для системных агентов, требующих высокопроизводительных и безопасных в плане памяти практик программирования на C","ar":"مثالي لعميل النظام الذي يتطلب ممارسات برمجة ذاكرة آمنة وعالي الأداء مع C"},"recommendation":{"en":"Empowers agents to build safe and modular systems using procedural Clean Architecture, with a focus on modular design, memory safety, and strict ownership rules, leveraging C idioms and error handling mechanisms","zh":"赋予代理构建安全和模块化系统的能力，使用面向过程的Clean Architecture，注重模块化设计、内存安全和严格的所有权规则，利用C惯用语和错误处理机制","ja":"エージェントがモジュラーで安全なシステムを構築できるようにし、手続き型のClean Architectureを使用し、モジュラー設計、メモリセーフティ、厳格な所有権ルールに焦点を当て、Cの慣用句とエラーハンドリングメカニズムを利用する","ko":"에이전트가 안전하고 모듈화된 시스템을 구축할 수 있도록 하며, thủ tục형 Clean Architecture를 사용하여 모듈화 설계, 메모리 안전 및 엄격한 소유권 규칙에 중점을 두고 C 관용구 및 오류 처리 메커니즘을 활용","es":"Permite a los agentes crear sistemas seguros y modulares utilizando arquitectura Clean procedimental, con un enfoque en diseño modular, seguridad de memoria y reglas estrictas de propiedad, aprovechando los modos de C y los mecanismos de manejo de errores","fr":"Permet aux agents de créer des systèmes sûrs et modulaires en utilisant une architecture Clean procédurale, avec un focus sur la conception modulaire, la sécurité de la mémoire et les règles de propriété strictes, en exploitant les idiomes C et les mécanismes de gestion d''erreurs","de":"Ermöglicht es Agenten, sichere und modulare Systeme mit Hilfe von prozeduralem Clean Architecture zu erstellen, mit Fokus auf modulares Design, Speichersicherheit und strenge Eigentumsregeln, unter Ausnutzung von C-Idiomen und Fehlerbehandlungsmechanismen","pt":"Habilita agentes a construir sistemas seguros e modulares usando arquitetura limpa procedural, com foco em design modular, segurança de memória e regras de propriedade estritas, aproveitando idiomas C e mecanismos de tratamento de erros","ru":"Наделяет агентов возможностью создавать безопасные и модульные системы с помощью процедурной чистой архитектуры, с фокусом на модульном дизайне, безопасности памяти и строгих правилах владения, используя идиомы C и механизмы обработки ошибок","ar":"تمكين الوكلاء من بناء أنظمة آمنة ومتواصلة باستخدام هندسة معمارية نظيفة إجرائية، مع التركيز على التصميم المتناسق، وأمان الذاكرة، وقواعد الملكية الصارمة، واستخدام أidioms C وآليات معالجة الأخطاء"},"useCases":{"en":["Developing secure and performant embedded systems","Implementing modular architecture with opaque pointers and header encapsulation","Ensuring memory safety with buffer safety and strict ownership rules"],"zh":["开发安全高效的嵌入式系统","实现模块化架构，使用不透明指针和头文件封装","确保内存安全，使用缓冲区安全和严格的所有权规则"],"ja":["セキュアで高性能な組み込みシステムの開発","モジュラーなアーキテクチャの実装、不透明なポインタとヘッダーエンキャプセレーションを使用","メモリセーフティの確保、バッファーセーフティと厳格な所有権ルールを使用"],"ko":["보안 및 성능이 뛰어난 임베디드 시스템 개발","모듈화된 아키텍처 구현, 불투명한 포인터 및 헤더封装 사용","메모리 안전 보장, 버퍼 안전 및 엄격한 소유권 규칙 사용"],"es":["Desarrollar sistemas integrados seguros y de alto rendimiento","Implementar arquitectura modular con punteros opacos y encapsulación de encabezados","Garantizar la seguridad de la memoria con seguridad de búfer y reglas estrictas de propiedad"],"fr":["Développer des systèmes intégrés sécurisés et performants","Mettre en œuvre une architecture modulaire avec des pointeurs opaques et une encapsulation d''en-tête","Assurer la sécurité de la mémoire avec la sécurité du tampon et les règles de propriété strictes"],"de":["Entwicklung sicherer und leistungsfähiger eingebetteter Systeme","Implementierung modularer Architektur mit undurchsichtigen Zeigern und Header-Kapselung","Gewährleistung der Speichersicherheit mit Puffer-Sicherheit und strengen Eigentumsregeln"],"pt":["Desenvolver sistemas incorporados seguros e de alto desempenho","Implementar arquitetura modular com ponteiros opacos e encapsulamento de cabeçalho","Garantir segurança de memória com segurança de buffer e regras de propriedade estritas"],"ru":["Разработка безопасных и высокопроизводительных встроенных систем","Реализация модульной архитектуры с непрозрачными указателями и инкапсуляцией заголовков","Обеспечение безопасности памяти с помощью защиты буфера и строгих правил владения"],"ar":["تطوير أنظمة مدمجة آمنة وذات أداء عال","تنفيذ هندسة معمارية متواصلة مع منazers opacos وencapsulamento من رأس","ضمان أمان الذاكرة مع أمان buffer وقواعد ملكية صارمة"]},"limitations":{"en":["Requires proficiency in C programming language","Focus on procedural Clean Architecture may limit applicability to object-oriented systems"],"zh":["需要C编程语言的专业知识","注重面向过程的Clean Architecture可能会限制其应用于面向对象的系统"],"ja":["Cプログラミング言語の熟練度が必要","手続き型のClean Architectureに焦点を当てているため、オブジェクト指向のシステムへの適用性が制限される可能性がある"],"ko":["C 프로그래밍 언어의 熟練度가 필요"," thủ tục형 Clean Architecture에 중점을 둔ため, 객체지향 시스템への 적용성 제한될 수 있음"],"es":["Requiere conocimientos en el lenguaje de programación C","El enfoque en la arquitectura Clean procedimental puede limitar la aplicabilidad a sistemas orientados a objetos"],"fr":["Nécessite une maîtrise du langage de programmation C","L''accent mis sur l''architecture Clean procédurale peut limiter l''applicabilité aux systèmes orientés objet"],"de":["Erfordert Kenntnisse in der Programmiersprache C","Der Fokus auf prozedurale Clean-Architecture kann die Anwendbarkeit auf objektorientierte Systeme einschränken"],"pt":["Requer proficiência na linguagem de programação C","O foco na arquitetura limpa procedural pode limitar a aplicabilidade a sistemas orientados a objetos"],"ru":["Требует профессионализма в языке программирования C","Фокус на процедурной чистой архитектуре может ограничить применимость к объектно-ориентированным системам"],"ar":["يتطلب إجادة في لغة البرمجة C","التركيز على هندسة معمارية نظيفة إجرائية قد يحد من التطبيق إلى أنظمة متوجهة إلى الكائنات"]},"version":4},"contentHash":"9ee7a7c45ca17202ad69a120b3d6c214d00a9b14315cd11f002784895949df1d","qualityScore":38}');
