INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('takayatomose/tas-agent-skills/c', 'c', 'takayatomose', 'tas-agent-skills', 'community', 'c takayatomose tas-agent-skills community The C skill enables developers to build safe and performant systems using procedural Clean Architecture, with a focus on modular design and memory safety. This skill benefits systems developers and architects. C语言系统开发专家，构建安全、模块化和高性能的系统。 C言語システム開発の専門家が、高性能で安全なシステムを構築する。 C 시스템 개발 전문가가 안전하고 모듈식이며 고성능의 시스템을 구축합니다. Desarrolla sistemas seguros y modulares con C, utilizando una arquitectura limpia y procedural Développez des systèmes sécurisés et modulaires avec C, en utilisant une architecture propre et procédurale Entwickeln Sie sichere und modulare Systeme mit C, indem Sie eine saubere und prozedurale Architektur verwenden O Skill C Systems Development é especializado em construir sistemas C seguros, modulares e performáticos Навык C Systems Development специализируется на создании безопасных, модульных и производительных систем C مهارة تطوير أنظمة سي تختص ببناء أنظمة سي آمنة ومدولة وأداء how to use C for systems development C programming language best practices procedural Clean Architecture tutorial C vs C++ for systems programming C install guide for Linux C setup guide for Windows modular architecture in C memory safety in C C error handling techniques C语言系统开发 模块化架构 内存安全性 错误处理 C语言编程 系统开发最佳实践 AI工具 C语言开发指南 Implements modular architecture using opaque pointers and header encapsulation Ensures memory safety with strict ownership rules and buffer safety protocols Supports clear layering for scalable and maintainable systems Enforces error handling best practices using C idioms and rules Utilizes procedural Clean Architecture for robust and efficient systems development C is a skill for building safe, modular, and performant systems using the C programming language, with a focus on procedural Clean Architecture and strict ownership rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Senury/senury-website/frontend-responsive', 'community', 'Senury', 'senury-website', 'Senury/senury-website', 'frontend-responsive', 0, 0, 38, '2026-03-01T15:30:40Z', '2026-03-07T04:06:48.446Z', 'debe4598217dfd3be8bc0f040d8159db8cd327606ad620c4c1da4e378181267a', '{"id":"Senury/senury-website/frontend-responsive","name":"frontend-responsive","description":{"en":"The frontend-responsive skill provides guidance on coding standards for handling responsive frontend development, benefiting developers working with React, CSS Grid, and Tailwind CSS.","zh":"前端响应式设计 Skill 提供了使用 React、CSS Grid 和 Tailwind CSS 实现响应式布局的指导。","ja":"フロントエンドレスポンシブ Skill は、React、CSS Grid、Flexbox、Tailwind CSS を使用してレスポンシブなレイアウトを実現するためのガイダンスを提供します。","ko":"프론트엔드 반응형 Skill은 React, CSS Grid, Flexbox, Tailwind CSS를 사용하여 반응형 레이아웃을 구현하는 방법에 대한 지침을 제공합니다.","es":"El skill de frontend responsive proporciona orientación para implementar diseños responsivos con tecnologías como React y CSS. Aprende a crear componentes responsivos con Tailwind CSS y patrones de diseño para dispositivos móviles.","fr":"Le skill de frontend responsive fournit des conseils pour mettre en place des conceptions responsives avec des technologies comme React et CSS. Découvrez comment créer des composants responsifs avec Tailwind CSS et des modèles de conception pour les appareils mobiles.","de":"Das frontend-responsive-Skill bietet Anleitungen zur Umsetzung responsiver Designs mit Technologien wie React und CSS. Erfahren Sie, wie Sie responsives Design mit Tailwind CSS und Entwurfsmustern für mobile Geräte erstellen können.","pt":"O Frontend Responsivo é uma habilidade que fornece orientação para criar layouts responsivos com React e CSS","ru":"Отзывчивый Frontend - это навык, который предоставляет руководство по созданию отзывчивых макетов с React и CSS","ar":"الواجهة الأمامية ا