INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Senury/senury-website/frontend-responsive', 'frontend-responsive', 'Senury', 'senury-website', 'community', 'frontend-responsive Senury senury-website community The frontend-responsive skill provides guidance on coding standards for handling responsive frontend development, benefiting developers working with React, CSS Grid, and Tailwind CSS. 前端响应式设计 Skill 提供了使用 React、CSS Grid 和 Tailwind CSS 实现响应式布局的指导。 フロントエンドレスポンシブ Skill は、React、CSS Grid、Flexbox、Tailwind CSS を使用してレスポンシブなレイアウトを実現するためのガイダンスを提供します。 프론트엔드 반응형 Skill은 React, CSS Grid, Flexbox, Tailwind CSS를 사용하여 반응형 레이아웃을 구현하는 방법에 대한 지침을 제공합니다. El skill de frontend responsive proporciona orientación para implementar diseños responsivos con tecnologías como React y CSS. Aprende a crear componentes responsivos con Tailwind CSS y patrones de diseño para dispositivos móviles. Le skill de frontend responsive fournit des conseils pour mettre en place des conceptions responsives avec des technologies comme React et CSS. Découvrez comment créer des composants responsifs avec Tailwind CSS et des modèles de conception pour les appareils mobiles. Das frontend-responsive-Skill bietet Anleitungen zur Umsetzung responsiver Designs mit Technologien wie React und CSS. Erfahren Sie, wie Sie responsives Design mit Tailwind CSS und Entwurfsmustern für mobile Geräte erstellen können. O Frontend Responsivo é uma habilidade que fornece orientação para criar layouts responsivos com React e CSS Отзывчивый Frontend - это навык, который предоставляет руководство по созданию отзывчивых макетов с React и CSS الواجهة الأمامية المتجاوبة هي مهارة توفر إرشادات لإنشاء تصاميم متجاوبة مع React و CSS how to use frontend-responsive frontend-responsive setup guide responsive frontend development best practices Tailwind CSS utility classes tutorial mobile-first design patterns examples frontend-responsive vs responsive web design install frontend-responsive frontend-responsive alternative 前端响应式设计 React响应式 CSS Grid响应式 Tailwind CSS响应式 移动优先设计 导航菜单实现 AIエージェント 前端开发 Provides guidance on creating responsive layouts using CSS Grid and Flexbox Supports implementation of mobile-first design patterns Generates responsive utility classes using Tailwind CSS (sm:, md:, lg:, xl:, 2xl:) Optimizes React components in .tsx or .jsx files for responsive design Enhances navigation menu development for responsive interfaces frontend-responsive is a set of guidelines for developing responsive and mobile-first interfaces using React, CSS Grid, Flexbox, and Tailwind CSS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lucasmartinsr/barber-go/aios-analyst', 'community', 'lucasmartinsr', 'barber-go', 'lucasmartinsr/barber-go', 'aios-analyst', 0, 0, 38, '2026-03-05T11:59:49Z', '2026-03-07T04:18:31.259Z', '7393efc370b264c83fe201db8cc66a6a71ba72895ddedd05205e0ddc87a7c4b9', '{"id":"lucasmartinsr/barber-go/aios-analyst","name":"aios-analyst","description":{"en":"The aios-analyst skill facilitates market research, competitive analysis, and user research, benefiting business analysts and project managers. It enables structured ideation workshops and project discovery.","zh":"AIOS Analyst 是一个用于业务分析和市场研究的工具，支持用户研究、竞争对手分析和行业趋势分析","ja":"AIOS Analyst はビジネス分析と市場調査に使用されるツールで、ユーザー調査、競合分析、業界動向分析をサポート","ko":"AIOS Analyst는 비즈니스 분석 및 시장 연구에 사용되는 도구로 사용자 연구, 경쟁 분석 및 산업 동향 분석을 지원합니다","es":"El agente AIOS Analyst es una herramienta para investigación de mercado y análisis competitivo que utiliza Node.js para mejorar la eficiencia","fr":"L''agent AIOS Analyst est un outil pour l''analyse de marché et concurrentielle qui utilise Node.js pour améliorer l''efficacité","de":"Der AIOS Analyst Agent ist ein Tool für Marktforschung und Wettbewerbsanalyse, das Node.js verwendet, um die Effizienz zu verbessern","pt":"O AIOS Analyst é uma ferramenta de análise de negócios que ajuda os desenvolvedores a realizar pesquisas de mercado e análise competitiva de forma eficaz","ru":"ИИ Агент AIOS Analyst - это инструмент бизнес-аналитики, помогающий разработчикам проводить рыночные исследования и конкурентный анализ","ar":"AIOS Analyst هو أداة تحليل أعمال تساعد المطورين على إجراء بحث سوقي و تحليل تنافسي بشكل فعال"},"seo":{"title":{"en":"aios-analyst: Setup Guide for AI Agents | AIOS Business A...","zh":"AIOS Analyst 设置指南 - 业务分析和市场研究","ja":"AIOS Analyst 導入ガイド - ビジネス分析と市場調査","ko":"AIOS Analyst 설정 가이드 - 비즈니스 분석 및 시장 연구","es":"Guía de configuración del agente AIOS 