INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lucasmartinsr/barber-go/aios-analyst', 'aios-analyst', 'lucasmartinsr', 'barber-go', 'community', 'aios-analyst lucasmartinsr barber-go community The aios-analyst skill facilitates market research, competitive analysis, and user research, benefiting business analysts and project managers. It enables structured ideation workshops and project discovery. AIOS Analyst 是一个用于业务分析和市场研究的工具，支持用户研究、竞争对手分析和行业趋势分析 AIOS Analyst はビジネス分析と市場調査に使用されるツールで、ユーザー調査、競合分析、業界動向分析をサポート AIOS Analyst는 비즈니스 분석 및 시장 연구에 사용되는 도구로 사용자 연구, 경쟁 분석 및 산업 동향 분석을 지원합니다 El agente AIOS Analyst es una herramienta para investigación de mercado y análisis competitivo que utiliza Node.js para mejorar la eficiencia L''agent AIOS Analyst est un outil pour l''analyse de marché et concurrentielle qui utilise Node.js pour améliorer l''efficacité Der AIOS Analyst Agent ist ein Tool für Marktforschung und Wettbewerbsanalyse, das Node.js verwendet, um die Effizienz zu verbessern O AIOS Analyst é uma ferramenta de análise de negócios que ajuda os desenvolvedores a realizar pesquisas de mercado e análise competitiva de forma eficaz ИИ Агент AIOS Analyst - это инструмент бизнес-аналитики, помогающий разработчикам проводить рыночные исследования и конкурентный анализ AIOS Analyst هو أداة تحليل أعمال تساعد المطورين على إجراء بحث سوقي و تحليل تنافسي بشكل فعال how to use aios-analyst aios-analyst setup guide aios-analyst vs business analyst tools aios-analyst install what is aios-analyst aios-analyst alternative aios-analyst for market research aios-analyst for competitive analysis aios-analyst for project discovery AIOS Analyst AI 业务分析 市场研究 竞争对手分析 用户研究 业界动向分析 Node.js 项目发现 AI 工具 Loads .aios-core/development/agents/analyst.md as source of truth Adopts the agent persona and command system Generates greeting via node .aios-core/development Facilitates structured ideation workshops Conducts industry trends analysis and feasibility studies Supports project discovery and brownfield documentation aios-analyst is a business analyst activator for market research, competitive analysis, and project discovery, utilizing the .aios-core/development/agents/analyst.md protocol.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Emz1998/avaris-ai/backlog', 'community', 'Emz1998', 'avaris-ai', 'Emz1998/avaris-ai', 'backlog', 0, 0, 38, '2026-03-05T02:14:08Z', '2026-03-07T04:18:46.971Z', 'a37c5bcf66c7e289ac655fb88861a13bac904a329d51c7b703626a3379f8b089', '{"id":"Emz1998/avaris-ai/backlog","name":"backlog","description":{"en":"The backlog skill helps developers create and maintain a structured backlog.md file, enabling efficient project management. It benefits development teams by organizing tasks and priorities.","zh":"Backlog 是一个用于管理项目的结构化文件，使用模板和优先级可以高效地管理项目","ja":"バックログはプロジェクトを管理するための構造化されたファイルです。テンプレートと優先順位を使用して効率的にプロジェクトを管理できます","ko":"백로그는 프로젝트를 관리하는 데 사용되는 구조화된 파일입니다. 템플릿과 우선순위를 사용하여 효율적으로 프로젝트를 관리할 수 있습니다","es":"El backlog es un componente clave en el desarrollo ágil, que permite priorizar y organizar las tareas del proyecto de manera eficiente.","fr":"Le backlog est un élément clé dans le développement agile, permettant de prioriser et d''organiser les tâches du projet de manière efficace.","de":"Das Backlog ist ein wichtiger Bestandteil im agilen Entwicklung, das die Priorisierung und Organisation der Projekttaufgaben ermöglicht.","pt":"O backlog é um arquivo estruturado que contém epics, histórias e tarefas para melhorar a produtividade da equipe","ru":"Backlog - это структурированный файл, содержащий эпические истории и задачи для управления проектами","ar":"ال백لوغ هو ملف منظم يحتوي على قصص و مهام لتحسين أداء الفريق"},"seo":{"title":{"en":"Backlog: Structured Project Management Setup Guide | AI A...","zh":"Backlog 设置指南：使用模板和优先级管理项目","ja":"バックログのベストプラクティス：AIエージェントを使用した効率的なプロジェクト管理","ko":"백로그 설정 가이드: 템플릿과 우선순위를 사용한 프로젝트 관리","es":"Guía de configuración de backlog para proyectos ágiles","fr":"Guide de mise en place du backlog pour les projets agiles","de":"Backlog Einrichtungsleitfaden für agilen Projektmanagement","pt":"Guia de Configuração de Backlog para Desenvolvedores","ru":"Настройка ИИ Агентов: Руководство по созданию Backlog","ar":"دليل إعداد Backlog للعمليات التجارية باستخدام أدوات الذكا..."},"description":{"en":"Discover how to create and maintain a structured backlog.md file with our expert guide. Learn to prioritize tasks and manage projects efficiently with AI age...","zh":"了解如何使用 backlog.md 文件和模板高效管理项目，包括创建和维护结构化的 backlog 并设置优先级","ja":"プロジェクト管理を効率化するためのバックログの作成と管理方法を紹介します。AIエージェントを使用したベストプラクティスを学びましょう","ko":"백로그 설정과 관리 방법을 알아보세요. 템플릿을 사용하여 구조화된 백로그를 생성하고 우선순위를 설정하는 방법을 포함합니다","es":"Aprende a crear y mantener un backlog estructurado con nuestra guía paso a paso para proyectos ágiles y herramientas de desarrollo","fr":"Découvrez comment créer et maintenir un backlog structuré avec notre guide étape par étape pour les projets agiles et les outils de développement","de":"Erfahren Sie, wie Sie ein strukturiertes Backlog erstellen und pflegen können, mit unserer Schritt-für-Schritt-Anleitung für agile Projekte und Entwicklungst...","pt":"Aprenda a criar e manter um arquivo de backlog estruturado com prioridades e hierarquias claras para melhorar a produtividade da equipe","ru":"Создайте эффективный Backlog с помощью ИИ Агентов и улучшите управление проектами","ar":"تعرف على كيفية إنشاء وتحديث ملف Backlog المنظم باستخدام أدوات الذكاء الاصطناعي لتحسين أداء الفريق"},"definition":{"en":"Backlog is a structured project management approach using a backlog.md file to organize epics, stories, and tasks with priority levels and global IDs.","zh":"Backlog 是一个项目管理术语，指的是一个结构化的文件，用于记录和管理项目的需求和任务","ja":"バックログとは、プロジェクトの要件とタスクを記録して管理するための構造化されたファイルです","ko":"백로그는 프로젝트의 요구 사항과 태스크를 기록하고 관리하는 데 사용되는 구조화된 파일입니다","es":"Un backlog es un registro estructurado de tareas y requisitos del proyecto, que se utiliza para priorizar y planificar el desarrollo","fr":"Un backlog est un registre structuré des tâches et des exigences du projet, utilisé pour prioriser et planifier le développement","de":"Ein Backlog ist ein strukturierter Nachweis von Aufgaben und Anforderungen des Projekts, der zur Priorisierung und Planung der Entwicklung verwendet wird","pt":"Backlog é um arquivo que contém todas as tarefas e histórias de um projeto","ru":"Backlog - это файл, содержащий все задачи и истории проекта","ar":"ال백لوغ هو ملف يحتوي على جميع المهام و القصص الخاصة بمشروع"},"features":{"en":["Generates a structured backlog.md file using a template at template/backlog.md","Organizes tasks into epics, stories, and tasks with global IDs and prefixes","Supports priority levels: Must have, Should have, Nice to have, and Spikes","Creates tasks at sprint level with IDs starting with T-NNN","Maintains a hierarchy of epics containing stories with IDs like US-NNN, TS-NNN, BG-NNN, SK-NNN"],"zh":["使用模板创建结构化的 backlog","设置优先级：必须、应该、好的","创建和管理 Epics、Stories 和 Tasks","使用全局和顺序 ID","支持 Spikes"],"ja":["テンプレートを使用して構造化されたバックログを作成","優先順位の設定：必須、べき、良い","エピック、ストーリー、タスクの作成と管理","グローバルとシーケンシャル ID の使用","スパイクのサポート"],"ko":["템플릿을 사용하여 구조화된 백로그를 생성","우선순위 설정: 반드시, 해야, 좋음","에픽, 스토리, 태스크의 생성 및 관리","전역 및 순차 ID 사용","스파이크 지원"],"es":["Jerarquía de epics y stories","Priorización de tareas con niveles de prioridad","Uso de IDs globales y secuenciales","Creación de tareas al nivel de sprint","Plantilla de backlog personalizable"],"fr":["Hiérarchie d''épics et d''histoires","Priorisation des tâches avec des niveaux de priorité","Utilisation d''IDs globales et séquentielles","Création de tâches au niveau du sprint","Modèle de backlog personnalisable"],"de":["Hierarchie von Epics und Stories","Priorisierung von Aufgaben mit Prioritätsstufen","Verwendung globaler und sequenzieller IDs","Erstellung von Aufgaben auf Sprint-Ebene","Anpassbares Backlog-Template"],"pt":["Criação de epics e histórias com IDs globais e sequenciais","Definição de prioridades com níveis de Must have, Should have e Nice to have","Organização de tarefas em sprints","Uso de template para criação de arquivo de backlog"],"ru":["Создание эпических историй и задач с глобальными и последовательными ID","Определение приоритетов с уровнями Must have, Should have и Nice to have","Организация задач в спринтах","Использование шаблона для создания файла Backlog"],"ar":["إنشاء قصص و مهام مع معرفات عالمية و متسلسلة","تحديد الأولويات بمستويات يجب أن يكون، ينبغي أن يكون و من المفيد أن يكون","تنظيم المهام في سبرينتات","استخدام قالب لإنشاء ملف الباكلوغ"]},"keywords":{"en":["how to use backlog in project management","what is backlog management","backlog setup guide for developers","backlog vs agile project management","backlog install and configuration","structured project management with backlog","prioritizing tasks in backlog","backlog alternative for development teams","backlog best practices for AI agents"],"zh":["backlog 管理","项目管理工具","AI 工具","优先级设置","结构化文件","Epics 和 Stories","Tasks 和 Spikes","全局 ID","顺序 ID"],"ja":["バックログ管理","プロジェクト管理ツール","AIエージェント","優先順位設定","構造化ファイル","エピックとストーリー","タスクとスパイク","グローバルID","シーケンシャルID"],"ko":["백로그 관리","프로젝트 관리 도구","AI 에이전트","우선순위 설정","구조화된 파일","에픽과 스토리","태스크와 스파이크","전역 ID","순차 ID"],"es":["backlog en desarrollo ágil","herramientas de backlog","priorización de tareas","gestión de proyectos ágiles","desarrollo de software","agile project management","backlog template","prioridad de tareas"],"fr":["backlog dans le développement agile","outils de backlog","priorisation des tâches","gestion de projets agiles","développement de logiciels","agile project management","modèle de backlog","priorité des tâches"],"de":["Backlog im agilen Entwicklung","Backlog-Tools","Priorisierung von Aufgaben","Agiles Projektmanagement","Softwareentwicklung","agile project management","Backlog-Vorlage","Priorität von Aufgaben"],"pt":["backlog para desenvolvedores","criação de backlog","gestão de projetos com backlog","prioridades no backlog","hierarquias no backlog","ferramentas de backlog"],"ru":["Backlog для разработчиков","создание Backlog","управление проектами с помощью Backlog","приоритеты в Backlog","иерархии в Backlog","инструменты для Backlog"],"ar":["باكلوغ للتنمية","إنشاء باكلوغ","إدارة المشاريع باستخدام الباكلوغ","أولويات الباكلوغ","هياكل الباكلوغ","أدوات الباكلوغ"]}},"owner":"Emz1998","repo":"avaris-ai","repoPath":"Emz1998/avaris-ai","stars":0,"forks":0,"updatedAt":"2026-03-05T02:14:08Z","topics":[],"category":"community","skillMd":{"name":"backlog","description":"Creates and manages product backlog markdown files with epics, user stories, technical stories, bugs, and spikes. Use when creating backlogs, adding epics/stories/tasks, updating story status, or when user mentions backlog, sprint planning, project management, or task tracking.","bodyPreview":"**Goal**: Create and maintain a structured `backlog.md` file at `project/workflow/backlog.md` using the template at `template/backlog.md`.\n\n## Instructions\n\n- Read project specs for context before creating or modifying the backlog\n- **Hierarchy**: Epics (EP-NNN) contain stories (US-NNN, TS-NNN, BG-NNN, SK-NNN). Tasks (T-NNN) are created at sprint level, not in the backlog\n- All IDs are global and sequential within their prefix\n- Use priority levels: Must have, Should have, Nice to have\n- Spikes","body":"**Goal**: Create and maintain a structured `backlog.md` file at `project/workflow/backlog.md` using the template at `template/backlog.md`.\n\n## Instructions\n\n- Read project specs for context before creating or modifying the backlog\n- **Hierarchy**: Epics (EP-NNN) contain stories (US-NNN, TS-NNN, BG-NNN, SK-NNN). Tasks (T-NNN) are created at sprint level, not in the backlog\n- All IDs are global and sequential within their prefix\n- Use priority levels: Must have, Should have, Nice to have\n- Spikes reference which story they unblock\n- Bugs reference the story they were found in (if known)\n- A story can only belong to one epic\n- Stories that don''t fit an epic go in **Tech Debt / Infrastructure** or **Bug Backlog** sections\n\n## Workflow\n\n1. Read project specs for context:\n   - **Product Brief**: `project/docs/product/product-brief.md`\n   - **Architecture**: `project/docs/architecture/architecture.md`\n   - **Coding Standards**: `project/docs/architecture/coding-standards.md`\n   - **Definition of Done**: `project/docs/governance/definition-of-done.md`\n   - **Decisions**: `project/docs/architecture/decisions.md`\n\n2. Read the backlog template: [template/backlog.md](template/backlog.md)\n\n3. Check if `backlog.md` exists at `project/workflow/backlog.md`. If not, create it from the template.\n\n4. Create or update the backlog following the template structure:\n   - Fill the **Epics Overview** table with all epics and their priorities\n   - Fill **Epic Details** sections with stories for each epic\n   - Populate **Tech Debt / Infrastructure** and **Bug Backlog** as needed\n   - Move completed stories to the **Completed** table\n\n5. Provide summary report to the user\n\n## Rules\n\n- Most stories should be independent per INVEST principles\n- Avoid dependencies between stories as much as possible\n- Do not add task-level detail to the backlog; that belongs in sprint planning\n- Must have bugs take priority over Should have stories in the next sprint\n- Reprioritize at every sprint close based on Scrum Master recommendations\n- Stories use their type-specific format (US/TS/BG/SK) matching sprint.md conventions\n\n## Acceptance Criteria\n\n- Backlog follows the exact structure from `template/backlog.md`\n- All IDs follow correct patterns (EP-NNN, US-NNN, TS-NNN, BG-NNN, SK-NNN)\n- Each epic has a description, priority, and status\n- Stories use the correct format: \"As a [user], I want [what] so that [why]\"\n- Priority legend, status values, and ID conventions match the template\n- Epics Overview table accurately reflects current counts and statuses\n- File written to correct path: `project/workflow/backlog.md`\n"},"lastSynced":"2026-03-07T04:18:46.971Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents requiring structured task organization and prioritization.","zh":"适用于需要结构化任务组织和优先级的项目管理代理。","ja":"構造化されたタスクの組織化と優先順位が必要なプロジェクト管理エージェントに適しています。","ko":"구조화된 작업 조직 및 우선순위가 필요한 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Proyectos que requieren una organización de tareas estructurada y priorización.","fr":"Idéal pour les agents de gestion de projet nécessitant une organisation de tâches structurée et une priorisation.","de":"Ideal für Projektmanagement-Agenten, die eine strukturierte Aufgabenorganisation und Priorisierung benötigen.","pt":"Ideal para Agentes de Gerenciamento de Projetos que requerem organização de tarefas estruturada e priorização.","ru":"Идеально для агентов по управлению проектами, требующих структурированной организации задач и приоритизации.","ar":"مثالي للوكلاء إدارة المشاريع الذين يتطلبون تنظيم المهام المنظم والتدرج"},"recommendation":{"en":"Empowers agents to manage project workflows by creating and maintaining a standardized `backlog.md` file, utilizing a hierarchical structure with epics, stories, and tasks, and implementing priority levels such as Must have, Should have, and Nice to have.","zh":"使代理能够通过创建和维护标准化的 `backlog.md` 文件、利用具有史诗、故事和任务的层次结构以及实现Must have、Should have和Nice to have等优先级来管理项目工作流。","ja":"エージェントがプロジェクトのワークフローを管理できるようにすることで、標準化された `backlog.md` ファイルを作成して維持し、エピック、ストーリー、タスクの階層構造を利用し、Must have、Should have、Nice to haveなどの優先レベルを実装する。","ko":"에이전트가 프로젝트 워크플ロー 관리를 통하여 표준화된 `backlog.md` 파일을 생성 및 유지 관리하고, 에픽, 스토리, 작업의 계층 구조를 활용하며, Must have, Should have, Nice to have 등의 우선 순위를 구현할 수 있도록 합니다.","es":"Habilita a los agentes a gestionar flujos de trabajo de proyecto mediante la creación y el mantenimiento de un archivo `backlog.md` estandarizado, que utiliza una estructura jerárquica con epics, stories y tareas, e implementa niveles de prioridad como Debe tener, Debe tener y Agradable de tener.","fr":"Permet aux agents de gérer les flux de travail de projet en créant et en maintenant un fichier `backlog.md` standardisé, qui utilise une structure hiérarchique avec des épopées, des histoires et des tâches, et met en œuvre des niveaux de priorité tels que Doit avoir, Devrait avoir et Agréable à avoir.","de":"Ermöglicht es Agenten, Projektworkflows zu verwalten, indem sie eine standardisierte `backlog.md`-Datei erstellen und pflegen, die eine hierarchische Struktur mit Epics, Stories und Aufgaben verwendet und Prioritätsstufen wie Muss haben, Sollte haben und Schön zu haben implementiert.","pt":"Habilita os agentes a gerenciar fluxos de trabalho de projeto criando e mantendo um arquivo `backlog.md` padronizado, utilizando uma estrutura hierárquica com épicos, histórias e tarefas, e implementando níveis de prioridade, como Deve ter, Pode ter e Bom ter.","ru":"Наделяет агентов возможностью управлять рабочими процессами проекта, создавая и поддерживая стандартизированный файл `backlog.md`, используя иерархическую структуру с эпиками, историями и задачами, и реализуя уровни приоритета, такие как Должно быть, Может быть и Хорошо бы.","ar":"يمنح الوكلاء إمكانية إدارة سير عمل المشروع من خلال إنشاء ملف `backlog.md` معياري والحفاظ عليه، باستخدام هيكل هرمي مع ملحمة وقصص ومهام، وتنفيذ مستويات الأولوية مثل يجب أن يكون، ويمكن أن يكون، وجيد أن يكون"},"useCases":{"en":["Automating backlog updates with sequential IDs","Generating task reports based on priority levels","Maintaining a structured project workflow with epics and stories"],"zh":["使用顺序ID自动更新待办事项","根据优先级生成任务报告","使用史诗和故事维护结构化的项目工作流"],"ja":["順序IDを使用してバックログを自動更新する","優先レベルに基づいてタスクレポートを生成する","エピックとストーリーを使用して構造化されたプロジェクトワークフローを維持する"],"ko":["순차 ID를 사용하여 백로그를 자동으로 업데이트하는","우선 순위 수준에 따라 작업 보고서를 생성하는","에픽과 스토리를 사용하여 구조화된 프로젝트 워크플ロー 유지"],"es":["Automatizar actualizaciones de backlog con IDs secuenciales","Generar informes de tareas en función de los niveles de prioridad","Mantener un flujo de trabajo de proyecto estructurado con epics y stories"],"fr":["Automatiser les mises à jour de backlog avec des ID séquentiels","Générer des rapports de tâches en fonction des niveaux de priorité","Maintenir un flux de travail de projet structuré avec des épopées et des histoires"],"de":["Automatisieren von Backlog-Updates mit sequenziellen IDs","Erstellen von Aufgabenberichten basierend auf Prioritätsstufen","Aufrechterhalten eines strukturierten Projektworkflows mit Epics und Stories"],"pt":["Automatizar atualizações do backlog com IDs seqüenciais","Gerar relatórios de tarefas com base nos níveis de prioridade","Manter um fluxo de trabalho de projeto estruturado com épicos e histórias"],"ru":["Автоматизировать обновления бэклога с последовательными идентификаторами","Генерировать отчеты о задачах на основе уровней приоритета","Поддерживать структурированный рабочий процесс проекта с эпиками и историями"],"ar":["توفير تحديثات الباكلوغ الآلية بالأرقام التسلسلية","توليد تقارير المهام على أساس مستويات الأولوية","الحفاظ على سير عمل مشروع منظم بالملحمة والقصص"]},"limitations":{"en":["Requires access to project specifications","Limited to Markdown file format","Hierarchy and ID sequencing must be manually maintained"],"zh":["需要访问项目规格","仅限Markdown文件格式","层次结构和ID序列必须手动维护"],"ja":["プロジェクトの仕様にアクセスする必要がある","Markdownファイル形式のみに限定される","階層構造とIDシーケンスは手動で維持する必要がある"],"ko":["프로젝트 사양에 액세스해야 함","Markdown 파일 형식만으로 제한됨","계층 구조 및 ID 시퀀스는 수동으로 유지 관리해야 함"],"es":["Requiere acceso a las especificaciones del proyecto","Limitado al formato de archivo Markdown","La jerarquía y la secuencia de IDs deben mantenerse manualmente"],"fr":["Nécessite un accès aux spécifications du projet","Limité au format de fichier Markdown","La hiérarchie et la séquence d''ID doivent être maintenues manuellement"],"de":["Benötigt Zugriff auf die Projektspezifikationen","Begrenzt auf das Markdown-Dateiformat","Die Hierarchie und die ID-Sequenz müssen manuell aufrechterhalten werden"],"pt":["Requer acesso às especificações do projeto","Limitado ao formato de arquivo Markdown","A hierarquia e a sequência de IDs devem ser mantidas manualmente"],"ru":["Требует доступа к спецификациям проекта","Ограничен форматом файла Markdown","Иерархия и последовательность идентификаторов должны поддерживаться вручную"],"ar":["يتطلب الوصول إلى مواصفات المشروع","محدود بتنسيق ملف ماركداون","يجب الحفاظ على التدرج والترتيب الهرمي للأرقام التسلسلية يدويا"]},"version":4},"contentHash":"a37c5bcf66c7e289ac655fb88861a13bac904a329d51c7b703626a3379f8b089","qualityScore":38}');
