INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('beyondeye/aitasks/aitask-review', 'aitask-review', 'beyondeye', 'aitasks', 'community', 'aitask-review beyondeye aitasks community The aitask-review skill is a Codex CLI wrapper that enables AI agents to interact with the aitask-review workflow. It benefits developers who need to integrate AI tasks with their existing workflows. aitask-review技能是Codex CLI的封装，提供了AI任务审查的解决方案 aitask-reviewスキルはCodex CLIのラッパーであり、AIタスクのレビュー機能を提供する aitask-review 스킬은 Codex CLI의 래퍼이며 AI 태스크 리뷰 기능을 제공합니다 aitask-review es un wrapper de la interfaz de línea de comandos de Codex que permite a los desarrolladores simplificar sus tareas. Sigue nuestro tutorial para configurarlo. aitask-review est un wrapper de l''interface de ligne de commande de Codex qui permet aux développeurs de simplifier leurs tâches. Suivez notre tutoriel pour le configurer. aitask-review ist ein Wrapper der Codex-CLI, der es Entwicklern ermöglicht, ihre Aufgaben zu vereinfachen. Folgen Sie unserem Tutorial, um es zu konfigurieren. O aitask-review é uma habilidade que envolve a integração com o Codex CLI para otimizar workflows. Aitask-review - это навык, который включает в себя интеграцию с Codex CLI для оптимизации рабочих процессов. aitask-review هو مهارة ي涉ل دمج مع Codex CLI لتحسين سير العمل. how to use aitask-review aitask-review setup guide Codex CLI wrapper AI agent integration aitask-review alternative aitask-review vs Codex CLI aitask-review install what is aitask-review AI工具 aitask-review Codex CLI AI任务审查 `.agents/skills/codex_interactive_prereqs.md` `.claude/skills/aitask-review/SKILL.md` Follows interact protocol for seamless AI agent integration Requires prerequisites outlined in `.agents/skills/codex_interactive_prereqs.md` Utilizes Codex CLI for workflow management Adapts tool mappings according to `.agents/skills/codex_tool_mapping.md` Source of truth defined in `.claude/skills/aitask-review/SKILL.md` aitask-review is a Codex CLI wrapper skill that provides a standardized interface for AI agents to review and interact with AI tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jacksonemmerich/farmapub/upstash-qstash', 'community', 'jacksonemmerich', 'farmapub', 'jacksonemmerich/farmapub', 'upstash-qstash', 0, 0, 38, '2026-03-04T19:31:21Z', '2026-03-07T13:14:31.194Z', 'e2326fed56112197d6da66b4551d4d3f6e666eb2d127d4232e0285c574d829ab', '{"id":"jacksonemmerich/farmapub/upstash-qstash","name":"upstash-qstash","description":{"en":"upstash-qstash is a serverless messaging expert that builds reliable systems without infrastructure management. It simplifies messaging with HTTP in, HTTP out, and reliability in between, ideal for developers needing to schedule messages and set up cron jobs.","zh":"Upstash QStash 是一个可靠的服务器无消息队列，支持 HTTP 调用和 cron 作业","ja":"Upstash QStash は信頼性の高いサーバーレスメッセージングソリューションで、HTTP のイン/アウトと cron ジョブをサポート","ko":"Upstash QStash는 안정적인 서버리스 메시징 솔루션으로 HTTP인/아웃과 크론잡을 지원","es":"Upstash QStash es una herramienta de mensajería serverless que permite programar millones de mensajes con HTTP. Conecta fácilmente con sistemas de entrega de webhooks","fr":"Upstash QStash est un outil de messagerie sans serveur qui permet de planifier des millions de messages avec HTTP. Connectez facilement avec des systèmes de livraison de webhooks","de":"Upstash QStash ist ein Tool für serverlose Messaging, das das Planen von Millionen von Nachrichten mit HTTP ermöglicht. Verbinden Sie einfach mit Webhook-Lieferungssystemen","pt":"O Upstash QStash é uma ferramenta de mensagens serverless que permite HTTP in, HTTP out com confiabilidade","ru":"Upstash QStash - это инструмент для серверных сообщений, который позволяет HTTP в, HTTP из с надежностью","ar":"Upstash QStash هو أداة لأجهزة النصية الخادمة التي تسمح ب HTTP في، HTTP خارج مع موثوقية"},"seo":{"title":{"en":"upstash-qstash: Reliable Serverless Messaging Setup Guide...","zh":"Upstash QStash 设置指南：可靠的服务器无消息队列","ja":"Upstash QStash のベストプラクティス：信頼性の高いサ